window.REELS=[{"id":"pf-p-hashing-217","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Is any number in the list repeated?","a":"Hash map / set","x":"One pass with a hash set: if the number is already in the set, I've found a duplicate. O(n) time and O(n) space.","t":"Contains Duplicate","L":"hashing.html#p-217","d":"p-hashing-217"},{"id":"gt-p-hashing-217","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Contains Duplicate?","a":"len(set(nums)) != len(nums) works but can’t stop early.","x":"“Seen before?” → set.","t":"Contains Duplicate","L":"hashing.html#p-217","d":"p-hashing-217"},{"id":"pf-p-hashing-242","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Do the two strings use exactly the same letters, the same number of times?","a":"Hash map / set","x":"Count letters of the first string and subtract the counts of the second; it's an anagram only if every count ends at zero. O(n).","t":"Valid Anagram","L":"hashing.html#p-242","d":"p-hashing-242"},{"id":"gt-p-hashing-242","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Valid Anagram?","a":"Check lengths first for a quick exit.","x":"Frequencies → Counter.","t":"Valid Anagram","L":"hashing.html#p-242","d":"p-hashing-242"},{"id":"pf-p-hashing-1","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Find two different positions whose values add up to target.","a":"Hash map / set","x":"For each number I need target minus x; I keep a hash map from value to index of what I've seen, so it's one pass, O(n).","t":"Two Sum","L":"hashing.html#p-1","d":"p-hashing-1"},{"id":"gt-p-hashing-1","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Two Sum?","a":"Sorting + two pointers loses the original indexes unless you carry them along.","x":"Pair with a target → complement lookup.","t":"Two Sum","L":"hashing.html#p-1","d":"p-hashing-1"},{"id":"pf-p-hashing-49","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Put words with the same letters (in any order) into the same group.","a":"Hash map / set","x":"Anagrams share a signature, the sorted letters or a 26-count tuple, so I use that as a hash map key and append each word to its group.","t":"Group Anagrams","L":"hashing.html#p-49","d":"p-hashing-49"},{"id":"gt-p-hashing-49","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Group Anagrams?","a":"Lists can’t be dict keys; convert to a tuple.","x":"Group by sameness → canonical key.","t":"Group Anagrams","L":"hashing.html#p-49","d":"p-hashing-49"},{"id":"pf-p-hashing-347","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Which k numbers appear most often?","a":"Heap / top-k","x":"Count frequencies with a hash map, then either keep a size-k min-heap, n log k, or bucket by frequency for O(n).","t":"Top K Frequent Elements","L":"hashing.html#p-347","d":"p-hashing-347"},{"id":"gt-p-hashing-347","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Top K Frequent Elements?","a":"Bucket list size is len(nums) + 1, because a count can equal n.","x":"Top k by frequency → bucket sort.","t":"Top K Frequent Elements","L":"hashing.html#p-347","d":"p-hashing-347"},{"id":"pf-p-hashing-238","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"For each position, multiply every other number, without using division.","a":"Prefix sums","x":"Each answer is the product of everything to the left times everything to the right, so two passes with running products. O(n), O(1) extra.","t":"Product of Array Except Self","L":"hashing.html#p-238","d":"p-hashing-238"},{"id":"gt-p-hashing-238","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Product of Array Except Self?","a":"Division fails with zeros, and it’s banned anyway.","x":"Left and right info → two passes.","t":"Product of Array Except Self","L":"hashing.html#p-238","d":"p-hashing-238"},{"id":"pf-p-hashing-36","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Check the filled cells: no digit may repeat in a row, a column or a 3×3 box.","a":"Hash map / set","x":"One pass over the cells with a set per row, per column and per box; the box index is row divided by three and column divided by three.","t":"Valid Sudoku","L":"hashing.html#p-36","d":"p-hashing-36"},{"id":"gt-p-hashing-36","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Valid Sudoku?","a":"Box index is (r // 3, c // 3), not r // 3 + c // 3 alone without care.","x":"“Seen before?” → set, with tagged keys.","t":"Valid Sudoku","L":"hashing.html#p-36","d":"p-hashing-36"},{"id":"pf-p-hashing-128","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"How long is the longest run like 4, 5, 6, 7 using numbers from the list (any order)?","a":"Hash map / set","x":"Put everything in a hash set and only start counting from numbers whose predecessor is missing; each number is visited a constant number of times, O(n).","t":"Longest Consecutive Sequence","L":"hashing.html#p-128","d":"p-hashing-128"},{"id":"gt-p-hashing-128","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Longest Consecutive Sequence?","a":"Iterate over the set, not the list, so duplicates don’t restart walks.","x":"Count runs only from their start.","t":"Longest Consecutive Sequence","L":"hashing.html#p-128","d":"p-hashing-128"},{"id":"pf-p-hashing-560","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"How many contiguous pieces of the array add up exactly to k?","a":"Prefix sums","x":"Prefix sums with a hash map of how many times each prefix has occurred; for each prefix p, add the count of p minus k. O(n).","t":"Subarray Sum Equals K","L":"hashing.html#p-560","d":"p-hashing-560"},{"id":"gt-p-hashing-560","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Subarray Sum Equals K?","a":"Sliding window fails with negatives.","x":"Subarray sum = k → prefix + dict.","t":"Subarray Sum Equals K","L":"hashing.html#p-560","d":"p-hashing-560"},{"id":"pf-p-hashing-303","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Answer many 'sum from index l to r' questions on an array that never changes.","a":"Prefix sums","x":"Precompute prefix sums once; each query is prefix of right plus one minus prefix of left, so O(n) build and O(1) per query.","t":"Range Sum Query – Immutable","L":"hashing.html#p-303","d":"p-hashing-303"},{"id":"gt-p-hashing-303","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Range Sum Query – Immutable?","a":"The leading 0 removes every edge case at l = 0.","x":"Many range sums → prefix array.","t":"Range Sum Query – Immutable","L":"hashing.html#p-303","d":"p-hashing-303"},{"id":"pf-p-hashing-169","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"One value appears more than half the time. Which one?","a":"Hash map / set","x":"Boyer-Moore voting: keep a candidate and a counter, increment on match, decrement otherwise, switch when it hits zero. O(n) time, O(1) space.","t":"Majority Element","L":"hashing.html#p-169","d":"p-hashing-169"},{"id":"gt-p-hashing-169","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Majority Element?","a":"Only valid when a true majority is guaranteed.","x":"Frequency with O(1) space → voting.","t":"Majority Element","L":"hashing.html#p-169","d":"p-hashing-169"},{"id":"pf-p-hashing-271","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Turn a list of strings into one string and back, even if the strings contain any character.","a":"Design a data structure","x":"Length-prefix every string, like four, hash, then the four characters; decoding reads the length, skips the marker and slices exactly that many characters.","t":"Encode and Decode Strings","L":"hashing.html#p-271","d":"p-hashing-271"},{"id":"gt-p-hashing-271","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Encode and Decode Strings?","a":"Splitting on a delimiter breaks the moment a string contains it.","x":"Arbitrary content → length-prefix, never a bare delimiter.","t":"Encode and Decode Strings","L":"hashing.html#p-271","d":"p-hashing-271"},{"id":"pf-p-hashing-41","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"What's the smallest positive integer not in the list? Use O(1) extra space.","a":"Hash map / set","x":"The answer is between one and n plus one, so I use the array as its own hash: place each value v at index v minus one by swapping, then scan for the first mismatch.","t":"First Missing Positive","L":"hashing.html#p-41","d":"p-hashing-41"},{"id":"gt-p-hashing-41","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in First Missing Positive?","a":"Use abs() when reading, since earlier marks may have flipped signs.","x":"Values 1…n with O(1) space → index-as-hash.","t":"First Missing Positive","L":"hashing.html#p-41","d":"p-hashing-41"},{"id":"pf-p-hashing-48","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Rotate a square matrix 90° clockwise without making a copy.","a":"Matrix traversal","x":"Transpose across the main diagonal, then reverse each row. O(n squared) time and O(1) extra space.","t":"Rotate Image","L":"hashing.html#p-48","d":"p-hashing-48"},{"id":"gt-p-hashing-48","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Rotate Image?","a":"Transpose only the upper triangle (c > r), or you swap everything back.","x":"Rotate → transpose + flip.","t":"Rotate Image","L":"hashing.html#p-48","d":"p-hashing-48"},{"id":"pf-p-hashing-54","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Read the matrix in a clockwise spiral from the outside in.","a":"Matrix traversal","x":"Keep four walls, top, bottom, left and right; walk each side and shrink that wall, stopping when they cross. O(m times n).","t":"Spiral Matrix","L":"hashing.html#p-54","d":"p-hashing-54"},{"id":"gt-p-hashing-54","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Spiral Matrix?","a":"Single-row or single-column leftovers get double-counted without the guards.","x":"Spiral → four shrinking walls.","t":"Spiral Matrix","L":"hashing.html#p-54","d":"p-hashing-54"},{"id":"pf-p-hashing-73","y":"pattern","tr":"dsa","s":"Arrays & Hashing","q":"Wherever there's a 0, wipe its whole row and column to 0, in place.","a":"Matrix traversal","x":"Use the first row and first column as marker storage, with one extra flag for the first column, then zero cells based on the markers.","t":"Set Matrix Zeroes","L":"hashing.html#p-73","d":"p-hashing-73"},{"id":"gt-p-hashing-73","y":"gotcha","tr":"dsa","s":"Arrays & Hashing","q":"What's the classic trap in Set Matrix Zeroes?","a":"Zeroing row 0 too early erases your flags.","x":"O(1) marking in a matrix → first row/col as flags.","t":"Set Matrix Zeroes","L":"hashing.html#p-73","d":"p-hashing-73"},{"id":"pf-p-two-pointers-125","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Ignoring punctuation, spaces and case, does it read the same both ways?","a":"Two pointers","x":"Two pointers from both ends, skipping non-alphanumerics and comparing lowercased characters as they move inward. O(n) time, O(1) space.","t":"Valid Palindrome","L":"two-pointers.html#p-125","d":"p-two-pointers-125"},{"id":"gt-p-two-pointers-125","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Valid Palindrome?","a":"Building a cleaned string is fine but costs O(n) space.","x":"Palindrome → converge from both ends.","t":"Valid Palindrome","L":"two-pointers.html#p-125","d":"p-two-pointers-125"},{"id":"pf-p-two-pointers-167","y":"pattern","tr":"dsa","s":"Two Pointers","q":"The array is sorted. Find the two positions (1-indexed) that sum to target.","a":"Two pointers","x":"Sorted means I can converge: left at the start, right at the end; too small, move left up, too big, move right down. O(n), O(1).","t":"Two Sum II – Input Array Is Sorted","L":"two-pointers.html#p-167","d":"p-two-pointers-167"},{"id":"pf-p-two-pointers-15","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Find every distinct triple of numbers that adds up to 0.","a":"Two pointers","x":"Sort, fix each number, then two-pointer the rest looking for its negative, skipping duplicate values at every level. O(n squared).","t":"3Sum","L":"two-pointers.html#p-15","d":"p-two-pointers-15"},{"id":"gt-p-two-pointers-15","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in 3Sum?","a":"Dedupe by skipping neighbours, not with a set of tuples.","x":"K-sum → sort + fix + two pointers.","t":"3Sum","L":"two-pointers.html#p-15","d":"p-two-pointers-15"},{"id":"pf-p-two-pointers-16","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Which sum of three numbers is closest to target?","a":"Two pointers","x":"Same as 3Sum: sort, fix one, two pointers on the rest, and track the closest sum; move pointers by whether the sum is below or above target.","t":"3Sum Closest","L":"two-pointers.html#p-16","d":"p-two-pointers-16"},{"id":"gt-p-two-pointers-16","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in 3Sum Closest?","a":"Return early on an exact match.","x":"K-sum → sort + fix + two pointers.","t":"3Sum Closest","L":"two-pointers.html#p-16","d":"p-two-pointers-16"},{"id":"pf-p-two-pointers-18","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Find every distinct group of four numbers that adds up to target.","a":"Two pointers","x":"Sort, two nested loops fix the first two numbers, then two pointers find the last two, skipping duplicates. O(n cubed).","t":"4Sum","L":"two-pointers.html#p-18","d":"p-two-pointers-18"},{"id":"gt-p-two-pointers-18","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in 4Sum?","a":"Skip check for the second loop is b > a + 1, not b > 0.","x":"K-sum → one more fixed loop per extra number.","t":"4Sum","L":"two-pointers.html#p-18","d":"p-two-pointers-18"},{"id":"pf-p-two-pointers-11","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Pick two vertical lines that, with the x-axis, hold the most water.","a":"Two pointers","x":"Start with the widest pair and always move the shorter line inward, since the shorter one limits the area. O(n).","t":"Container With Most Water","L":"two-pointers.html#p-11","d":"p-two-pointers-11"},{"id":"gt-p-two-pointers-11","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Container With Most Water?","a":"Moving the taller wall can skip the optimum.","x":"Container → move the shorter side.","t":"Container With Most Water","L":"two-pointers.html#p-11","d":"p-two-pointers-11"},{"id":"pf-p-two-pointers-42","y":"pattern","tr":"dsa","s":"Two Pointers","q":"How much rain water collects between the bars?","a":"Two pointers","x":"Water above each bar is min of the tallest bar to its left and right, minus its height; two pointers let me process the side with the smaller max in O(n) and O(1) space.","t":"Trapping Rain Water","L":"two-pointers.html#p-42","d":"p-two-pointers-42"},{"id":"gt-p-two-pointers-42","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Trapping Rain Water?","a":"Prefix/suffix max arrays also work in O(n) space; mention both.","x":"Trap water → two pointers with side maxima.","t":"Trapping Rain Water","L":"two-pointers.html#p-42","d":"p-two-pointers-42"},{"id":"pf-p-two-pointers-26","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Keep one copy of each value at the front of a sorted array; return how many.","a":"Two pointers","x":"A slow write pointer and a fast read pointer: whenever the reader sees a new value, write it at the slow pointer. O(n), O(1).","t":"Remove Duplicates from Sorted Array","L":"two-pointers.html#p-26","d":"p-two-pointers-26"},{"id":"gt-p-two-pointers-26","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Remove Duplicates from Sorted Array?","a":"Compare with the last kept value, not the previous index.","x":"In place → writer and reader.","t":"Remove Duplicates from Sorted Array","L":"two-pointers.html#p-26","d":"p-two-pointers-26"},{"id":"pf-p-two-pointers-283","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Push all zeros to the end, keeping the other numbers in order.","a":"Two pointers","x":"A write pointer copies or swaps each non-zero forward; whatever is left after it becomes zeros. O(n), O(1).","t":"Move Zeroes","L":"two-pointers.html#p-283","d":"p-two-pointers-283"},{"id":"gt-p-two-pointers-283","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Move Zeroes?","a":"Swapping (not copying) leaves zeros at the end for free.","x":"In place → writer and reader.","t":"Move Zeroes","L":"two-pointers.html#p-283","d":"p-two-pointers-283"},{"id":"pf-p-two-pointers-75","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Sort 0s, 1s and 2s in a single pass, in place.","a":"Two pointers","x":"Dutch national flag: low marks where the next zero goes, high where the next two goes, and mid scans; swap and move the right pointers. O(n), O(1).","t":"Sort Colors","L":"two-pointers.html#p-75","d":"p-two-pointers-75"},{"id":"pf-p-two-pointers-88","y":"pattern","tr":"dsa","s":"Two Pointers","q":"nums1 has room at the end. Merge sorted nums2 into it, keeping it sorted.","a":"Two pointers","x":"Fill from the back: compare the largest remaining elements and write the bigger one into the last free slot. O(m plus n), no extra space.","t":"Merge Sorted Array","L":"two-pointers.html#p-88","d":"p-two-pointers-88"},{"id":"gt-p-two-pointers-88","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Merge Sorted Array?","a":"Guard i ≥ 0 before reading nums1[i].","x":"Spare space at the end → fill backwards.","t":"Merge Sorted Array","L":"two-pointers.html#p-88","d":"p-two-pointers-88"},{"id":"pf-p-two-pointers-977","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Square each number of a sorted array (may contain negatives) and return them sorted.","a":"Two pointers","x":"The biggest square is at one of the two ends, so two pointers fill the result from the back. O(n).","t":"Squares of a Sorted Array","L":"two-pointers.html#p-977","d":"p-two-pointers-977"},{"id":"gt-p-two-pointers-977","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Squares of a Sorted Array?","a":"Squaring then sorting is O(n log n).","x":"Extremes at the ends → converge, fill backwards.","t":"Squares of a Sorted Array","L":"two-pointers.html#p-977","d":"p-two-pointers-977"},{"id":"pf-p-two-pointers-680","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Can you make it a palindrome by deleting at most one character?","a":"Two pointers","x":"Walk two pointers inward; on the first mismatch, try skipping the left or the right character once and check the remainder. O(n).","t":"Valid Palindrome II","L":"two-pointers.html#p-680","d":"p-two-pointers-680"},{"id":"gt-p-two-pointers-680","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Valid Palindrome II?","a":"Branch only once; nested branching is O(2ⁿ).","x":"Palindrome with one deletion → branch once on mismatch.","t":"Valid Palindrome II","L":"two-pointers.html#p-680","d":"p-two-pointers-680"},{"id":"pf-p-two-pointers-392","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Can you get s by deleting some letters of t (keeping order)?","a":"Two pointers","x":"Greedy two pointers: scan t and advance a pointer in s every time the characters match; true if s is fully matched. O(length of t).","t":"Is Subsequence","L":"two-pointers.html#p-392","d":"p-two-pointers-392"},{"id":"gt-p-two-pointers-392","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Is Subsequence?","a":"For many s queries on one t, precompute next-occurrence tables.","x":"Subsequence → one pointer per string.","t":"Is Subsequence","L":"two-pointers.html#p-392","d":"p-two-pointers-392"},{"id":"pf-p-two-pointers-881","y":"pattern","tr":"dsa","s":"Two Pointers","q":"Each boat holds at most 2 people and a weight limit. Fewest boats?","a":"Greedy","x":"Sort, then pair the heaviest remaining with the lightest if they fit; the heaviest always takes a boat. Two pointers, O(n log n).","t":"Boats to Save People","L":"two-pointers.html#p-881","d":"p-two-pointers-881"},{"id":"gt-p-two-pointers-881","y":"gotcha","tr":"dsa","s":"Two Pointers","q":"What's the classic trap in Boats to Save People?","a":"Loop while l ≤ r, so a lone middle person gets a boat.","x":"Pairing extremes → sort + converge.","t":"Boats to Save People","L":"two-pointers.html#p-881","d":"p-two-pointers-881"},{"id":"pf-p-sliding-window-121","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Buy one day, sell a later day. Biggest profit?","a":"Greedy","x":"Track the minimum price so far; at each day, profit is price minus that minimum, and keep the best. One pass, O(n).","t":"Best Time to Buy and Sell Stock","L":"sliding-window.html#p-121","d":"p-sliding-window-121"},{"id":"gt-p-sliding-window-121","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Best Time to Buy and Sell Stock?","a":"You can’t sell before buying, so update the min first or second consistently.","x":"Later minus earlier → min so far.","t":"Best Time to Buy and Sell Stock","L":"sliding-window.html#p-121","d":"p-sliding-window-121"},{"id":"pf-p-sliding-window-3","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Longest stretch of the string with no repeated character.","a":"Sliding window","x":"Sliding window with a map of last seen positions; when a repeat enters, jump the left edge past its previous position. O(n).","t":"Longest Substring Without Repeating Characters","L":"sliding-window.html#p-3","d":"p-sliding-window-3"},{"id":"gt-p-sliding-window-3","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Longest Substring Without Repeating Characters?","a":"In the jump version, only jump if last[ch] ≥ l.","x":"Longest valid → expand, shrink while invalid.","t":"Longest Substring Without Repeating Characters","L":"sliding-window.html#p-3","d":"p-sliding-window-3"},{"id":"pf-p-sliding-window-424","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Longest substring you can turn into all-one-letter with at most k changes.","a":"Sliding window","x":"Sliding window where window length minus the count of its most frequent letter must stay at most k; shrink when it's exceeded. O(n).","t":"Longest Repeating Character Replacement","L":"sliding-window.html#p-424","d":"p-sliding-window-424"},{"id":"gt-p-sliding-window-424","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Longest Repeating Character Replacement?","a":"maxf never needs to decrease.","x":"Repaint k → len − max freq ≤ k.","t":"Longest Repeating Character Replacement","L":"sliding-window.html#p-424","d":"p-sliding-window-424"},{"id":"pf-p-sliding-window-567","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Does s2 contain some rearrangement of s1 as a contiguous piece?","a":"Sliding window","x":"A fixed-size window of length s1 slides across s2, maintaining letter counts; it's a match when the counts are equal. O(n).","t":"Permutation in String","L":"sliding-window.html#p-567","d":"p-sliding-window-567"},{"id":"gt-p-sliding-window-567","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Permutation in String?","a":"Delete zero counts so Counter equality works.","x":"Anagram inside → fixed count window.","t":"Permutation in String","L":"sliding-window.html#p-567","d":"p-sliding-window-567"},{"id":"pf-p-sliding-window-438","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Every start index in s where some rearrangement of p begins.","a":"Sliding window","x":"Same fixed-size count window as permutation-in-string, but collect every index where the counts match. O(n).","t":"Find All Anagrams in a String","L":"sliding-window.html#p-438","d":"p-sliding-window-438"},{"id":"gt-p-sliding-window-438","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Find All Anagrams in a String?","a":"Start comparing only once the window is full.","x":"Anagram inside → fixed count window.","t":"Find All Anagrams in a String","L":"sliding-window.html#p-438","d":"p-sliding-window-438"},{"id":"pf-p-sliding-window-76","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Smallest substring of s that contains every character of t (with counts).","a":"Sliding window","x":"Expand the right edge until the window covers t, then shrink the left edge while it still covers, tracking a missing-characters counter. O(length of s plus t).","t":"Minimum Window Substring","L":"sliding-window.html#p-76","d":"p-sliding-window-76"},{"id":"gt-p-sliding-window-76","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Minimum Window Substring?","a":"Count duplicates in t: &quot;aa&quot; needs two a’s.","x":"Shortest covering window → shrink while valid, track missing.","t":"Minimum Window Substring","L":"sliding-window.html#p-76","d":"p-sliding-window-76"},{"id":"pf-p-sliding-window-239","y":"pattern","tr":"dsa","s":"Sliding Window","q":"For every window of size k, what's the maximum?","a":"Monotonic deque","x":"Keep a deque of indices with decreasing values; pop smaller ones from the back, drop the front when it leaves the window, and the front is the max. O(n).","t":"Sliding Window Maximum","L":"sliding-window.html#p-239","d":"p-sliding-window-239"},{"id":"gt-p-sliding-window-239","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Sliding Window Maximum?","a":"Pop with ≤ so equal older values go too.","x":"Window max → monotonic deque.","t":"Sliding Window Maximum","L":"sliding-window.html#p-239","d":"p-sliding-window-239"},{"id":"pf-p-sliding-window-209","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Shortest contiguous piece with sum ≥ target (all numbers positive).","a":"Sliding window","x":"All numbers are positive, so grow the window to the right and shrink from the left while the sum is still at least the target. O(n).","t":"Minimum Size Subarray Sum","L":"sliding-window.html#p-209","d":"p-sliding-window-209"},{"id":"gt-p-sliding-window-209","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Minimum Size Subarray Sum?","a":"Return 0 if nothing qualifies.","x":"Shortest valid → shrink while valid.","t":"Minimum Size Subarray Sum","L":"sliding-window.html#p-209","d":"p-sliding-window-209"},{"id":"pf-p-sliding-window-643","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Best average over any k consecutive numbers.","a":"Sliding window","x":"Fixed-size sliding window: add the incoming number, subtract the outgoing one, track the best sum, divide by k at the end. O(n).","t":"Maximum Average Subarray I","L":"sliding-window.html#p-643","d":"p-sliding-window-643"},{"id":"gt-p-sliding-window-643","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Maximum Average Subarray I?","a":"Divide only once at the end.","x":"Fixed size → add one, drop one.","t":"Maximum Average Subarray I","L":"sliding-window.html#p-643","d":"p-sliding-window-643"},{"id":"pf-p-sliding-window-904","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Longest stretch containing at most 2 different values.","a":"Sliding window","x":"It's the longest subarray with at most two distinct values: a window with a count map, shrinking when a third type appears. O(n).","t":"Fruit Into Baskets","L":"sliding-window.html#p-904","d":"p-sliding-window-904"},{"id":"gt-p-sliding-window-904","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Fruit Into Baskets?","a":"Delete keys at zero, or len(count) lies.","x":"At most K distinct → window + dict.","t":"Fruit Into Baskets","L":"sliding-window.html#p-904","d":"p-sliding-window-904"},{"id":"pf-p-sliding-window-992","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Count subarrays with exactly k different values.","a":"Sliding window","x":"Exactly k equals at most k minus at most k minus one; each at-most count is a normal shrinking window. O(n).","t":"Subarrays with K Different Integers","L":"sliding-window.html#p-992","d":"p-sliding-window-992"},{"id":"gt-p-sliding-window-992","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Subarrays with K Different Integers?","a":"r − l + 1 counts all valid windows ending at r.","x":"Exactly K → difference of at-mosts.","t":"Subarrays with K Different Integers","L":"sliding-window.html#p-992","d":"p-sliding-window-992"},{"id":"pf-p-sliding-window-1004","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Longest run of 1s if you may flip at most k zeros.","a":"Sliding window","x":"Sliding window that holds at most k zeros; when it holds more, move left past a zero. O(n).","t":"Max Consecutive Ones III","L":"sliding-window.html#p-1004","d":"p-sliding-window-1004"},{"id":"gt-p-sliding-window-1004","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Max Consecutive Ones III?","a":"It’s the same as “longest with at most k zeros”.","x":"At most K → window.","t":"Max Consecutive Ones III","L":"sliding-window.html#p-1004","d":"p-sliding-window-1004"},{"id":"pf-p-sliding-window-1423","y":"pattern","tr":"dsa","s":"Sliding Window","q":"Take exactly k cards from the two ends. Max total?","a":"Sliding window","x":"Taking k from the ends leaves a contiguous middle of n minus k; minimise that middle with a fixed window, or slide the split between left and right. O(n).","t":"Maximum Points You Can Obtain from Cards","L":"sliding-window.html#p-1423","d":"p-sliding-window-1423"},{"id":"gt-p-sliding-window-1423","y":"gotcha","tr":"dsa","s":"Sliding Window","q":"What's the classic trap in Maximum Points You Can Obtain from Cards?","a":"If k = n, the window is empty: answer is the total.","x":"Both ends → complement window.","t":"Maximum Points You Can Obtain from Cards","L":"sliding-window.html#p-1423","d":"p-sliding-window-1423"},{"id":"pf-p-stack-20","y":"pattern","tr":"dsa","s":"Stack","q":"Is every bracket closed by the right type, in the right order?","a":"Stack","x":"Push openers on a stack; on a closer, the top must be its matching opener, else invalid; valid if the stack is empty at the end. O(n).","t":"Valid Parentheses","L":"stack.html#p-20","d":"p-stack-20"},{"id":"gt-p-stack-20","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Valid Parentheses?","a":"A closer on an empty stack is invalid.","x":"Nesting → stack.","t":"Valid Parentheses","L":"stack.html#p-20","d":"p-stack-20"},{"id":"pf-p-stack-155","y":"pattern","tr":"dsa","s":"Stack","q":"A stack that can also report its minimum in O(1).","a":"Design a data structure","x":"Store each element alongside the minimum at that moment, or keep a second stack of minimums; getMin reads the top. All O(1).","t":"Min Stack","L":"stack.html#p-155","d":"p-stack-155"},{"id":"gt-p-stack-155","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Min Stack?","a":"A single min variable breaks after popping the min.","x":"O(1) min with pops → store running min per frame.","t":"Min Stack","L":"stack.html#p-155","d":"p-stack-155"},{"id":"pf-p-stack-150","y":"pattern","tr":"dsa","s":"Stack","q":"Compute an expression written like '2 1 + 3 *'.","a":"Stack","x":"Push numbers on a stack; for an operator, pop two, apply it in the right order, push the result. O(n).","t":"Evaluate Reverse Polish Notation","L":"stack.html#p-150","d":"p-stack-150"},{"id":"gt-p-stack-150","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Evaluate Reverse Polish Notation?","a":"Python’s // floors negatives; use int(a / b).","x":"Postfix → operand stack.","t":"Evaluate Reverse Polish Notation","L":"stack.html#p-150","d":"p-stack-150"},{"id":"pf-p-stack-394","y":"pattern","tr":"dsa","s":"Stack","q":"Expand '3[a2[c]]' into 'accaccacc'.","a":"Stack","x":"A stack of contexts: on open bracket push the current string and repeat count; on close pop and set current to previous plus count times current. O(output).","t":"Decode String","L":"stack.html#p-394","d":"p-stack-394"},{"id":"pf-p-stack-71","y":"pattern","tr":"dsa","s":"Stack","q":"Turn a Unix path like '/a/./b/../../c/' into '/c'.","a":"Stack","x":"Split on slashes and use a stack of folder names: skip empty and dot, pop on double dot, push anything else, then join. O(n).","t":"Simplify Path","L":"stack.html#p-71","d":"p-stack-71"},{"id":"gt-p-stack-71","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Simplify Path?","a":"“..” at root does nothing.","x":"Cancel the last → stack.","t":"Simplify Path","L":"stack.html#p-71","d":"p-stack-71"},{"id":"pf-p-stack-844","y":"pattern","tr":"dsa","s":"Stack","q":"Do two strings match after applying '#' as backspace?","a":"Two pointers","x":"Walk both strings from the end with skip counters, comparing the next visible characters. O(n) time, O(1) space; a stack works too with O(n) space.","t":"Backspace String Compare","L":"stack.html#p-844","d":"p-stack-844"},{"id":"gt-p-stack-844","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Backspace String Compare?","a":"O(1) space version: walk both from the end counting skips.","x":"Undo → stack.","t":"Backspace String Compare","L":"stack.html#p-844","d":"p-stack-844"},{"id":"pf-p-stack-739","y":"pattern","tr":"dsa","s":"Stack","q":"For each day, how many days until a warmer one?","a":"Monotonic stack","x":"A monotonic stack of indices still waiting for a warmer day; when a warmer day comes, pop and record the distance. O(n).","t":"Daily Temperatures","L":"stack.html#p-739","d":"p-stack-739"},{"id":"gt-p-stack-739","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Daily Temperatures?","a":"Store indexes, not temperatures.","x":"Next greater → monotonic stack.","t":"Daily Temperatures","L":"stack.html#p-739","d":"p-stack-739"},{"id":"pf-p-stack-496","y":"pattern","tr":"dsa","s":"Stack","q":"For each number in nums1, the next bigger number to its right in nums2.","a":"Monotonic stack","x":"Precompute next greater for every value in nums2 with a decreasing stack into a hash map, then look up each nums1 value. O(n plus m).","t":"Next Greater Element I","L":"stack.html#p-496","d":"p-stack-496"},{"id":"gt-p-stack-496","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Next Greater Element I?","a":"Values are unique, so a dict by value works.","x":"Next greater → monotonic stack + dict.","t":"Next Greater Element I","L":"stack.html#p-496","d":"p-stack-496"},{"id":"pf-p-stack-503","y":"pattern","tr":"dsa","s":"Stack","q":"Next greater element when the array wraps around.","a":"Monotonic stack","x":"Run the monotonic stack over the array twice using index mod n, only pushing indices in the first pass. O(n).","t":"Next Greater Element II","L":"stack.html#p-503","d":"p-stack-503"},{"id":"gt-p-stack-503","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Next Greater Element II?","a":"Pushing in the second pass creates duplicate waits.","x":"Circular → loop twice.","t":"Next Greater Element II","L":"stack.html#p-503","d":"p-stack-503"},{"id":"pf-p-stack-901","y":"pattern","tr":"dsa","s":"Stack","q":"For each new price, how many consecutive days back (including today) had price ≤ today?","a":"Monotonic stack","x":"A stack of price and span pairs: pop every pair with price at most today's, add their spans to today's, push today. Amortised O(1).","t":"Online Stock Span","L":"stack.html#p-901","d":"p-stack-901"},{"id":"gt-p-stack-901","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Online Stock Span?","a":"Absorbing spans keeps each price on the stack once.","x":"Span back to previous greater → monotonic stack.","t":"Online Stock Span","L":"stack.html#p-901","d":"p-stack-901"},{"id":"pf-p-stack-853","y":"pattern","tr":"dsa","s":"Stack","q":"Cars head to a target; faster cars catch up and merge into fleets. How many fleets arrive?","a":"Stack","x":"Sort by position closest to target first, compute each car's arrival time; a car arriving no later than the fleet ahead merges, otherwise it starts a new fleet. O(n log n).","t":"Car Fleet","L":"stack.html#p-853","d":"p-stack-853"},{"id":"gt-p-stack-853","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Car Fleet?","a":"Equal times merge (≤ doesn’t push).","x":"Catch up and merge → stack of survivors.","t":"Car Fleet","L":"stack.html#p-853","d":"p-stack-853"},{"id":"pf-p-stack-84","y":"pattern","tr":"dsa","s":"Stack","q":"Largest rectangle that fits under the histogram.","a":"Monotonic stack","x":"Keep an increasing stack of indices; when a shorter bar arrives, pop taller bars and compute their area using the new top as the left boundary. O(n).","t":"Largest Rectangle in Histogram","L":"stack.html#p-84","d":"p-stack-84"},{"id":"gt-p-stack-84","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Largest Rectangle in Histogram?","a":"Use ≥ when popping so equal heights are handled.","x":"How far a bar extends → increasing stack + sentinel.","t":"Largest Rectangle in Histogram","L":"stack.html#p-84","d":"p-stack-84"},{"id":"pf-p-stack-85","y":"pattern","tr":"dsa","s":"Stack","q":"Largest rectangle made only of 1s in a grid.","a":"Monotonic stack","x":"Treat each row as the floor of a histogram of consecutive ones above it, and run largest-rectangle-in-histogram on every row. O(rows times columns).","t":"Maximal Rectangle","L":"stack.html#p-85","d":"p-stack-85"},{"id":"gt-p-stack-85","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Maximal Rectangle?","a":"Reset height to 0 on a “0” cell.","x":"2-D rectangle → histogram per row.","t":"Maximal Rectangle","L":"stack.html#p-85","d":"p-stack-85"},{"id":"pf-p-stack-402","y":"pattern","tr":"dsa","s":"Stack","q":"Remove k digits to make the smallest number.","a":"Monotonic stack","x":"Greedy increasing stack: while the top is bigger than the current digit and removals remain, pop it; trim leftovers from the end and strip leading zeros. O(n).","t":"Remove K Digits","L":"stack.html#p-402","d":"p-stack-402"},{"id":"gt-p-stack-402","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Remove K Digits?","a":"Return &quot;0&quot; for an empty result.","x":"Smallest after removals → greedy increasing stack.","t":"Remove K Digits","L":"stack.html#p-402","d":"p-stack-402"},{"id":"pf-p-stack-735","y":"pattern","tr":"dsa","s":"Stack","q":"Asteroids move right (+) or left (−); colliding ones explode. What's left?","a":"Stack","x":"A stack of survivors: only a right-mover on top can collide with a new left-mover; resolve by size until it explodes or the stack settles. O(n).","t":"Asteroid Collision","L":"stack.html#p-735","d":"p-stack-735"},{"id":"gt-p-stack-735","y":"gotcha","tr":"dsa","s":"Stack","q":"What's the classic trap in Asteroid Collision?","a":"Only a negative meeting a positive top collides.","x":"Collisions with the latest → stack.","t":"Asteroid Collision","L":"stack.html#p-735","d":"p-stack-735"},{"id":"pf-p-binary-search-704","y":"pattern","tr":"dsa","s":"Binary Search","q":"Find target's index in a sorted array, or −1.","a":"Binary search","x":"Classic binary search: compare the middle with the target and discard half each time. O(log n).","t":"Binary Search","L":"binary-search.html#p-704","d":"p-binary-search-704"},{"id":"gt-p-binary-search-704","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Binary Search?","a":"Mixing inclusive hi with lo < hi skips the last element.","x":"Sorted + find → binary search.","t":"Binary Search","L":"binary-search.html#p-704","d":"p-binary-search-704"},{"id":"pf-p-binary-search-35","y":"pattern","tr":"dsa","s":"Binary Search","q":"Where is target, or where would it go to keep the array sorted?","a":"Binary search","x":"It's lower bound: the first index whose value is at least the target, found by binary search. O(log n).","t":"Search Insert Position","L":"binary-search.html#p-35","d":"p-binary-search-35"},{"id":"gt-p-binary-search-35","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Search Insert Position?","a":"hi must start at n so “insert at the end” is possible.","x":"Insert position → lower bound.","t":"Search Insert Position","L":"binary-search.html#p-35","d":"p-binary-search-35"},{"id":"pf-p-binary-search-34","y":"pattern","tr":"dsa","s":"Binary Search","q":"First and last index of target in a sorted array with repeats.","a":"Binary search","x":"Two binary searches: lower bound of target and lower bound of target plus one, minus one. O(log n).","t":"First and Last Position","L":"binary-search.html#p-34","d":"p-binary-search-34"},{"id":"gt-p-binary-search-34","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in First and Last Position?","a":"Expanding outward from a found index is O(n) worst case.","x":"First / last → two lower bounds.","t":"First and Last Position","L":"binary-search.html#p-34","d":"p-binary-search-34"},{"id":"pf-p-binary-search-74","y":"pattern","tr":"dsa","s":"Binary Search","q":"Each row is sorted and starts after the previous row ends. Is target in the matrix?","a":"Binary search","x":"Treat it as one sorted list of rows times columns; map index i to row i divided by columns and column i mod columns, and binary search. O(log of rows times columns).","t":"Search a 2D Matrix","L":"binary-search.html#p-74","d":"p-binary-search-74"},{"id":"gt-p-binary-search-74","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Search a 2D Matrix?","a":"Problem 240 (rows don’t continue) needs the staircase instead.","x":"Flattenable matrix → index arithmetic.","t":"Search a 2D Matrix","L":"binary-search.html#p-74","d":"p-binary-search-74"},{"id":"pf-p-binary-search-278","y":"pattern","tr":"dsa","s":"Binary Search","q":"Versions go good, good, …, bad, bad. Find the first bad one with few API calls.","a":"Binary search","x":"Binary search for the first true in a false-false-true-true sequence: if mid is bad, the answer is at mid or left; otherwise to the right. O(log n) calls.","t":"First Bad Version","L":"binary-search.html#p-278","d":"p-binary-search-278"},{"id":"gt-p-binary-search-278","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in First Bad Version?","a":"In other languages, mid = lo + (hi − lo) / 2 avoids overflow.","x":"First where it flips → lower bound.","t":"First Bad Version","L":"binary-search.html#p-278","d":"p-binary-search-278"},{"id":"pf-p-binary-search-153","y":"pattern","tr":"dsa","s":"Binary Search","q":"A sorted array was rotated. Find the smallest value.","a":"Binary search","x":"Compare mid with the right end: if nums of mid is greater than nums of high, the minimum is to the right; otherwise it's at mid or left. O(log n).","t":"Find Minimum in Rotated Sorted Array","L":"binary-search.html#p-153","d":"p-binary-search-153"},{"id":"pf-p-binary-search-33","y":"pattern","tr":"dsa","s":"Binary Search","q":"Find target in a rotated sorted array.","a":"Binary search","x":"At each mid, one half is sorted; check if the target lies within that half's range and keep it, otherwise search the other half. O(log n).","t":"Search in Rotated Sorted Array","L":"binary-search.html#p-33","d":"p-binary-search-33"},{"id":"gt-p-binary-search-33","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Search in Rotated Sorted Array?","a":"Use ≤ in nums[lo] ≤ nums[mid] for the lo == mid case.","x":"Rotated → find the sorted half.","t":"Search in Rotated Sorted Array","L":"binary-search.html#p-33","d":"p-binary-search-33"},{"id":"pf-p-binary-search-162","y":"pattern","tr":"dsa","s":"Binary Search","q":"Find any index that's bigger than both neighbours.","a":"Binary search","x":"If mid is smaller than mid plus one, we're on an uphill so a peak exists to the right; otherwise one exists at mid or left. O(log n).","t":"Find Peak Element","L":"binary-search.html#p-162","d":"p-binary-search-162"},{"id":"gt-p-binary-search-162","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Find Peak Element?","a":"Out-of-bounds neighbours count as −∞.","x":"Peak → walk uphill.","t":"Find Peak Element","L":"binary-search.html#p-162","d":"p-binary-search-162"},{"id":"pf-p-binary-search-540","y":"pattern","tr":"dsa","s":"Binary Search","q":"Every value appears twice, side by side, except one. Find it in O(log n).","a":"Binary search","x":"Before the single element, pairs start at even indices; after it, at odd. Binary search on an even mid and check whether its partner is next. O(log n).","t":"Single Element in a Sorted Array","L":"binary-search.html#p-540","d":"p-binary-search-540"},{"id":"gt-p-binary-search-540","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Single Element in a Sorted Array?","a":"Jump by 2 when the pair is intact.","x":"Pattern flips at the answer → binary search the flip.","t":"Single Element in a Sorted Array","L":"binary-search.html#p-540","d":"p-binary-search-540"},{"id":"pf-p-binary-search-875","y":"pattern","tr":"dsa","s":"Binary Search","q":"Slowest bananas-per-hour speed that finishes all piles within h hours.","a":"Binary search on the answer","x":"The answer is monotonic in speed, so binary search the speed from one to the biggest pile, checking total hours as the sum of ceilings. O(n log max).","t":"Koko Eating Bananas","L":"binary-search.html#p-875","d":"p-binary-search-875"},{"id":"gt-p-binary-search-875","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Koko Eating Bananas?","a":"Use ceil, or (p + k − 1) // k.","x":"Minimum speed that works → search the answer.","t":"Koko Eating Bananas","L":"binary-search.html#p-875","d":"p-binary-search-875"},{"id":"pf-p-binary-search-1011","y":"pattern","tr":"dsa","s":"Binary Search","q":"Smallest ship capacity that ships everything, in order, within D days.","a":"Binary search on the answer","x":"Binary search the capacity between the heaviest package and the total weight, greedily counting days for each candidate. O(n log sum).","t":"Capacity To Ship Packages Within D Days","L":"binary-search.html#p-1011","d":"p-binary-search-1011"},{"id":"gt-p-binary-search-1011","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Capacity To Ship Packages Within D Days?","a":"lo must be max(weights), or a single package can never fit.","x":"Minimum capacity → search the answer.","t":"Capacity To Ship Packages Within D Days","L":"binary-search.html#p-1011","d":"p-binary-search-1011"},{"id":"pf-p-binary-search-410","y":"pattern","tr":"dsa","s":"Binary Search","q":"Split into k contiguous parts so the biggest part's sum is as small as possible.","a":"Binary search on the answer","x":"Binary search the answer X and greedily check if we can split into at most k parts each at most X. O(n log sum).","t":"Split Array Largest Sum","L":"binary-search.html#p-410","d":"p-binary-search-410"},{"id":"gt-p-binary-search-410","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Split Array Largest Sum?","a":"Same code as 1011 with renamed variables.","x":"Minimize the max → binary search the answer.","t":"Split Array Largest Sum","L":"binary-search.html#p-410","d":"p-binary-search-410"},{"id":"pf-p-binary-search-69","y":"pattern","tr":"dsa","s":"Binary Search","q":"Integer square root, rounded down, without sqrt().","a":"Binary search","x":"Binary search for the largest m with m times m at most x. O(log x).","t":"Sqrt(x)","L":"binary-search.html#p-69","d":"p-binary-search-69"},{"id":"gt-p-binary-search-69","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Sqrt(x)?","a":"Rounding down here loops forever.","x":"Largest x that works → round mid up.","t":"Sqrt(x)","L":"binary-search.html#p-69","d":"p-binary-search-69"},{"id":"pf-p-binary-search-378","y":"pattern","tr":"dsa","s":"Binary Search","q":"Rows and columns are sorted. Find the kth smallest value.","a":"Binary search","x":"Binary search on the value range; for each mid, count cells at most mid by walking from the bottom-left corner, O(n), and narrow until low meets high. O(n log range).","t":"Kth Smallest Element in a Sorted Matrix","L":"binary-search.html#p-378","d":"p-binary-search-378"},{"id":"gt-p-binary-search-378","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Kth Smallest Element in a Sorted Matrix?","a":"A heap solution is O(k log n); both are worth knowing.","x":"Kth smallest in structure → binary search the value.","t":"Kth Smallest Element in a Sorted Matrix","L":"binary-search.html#p-378","d":"p-binary-search-378"},{"id":"pf-p-binary-search-4","y":"pattern","tr":"dsa","s":"Binary Search","q":"Median of two sorted arrays combined, in O(log(min(m, n))).","a":"Binary search","x":"Binary search a cut in the smaller array so the left halves hold half the elements and every left value is at most every right value; the median comes from the border values. O(log of min of m and n).","t":"Median of Two Sorted Arrays","L":"binary-search.html#p-4","d":"p-binary-search-4"},{"id":"pf-p-binary-search-981","y":"pattern","tr":"dsa","s":"Binary Search","q":"Store values with timestamps; get(key, t) returns the value set at the latest time ≤ t.","a":"Binary search","x":"A hash map from key to a list of timestamp and value pairs; timestamps arrive increasing, so get binary searches for the last timestamp at most t. O(log n) per get.","t":"Time Based Key-Value Store","L":"binary-search.html#p-981","d":"p-binary-search-981"},{"id":"gt-p-binary-search-981","y":"gotcha","tr":"dsa","s":"Binary Search","q":"What's the classic trap in Time Based Key-Value Store?","a":"Timestamps are strictly increasing per key, so append keeps order.","x":"Latest ≤ t in sorted data → bisect.","t":"Time Based Key-Value Store","L":"binary-search.html#p-981","d":"p-binary-search-981"},{"id":"pf-p-linked-list-206","y":"pattern","tr":"dsa","s":"Linked List","q":"Make the list point backwards and return the new head.","a":"Linked-list pointer rewiring","x":"Walk once with prev and current: save next, point current back to prev, then step both forward. O(n) time, O(1) space.","t":"Reverse Linked List","L":"linked-list.html#p-206","d":"p-linked-list-206"},{"id":"gt-p-linked-list-206","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Reverse Linked List?","a":"Returning head instead of prev returns the old head, now the tail.","x":"Reverse → save, rewire, step.","t":"Reverse Linked List","L":"linked-list.html#p-206","d":"p-linked-list-206"},{"id":"pf-p-linked-list-21","y":"pattern","tr":"dsa","s":"Linked List","q":"Merge two sorted lists into one sorted list.","a":"Linked-list pointer rewiring","x":"A dummy head and a tail pointer; always attach the smaller front node, then append whatever remains. O(m plus n), O(1).","t":"Merge Two Sorted Lists","L":"linked-list.html#p-21","d":"p-linked-list-21"},{"id":"gt-p-linked-list-21","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Merge Two Sorted Lists?","a":"The leftover list is already sorted: attach it in one step.","x":"Build a list → dummy + tail.","t":"Merge Two Sorted Lists","L":"linked-list.html#p-21","d":"p-linked-list-21"},{"id":"pf-p-linked-list-141","y":"pattern","tr":"dsa","s":"Linked List","q":"Does the list loop back on itself?","a":"Fast & slow pointers","x":"Floyd's tortoise and hare: slow moves one step, fast moves two; they meet only if there's a cycle. O(n), O(1).","t":"Linked List Cycle","L":"linked-list.html#p-141","d":"p-linked-list-141"},{"id":"gt-p-linked-list-141","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Linked List Cycle?","a":"Check fast and fast.next before stepping.","x":"Cycle with O(1) space → Floyd.","t":"Linked List Cycle","L":"linked-list.html#p-141","d":"p-linked-list-141"},{"id":"pf-p-linked-list-142","y":"pattern","tr":"dsa","s":"Linked List","q":"Where does the cycle start?","a":"Fast & slow pointers","x":"Run Floyd until they meet, then move one pointer from the head and one from the meeting point one step at a time; they meet at the cycle start.","t":"Linked List Cycle II","L":"linked-list.html#p-142","d":"p-linked-list-142"},{"id":"gt-p-linked-list-142","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Linked List Cycle II?","a":"Compare nodes with “is”, not values.","x":"Cycle entrance → restart from head.","t":"Linked List Cycle II","L":"linked-list.html#p-142","d":"p-linked-list-142"},{"id":"pf-p-linked-list-876","y":"pattern","tr":"dsa","s":"Linked List","q":"Return the middle node (the second one if there are two).","a":"Fast & slow pointers","x":"Fast moves two steps and slow one; when fast reaches the end, slow is at the middle. One pass, O(n).","t":"Middle of the Linked List","L":"linked-list.html#p-876","d":"p-linked-list-876"},{"id":"gt-p-linked-list-876","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Middle of the Linked List?","a":"Start fast at head.next for the first middle.","x":"Middle → fast and slow.","t":"Middle of the Linked List","L":"linked-list.html#p-876","d":"p-linked-list-876"},{"id":"pf-p-linked-list-19","y":"pattern","tr":"dsa","s":"Linked List","q":"Delete the nth node from the end in one pass.","a":"Two pointers","x":"Use a dummy, move a lead pointer n steps ahead, then move both until the lead hits the end; the trailing pointer is just before the node to remove. O(n).","t":"Remove Nth Node From End","L":"linked-list.html#p-19","d":"p-linked-list-19"},{"id":"gt-p-linked-list-19","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Remove Nth Node From End?","a":"Without a dummy, removing the head crashes.","x":"Nth from end → fixed gap.","t":"Remove Nth Node From End","L":"linked-list.html#p-19","d":"p-linked-list-19"},{"id":"pf-p-linked-list-143","y":"pattern","tr":"dsa","s":"Linked List","q":"Reorder to first, last, second, second-last, … in place.","a":"Linked-list pointer rewiring","x":"Three moves: find the middle with fast and slow, reverse the second half, then weave the two halves together. O(n), O(1).","t":"Reorder List","L":"linked-list.html#p-143","d":"p-linked-list-143"},{"id":"gt-p-linked-list-143","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Reorder List?","a":"Cut the first half (slow.next = None) or you create a cycle.","x":"Pull from the end → middle + reverse.","t":"Reorder List","L":"linked-list.html#p-143","d":"p-linked-list-143"},{"id":"pf-p-linked-list-234","y":"pattern","tr":"dsa","s":"Linked List","q":"Is the list a palindrome, using O(1) extra space?","a":"Fast & slow pointers","x":"Find the middle with fast and slow, reverse the second half, compare it with the first half, and optionally restore it. O(n), O(1).","t":"Palindrome Linked List","L":"linked-list.html#p-234","d":"p-linked-list-234"},{"id":"gt-p-linked-list-234","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Palindrome Linked List?","a":"Mention that it modifies the input; restore it if asked.","x":"Compare with the end → reverse the back half.","t":"Palindrome Linked List","L":"linked-list.html#p-234","d":"p-linked-list-234"},{"id":"pf-p-linked-list-2","y":"pattern","tr":"dsa","s":"Linked List","q":"Digits are stored in reverse. Add the two numbers and return a list.","a":"Linked-list pointer rewiring","x":"Grade-school addition: walk both lists with a carry, create a node for each digit, and add a final node if a carry remains. O(max of m and n).","t":"Add Two Numbers","L":"linked-list.html#p-2","d":"p-linked-list-2"},{"id":"gt-p-linked-list-2","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Add Two Numbers?","a":"Forgetting “or carry” drops the last digit of 5 + 5.","x":"Digit lists → carry loop with dummy.","t":"Add Two Numbers","L":"linked-list.html#p-2","d":"p-linked-list-2"},{"id":"pf-p-linked-list-138","y":"pattern","tr":"dsa","s":"Linked List","q":"Deep copy a list where nodes also have a random pointer.","a":"Hash map / set","x":"A hash map from old node to new node: first pass creates copies, second pass wires next and random through the map. O(n).","t":"Copy List with Random Pointer","L":"linked-list.html#p-138","d":"p-linked-list-138"},{"id":"gt-p-linked-list-138","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Copy List with Random Pointer?","a":"Seed the dict with None → None.","x":"Deep copy with cross links → dict, two passes.","t":"Copy List with Random Pointer","L":"linked-list.html#p-138","d":"p-linked-list-138"},{"id":"pf-p-linked-list-160","y":"pattern","tr":"dsa","s":"Linked List","q":"At which node do two lists merge, if any?","a":"Two pointers","x":"Two pointers; when one reaches the end, restart it at the other list's head; after equal distances they meet at the intersection or both reach null. O(m plus n), O(1).","t":"Intersection of Two Linked Lists","L":"linked-list.html#p-160","d":"p-linked-list-160"},{"id":"gt-p-linked-list-160","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Intersection of Two Linked Lists?","a":"Compare node identity, not value.","x":"Different lengths → switch tracks.","t":"Intersection of Two Linked Lists","L":"linked-list.html#p-160","d":"p-linked-list-160"},{"id":"pf-p-linked-list-61","y":"pattern","tr":"dsa","s":"Linked List","q":"Rotate the list to the right by k places.","a":"Linked-list pointer rewiring","x":"Find the length and tail, connect tail to head to form a ring, then break it after length minus k mod length steps. O(n).","t":"Rotate List","L":"linked-list.html#p-61","d":"p-linked-list-61"},{"id":"gt-p-linked-list-61","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Rotate List?","a":"k can exceed n: take k % n.","x":"Rotation → ring, then cut.","t":"Rotate List","L":"linked-list.html#p-61","d":"p-linked-list-61"},{"id":"pf-p-linked-list-328","y":"pattern","tr":"dsa","s":"Linked List","q":"Group nodes at odd positions first, then even positions, keeping relative order.","a":"Linked-list pointer rewiring","x":"Two chains, odd and even, relinked as I walk; save the even head and attach it to the odd tail at the end. O(n), O(1).","t":"Odd Even Linked List","L":"linked-list.html#p-328","d":"p-linked-list-328"},{"id":"pf-p-linked-list-148","y":"pattern","tr":"dsa","s":"Linked List","q":"Sort a linked list in O(n log n).","a":"Divide & conquer","x":"Merge sort: split at the middle with fast and slow, sort both halves recursively, and merge. O(n log n); bottom-up gets O(1) space.","t":"Sort List","L":"linked-list.html#p-148","d":"p-linked-list-148"},{"id":"gt-p-linked-list-148","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Sort List?","a":"Start fast at head.next, or a two-node list never splits.","x":"Sort a list → merge sort.","t":"Sort List","L":"linked-list.html#p-148","d":"p-linked-list-148"},{"id":"pf-p-linked-list-23","y":"pattern","tr":"dsa","s":"Linked List","q":"Merge k sorted lists into one.","a":"K-way merge","x":"A min-heap of the k current heads: pop the smallest, append it, push its next. O(N log k).","t":"Merge k Sorted Lists","L":"linked-list.html#p-23","d":"p-linked-list-23"},{"id":"gt-p-linked-list-23","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Merge k Sorted Lists?","a":"The index i breaks ties; nodes themselves can’t be compared.","x":"k sorted streams → heap.","t":"Merge k Sorted Lists","L":"linked-list.html#p-23","d":"p-linked-list-23"},{"id":"pf-p-linked-list-25","y":"pattern","tr":"dsa","s":"Linked List","q":"Reverse every block of k nodes; leave a short tail as is.","a":"Linked-list pointer rewiring","x":"Dummy head; for each block check k nodes exist, reverse them, and reconnect the previous group's tail to the new head. O(n), O(1).","t":"Reverse Nodes in k-Group","L":"linked-list.html#p-25","d":"p-linked-list-25"},{"id":"gt-p-linked-list-25","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in Reverse Nodes in k-Group?","a":"Leave a final short group as it is.","x":"Group reversal → dummy + per-group reverse.","t":"Reverse Nodes in k-Group","L":"linked-list.html#p-25","d":"p-linked-list-25"},{"id":"pf-p-linked-list-146","y":"pattern","tr":"dsa","s":"Linked List","q":"A cache with get/put in O(1) that evicts the least recently used key.","a":"Design a data structure","x":"A hash map from key to node plus a doubly linked list ordered by recency; move nodes to the front on use and evict from the tail. All O(1).","t":"LRU Cache","L":"linked-list.html#p-146","d":"p-linked-list-146"},{"id":"gt-p-linked-list-146","y":"gotcha","tr":"dsa","s":"Linked List","q":"What's the classic trap in LRU Cache?","a":"Store the key in each node so you can delete it from the dict on eviction.","x":"LRU → dict + doubly linked list.","t":"LRU Cache","L":"linked-list.html#p-146","d":"p-linked-list-146"},{"id":"pf-p-recursion-50","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Compute xⁿ faster than n multiplications (n may be negative).","a":"Divide & conquer","x":"Fast exponentiation: compute x to the n over two once and square it, multiplying by x when n is odd. O(log n).","t":"Pow(x, n)","L":"recursion.html#p-50","d":"p-recursion-50"},{"id":"gt-p-recursion-50","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Pow(x, n)?","a":"Writing my_pow(x, n // 2) * my_pow(x, n // 2) makes two calls per level and drags you back to O(n). Store it in a variable.","x":"Halve the input and call once → O(log n).","t":"Pow(x, n)","L":"recursion.html#p-50","d":"p-recursion-50"},{"id":"pf-p-recursion-24","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Swap every two adjacent nodes by relinking, not by changing values.","a":"Linked-list pointer rewiring","x":"Swap the first pair and hang the recursively swapped rest after it; iteratively, use a dummy and relink three pointers per pair. O(n).","t":"Swap Nodes in Pairs","L":"recursion.html#p-24","d":"p-recursion-24"},{"id":"gt-p-recursion-24","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Swap Nodes in Pairs?","a":"Grab second.next before you overwrite pointers, or you lose the rest of the list.","x":"Handle one chunk, trust the call for the rest.","t":"Swap Nodes in Pairs","L":"recursion.html#p-24","d":"p-recursion-24"},{"id":"pf-p-recursion-classic","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Move n disks from one peg to another, one at a time, never putting a bigger disk on a smaller one.","a":"Divide & conquer","x":"To move n disks, move n minus one to the spare peg, move the biggest to the target, then move n minus one on top. That's two to the n minus one moves.","t":"Tower of Hanoi","L":"recursion.html#p-classic","d":"p-recursion-classic"},{"id":"gt-p-recursion-classic","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Tower of Hanoi?","a":"Trying to trace this by hand for n = 4 is exactly the habit the leap of faith is meant to break.","x":"Recursive call → trust it. This problem is impossible any other way.","t":"Tower of Hanoi","L":"recursion.html#p-classic","d":"p-recursion-classic"},{"id":"pf-p-recursion-104","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Return the number of nodes on the longest root-to-leaf path.","a":"Tree DFS / recursion","x":"Recursion: depth of a node is one plus the larger depth of its children, with null being zero. O(n) time, O(h) stack.","t":"Maximum Depth of Binary Tree","L":"recursion.html#p-104","d":"p-recursion-104"},{"id":"gt-p-recursion-104","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Maximum Depth of Binary Tree?","a":"Some versions count edges, not nodes. Read which one they want.","x":"Depends on children → postorder.","t":"Maximum Depth of Binary Tree","L":"recursion.html#p-104","d":"p-recursion-104"},{"id":"pf-p-recursion-226","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Mirror the tree: every left child becomes a right child and vice versa.","a":"Tree DFS / recursion","x":"At each node swap the two children and recurse into both; works in pre or postorder. O(n) time, O(h) stack.","t":"Invert Binary Tree","L":"recursion.html#p-226","d":"p-recursion-226"},{"id":"gt-p-recursion-226","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Invert Binary Tree?","a":"The one-line swap is safe because Python evaluates the whole right-hand side before assigning.","x":"Changing shape → reassign what the call returns.","t":"Invert Binary Tree","L":"recursion.html#p-226","d":"p-recursion-226"},{"id":"pf-p-recursion-101","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Is the left side a mirror image of the right side?","a":"Tree DFS / recursion","x":"Compare two trees at once: the left subtree's left with the right subtree's right, and its right with the other's left, plus equal values. O(n).","t":"Symmetric Tree","L":"recursion.html#p-101","d":"p-recursion-101"},{"id":"gt-p-recursion-101","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Symmetric Tree?","a":"Compare outside with outside. Comparing left with left checks “same tree”, a different problem.","x":"Two trees at once → recurse on a pair.","t":"Symmetric Tree","L":"recursion.html#p-101","d":"p-recursion-101"},{"id":"pf-p-recursion-543","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Longest path (in edges) between any two nodes, which may not pass through the root.","a":"Tree DFS / recursion","x":"Each call returns its height; at each node, the longest path bending there is left height plus right height, so I track the best globally. O(n).","t":"Diameter of Binary Tree","L":"recursion.html#p-543","d":"p-recursion-543"},{"id":"gt-p-recursion-543","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Diameter of Binary Tree?","a":"The longest path doesn't have to pass through the root. That's why you track the best at every node.","x":"Path bends through a node → return one side, track both.","t":"Diameter of Binary Tree","L":"recursion.html#p-543","d":"p-recursion-543"},{"id":"pf-p-recursion-113","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Return every root-to-leaf path whose values add up to the target.","a":"Backtracking","x":"DFS carrying the current path and remaining sum; at a leaf with remaining zero, copy the path; pop on the way back. O(n squared) worst case for copying.","t":"Path Sum II","L":"recursion.html#p-113","d":"p-recursion-113"},{"id":"gt-p-recursion-113","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Path Sum II?","a":"Pop the node on the way out even after recording, or the next path starts dirty.","x":"Info from above → parameter. Listing paths → choose / un-choose.","t":"Path Sum II","L":"recursion.html#p-113","d":"p-recursion-113"},{"id":"pf-p-recursion-236","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"The deepest node that has both p and q underneath it (a node can be its own descendant).","a":"Tree DFS / recursion","x":"Each call returns p or q if found below; if both sides return something, the current node is the answer, else pass up the non-null side. O(n).","t":"Lowest Common Ancestor","L":"recursion.html#p-236","d":"p-recursion-236"},{"id":"gt-p-recursion-236","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Lowest Common Ancestor?","a":"Returning the node when it equals p handles the case where p is an ancestor of q.","x":"“Find” → return the found node upward.","t":"Lowest Common Ancestor","L":"recursion.html#p-236","d":"p-recursion-236"},{"id":"pf-p-recursion-98","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Is this a valid binary search tree (left < node < right for whole subtrees)?","a":"Tree DFS / recursion","x":"Pass an allowed low and high range down: left children tighten the high bound, right children tighten the low bound. O(n).","t":"Validate Binary Search Tree","L":"recursion.html#p-98","d":"p-recursion-98"},{"id":"gt-p-recursion-98","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Validate Binary Search Tree?","a":"Checking only parent vs children fails on [5, 4, 6, null, null, 3, 7]: 3 sits in 5's right subtree.","x":"Needs bounds from ancestors → pass (low, high) down.","t":"Validate Binary Search Tree","L":"recursion.html#p-98","d":"p-recursion-98"},{"id":"pf-p-recursion-105","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Rebuild a tree from its preorder and inorder sequences.","a":"Divide & conquer","x":"The first preorder value is the root; its position in inorder splits the left and right subtrees, and a value-to-index map makes it O(n).","t":"Construct Tree from Preorder and Inorder","L":"recursion.html#p-105","d":"p-recursion-105"},{"id":"gt-p-recursion-105","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Construct Tree from Preorder and Inorder?","a":"Build the left subtree before the right, because preorder lists root, then all of left, then right.","x":"Preorder gives the roots, inorder gives the sides.","t":"Construct Tree from Preorder and Inorder","L":"recursion.html#p-105","d":"p-recursion-105"},{"id":"pf-p-recursion-124","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Biggest sum along any path (any start and end), values may be negative.","a":"Tree DFS / recursion","x":"At each node, the best path bending there is node plus max of zero and left gain plus max of zero and right gain; return node plus the better single side upward. O(n).","t":"Binary Tree Maximum Path Sum","L":"recursion.html#p-124","d":"p-recursion-124"},{"id":"gt-p-recursion-124","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Binary Tree Maximum Path Sum?","a":"Start best at −∞, not 0. An all-negative tree still has an answer.","x":"Path bends → hybrid. Negative branch → max with 0.","t":"Binary Tree Maximum Path Sum","L":"recursion.html#p-124","d":"p-recursion-124"},{"id":"pf-p-recursion-114","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Rearrange the tree into a right-only chain in preorder, in place.","a":"Tree DFS / recursion","x":"Process in reverse preorder, right then left then node, keeping a prev pointer; set node.right to prev and node.left to null. O(n).","t":"Flatten Binary Tree to Linked List","L":"recursion.html#p-114","d":"p-recursion-114"},{"id":"gt-p-recursion-114","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Flatten Binary Tree to Linked List?","a":"Doing it in normal preorder overwrites node.right before you visit it. Save it first, or go in reverse. Watch the lab above.","x":"Changing shape and need old pointers → process in reverse with a prev pointer.","t":"Flatten Binary Tree to Linked List","L":"recursion.html#p-114","d":"p-recursion-114"},{"id":"pf-p-recursion-199","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Return the values you’d see standing on the right of the tree, top to bottom.","a":"BFS","x":"Level-order traversal and take the last node of each level; or DFS right-first and record the first node at each new depth. O(n).","t":"Binary Tree Right Side View","L":"recursion.html#p-199","d":"p-recursion-199"},{"id":"gt-p-recursion-199","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Binary Tree Right Side View?","a":"It’s not just the right spine: a deep left subtree peeks out where the right side is shorter.","x":"“Level” wording → BFS, or DFS carrying depth.","t":"Binary Tree Right Side View","L":"recursion.html#p-199","d":"p-recursion-199"},{"id":"pf-p-recursion-103","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Level order, but alternate left-to-right and right-to-left each level.","a":"BFS","x":"Normal BFS one level per loop, reversing every other level's list, or filling with a deque from alternating ends. O(n).","t":"Binary Tree Zigzag Level Order","L":"recursion.html#p-103","d":"p-recursion-103"},{"id":"gt-p-recursion-103","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Binary Tree Zigzag Level Order?","a":"Don’t change the order you push children; only flip the finished level list.","x":"“Level by level” → queue, one level per loop.","t":"Binary Tree Zigzag Level Order","L":"recursion.html#p-103","d":"p-recursion-103"},{"id":"pf-p-recursion-230","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"The kth smallest value in a BST.","a":"Tree DFS / recursion","x":"Inorder traversal of a BST is sorted, so traverse inorder and stop at the kth node. O(h plus k).","t":"Kth Smallest Element in a BST","L":"recursion.html#p-230","d":"p-recursion-230"},{"id":"gt-p-recursion-230","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Kth Smallest Element in a BST?","a":"Collecting the whole inorder list works but wastes O(n). Stop early.","x":"BST + order → inorder is sorted.","t":"Kth Smallest Element in a BST","L":"recursion.html#p-230","d":"p-recursion-230"},{"id":"pf-p-recursion-235","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Lowest common ancestor when the tree is a BST.","a":"Tree DFS / recursion","x":"Use BST order: if both values are smaller go left, if both bigger go right, otherwise this node is the split point. O(h), O(1) iteratively.","t":"Lowest Common Ancestor of a BST","L":"recursion.html#p-235","d":"p-recursion-235"},{"id":"gt-p-recursion-235","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Lowest Common Ancestor of a BST?","a":"Using the general 236 solution works but ignores the BST and costs O(n).","x":"BST → walk one direction, O(h).","t":"Lowest Common Ancestor of a BST","L":"recursion.html#p-235","d":"p-recursion-235"},{"id":"pf-p-recursion-572","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Does root contain a subtree identical to sub?","a":"Tree DFS / recursion","x":"At every node of the main tree, run a same-tree check against the sub tree. O(m times n) worst case.","t":"Subtree of Another Tree","L":"recursion.html#p-572","d":"p-recursion-572"},{"id":"gt-p-recursion-572","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Subtree of Another Tree?","a":"a is b is True only when both are None, a compact base case for the pair.","x":"Two trees → pair recursion inside a normal recursion.","t":"Subtree of Another Tree","L":"recursion.html#p-572","d":"p-recursion-572"},{"id":"pf-p-recursion-297","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Turn a tree into a string and back.","a":"Design a data structure","x":"Preorder with a null marker makes the shape unambiguous; deserialize by reading tokens in the same order recursively. O(n) both ways.","t":"Serialize and Deserialize Binary Tree","L":"recursion.html#p-297","d":"p-recursion-297"},{"id":"gt-p-recursion-297","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Serialize and Deserialize Binary Tree?","a":"Deserialize must read in exactly the order serialize wrote. One shared iterator makes that automatic.","x":"Rebuild a tree → recurse in the same order it was written.","t":"Serialize and Deserialize Binary Tree","L":"recursion.html#p-297","d":"p-recursion-297"},{"id":"pf-p-recursion-437","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Count downward paths (any start, any end) that add up to target.","a":"Prefix sums","x":"Prefix sums along the current root path in a hash map; paths ending here equal the count of current minus target. Add on the way down, remove on the way back. O(n).","t":"Path Sum III","L":"recursion.html#p-437","d":"p-recursion-437"},{"id":"gt-p-recursion-437","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Path Sum III?","a":"Seed seen[0] = 1, or paths that start at the root are missed.","x":"Path sums anywhere → prefix sums + hashmap, added in, removed out.","t":"Path Sum III","L":"recursion.html#p-437","d":"p-recursion-437"},{"id":"pf-p-recursion-863","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Return all values exactly k edges away from a target node.","a":"BFS","x":"Trees only point down, so first record parent pointers, then BFS outward from the target like an undirected graph, k levels. O(n).","t":"All Nodes Distance K in Binary Tree","L":"recursion.html#p-863","d":"p-recursion-863"},{"id":"gt-p-recursion-863","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in All Nodes Distance K in Binary Tree?","a":"Use a seen set, or you’ll bounce child → parent → child forever.","x":"Need to go upward → parent map, then BFS.","t":"All Nodes Distance K in Binary Tree","L":"recursion.html#p-863","d":"p-recursion-863"},{"id":"pf-p-recursion-108","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Build a height-balanced BST from a sorted array.","a":"Divide & conquer","x":"The middle element becomes the root; recurse on the left half for the left subtree and the right half for the right subtree. O(n).","t":"Convert Sorted Array to BST","L":"recursion.html#p-108","d":"p-recursion-108"},{"id":"gt-p-recursion-108","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Convert Sorted Array to BST?","a":"Pass indexes, not slices, to avoid O(n log n) copying.","x":"Build a tree → choose a root, recurse on the two sides.","t":"Convert Sorted Array to BST","L":"recursion.html#p-108","d":"p-recursion-108"},{"id":"pf-p-recursion-450","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Delete a key from a BST and return the (possibly new) root.","a":"Tree DFS / recursion","x":"Find it by BST order; with no or one child, return the other child; with two children, copy the smallest value from the right subtree and delete that node there. O(h).","t":"Delete Node in a BST","L":"recursion.html#p-450","d":"p-recursion-450"},{"id":"gt-p-recursion-450","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Delete Node in a BST?","a":"The reassign pattern means deleting the root needs no special case.","x":"Changing shape → root.left = f(root.left), return root.","t":"Delete Node in a BST","L":"recursion.html#p-450","d":"p-recursion-450"},{"id":"pf-p-recursion-337","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Houses form a tree; you can't rob a node and its child. Max loot?","a":"1-D dynamic programming","x":"Each node returns two numbers, the best if robbed and the best if skipped; robbed is value plus children skipped, skipped is the sum of each child's max. O(n).","t":"House Robber III","L":"recursion.html#p-337","d":"p-recursion-337"},{"id":"gt-p-recursion-337","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in House Robber III?","a":"Memoizing on nodes also works, but the tuple version is cleaner and needs no cache.","x":"Two states per node → return a tuple.","t":"House Robber III","L":"recursion.html#p-337","d":"p-recursion-337"},{"id":"pf-p-recursion-129","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Each root-to-leaf path spells a number (1 → 2 → 3 is 123). Sum them all.","a":"Tree DFS / recursion","x":"Carry the number so far down the tree, current times ten plus value, and add it at each leaf. O(n).","t":"Sum Root to Leaf Numbers","L":"recursion.html#p-129","d":"p-recursion-129"},{"id":"gt-p-recursion-129","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Sum Root to Leaf Numbers?","a":"Check “is leaf” before recursing, or each leaf’s number is counted zero times or twice.","x":"Info from above → parameter.","t":"Sum Root to Leaf Numbers","L":"recursion.html#p-129","d":"p-recursion-129"},{"id":"pf-p-recursion-968","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Fewest cameras so every node is watched (a camera covers parent, itself, children).","a":"Greedy","x":"Greedy from the leaves up: each node returns a state, needs cover, has camera or covered; place a camera at any node with an uncovered child. O(n).","t":"Binary Tree Cameras","L":"recursion.html#p-968","d":"p-recursion-968"},{"id":"gt-p-recursion-968","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Binary Tree Cameras?","a":"After the DFS, the root itself may still need a camera. Add one if it returned 0.","x":"Bottom-up with states → greedy from the leaves.","t":"Binary Tree Cameras","L":"recursion.html#p-968","d":"p-recursion-968"},{"id":"pf-p-recursion-77","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"All ways to choose k numbers from 1..n.","a":"Backtracking","x":"Backtracking with a start index so each combination is built in increasing order once; prune when too few numbers remain. O(k times n choose k).","t":"Combinations","L":"recursion.html#p-77","d":"p-recursion-77"},{"id":"gt-p-recursion-77","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Combinations?","a":"The prune n - i + 1 < k - len(path) turns a slow solution into a fast one on big n.","x":"Order doesn’t matter → start index. Too few left → break.","t":"Combinations","L":"recursion.html#p-77","d":"p-recursion-77"},{"id":"pf-p-recursion-40","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Combinations summing to target, each candidate used once, no duplicate combinations.","a":"Backtracking","x":"Sort, backtrack with a start index and recurse with i plus one, skipping a value equal to its left neighbour at the same depth. Break when the value exceeds what's left.","t":"Combination Sum II","L":"recursion.html#p-40","d":"p-recursion-40"},{"id":"gt-p-recursion-40","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Combination Sum II?","a":"It's Combination Sum + Subsets II: recurse with i + 1 and skip i > start duplicates.","x":"Duplicates + once each → sort, skip twins, recurse i + 1.","t":"Combination Sum II","L":"recursion.html#p-40","d":"p-recursion-40"},{"id":"pf-p-recursion-47","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"All distinct orderings of a list that has duplicates.","a":"Backtracking","x":"Sort, track used with a boolean array, and skip a number if it equals the previous one and the previous isn't used. O(n times n factorial).","t":"Permutations II","L":"recursion.html#p-47","d":"p-recursion-47"},{"id":"gt-p-recursion-47","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Permutations II?","a":"not used[i-1] means the earlier twin was already tried at this level and released. Using this one now repeats that branch.","x":"Order matters + duplicates → used[] and skip a twin whose earlier copy is unused.","t":"Permutations II","L":"recursion.html#p-47","d":"p-recursion-47"},{"id":"pf-p-recursion-17","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Digits 2–9 map to letters like a phone keypad. Return every possible string.","a":"Backtracking","x":"One recursion level per digit, branching over that digit's letters, appending when the string is complete. O(4 to the n times n).","t":"Letter Combinations of a Phone Number","L":"recursion.html#p-17","d":"p-recursion-17"},{"id":"gt-p-recursion-17","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Letter Combinations of a Phone Number?","a":"Empty input returns [], not [&quot;&quot;].","x":"One slot per position → index i, loop that slot’s options.","t":"Letter Combinations of a Phone Number","L":"recursion.html#p-17","d":"p-recursion-17"},{"id":"pf-p-recursion-131","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Split a string so every piece is a palindrome. Return all splits.","a":"Backtracking","x":"Backtrack over cut positions: try each palindromic prefix from the current start and recurse on the rest; precompute a palindrome table to speed checks. O(n times 2 to the n).","t":"Palindrome Partitioning","L":"recursion.html#p-131","d":"p-recursion-131"},{"id":"gt-p-recursion-131","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Palindrome Partitioning?","a":"Precompute a palindrome table with DP if the string is long; slicing and reversing every time is O(n) per check.","x":"Split a string → loop the end of the next piece.","t":"Palindrome Partitioning","L":"recursion.html#p-131","d":"p-recursion-131"},{"id":"pf-p-recursion-37","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Fill the Sudoku in place.","a":"Backtracking","x":"Backtracking: find an empty cell, try digits allowed by its row, column and box sets, recurse, and undo on failure; return true to stop once solved.","t":"Sudoku Solver","L":"recursion.html#p-37","d":"p-recursion-37"},{"id":"gt-p-recursion-37","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Sudoku Solver?","a":"Return True to stop at the first solution. Without it you'd undo the solved board on the way out.","x":"Placement under constraints → sets + return True to stop.","t":"Sudoku Solver","L":"recursion.html#p-37","d":"p-recursion-37"},{"id":"pf-p-recursion-784","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Return every string formed by changing each letter to lower or upper case.","a":"Backtracking","x":"Binary choice at each letter, one at each digit: recurse by index or iteratively double the list per letter. O(2 to the L times n).","t":"Letter Case Permutation","L":"recursion.html#p-784","d":"p-recursion-784"},{"id":"gt-p-recursion-784","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Letter Case Permutation?","a":"Digits have one choice, not two. A set avoids duplicates for non-letters.","x":"One slot per position → index i, loop that slot’s options.","t":"Letter Case Permutation","L":"recursion.html#p-784","d":"p-recursion-784"},{"id":"pf-p-recursion-494","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Number of ways to put + or − before each number to reach target.","a":"Knapsack DP","x":"It's a subset-sum count: positives sum to total plus target over two, so count subsets with that sum with a 1-D DP. O(n times sum).","t":"Target Sum","L":"recursion.html#p-494","d":"p-recursion-494"},{"id":"gt-p-recursion-494","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Target Sum?","a":"It asks “how many”, so states repeat. Plain backtracking is 2ⁿ; one decorator makes it polynomial.","x":"Count it → memo. List it → backtrack.","t":"Target Sum","L":"recursion.html#p-494","d":"p-recursion-494"},{"id":"pf-p-recursion-52","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"How many ways to place n queens with none attacking?","a":"Backtracking","x":"One queen per row; track used columns and both diagonals, row minus column and row plus column, in sets for O(1) checks. Backtrack row by row.","t":"N-Queens II","L":"recursion.html#p-52","d":"p-recursion-52"},{"id":"gt-p-recursion-52","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in N-Queens II?","a":"Return counts up the stack instead of storing boards. Less memory, same search.","x":"Constraint placement → sets for O(1) checks.","t":"N-Queens II","L":"recursion.html#p-52","d":"p-recursion-52"},{"id":"pf-p-recursion-698","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Can the numbers be split into k groups with equal sums?","a":"Backtracking","x":"Target is total over k; sort descending and fill buckets with backtracking, pruning when a value doesn't fit and skipping identical empty buckets.","t":"Partition to K Equal Sum Subsets","L":"recursion.html#p-698","d":"p-recursion-698"},{"id":"gt-p-recursion-698","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Partition to K Equal Sum Subsets?","a":"Sort descending so big numbers fail early. The same-sum-bucket skip removes symmetric duplicates. Matchsticks to Square (473) is this with k = 4.","x":"Prune before you grow; order choices so failures come early.","t":"Partition to K Equal Sum Subsets","L":"recursion.html#p-698","d":"p-recursion-698"},{"id":"pf-p-recursion-1219","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Walk from any cell with gold through non-empty cells, each once. Maximize gold collected.","a":"Backtracking","x":"DFS from every gold cell with temporary marking: set the cell to zero, explore four directions, restore it on the way back.","t":"Path with Maximum Gold","L":"recursion.html#p-1219","d":"p-recursion-1219"},{"id":"gt-p-recursion-1219","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Path with Maximum Gold?","a":"Mark by setting the cell to 0, and restore it after. It doubles as the visited set.","x":"Grid + use once → mark, explore 4, restore.","t":"Path with Maximum Gold","L":"recursion.html#p-1219","d":"p-recursion-1219"},{"id":"pf-p-recursion-980","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Count paths from start to end that walk over every empty square exactly once.","a":"Backtracking","x":"Grid backtracking that counts remaining empty squares; at the end square, count the path only if nothing remains. Mark and unmark as you go.","t":"Unique Paths III","L":"recursion.html#p-980","d":"p-recursion-980"},{"id":"gt-p-recursion-980","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Unique Paths III?","a":"Count the start square in empty, or every path is off by one.","x":"Grid + use once → mark, explore 4, restore.","t":"Unique Paths III","L":"recursion.html#p-980","d":"p-recursion-980"},{"id":"pf-p-recursion-212","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Find which listed words appear on the board.","a":"Trie","x":"Put all words in a trie and run one DFS from each cell, following trie children and stopping as soon as the path isn't a prefix. Remove found words to prune more.","t":"Word Search II","L":"recursion.html#p-212","d":"p-recursion-212"},{"id":"gt-p-recursion-212","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Word Search II?","a":"Running Word Search (79) once per word is too slow. One trie lets every word share the same DFS.","x":"Many words on one board → trie + grid backtracking.","t":"Word Search II","L":"recursion.html#p-212","d":"p-recursion-212"},{"id":"pf-p-recursion-282","y":"pattern","tr":"dsa","s":"Recursion & Backtracking","q":"Insert +, − or * between digits so the expression equals target. Return all expressions.","a":"Backtracking","x":"Backtrack over where each operand ends, tracking the running value and the last term; for times, undo the last term: value minus last plus last times x. O(4 to the n).","t":"Expression Add Operators","L":"recursion.html#p-282","d":"p-recursion-282"},{"id":"gt-p-recursion-282","y":"gotcha","tr":"dsa","s":"Recursion & Backtracking","q":"What's the classic trap in Expression Add Operators?","a":"For *, undo the last term and re-add it multiplied: value − last + last * x. Strings are immutable, so there’s no explicit un-choose.","x":"Split a string → loop the end of the next piece.","t":"Expression Add Operators","L":"recursion.html#p-282","d":"p-recursion-282"},{"id":"pf-p-heap-703","y":"pattern","tr":"dsa","s":"Heap","q":"After each added number, report the kth largest seen so far.","a":"Heap / top-k","x":"Keep a min-heap of the k largest values; on add, push and pop if the size exceeds k; the top is the answer. O(log k) per add.","t":"Kth Largest Element in a Stream","L":"heap.html#p-703","d":"p-heap-703"},{"id":"gt-p-heap-703","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Kth Largest Element in a Stream?","a":"Initial nums may be fewer than k.","x":"Kth largest → size-k min-heap.","t":"Kth Largest Element in a Stream","L":"heap.html#p-703","d":"p-heap-703"},{"id":"pf-p-heap-1046","y":"pattern","tr":"dsa","s":"Heap","q":"Repeatedly smash the two heaviest stones; return the last weight (or 0).","a":"Heap / top-k","x":"A max-heap gives the two heaviest each round; push the difference back if non-zero. O(n log n).","t":"Last Stone Weight","L":"heap.html#p-1046","d":"p-heap-1046"},{"id":"gt-p-heap-1046","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Last Stone Weight?","a":"Remember to negate back when reading.","x":"Repeatedly take the two biggest → max-heap.","t":"Last Stone Weight","L":"heap.html#p-1046","d":"p-heap-1046"},{"id":"pf-p-heap-973","y":"pattern","tr":"dsa","s":"Heap","q":"Return the k points nearest the origin.","a":"Heap / top-k","x":"A max-heap of size k keyed by squared distance; push each point and drop the farthest when the size exceeds k. O(n log k).","t":"K Closest Points to Origin","L":"heap.html#p-973","d":"p-heap-973"},{"id":"gt-p-heap-973","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in K Closest Points to Origin?","a":"Skip sqrt; it doesn’t change the order.","x":"k smallest → size-k max-heap.","t":"K Closest Points to Origin","L":"heap.html#p-973","d":"p-heap-973"},{"id":"pf-p-heap-215","y":"pattern","tr":"dsa","s":"Heap","q":"The kth largest number (not distinct).","a":"Heap / top-k","x":"A min-heap of size k gives O(n log k); quickselect gives average O(n).","t":"Kth Largest Element in an Array","L":"heap.html#p-215","d":"p-heap-215"},{"id":"gt-p-heap-215","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Kth Largest Element in an Array?","a":"Quickselect gives average O(n); mention it.","x":"Kth largest → size-k min-heap.","t":"Kth Largest Element in an Array","L":"heap.html#p-215","d":"p-heap-215"},{"id":"pf-p-heap-621","y":"pattern","tr":"dsa","s":"Heap","q":"Run tasks with at least n idle slots between the same task. Minimum time?","a":"Greedy","x":"The most frequent task sets the frame: max count minus one times n plus one, plus the number of tasks tied at max count; the answer is the max of that and the task total.","t":"Task Scheduler","L":"heap.html#p-621","d":"p-heap-621"},{"id":"gt-p-heap-621","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Task Scheduler?","a":"There’s also an O(T) counting formula: (maxf − 1) × (n + 1) + ties.","x":"Can’t repeat within n → heap + cooldown queue.","t":"Task Scheduler","L":"heap.html#p-621","d":"p-heap-621"},{"id":"pf-p-heap-767","y":"pattern","tr":"dsa","s":"Heap","q":"Rearrange so no two neighbours are the same letter.","a":"Heap / top-k","x":"Greedy with a max-heap of counts: always place the most frequent letter that isn't the previous one, holding the last used letter out for one step. O(n log 26).","t":"Reorganize String","L":"heap.html#p-767","d":"p-heap-767"},{"id":"gt-p-heap-767","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Reorganize String?","a":"Quick check: impossible if maxf > (n + 1) // 2.","x":"Can’t repeat → heap + hold out.","t":"Reorganize String","L":"heap.html#p-767","d":"p-heap-767"},{"id":"pf-p-heap-355","y":"pattern","tr":"dsa","s":"Heap","q":"Post, follow/unfollow, and fetch the 10 newest tweets from you and people you follow.","a":"K-way merge","x":"Store each user's tweets newest first with a global timestamp; the feed merges the newest from each followee with a max-heap, stopping after ten. O(F plus ten log F).","t":"Design Twitter","L":"heap.html#p-355","d":"p-heap-355"},{"id":"gt-p-heap-355","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Design Twitter?","a":"A user follows themselves for the feed.","x":"Latest across many sorted lists → merge k with a heap.","t":"Design Twitter","L":"heap.html#p-355","d":"p-heap-355"},{"id":"pf-p-heap-295","y":"pattern","tr":"dsa","s":"Heap","q":"Keep adding numbers; return the median any time.","a":"Two heaps","x":"Two heaps: a max-heap for the lower half and a min-heap for the upper half, kept balanced within one; the median comes from the tops. O(log n) add, O(1) median.","t":"Find Median from Data Stream","L":"heap.html#p-295","d":"p-heap-295"},{"id":"gt-p-heap-295","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Find Median from Data Stream?","a":"Always route through lo then hi to keep the order invariant.","x":"Running median → two heaps.","t":"Find Median from Data Stream","L":"heap.html#p-295","d":"p-heap-295"},{"id":"pf-p-heap-502","y":"pattern","tr":"dsa","s":"Heap","q":"Start with w capital; pick at most k projects (each needs capital, gives profit). Maximize capital.","a":"Heap / top-k","x":"Sort projects by capital; at each step unlock everything affordable into a max-heap of profit and take the best. O(n log n).","t":"IPO","L":"heap.html#p-502","d":"p-heap-502"},{"id":"gt-p-heap-502","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in IPO?","a":"Break when nothing is affordable.","x":"Unlock + best available → sort + heap.","t":"IPO","L":"heap.html#p-502","d":"p-heap-502"},{"id":"pf-p-heap-1642","y":"pattern","tr":"dsa","s":"Heap","q":"Climb buildings using bricks or ladders. How far can you get?","a":"Heap / top-k","x":"Use ladders on the biggest climbs: keep a min-heap of climbs; when it exceeds the ladder count, pay for the smallest with bricks; stop when bricks run out. O(n log L).","t":"Furthest Building You Can Reach","L":"heap.html#p-1642","d":"p-heap-1642"},{"id":"gt-p-heap-1642","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Furthest Building You Can Reach?","a":"Only positive climbs count.","x":"Save the best resource for the biggest needs → min-heap of size ladders.","t":"Furthest Building You Can Reach","L":"heap.html#p-1642","d":"p-heap-1642"},{"id":"pf-p-heap-253","y":"pattern","tr":"dsa","s":"Heap","q":"Minimum number of rooms so no meetings overlap in a room.","a":"Intervals: sort & sweep","x":"Sort by start and keep a min-heap of end times; if the earliest ending room is free, reuse it, otherwise add a room. The heap size is the answer. O(n log n).","t":"Meeting Rooms II","L":"heap.html#p-253","d":"p-heap-253"},{"id":"gt-p-heap-253","y":"gotcha","tr":"dsa","s":"Heap","q":"What's the classic trap in Meeting Rooms II?","a":"heapreplace pops and pushes in one step.","x":"Rooms in use → min-heap of end times.","t":"Meeting Rooms II","L":"heap.html#p-253","d":"p-heap-253"},{"id":"pf-p-trie-208","y":"pattern","tr":"dsa","s":"Trie","q":"Build a structure with insert, search(word) and startsWith(prefix).","a":"Trie","x":"Each node has children by character and an end-of-word flag; all three operations walk one node per character. O(L) each.","t":"Implement Trie (Prefix Tree)","L":"trie.html#p-208","d":"p-trie-208"},{"id":"gt-p-trie-208","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Implement Trie (Prefix Tree)?","a":"Forgetting the end flag makes search behave like startsWith.","x":"Prefix structure → trie node with end flag.","t":"Implement Trie (Prefix Tree)","L":"trie.html#p-208","d":"p-trie-208"},{"id":"pf-p-trie-211","y":"pattern","tr":"dsa","s":"Trie","q":"Like a trie, but search may contain '.' matching any letter.","a":"Trie","x":"A trie; search walks normally, and on a dot it tries every child with DFS. Insert is O(L); search is worst case all nodes at that depth.","t":"Design Add and Search Words","L":"trie.html#p-211","d":"p-trie-211"},{"id":"gt-p-trie-211","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Design Add and Search Words?","a":"Return node.end at the end of the pattern, not True.","x":"Wildcard → DFS all children.","t":"Design Add and Search Words","L":"trie.html#p-211","d":"p-trie-211"},{"id":"pf-p-trie-14","y":"pattern","tr":"dsa","s":"Trie","q":"Longest prefix shared by every string.","a":"Trie","x":"Vertical scan: compare character i across all strings until a mismatch or one ends. O(total characters).","t":"Longest Common Prefix","L":"trie.html#p-14","d":"p-trie-14"},{"id":"gt-p-trie-14","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Longest Common Prefix?","a":"Sorting and comparing the first and last strings is simpler; know both.","x":"Shared beginning → walk the single path.","t":"Longest Common Prefix","L":"trie.html#p-14","d":"p-trie-14"},{"id":"pf-p-trie-648","y":"pattern","tr":"dsa","s":"Trie","q":"Replace each word in a sentence with the shortest dictionary root it starts with.","a":"Trie","x":"Build a trie of roots; for each word, walk until you hit an end flag and replace with that prefix, or keep the word. O(total characters).","t":"Replace Words","L":"trie.html#p-648","d":"p-trie-648"},{"id":"gt-p-trie-648","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Replace Words?","a":"If no root matches, keep the word.","x":"Shortest root → first end flag.","t":"Replace Words","L":"trie.html#p-648","d":"p-trie-648"},{"id":"pf-p-trie-1268","y":"pattern","tr":"dsa","s":"Trie","q":"After each typed letter, suggest up to 3 products (alphabetical) with that prefix.","a":"Trie","x":"Sort the products; for each prefix, binary search the first match and take up to three that still match. Or a trie storing the top three per node.","t":"Search Suggestions System","L":"trie.html#p-1268","d":"p-trie-1268"},{"id":"gt-p-trie-1268","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Search Suggestions System?","a":"After the prefix breaks, keep appending [].","x":"Type-ahead → trie with top 3 per node.","t":"Search Suggestions System","L":"trie.html#p-1268","d":"p-trie-1268"},{"id":"pf-p-trie-421","y":"pattern","tr":"dsa","s":"Trie","q":"Max XOR of any two numbers in the list.","a":"Trie","x":"A binary trie of the numbers from the highest bit; for each number, greedily take the opposite bit at every level when it exists. O(32 n).","t":"Maximum XOR of Two Numbers","L":"trie.html#p-421","d":"p-trie-421"},{"id":"gt-p-trie-421","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Maximum XOR of Two Numbers?","a":"Insert high bit first, or greedy breaks.","x":"Max XOR → binary trie.","t":"Maximum XOR of Two Numbers","L":"trie.html#p-421","d":"p-trie-421"},{"id":"pf-p-trie-720","y":"pattern","tr":"dsa","s":"Trie","q":"Longest word whose every prefix is also a word (ties: smallest).","a":"Trie","x":"Build a trie and DFS only through nodes that are word ends, tracking the deepest; or sort words and keep a set of buildable words.","t":"Longest Word in Dictionary","L":"trie.html#p-720","d":"p-trie-720"},{"id":"gt-p-trie-720","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Longest Word in Dictionary?","a":"Handle the tie-break explicitly.","x":"Built letter by letter → walk only through end flags.","t":"Longest Word in Dictionary","L":"trie.html#p-720","d":"p-trie-720"},{"id":"pf-p-trie-677","y":"pattern","tr":"dsa","s":"Trie","q":"insert(key, value) and sum(prefix) of values for keys starting with prefix.","a":"Trie","x":"Each trie node stores the sum of values passing through it; on insert, add the delta from the old value along the path. Both O(L).","t":"Map Sum Pairs","L":"trie.html#p-677","d":"p-trie-677"},{"id":"gt-p-trie-677","y":"gotcha","tr":"dsa","s":"Trie","q":"What's the classic trap in Map Sum Pairs?","a":"Re-inserting a key must replace, not add.","x":"Prefix aggregate → sum on each node.","t":"Map Sum Pairs","L":"trie.html#p-677","d":"p-trie-677"},{"id":"pf-p-graphs-200","y":"pattern","tr":"dsa","s":"Graphs","q":"Count islands of “1” in a grid.","a":"Grid DFS / flood fill","x":"Scan the grid; each unvisited land cell starts a new island, and a DFS or BFS flood fill marks the whole island. O(rows times columns).","t":"Number of Islands","L":"graphs.html#p-200","d":"p-graphs-200"},{"id":"pf-p-graphs-695","y":"pattern","tr":"dsa","s":"Graphs","q":"Largest island area.","a":"Grid DFS / flood fill","x":"Same flood fill, but the DFS returns the number of cells it filled, and I track the maximum. O(rows times columns).","t":"Max Area of Island","L":"graphs.html#p-695","d":"p-graphs-695"},{"id":"gt-p-graphs-695","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Max Area of Island?","a":"max() needs default=0 for an all-water grid.","x":"Components with size → flood returns a count.","t":"Max Area of Island","L":"graphs.html#p-695","d":"p-graphs-695"},{"id":"pf-p-graphs-994","y":"pattern","tr":"dsa","s":"Graphs","q":"Each minute rot spreads to neighbours. Minutes until all oranges rot, or −1?","a":"BFS","x":"Multi-source BFS: queue all rotten oranges at once and expand level by level, where each level is one minute; at the end check if any fresh remain.","t":"Rotting Oranges","L":"graphs.html#p-994","d":"p-graphs-994"},{"id":"gt-p-graphs-994","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Rotting Oranges?","a":"If there are no fresh oranges, the answer is 0.","x":"Many sources → multi-source BFS.","t":"Rotting Oranges","L":"graphs.html#p-994","d":"p-graphs-994"},{"id":"pf-p-graphs-286","y":"pattern","tr":"dsa","s":"Graphs","q":"Fill each empty room with the distance to the nearest gate.","a":"BFS","x":"Multi-source BFS from all gates together; the first time a room is reached is its shortest distance. O(rows times columns).","t":"Walls and Gates","L":"graphs.html#p-286","d":"p-graphs-286"},{"id":"gt-p-graphs-286","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Walls and Gates?","a":"BFS from each gate separately is O((R·C)²).","x":"Nearest of many sources → multi-source BFS.","t":"Walls and Gates","L":"graphs.html#p-286","d":"p-graphs-286"},{"id":"pf-p-graphs-417","y":"pattern","tr":"dsa","s":"Graphs","q":"Which cells can drain water to both the Pacific (top/left) and Atlantic (bottom/right)?","a":"Grid DFS / flood fill","x":"Reverse the flow: flood from each ocean's border moving uphill to equal or higher cells, then return cells reached by both floods. O(rows times columns).","t":"Pacific Atlantic Water Flow","L":"graphs.html#p-417","d":"p-graphs-417"},{"id":"pf-p-graphs-130","y":"pattern","tr":"dsa","s":"Graphs","q":"Flip every 'O' region that doesn't touch the border into 'X'.","a":"Grid DFS / flood fill","x":"Mark safe cells by flooding from every border O, then flip the unmarked O's to X and restore the marked ones. O(rows times columns).","t":"Surrounded Regions","L":"graphs.html#p-130","d":"p-graphs-130"},{"id":"gt-p-graphs-130","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Surrounded Regions?","a":"Deep recursion on big boards: an explicit stack is safer.","x":"Not touching the border → flood from the border.","t":"Surrounded Regions","L":"graphs.html#p-130","d":"p-graphs-130"},{"id":"pf-p-graphs-133","y":"pattern","tr":"dsa","s":"Graphs","q":"Deep copy an undirected graph.","a":"Hash map / set","x":"DFS or BFS with a hash map from original node to its copy; the map prevents infinite loops on cycles and reuses copies. O(V plus E).","t":"Clone Graph","L":"graphs.html#p-133","d":"p-graphs-133"},{"id":"gt-p-graphs-133","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Clone Graph?","a":"Without the map, cycles recurse forever.","x":"Deep copy → dict + DFS.","t":"Clone Graph","L":"graphs.html#p-133","d":"p-graphs-133"},{"id":"pf-p-graphs-785","y":"pattern","tr":"dsa","s":"Graphs","q":"Can you colour nodes in two colours so every edge joins different colours?","a":"BFS","x":"Two-colour with BFS or DFS from every uncoloured node; if a neighbour already has my colour, there's an odd cycle, so it's not bipartite. O(V plus E).","t":"Is Graph Bipartite?","L":"graphs.html#p-785","d":"p-graphs-785"},{"id":"gt-p-graphs-785","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Is Graph Bipartite??","a":"The graph may be disconnected.","x":"Two groups → two-colouring.","t":"Is Graph Bipartite?","L":"graphs.html#p-785","d":"p-graphs-785"},{"id":"pf-p-graphs-127","y":"pattern","tr":"dsa","s":"Graphs","q":"Fewest words in a chain from beginWord to endWord, changing one letter each step.","a":"BFS","x":"BFS over words, since every step costs one; generate neighbours with wildcard patterns like h star t from a precomputed map. O(n times L squared).","t":"Word Ladder","L":"graphs.html#p-127","d":"p-graphs-127"},{"id":"gt-p-graphs-127","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Word Ladder?","a":"Return 0 if end isn’t in the list.","x":"Fewest moves between states → BFS.","t":"Word Ladder","L":"graphs.html#p-127","d":"p-graphs-127"},{"id":"pf-p-graphs-207","y":"pattern","tr":"dsa","s":"Graphs","q":"Courses have prerequisites. Can you finish all of them?","a":"Topological sort","x":"It's possible exactly when the prerequisite graph has no cycle; Kahn's algorithm takes courses with in-degree zero and counts how many come out. O(V plus E).","t":"Course Schedule","L":"graphs.html#p-207","d":"p-graphs-207"},{"id":"gt-p-graphs-207","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Course Schedule?","a":"The pair is [course, pre]: the edge goes pre → course.","x":"Prerequisites → topo sort.","t":"Course Schedule","L":"graphs.html#p-207","d":"p-graphs-207"},{"id":"pf-p-graphs-210","y":"pattern","tr":"dsa","s":"Graphs","q":"Return a valid order, or [].","a":"Topological sort","x":"Kahn's algorithm and record the order courses leave the queue; if fewer than n come out, return empty. O(V plus E).","t":"Course Schedule II","L":"graphs.html#p-210","d":"p-graphs-210"},{"id":"gt-p-graphs-210","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Course Schedule II?","a":"Any valid order is accepted.","x":"Ordering with dependencies → Kahn.","t":"Course Schedule II","L":"graphs.html#p-210","d":"p-graphs-210"},{"id":"pf-p-graphs-269","y":"pattern","tr":"dsa","s":"Graphs","q":"Derive letter order from a sorted alien word list.","a":"Topological sort","x":"Compare neighbouring words; the first differing letter gives one edge. Then topological sort. A longer word before its own prefix is invalid. O(total characters).","t":"Alien Dictionary","L":"graphs.html#p-269","d":"p-graphs-269"},{"id":"gt-p-graphs-269","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Alien Dictionary?","a":"Include letters that never get an edge.","x":"Hidden ordering → build edges, topo sort.","t":"Alien Dictionary","L":"graphs.html#p-269","d":"p-graphs-269"},{"id":"pf-p-graphs-323","y":"pattern","tr":"dsa","s":"Graphs","q":"Count components in an undirected graph.","a":"Union-find","x":"Union-find: start with n components and decrement on every union that merges two different roots; with path compression it's nearly O(E).","t":"Number of Connected Components","L":"graphs.html#p-323","d":"p-graphs-323"},{"id":"gt-p-graphs-323","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Number of Connected Components?","a":"DFS works too; mention both.","x":"Connectivity → union-find.","t":"Number of Connected Components","L":"graphs.html#p-323","d":"p-graphs-323"},{"id":"pf-p-graphs-684","y":"pattern","tr":"dsa","s":"Graphs","q":"Which edge creates the cycle in this tree-plus-one-edge?","a":"Union-find","x":"Union-find over the edges in order; the first edge whose endpoints already share a root closes a cycle and is the answer.","t":"Redundant Connection","L":"graphs.html#p-684","d":"p-graphs-684"},{"id":"gt-p-graphs-684","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Redundant Connection?","a":"Nodes are 1-indexed: size parent n + 1.","x":"Edge closing a cycle → shared root.","t":"Redundant Connection","L":"graphs.html#p-684","d":"p-graphs-684"},{"id":"pf-p-graphs-261","y":"pattern","tr":"dsa","s":"Graphs","q":"Do these edges form a valid tree?","a":"Union-find","x":"A tree has exactly n minus one edges and no cycle; check the count, then union-find: any union inside one component means a cycle.","t":"Graph Valid Tree","L":"graphs.html#p-261","d":"p-graphs-261"},{"id":"gt-p-graphs-261","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Graph Valid Tree?","a":"Check the edge count first: it’s free.","x":"Tree check → n − 1 edges + no cycle.","t":"Graph Valid Tree","L":"graphs.html#p-261","d":"p-graphs-261"},{"id":"pf-p-graphs-743","y":"pattern","tr":"dsa","s":"Graphs","q":"A signal starts at k. How long until every node receives it?","a":"Shortest path (Dijkstra)","x":"Dijkstra from k with a min-heap: always settle the closest node; the answer is the largest shortest distance, or minus one if some node is unreachable. O(E log V).","t":"Network Delay Time","L":"graphs.html#p-743","d":"p-graphs-743"},{"id":"pf-p-graphs-787","y":"pattern","tr":"dsa","s":"Graphs","q":"Cheapest flight from src to dst using at most k stops.","a":"Shortest path (Dijkstra)","x":"Bellman-Ford limited to k plus one rounds, copying distances each round so one round adds one edge. O(k times E).","t":"Cheapest Flights Within K Stops","L":"graphs.html#p-787","d":"p-graphs-787"},{"id":"gt-p-graphs-787","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Cheapest Flights Within K Stops?","a":"Without the copy, one round can chain several flights.","x":"Stop limit → Bellman-Ford rounds.","t":"Cheapest Flights Within K Stops","L":"graphs.html#p-787","d":"p-graphs-787"},{"id":"pf-p-graphs-1584","y":"pattern","tr":"dsa","s":"Graphs","q":"Connect all points with minimum total Manhattan distance.","a":"Minimum spanning tree","x":"It's a minimum spanning tree; Prim's grows from one point by always adding the cheapest edge out. With a dense graph, an O(n squared) array version is best.","t":"Min Cost to Connect All Points","L":"graphs.html#p-1584","d":"p-graphs-1584"},{"id":"gt-p-graphs-1584","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Min Cost to Connect All Points?","a":"Dense graph: an O(n²) Prim without a heap is also fine.","x":"Connect all cheaply → MST.","t":"Min Cost to Connect All Points","L":"graphs.html#p-1584","d":"p-graphs-1584"},{"id":"pf-p-graphs-778","y":"pattern","tr":"dsa","s":"Graphs","q":"Water rises over time; earliest time you can swim from top-left to bottom-right?","a":"Shortest path (Dijkstra)","x":"Minimise the maximum height on the path: Dijkstra where a path's cost is its highest cell, popping the smallest max first. O(n squared log n).","t":"Swim in Rising Water","L":"graphs.html#p-778","d":"p-graphs-778"},{"id":"gt-p-graphs-778","y":"gotcha","tr":"dsa","s":"Graphs","q":"What's the classic trap in Swim in Rising Water?","a":"Binary search on time + BFS also works.","x":"Minimize the max → Dijkstra with max.","t":"Swim in Rising Water","L":"graphs.html#p-778","d":"p-graphs-778"},{"id":"pf-p-dp-70","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Ways to climb n stairs taking 1 or 2 steps at a time.","a":"1-D dynamic programming","x":"Ways to reach n equals ways to reach n minus one plus ways to reach n minus two, since the last step was one or two; two variables, O(n) time, O(1) space.","t":"Climbing Stairs","L":"dp.html#p-70","d":"p-dp-70"},{"id":"gt-p-dp-70","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Climbing Stairs?","a":"It’s Fibonacci shifted by one.","x":"Last move options → sum of smaller states.","t":"Climbing Stairs","L":"dp.html#p-70","d":"p-dp-70"},{"id":"pf-p-dp-746","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Each step has a cost; start at step 0 or 1. Cheapest way past the top?","a":"1-D dynamic programming","x":"The cheapest way to reach step i is its cost plus the min of reaching i minus one and i minus two; the top is past the last step. O(n), O(1).","t":"Min Cost Climbing Stairs","L":"dp.html#p-746","d":"p-dp-746"},{"id":"gt-p-dp-746","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Min Cost Climbing Stairs?","a":"The top is one past the last index.","x":"Min over the last move.","t":"Min Cost Climbing Stairs","L":"dp.html#p-746","d":"p-dp-746"},{"id":"pf-p-dp-198","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Rob houses in a row, never two neighbours. Max money?","a":"1-D dynamic programming","x":"At each house, either rob it plus the best up to i minus two, or skip it and keep the best up to i minus one. Two variables, O(n).","t":"House Robber","L":"dp.html#p-198","d":"p-dp-198"},{"id":"pf-p-dp-213","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Houses in a circle.","a":"1-D dynamic programming","x":"The first and last can't both be robbed, so run house robber twice, once without the first house and once without the last, and take the max. O(n).","t":"House Robber II","L":"dp.html#p-213","d":"p-dp-213"},{"id":"gt-p-dp-213","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in House Robber II?","a":"One house: return it directly.","x":"Circular → solve two linear cases.","t":"House Robber II","L":"dp.html#p-213","d":"p-dp-213"},{"id":"pf-p-dp-91","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"How many ways to decode a digit string (1 → A … 26 → Z)?","a":"1-D dynamic programming","x":"Ways at i add ways at i minus one if the single digit is non-zero, plus ways at i minus two if the two-digit code is between ten and twenty-six. O(n), O(1).","t":"Decode Ways","L":"dp.html#p-91","d":"p-dp-91"},{"id":"gt-p-dp-91","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Decode Ways?","a":"“0” alone is invalid; “06” is not 6.","x":"Split a string → dp over prefixes.","t":"Decode Ways","L":"dp.html#p-91","d":"p-dp-91"},{"id":"pf-p-dp-152","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Largest product of a contiguous subarray (negatives allowed).","a":"1-D dynamic programming","x":"A negative flips the biggest into the smallest, so I track both the max and min product ending here, swapping on negatives. O(n).","t":"Maximum Product Subarray","L":"dp.html#p-152","d":"p-dp-152"},{"id":"gt-p-dp-152","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Maximum Product Subarray?","a":"Compute both from the old hi/lo at once.","x":"Negatives flip → track max and min.","t":"Maximum Product Subarray","L":"dp.html#p-152","d":"p-dp-152"},{"id":"pf-p-dp-300","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Length of the longest strictly increasing subsequence.","a":"1-D dynamic programming","x":"O(n squared) DP over earlier indices, or O(n log n) with a tails array, binary searching where each number goes.","t":"Longest Increasing Subsequence","L":"dp.html#p-300","d":"p-dp-300"},{"id":"gt-p-dp-300","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Longest Increasing Subsequence?","a":"tails isn’t the subsequence itself; only its length is right.","x":"Best ending here → dp[i] over earlier j.","t":"Longest Increasing Subsequence","L":"dp.html#p-300","d":"p-dp-300"},{"id":"pf-p-dp-5","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Longest palindrome inside s.","a":"2-D dynamic programming","x":"Every palindrome has a centre, so expand around each of the 2n minus 1 centres, odd and even, and keep the longest. O(n squared), O(1).","t":"Longest Palindromic Substring","L":"dp.html#p-5","d":"p-dp-5"},{"id":"gt-p-dp-5","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Longest Palindromic Substring?","a":"Don’t forget even-length centers.","x":"Palindromic substrings → expand around centers.","t":"Longest Palindromic Substring","L":"dp.html#p-5","d":"p-dp-5"},{"id":"pf-p-dp-647","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"How many substrings are palindromes?","a":"2-D dynamic programming","x":"Expand around every centre and count each successful expansion. O(n squared), O(1).","t":"Palindromic Substrings","L":"dp.html#p-647","d":"p-dp-647"},{"id":"pf-p-dp-139","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Can s be split into dictionary words?","a":"1-D dynamic programming","x":"dp of i means the first i characters can be split; it's true if some dp of j is true and s from j to i is a word. Put words in a set. O(n squared).","t":"Word Break","L":"dp.html#p-139","d":"p-dp-139"},{"id":"gt-p-dp-139","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Word Break?","a":"Limit j to the max word length for speed.","x":"Segmentation → dp over prefixes.","t":"Word Break","L":"dp.html#p-139","d":"p-dp-139"},{"id":"pf-p-dp-322","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Fewest coins to make the amount (unlimited coins).","a":"Knapsack DP","x":"Unbounded knapsack: dp of a is one plus the min over coins of dp of a minus coin, built from zero up. O(amount times coins).","t":"Coin Change","L":"dp.html#p-322","d":"p-dp-322"},{"id":"gt-p-dp-322","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Coin Change?","a":"Greedy fails for coins like [1, 3, 4].","x":"Fewest reusable items → unbounded knapsack.","t":"Coin Change","L":"dp.html#p-322","d":"p-dp-322"},{"id":"pf-p-dp-518","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"How many coin combinations make the amount? (Order doesn't matter.)","a":"Knapsack DP","x":"Loop coins on the outside and amounts on the inside, adding dp of a minus coin, so each combination is counted once. O(amount times coins).","t":"Coin Change II","L":"dp.html#p-518","d":"p-dp-518"},{"id":"gt-p-dp-518","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Coin Change II?","a":"Swapping loops counts orderings instead.","x":"Count combinations → items outer.","t":"Coin Change II","L":"dp.html#p-518","d":"p-dp-518"},{"id":"pf-p-dp-416","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Can the array be split into two subsets with equal sums?","a":"Knapsack DP","x":"It's whether a subset sums to total over two; 0/1 knapsack on reachable sums, iterating capacity backwards. O(n times total).","t":"Partition Equal Subset Sum","L":"dp.html#p-416","d":"p-dp-416"},{"id":"gt-p-dp-416","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Partition Equal Subset Sum?","a":"Odd total → False immediately.","x":"Equal halves → subset sum.","t":"Partition Equal Subset Sum","L":"dp.html#p-416","d":"p-dp-416"},{"id":"pf-p-dp-62","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Paths from top-left to bottom-right moving only right or down.","a":"2-D dynamic programming","x":"Paths to a cell equal paths from above plus paths from the left, filled row by row with one array. O(m times n). Or it's m plus n minus two choose m minus one.","t":"Unique Paths","L":"dp.html#p-62","d":"p-dp-62"},{"id":"gt-p-dp-62","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Unique Paths?","a":"Combinatorics: C(m + n − 2, m − 1) also works.","x":"Grid paths → above + left.","t":"Unique Paths","L":"dp.html#p-62","d":"p-dp-62"},{"id":"pf-p-dp-1143","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Length of the longest subsequence common to both strings.","a":"2-D dynamic programming","x":"A table over prefixes: if the last letters match, one plus the diagonal; else the max of top and left. O(m times n), O(min) space with rolling rows.","t":"Longest Common Subsequence","L":"dp.html#p-1143","d":"p-dp-1143"},{"id":"gt-p-dp-1143","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Longest Common Subsequence?","a":"Index with i − 1 and j − 1 inside the table.","x":"Two strings → prefix table.","t":"Longest Common Subsequence","L":"dp.html#p-1143","d":"p-dp-1143"},{"id":"pf-p-dp-72","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Fewest inserts, deletes or replacements to turn word a into word b.","a":"2-D dynamic programming","x":"dp over prefixes: if letters match take the diagonal, else one plus the min of insert, delete and replace, which are left, top and diagonal. O(m times n).","t":"Edit Distance","L":"dp.html#p-72","d":"p-dp-72"},{"id":"gt-p-dp-72","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Edit Distance?","a":"Initialize the borders, not zeros.","x":"Edits → above / left / diagonal.","t":"Edit Distance","L":"dp.html#p-72","d":"p-dp-72"},{"id":"pf-p-dp-309","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Max stock profit with unlimited trades, but a 1-day rest after each sell.","a":"1-D dynamic programming","x":"A state machine with three states per day, holding, just sold and resting, each updated from yesterday's values. O(n), O(1).","t":"Best Time to Buy and Sell Stock with Cooldown","L":"dp.html#p-309","d":"p-dp-309"},{"id":"gt-p-dp-309","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Best Time to Buy and Sell Stock with Cooldown?","a":"Update all three simultaneously.","x":"Stock rules → state machine.","t":"Best Time to Buy and Sell Stock with Cooldown","L":"dp.html#p-309","d":"p-dp-309"},{"id":"pf-p-dp-312","y":"pattern","tr":"dsa","s":"Dynamic Programming","q":"Burst balloons for coins (left × self × right). Max coins?","a":"2-D dynamic programming","x":"Interval DP: think of the last balloon burst in an interval; its neighbours are the fixed interval ends. dp over lengths, O(n cubed).","t":"Burst Balloons","L":"dp.html#p-312","d":"p-dp-312"},{"id":"gt-p-dp-312","y":"gotcha","tr":"dsa","s":"Dynamic Programming","q":"What's the classic trap in Burst Balloons?","a":"Choosing the first balloon creates dependent sides; choose the last.","x":"Range splitting → interval DP by length.","t":"Burst Balloons","L":"dp.html#p-312","d":"p-dp-312"},{"id":"pf-p-greedy-intervals-53","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Largest sum of any contiguous subarray.","a":"Greedy","x":"Kadane's algorithm: keep a running sum and restart from the current number whenever the running sum goes negative, tracking the best. O(n), O(1).","t":"Maximum Subarray","L":"greedy-intervals.html#p-53","d":"p-greedy-intervals-53"},{"id":"gt-p-greedy-intervals-53","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Maximum Subarray?","a":"Initialize with nums[0], not 0.","x":"Max subarray → Kadane.","t":"Maximum Subarray","L":"greedy-intervals.html#p-53","d":"p-greedy-intervals-53"},{"id":"pf-p-greedy-intervals-55","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Each value is your max jump length. Can you reach the last index?","a":"Greedy","x":"Track the farthest reachable index; if the current index is beyond it, fail; otherwise extend it. One pass, O(n), O(1).","t":"Jump Game","L":"greedy-intervals.html#p-55","d":"p-greedy-intervals-55"},{"id":"pf-p-greedy-intervals-45","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Fewest jumps to reach the last index.","a":"Greedy","x":"Greedy BFS by levels: the current jump covers a window; the next jump's window extends to the farthest reach from it. Count windows. O(n).","t":"Jump Game II","L":"greedy-intervals.html#p-45","d":"p-greedy-intervals-45"},{"id":"gt-p-greedy-intervals-45","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Jump Game II?","a":"Loop to n − 2, or you count an extra jump at the end.","x":"Fewest jumps → implicit BFS levels.","t":"Jump Game II","L":"greedy-intervals.html#p-45","d":"p-greedy-intervals-45"},{"id":"pf-p-greedy-intervals-134","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Find the start station that lets you drive the whole circle (or −1).","a":"Greedy","x":"If total gas is at least total cost, a start exists; whenever the tank goes negative, the next station becomes the candidate start. One pass, O(n).","t":"Gas Station","L":"greedy-intervals.html#p-134","d":"p-greedy-intervals-134"},{"id":"gt-p-greedy-intervals-134","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Gas Station?","a":"The total check is what makes the single pass correct.","x":"Negative tank → restart after it.","t":"Gas Station","L":"greedy-intervals.html#p-134","d":"p-greedy-intervals-134"},{"id":"pf-p-greedy-intervals-846","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Can the cards be split into groups of groupSize consecutive values?","a":"Greedy","x":"The smallest remaining card must start a group; count with a sorted map and consume groupSize consecutive values from the smallest. O(n log n).","t":"Hand of Straights","L":"greedy-intervals.html#p-846","d":"p-greedy-intervals-846"},{"id":"gt-p-greedy-intervals-846","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Hand of Straights?","a":"Subtract n copies at once, not one at a time.","x":"Consecutive groups → smallest must start one.","t":"Hand of Straights","L":"greedy-intervals.html#p-846","d":"p-greedy-intervals-846"},{"id":"pf-p-greedy-intervals-1899","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Can max-merging some triplets produce exactly the target triplet?","a":"Greedy","x":"Ignore any triplet with a value above the target in any position; among the rest, check that each target value appears in its position. O(n).","t":"Merge Triplets to Form Target","L":"greedy-intervals.html#p-1899","d":"p-greedy-intervals-1899"},{"id":"gt-p-greedy-intervals-1899","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Merge Triplets to Form Target?","a":"A triplet with any value above target can never be used.","x":"Max-merge → discard anything that would overshoot.","t":"Merge Triplets to Form Target","L":"greedy-intervals.html#p-1899","d":"p-greedy-intervals-1899"},{"id":"pf-p-greedy-intervals-763","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Most parts with each letter in one part.","a":"Greedy","x":"Record each letter's last occurrence; extend the current part's end to the max last occurrence seen and cut when the index reaches it. O(n).","t":"Partition Labels","L":"greedy-intervals.html#p-763","d":"p-greedy-intervals-763"},{"id":"gt-p-greedy-intervals-763","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Partition Labels?","a":"Return sizes, not the parts.","x":"Letter in one part → last occurrence.","t":"Partition Labels","L":"greedy-intervals.html#p-763","d":"p-greedy-intervals-763"},{"id":"pf-p-greedy-intervals-678","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Is the string valid if '*' can be '(', ')' or empty?","a":"Greedy","x":"Track the range low to high of possible open counts: open raises both, close lowers both, star widens the range; fail if high goes negative and require low to reach zero. O(n), O(1).","t":"Valid Parenthesis String","L":"greedy-intervals.html#p-678","d":"p-greedy-intervals-678"},{"id":"gt-p-greedy-intervals-678","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Valid Parenthesis String?","a":"Clamp lo at 0, but check hi first.","x":"Wildcard choices → range of states.","t":"Valid Parenthesis String","L":"greedy-intervals.html#p-678","d":"p-greedy-intervals-678"},{"id":"pf-p-greedy-intervals-135","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Give candies so higher-rated kids get more than their neighbours. Minimum total?","a":"Greedy","x":"Two passes: left to right handles the left neighbour, right to left handles the right neighbour, taking the max of both. O(n).","t":"Candy","L":"greedy-intervals.html#p-135","d":"p-greedy-intervals-135"},{"id":"gt-p-greedy-intervals-135","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Candy?","a":"Use max in pass 2 or you break pass 1’s guarantee.","x":"Both neighbours → two passes.","t":"Candy","L":"greedy-intervals.html#p-135","d":"p-greedy-intervals-135"},{"id":"pf-p-greedy-intervals-1029","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Send exactly half the people to city A and half to B, minimum total cost.","a":"Greedy","x":"Sort by cost A minus cost B; the first half go to A and the rest to B. O(n log n).","t":"Two City Scheduling","L":"greedy-intervals.html#p-1029","d":"p-greedy-intervals-1029"},{"id":"gt-p-greedy-intervals-1029","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Two City Scheduling?","a":"Sorting by costA alone ignores what B would cost.","x":"Two choices with a quota → sort by difference.","t":"Two City Scheduling","L":"greedy-intervals.html#p-1029","d":"p-greedy-intervals-1029"},{"id":"pf-p-greedy-intervals-56","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Merge all overlapping intervals.","a":"Intervals: sort & sweep","x":"Sort by start; each interval either extends the last merged one, if it starts before that one ends, or starts a new one. O(n log n).","t":"Merge Intervals","L":"greedy-intervals.html#p-56","d":"p-greedy-intervals-56"},{"id":"gt-p-greedy-intervals-56","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Merge Intervals?","a":"Extend with max, since a contained interval ends earlier.","x":"Merge → sort by start.","t":"Merge Intervals","L":"greedy-intervals.html#p-56","d":"p-greedy-intervals-56"},{"id":"pf-p-greedy-intervals-57","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Insert a new interval into a sorted, non-overlapping list and merge.","a":"Intervals: sort & sweep","x":"Three phases in one pass: copy intervals that end before it, merge all that overlap into it, then copy the rest. O(n).","t":"Insert Interval","L":"greedy-intervals.html#p-57","d":"p-greedy-intervals-57"},{"id":"pf-p-greedy-intervals-435","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Remove the fewest intervals so the rest don't overlap.","a":"Intervals: sort & sweep","x":"Keep as many as possible: sort by end and always keep the interval that ends earliest; removals are the total minus kept. O(n log n).","t":"Non-overlapping Intervals","L":"greedy-intervals.html#p-435","d":"p-greedy-intervals-435"},{"id":"gt-p-greedy-intervals-435","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Non-overlapping Intervals?","a":"Touching ends don’t overlap here.","x":"Remove the fewest → sort by end.","t":"Non-overlapping Intervals","L":"greedy-intervals.html#p-435","d":"p-greedy-intervals-435"},{"id":"pf-p-greedy-intervals-452","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"Fewest vertical arrows to burst all balloons.","a":"Intervals: sort & sweep","x":"Sort by end; shoot at the end of the first balloon, which bursts every balloon starting before that point; repeat from the next unburst one. O(n log n).","t":"Minimum Number of Arrows to Burst Balloons","L":"greedy-intervals.html#p-452","d":"p-greedy-intervals-452"},{"id":"gt-p-greedy-intervals-452","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Minimum Number of Arrows to Burst Balloons?","a":"Touching counts as hit here: use s > pos for a new arrow.","x":"Fewest stabbing points → sort by end.","t":"Minimum Number of Arrows to Burst Balloons","L":"greedy-intervals.html#p-452","d":"p-greedy-intervals-452"},{"id":"pf-p-greedy-intervals-1851","y":"pattern","tr":"dsa","s":"Greedy & Intervals","q":"For each query point, the size of the smallest interval containing it.","a":"Heap / top-k","x":"Offline: sort queries and intervals; for each query, push intervals that start before it into a min-heap by size, pop those that already ended, and read the top. O of n plus q times log n.","t":"Minimum Interval to Include Each Query","L":"greedy-intervals.html#p-1851","d":"p-greedy-intervals-1851"},{"id":"gt-p-greedy-intervals-1851","y":"gotcha","tr":"dsa","s":"Greedy & Intervals","q":"What's the classic trap in Minimum Interval to Include Each Query?","a":"Map answers back to the original query order.","x":"Many interval queries → offline sweep + heap.","t":"Minimum Interval to Include Each Query","L":"greedy-intervals.html#p-1851","d":"p-greedy-intervals-1851"},{"id":"pf-p-bits-136","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Every number appears twice except one. Find it with O(1) space.","a":"Bit manipulation","x":"XOR everything: x XOR x is zero and x XOR zero is x, so pairs cancel and the single number remains. O(n), O(1).","t":"Single Number","L":"bits.html#p-136","d":"p-bits-136"},{"id":"gt-p-bits-136","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Single Number?","a":"A set works but costs O(n) space.","x":"Pairs cancel → XOR.","t":"Single Number","L":"bits.html#p-136","d":"p-bits-136"},{"id":"pf-p-bits-191","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Count the 1 bits in a number.","a":"Bit manipulation","x":"n AND n minus one clears the lowest set bit, so count how many times I can do that before n is zero. O(number of set bits).","t":"Number of 1 Bits","L":"bits.html#p-191","d":"p-bits-191"},{"id":"gt-p-bits-191","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Number of 1 Bits?","a":"bin(n).count(&quot;1&quot;) is fine in Python too.","x":"Count set bits → n & (n − 1).","t":"Number of 1 Bits","L":"bits.html#p-191","d":"p-bits-191"},{"id":"pf-p-bits-338","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"For every i from 0 to n, how many 1 bits does i have?","a":"Bit manipulation","x":"bits of i equals bits of i shifted right by one plus i AND one, reusing smaller answers. O(n).","t":"Counting Bits","L":"bits.html#p-338","d":"p-bits-338"},{"id":"gt-p-bits-338","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Counting Bits?","a":"Also works: dp[i] = dp[i & (i − 1)] + 1.","x":"Counts for a range → bit DP.","t":"Counting Bits","L":"bits.html#p-338","d":"p-bits-338"},{"id":"pf-p-bits-190","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Reverse the 32 bits of an unsigned integer.","a":"Bit manipulation","x":"Thirty-two times: shift the result left, add n's lowest bit, shift n right. O(32).","t":"Reverse Bits","L":"bits.html#p-190","d":"p-bits-190"},{"id":"gt-p-bits-190","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Reverse Bits?","a":"Loop exactly 32 times, even after n becomes 0.","x":"Bit by bit → shift and mask.","t":"Reverse Bits","L":"bits.html#p-190","d":"p-bits-190"},{"id":"pf-p-bits-268","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Numbers 0..n with one missing. Which one?","a":"Bit manipulation","x":"XOR all indices zero to n with all values; pairs cancel and the missing number remains. Or use n times n plus one over two minus the sum. O(n), O(1).","t":"Missing Number","L":"bits.html#p-268","d":"p-bits-268"},{"id":"gt-p-bits-268","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Missing Number?","a":"n(n + 1)/2 − sum works too; XOR can’t overflow in other languages.","x":"Missing from a range → XOR indexes and values.","t":"Missing Number","L":"bits.html#p-268","d":"p-bits-268"},{"id":"pf-p-bits-371","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Add without + or −.","a":"Bit manipulation","x":"XOR adds without carrying and AND shifted left gives the carries; repeat until there's no carry. In Python, mask to 32 bits. O(32).","t":"Sum of Two Integers","L":"bits.html#p-371","d":"p-bits-371"},{"id":"gt-p-bits-371","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Sum of Two Integers?","a":"Without the mask, negatives loop forever in Python.","x":"Add with bits → XOR + carry loop.","t":"Sum of Two Integers","L":"bits.html#p-371","d":"p-bits-371"},{"id":"pf-p-bits-231","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Is n a power of two?","a":"Bit manipulation","x":"A power of two has exactly one set bit, so n greater than zero and n AND n minus one equals zero. O(1).","t":"Power of Two","L":"bits.html#p-231","d":"p-bits-231"},{"id":"gt-p-bits-231","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Power of Two?","a":"0 and negatives are not powers of two.","x":"Power of two → one set bit.","t":"Power of Two","L":"bits.html#p-231","d":"p-bits-231"},{"id":"pf-p-bits-461","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"In how many bit positions do x and y differ?","a":"Bit manipulation","x":"x XOR y has ones exactly where they differ; count its set bits. O(1).","t":"Hamming Distance","L":"bits.html#p-461","d":"p-bits-461"},{"id":"gt-p-bits-461","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Hamming Distance?","a":"Same trick for Total Hamming Distance, counted per bit.","x":"Differing bits → XOR then count.","t":"Hamming Distance","L":"bits.html#p-461","d":"p-bits-461"},{"id":"pf-p-bits-137","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Every number appears three times except one. Find it.","a":"Bit manipulation","x":"Count each bit position across all numbers mod three; the leftover bits form the answer. Or the ones and twos bitmask trick. O(n), O(1).","t":"Single Number II","L":"bits.html#p-137","d":"p-bits-137"},{"id":"gt-p-bits-137","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Single Number II?","a":"Summing each of 32 bits mod 3 is easier to explain; mention both.","x":"Triples → count bits mod 3.","t":"Single Number II","L":"bits.html#p-137","d":"p-bits-137"},{"id":"pf-p-bits-260","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Two numbers appear once, the rest twice. Find both.","a":"Bit manipulation","x":"XOR all to get a XOR b; any set bit of it, like the lowest, splits numbers into two groups, each containing one single; XOR each group. O(n), O(1).","t":"Single Number III","L":"bits.html#p-260","d":"p-bits-260"},{"id":"gt-p-bits-260","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Single Number III?","a":"In other languages, x & −x can overflow for INT_MIN.","x":"Two singles → split by a differing bit.","t":"Single Number III","L":"bits.html#p-260","d":"p-bits-260"},{"id":"pf-p-bits-78","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"All subsets, without recursion.","a":"Bit manipulation","x":"Each mask from zero to two to the n minus one is a subset: bit i set means include element i. O(n times 2 to the n).","t":"Subsets (bitmask)","L":"bits.html#p-78","d":"p-bits-78"},{"id":"pf-p-bits-201","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"Bitwise AND of every integer from left to right.","a":"Bit manipulation","x":"The answer is the common binary prefix of left and right: shift both right until equal, then shift back. O(32).","t":"Bitwise AND of Numbers Range","L":"bits.html#p-201","d":"p-bits-201"},{"id":"gt-p-bits-201","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Bitwise AND of Numbers Range?","a":"Looping through the range is far too slow.","x":"AND of a range → common prefix.","t":"Bitwise AND of Numbers Range","L":"bits.html#p-201","d":"p-bits-201"},{"id":"pf-p-bits-89","y":"pattern","tr":"dsa","s":"Bit Manipulation","q":"List 2ⁿ numbers where neighbours differ in exactly one bit.","a":"Bit manipulation","x":"The ith Gray code is i XOR i shifted right by one. O(2 to the n).","t":"Gray Code","L":"bits.html#p-89","d":"p-bits-89"},{"id":"gt-p-bits-89","y":"gotcha","tr":"dsa","s":"Bit Manipulation","q":"What's the classic trap in Gray Code?","a":"The reflect-and-prefix construction also works.","x":"One-bit neighbours → i ^ (i >> 1).","t":"Gray Code","L":"bits.html#p-89","d":"p-bits-89"},{"id":"qz-hashing-h1","y":"quiz","lb":"","tr":"dsa","s":"Arrays & Hashing","q":"In Two Sum, what goes wrong if you write <code>seen[x] = i</code> <i>before</i> checking <code>target − x in seen</code>?","code":"","o":["Nothing","An element can pair with itself, e.g. target 6 with x = 3 returns [i, i]","It becomes O(n²)","It misses valid pairs"],"c":1,"a":"Storing first means the lookup can find x itself. Check first, then store.","L":"hashing.html"},{"id":"qz-hashing-h2","y":"quiz","lb":"","tr":"dsa","s":"Arrays & Hashing","q":"Which dict key groups anagrams in O(k) per word, without sorting?","code":"","o":["sorted(word)","tuple of 26 letter counts","len(word)","set(word)"],"c":1,"a":"Sorting is O(k log k). A count tuple is O(k). <code>set</code> loses repeats (\"aab\" vs \"ab\"), and length groups non-anagrams.","L":"hashing.html"},{"id":"qz-hashing-h3","y":"quiz","lb":"","tr":"dsa","s":"Arrays & Hashing","q":"Why does <code>subarray_sum</code> start with <code>seen = {0: 1}</code>?","code":"","o":["To avoid a KeyError","So subarrays that start at index 0 are counted","To handle negative numbers","It’s optional"],"c":1,"a":"A subarray from index 0 to i has sum = running. Looking up running − k = 0 needs the empty prefix to be there.","L":"hashing.html"},{"id":"qz-hashing-h4","y":"quiz","lb":"","tr":"dsa","s":"Arrays & Hashing","q":"Subarray sum equals k, with negative numbers. Can a sliding window replace the prefix-sum dict?","code":"","o":["Yes, always","No: with negatives, shrinking the window can make the sum go up, so the shrink rule breaks","Only if k > 0","Only if the array is sorted"],"c":1,"a":"Sliding windows need “adding makes it bigger, removing makes it smaller”. Negatives break that monotonicity; prefix sums don’t care.","L":"hashing.html"},{"id":"qz-hashing-d1","y":"quiz","lb":"Name the tool","tr":"dsa","s":"Arrays & Hashing","q":"“Is there a pair whose difference is exactly k?”","code":"","o":["Set: for each x check x − k (or x + k)","Prefix sums","Bucket sort","Transpose"],"c":0,"a":"A complement lookup, just with subtraction. One pass with a set.","L":"hashing.html"},{"id":"qz-hashing-d2","y":"quiz","lb":"Name the tool","tr":"dsa","s":"Arrays & Hashing","q":"“Return the k most frequent words.”","code":"","o":["Two pointers","Counter, then buckets or a heap of size k","Prefix sums","Index-as-hash"],"c":1,"a":"Frequencies → Counter. Then bucket sort for O(n), or a size-k heap for O(n log k).","L":"hashing.html"},{"id":"qz-hashing-d3","y":"quiz","lb":"Name the tool","tr":"dsa","s":"Arrays & Hashing","q":"“Count subarrays whose sum is divisible by k.”","code":"","o":["Sliding window","Prefix sums with a dict of remainders","Sort and two pointers","Spiral walk"],"c":1,"a":"Two prefixes with the same remainder mod k bound a subarray divisible by k. Count remainders as you go.","L":"hashing.html"},{"id":"qz-hashing-d4","y":"quiz","lb":"Name the tool","tr":"dsa","s":"Arrays & Hashing","q":"“Rotate an n × n image 90° counterclockwise, in place.”","code":"","o":["Transpose, then reverse each column","Reverse each row only","Spiral walk","Prefix sums"],"c":0,"a":"Counterclockwise maps (r, c) to (n − 1 − c, r): transpose, then flip vertically.","L":"hashing.html"},{"id":"qz-hashing-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Arrays & Hashing","q":"Time and space of this?","code":"def has_dup(a):\n    seen = set()\n    for x in a:\n        if x in seen:\n            return True\n        seen.add(x)\n    return False","o":["O(n²) time, O(1) space","O(n) time, O(n) space","O(n log n) time, O(1) space","O(n) time, O(1) space"],"c":1,"a":"One pass with O(1) average set operations; the set can hold all n items.","L":"hashing.html"},{"id":"qz-hashing-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Arrays & Hashing","q":"All n keys land in the same hash bucket. What does one lookup cost now?","code":"","o":["O(1)","O(log n)","O(n)","O(n²)"],"c":2,"a":"The bucket becomes a list of n items to scan. That’s why we say O(1) <i>average</i>. (Java 8+ HashMap turns long buckets into trees: O(log n).)","L":"hashing.html"},{"id":"qz-two-pointers-t1","y":"quiz","lb":"","tr":"dsa","s":"Two Pointers","q":"Container With Most Water: why move the <i>shorter</i> wall inward?","code":"","o":["It doesn’t matter which","The shorter wall caps the height; any narrower container with it can only be worse","Moving the taller one is O(n²)","To keep the array sorted"],"c":1,"a":"Area = min(h[l], h[r]) × width. Keeping the shorter wall, the min can’t grow and width shrinks, so every container using it is already beaten.","L":"two-pointers.html"},{"id":"qz-two-pointers-t2","y":"quiz","lb":"","tr":"dsa","s":"Two Pointers","q":"In 3Sum, after recording a triple, why skip <code>nums[l]</code> values equal to the one just used?","code":"","o":["For speed only","To avoid recording the same triple twice","Because the array is unsorted","It’s required to terminate"],"c":1,"a":"With the same first number and the same second number, the third is forced, so the triple would repeat.","L":"two-pointers.html"},{"id":"qz-two-pointers-t3","y":"quiz","lb":"","tr":"dsa","s":"Two Pointers","q":"Sort Colors: after swapping <code>nums[i]</code> (a 2) with <code>nums[hi]</code>, why not <code>i += 1</code>?","code":"","o":["It would be out of bounds","The value that came from hi hasn’t been examined yet","2s must be checked twice","No reason, it’s fine"],"c":1,"a":"hi’s old value could be 0, 1 or 2. It must be classified before i moves past it.","L":"two-pointers.html"},{"id":"qz-two-pointers-t4","y":"quiz","lb":"","tr":"dsa","s":"Two Pointers","q":"Merge Sorted Array (88): why fill <code>nums1</code> from the back?","code":"","o":["It’s faster","The back is empty space, so writing there never overwrites unread values","Python lists require it","To keep it stable"],"c":1,"a":"Filling from the front would clobber nums1’s own unmerged values. The tail has m + n − m free slots.","L":"two-pointers.html"},{"id":"qz-two-pointers-d1","y":"quiz","lb":"Name the setup","tr":"dsa","s":"Two Pointers","q":"“Sorted array: count pairs with sum less than target.”","code":"","o":["Converging pointers: when nums[l] + nums[r] &lt; target, add r − l, then l += 1","Hash set","Read/write pointers","Fast and slow"],"c":0,"a":"If l pairs with r, it also pairs with everything between, so r − l pairs are counted at once.","L":"two-pointers.html"},{"id":"qz-two-pointers-d2","y":"quiz","lb":"Name the setup","tr":"dsa","s":"Two Pointers","q":"“Remove every occurrence of val in place and return the new length.”","code":"","o":["Converging pointers","Writer and reader","Fast and slow","Prefix sums"],"c":1,"a":"Keep everything that isn’t val by writing it at w.","L":"two-pointers.html"},{"id":"qz-two-pointers-d3","y":"quiz","lb":"Name the setup","tr":"dsa","s":"Two Pointers","q":"“Find the duplicate number in [1..n] with O(1) space, without modifying the array.” (287)","code":"","o":["Sort it","Hash set","Fast and slow pointers on i → nums[i]","Dutch flag"],"c":2,"a":"Treat the array as a linked list i → nums[i]. The duplicate is the cycle entrance (Floyd’s algorithm).","L":"two-pointers.html"},{"id":"qz-two-pointers-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Two Pointers","q":"Remove duplicates in-place from a sorted array with a slow and a fast pointer. Time and extra space?","code":"","o":["O(n²), O(1)","O(n), O(1)","O(n), O(n)","O(n log n), O(1)"],"c":1,"a":"The fast pointer visits each element once; the slow one never passes it. Two integers of extra space.","L":"two-pointers.html"},{"id":"qz-two-pointers-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Two Pointers","q":"Container With Most Water: two pointers from both ends. Why is it O(n) and not O(n²)?","code":"","o":["It skips half the pairs","Every step moves one pointer inward, and they meet after n − 1 steps","It sorts first","Heights are bounded"],"c":1,"a":"Each iteration permanently discards one line, so there are at most n − 1 iterations.","L":"two-pointers.html"},{"id":"qz-sliding-window-s1","y":"quiz","lb":"","tr":"dsa","s":"Sliding Window","q":"Longest Substring Without Repeating: why <code>while ch in window</code> instead of <code>if</code>?","code":"","o":["Style only","The repeat may be several positions back, so several letters must leave","To avoid an infinite loop","<code>if</code> would be O(n²)"],"c":1,"a":"In \"abca…\" arriving at a second \"b\" after \"abc\" needs \"a\" and \"b\" to leave. One removal isn’t enough.","L":"sliding-window.html"},{"id":"qz-sliding-window-s2","y":"quiz","lb":"","tr":"dsa","s":"Sliding Window","q":"Character Replacement never decreases <code>maxf</code> when shrinking. Why is the answer still right?","code":"","o":["It’s a bug that happens to pass","A stale maxf only blocks the window from growing; the best is only updated when a truly better maxf appears","maxf can’t change","Python recomputes it"],"c":1,"a":"To beat the current best you need a bigger true max frequency. Until then, the window just slides at the same length.","L":"sliding-window.html"},{"id":"qz-sliding-window-s3","y":"quiz","lb":"","tr":"dsa","s":"Sliding Window","q":"Sliding Window Maximum: why store <b>indexes</b> in the deque, not values?","code":"","o":["Indexes are smaller","To know when the front has slid out of the window","To sort them","Deques can’t hold values"],"c":1,"a":"Expiry depends on position. With duplicates, values alone can’t tell you which copy left.","L":"sliding-window.html"},{"id":"qz-sliding-window-s4","y":"quiz","lb":"","tr":"dsa","s":"Sliding Window","q":"“Longest subarray with sum ≤ k”, numbers may be negative. Window?","code":"","o":["Yes, same template","No: with negatives, shrinking doesn’t reliably lower the sum, so validity isn’t monotone","Only for k ≥ 0","Only if sorted"],"c":1,"a":"Use prefix sums with a monotonic structure (or a sorted list) instead.","L":"sliding-window.html"},{"id":"qz-sliding-window-d1","y":"quiz","lb":"Which window?","tr":"dsa","s":"Sliding Window","q":"“Longest subarray with at most 2 distinct values.” (904)","code":"","o":["Fixed size","Variable: shrink while distinct &gt; 2","Deque","Not a window"],"c":1,"a":"At most K distinct is monotone. Count dict + shrink.","L":"sliding-window.html"},{"id":"qz-sliding-window-d2","y":"quiz","lb":"Which window?","tr":"dsa","s":"Sliding Window","q":"“Number of subarrays with exactly 3 odd numbers.”","code":"","o":["Variable window directly","atMost(3) − atMost(2)","Fixed window of 3","Deque"],"c":1,"a":"“Exactly” isn’t monotone; subtract two “at most” counts.","L":"sliding-window.html"},{"id":"qz-sliding-window-d3","y":"quiz","lb":"Which window?","tr":"dsa","s":"Sliding Window","q":"“Max number of vowels in any substring of length k.”","code":"","o":["Fixed: add one, drop one","Variable","Prefix sums with dict","Two pointers from both ends"],"c":0,"a":"Size is given. Keep a running vowel count.","L":"sliding-window.html"},{"id":"qz-sliding-window-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Sliding Window","q":"Minimum window substring: right moves over s (length n), left only moves forward. Time, ignoring the size of t?","code":"","o":["O(n²)","O(n)","O(n log n)","O(2ⁿ)"],"c":1,"a":"Both pointers move forward at most n times each.","L":"sliding-window.html"},{"id":"qz-sliding-window-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Sliding Window","q":"Sliding window maximum with a monotonic deque. Each index is appended once and popped at most once. Time?","code":"","o":["O(n·k)","O(n log k)","O(n)","O(k)"],"c":2,"a":"At most n pushes and n pops in total → O(n).","L":"sliding-window.html"},{"id":"qz-stack-k1","y":"quiz","lb":"","tr":"dsa","s":"Stack","q":"Input <code>\"((\"</code>. The loop finishes without returning False. What does <code>is_valid</code> return?","code":"","o":["True","False, because the stack still holds two openers","An error","It depends on Python version"],"c":1,"a":"<code>return not stack</code>: leftover openers were never closed.","L":"stack.html"},{"id":"qz-stack-k2","y":"quiz","lb":"","tr":"dsa","s":"Stack","q":"MinStack stores <code>(value, min so far)</code>. Why not one global <code>min</code> variable?","code":"","o":["Pairs are faster","After popping the current min, a single variable can’t recover the previous min","Python has no global variables","To support duplicates only"],"c":1,"a":"Each frame remembers the min beneath it, so pops restore the old min in O(1).","L":"stack.html"},{"id":"qz-stack-k3","y":"quiz","lb":"","tr":"dsa","s":"Stack","q":"For “next <b>smaller</b> element to the right”, which order do values on the stack keep?","code":"","o":["Decreasing","Increasing","Sorted by index only","Random"],"c":1,"a":"You pop when the current is smaller than the top, so whatever survives is increasing.","L":"stack.html"},{"id":"qz-stack-k4","y":"quiz","lb":"","tr":"dsa","s":"Stack","q":"Largest Rectangle appends a sentinel <code>0</code> to heights. Why?","code":"","o":["To avoid an empty list","It forces every remaining bar to be popped and measured at the end","To handle negative heights","For sorting"],"c":1,"a":"Without it, bars still on the stack at the end would never get their area computed.","L":"stack.html"},{"id":"qz-stack-d1","y":"quiz","lb":"Which stack?","tr":"dsa","s":"Stack","q":"“For each stock price, how many consecutive days up to today had price ≤ today?” (901)","code":"","o":["Plain stack","Monotonic decreasing stack of (price, span)","Queue","Two pointers"],"c":1,"a":"Pop days with price ≤ today and absorb their spans.","L":"stack.html"},{"id":"qz-stack-d2","y":"quiz","lb":"Which stack?","tr":"dsa","s":"Stack","q":"“Remove duplicate letters so the result is the smallest in lexicographic order.” (316)","code":"","o":["Monotonic increasing stack with a “last occurrence” check","Plain stack","Hash set only","Sliding window"],"c":0,"a":"Like Remove K Digits: pop a bigger top if it appears again later.","L":"stack.html"},{"id":"qz-stack-d3","y":"quiz","lb":"Which stack?","tr":"dsa","s":"Stack","q":"“Simplify a Unix path like /a/./b/../../c/.”","code":"","o":["Monotonic stack","Plain stack of folder names","Sliding window","Two pointers"],"c":1,"a":"“..” cancels the most recent folder: pop.","L":"stack.html"},{"id":"qz-stack-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Stack","q":"Valid parentheses on a string of length n. Time and space?","code":"","o":["O(n), O(1)","O(n), O(n)","O(n²), O(n)","O(log n), O(n)"],"c":1,"a":"One pass; the stack can hold up to n opening brackets (“((((…”).","L":"stack.html"},{"id":"qz-stack-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Stack","q":"Largest rectangle in histogram with a monotonic stack. Time?","code":"","o":["O(n²)","O(n log n)","O(n)","O(n³)"],"c":2,"a":"Each bar is pushed and popped once; each pop computes one area in O(1).","L":"stack.html"},{"id":"qz-binary-search-b1","y":"quiz","lb":"","tr":"dsa","s":"Binary Search","q":"Lower-bound template: <code>while lo &lt; hi</code> with <code>hi = mid</code>. What is true when the loop ends?","code":"","o":["lo &gt; hi","lo == hi, and it’s the first index where the predicate is True (or n if none)","lo is the last False","Nothing; you must check both"],"c":1,"a":"The invariant “answer ∈ [lo, hi]” plus lo == hi pins it down.","L":"binary-search.html"},{"id":"qz-binary-search-b2","y":"quiz","lb":"","tr":"dsa","s":"Binary Search","q":"Which loop can run forever?","code":"lo, hi = 0, len(a) - 1\nwhile lo < hi:\n    mid = (lo + hi) // 2\n    if ok(mid):\n        lo = mid\n    else:\n        hi = mid - 1","o":["None of them","This one: when hi = lo + 1 and ok(mid) is True, lo stays the same","Only if a is empty","Only with negatives"],"c":1,"a":"mid rounds down to lo, and lo = mid changes nothing. Round up: (lo + hi + 1) // 2.","L":"binary-search.html"},{"id":"qz-binary-search-b3","y":"quiz","lb":"","tr":"dsa","s":"Binary Search","q":"Koko: when <code>hours(mid) ≤ h</code>, why <code>hi = mid</code> and not <code>hi = mid − 1</code>?","code":"","o":["Typo-tolerant","mid itself might be the slowest speed that works","It’s faster","To avoid negatives"],"c":1,"a":"A feasible mid is a candidate answer; discarding it could skip the answer.","L":"binary-search.html"},{"id":"qz-binary-search-b4","y":"quiz","lb":"","tr":"dsa","s":"Binary Search","q":"Find Min in Rotated Sorted Array compares <code>nums[mid]</code> with <code>nums[hi]</code>. Why not with <code>nums[lo]</code>?","code":"","o":["No reason","With nums[lo], an unrotated array looks the same as a rotated one and you go the wrong way","It’s faster","To handle duplicates"],"c":1,"a":"nums[lo] ≤ nums[mid] is true for both [1,2,3,4,5] (min left) and [3,4,5,1,2] (min right). Comparing with hi distinguishes them.","L":"binary-search.html"},{"id":"qz-binary-search-d1","y":"quiz","lb":"Name the predicate","tr":"dsa","s":"Binary Search","q":"“Minimum number of days so that you can make m bouquets.” (1482)","code":"","o":["Sort and two pointers","Binary search days with feasible(day) = can make m bouquets","Sliding window","Heap"],"c":1,"a":"If you can make them by day d, you can by any later day. Monotone predicate on the answer.","L":"binary-search.html"},{"id":"qz-binary-search-d2","y":"quiz","lb":"Name the predicate","tr":"dsa","s":"Binary Search","q":"“Find the smallest divisor so the sum of ceil(n / d) ≤ threshold.” (1283)","code":"","o":["Binary search d","Prefix sums","DP","Greedy sort"],"c":0,"a":"Bigger divisor → smaller sum. First d where the sum fits.","L":"binary-search.html"},{"id":"qz-binary-search-d3","y":"quiz","lb":"Name the predicate","tr":"dsa","s":"Binary Search","q":"“Search a 2-D matrix where rows and columns are sorted but rows don’t continue each other.” (240)","code":"","o":["Flatten and binary search","Staircase walk from the top-right corner","Heap","Union-find"],"c":1,"a":"Not one sorted list. From top-right, each comparison removes a row or a column: O(R + C).","L":"binary-search.html"},{"id":"qz-binary-search-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Binary Search","q":"Search a 2-D matrix of R × C (rows sorted, each row starts after the previous ends) by treating it as one array. Time?","code":"","o":["O(R + C)","O(log(R · C))","O(R log C)","O(R · C)"],"c":1,"a":"It’s one sorted array of R·C items: log₂(R·C) halvings.","L":"binary-search.html"},{"id":"qz-binary-search-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Binary Search","q":"Ship packages within D days: binary search capacity in [max(w), sum(w)], each check is O(n). Time?","code":"","o":["O(n)","O(n log(sum w))","O(n²)","O(log n)"],"c":1,"a":"log of the answer range × O(n) per feasibility check.","L":"binary-search.html"},{"id":"qz-linked-list-l1","y":"quiz","lb":"","tr":"dsa","s":"Linked List","q":"In reverse, what happens if you write <code>curr.next = prev</code> <i>before</i> saving <code>nxt = curr.next</code>?","code":"","o":["Nothing","The rest of the list becomes unreachable, so the loop stops after one node","Infinite loop","It still works in Python"],"c":1,"a":"curr.next was the only reference to the remaining nodes.","L":"linked-list.html"},{"id":"qz-linked-list-l2","y":"quiz","lb":"","tr":"dsa","s":"Linked List","q":"Remove Nth From End uses a dummy and moves fast <code>n + 1</code> steps. Why n + 1 and not n?","code":"","o":["Off-by-one doesn’t matter","So slow stops at the node <i>before</i> the target, which is the one you need to rewire","Because lists are 1-indexed","To handle cycles"],"c":1,"a":"Deleting needs the predecessor. The dummy makes the predecessor exist even when the head is removed.","L":"linked-list.html"},{"id":"qz-linked-list-l3","y":"quiz","lb":"","tr":"dsa","s":"Linked List","q":"For 1 → 2 → 3 → 4 → 5 → 6, which node does <code>while fast and fast.next</code> return?","code":"","o":["3","4","Either, randomly","6"],"c":1,"a":"This version returns the second middle. Starting fast at head.next returns the first middle, which is what merge sort needs.","L":"linked-list.html"},{"id":"qz-linked-list-d1","y":"quiz","lb":"Which tool?","tr":"dsa","s":"Linked List","q":"“Rotate the list to the right by k places.”","code":"","o":["Reverse three times","Find length, close the ring, cut at n − k % n","Fast and slow only","Heap"],"c":1,"a":"Rotation is just choosing a new head on a ring.","L":"linked-list.html"},{"id":"qz-linked-list-d2","y":"quiz","lb":"Which tool?","tr":"dsa","s":"Linked List","q":"“Sort a linked list in O(n log n).”","code":"","o":["Copy to an array","Merge sort: split at the middle with fast/slow, merge with a dummy","Quick sort","Heap of all nodes"],"c":1,"a":"Merge sort needs no random access, just splitting and merging.","L":"linked-list.html"},{"id":"qz-linked-list-d3","y":"quiz","lb":"Which tool?","tr":"dsa","s":"Linked List","q":"“Partition the list so all nodes &lt; x come before nodes ≥ x, keeping order.” (86)","code":"","o":["Two dummy lists, then join them","Reverse","Fast and slow","Sort"],"c":0,"a":"Build “small” and “big” lists with their own dummies and tails, then connect small’s tail to big’s head.","L":"linked-list.html"},{"id":"qz-linked-list-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Linked List","q":"Merge two sorted lists of lengths m and n iteratively. Time and extra space?","code":"","o":["O(m·n), O(1)","O(m + n), O(1)","O(m + n), O(m + n)","O(log(m + n)), O(1)"],"c":1,"a":"Each step moves one node; relinking existing nodes needs no new memory.","L":"linked-list.html"},{"id":"qz-linked-list-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Linked List","q":"Copy a list into a Python list, sort it, rebuild the linked list. Time and space?","code":"","o":["O(n), O(1)","O(n log n), O(n)","O(n²), O(1)","O(n log n), O(1)"],"c":1,"a":"The sort dominates time; the copy is O(n) space. Merge sort on the list itself can do O(n log n) with O(log n) stack.","L":"linked-list.html"},{"id":"qz-recursion-q1","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"What does <code>f(3)</code> print?","code":"def f(n):\n    if n == 0:\n        return\n    print(n)\n    f(n - 1)","o":["3 2 1","1 2 3","3 2 1 0","Nothing"],"c":0,"a":"The print happens <i>before</i> the recursive call, so each frame speaks on the way down: 3, then 2, then 1. The base case prints nothing.","L":"recursion.html"},{"id":"qz-recursion-q2","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"Now the print moved below the call. What does <code>f(3)</code> print?","code":"def f(n):\n    if n == 0:\n        return\n    f(n - 1)\n    print(n)","o":["3 2 1","1 2 3","0 1 2 3","3 3 3"],"c":1,"a":"Each print waits until the call below it returns. The deepest frame (n = 1) finishes first, so output comes on the way back up: 1, 2, 3. This exact difference is preorder vs postorder.","L":"recursion.html"},{"id":"qz-recursion-q3","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"How many calls does naive <code>fib(5)</code> make in total?","code":"","o":["5","9","15","32"],"c":2,"a":"calls(n) = calls(n−1) + calls(n−2) + 1, giving 1, 1, 3, 5, 9, 15. It grows roughly like 1.6ⁿ. With memoization it drops to 9 calls, only 6 of which do real work.","L":"recursion.html"},{"id":"qz-recursion-q4","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"Which traversal of a binary search tree returns the values in sorted order?","code":"","o":["Preorder","Inorder","Postorder","Level order"],"c":1,"a":"Inorder visits left subtree, node, right subtree. In a BST everything on the left is smaller and everything on the right is bigger, so the output comes out sorted. Great for “kth smallest” and validating a BST.","L":"recursion.html"},{"id":"qz-recursion-q5","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"A node needs both subtrees' answers before it can compute its own (height, deleting the tree). Which order is that?","code":"","o":["Preorder","Inorder","Postorder","Level order"],"c":2,"a":"Postorder handles both children first and the node last. That's why the bottom-up template (ask left, ask right, combine) is postorder.","L":"recursion.html"},{"id":"qz-recursion-q6","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"Spot the bug. What does <code>subsets([1, 2])</code> return?","code":"def subsets(nums):\n    res, path = [], []\n    def backtrack(start):\n        res.append(path)        # <- look here\n        for i in range(start, len(nums)):\n            path.append(nums[i])\n            backtrack(i + 1)\n            path.pop()\n    backtrack(0)\n    return res","o":["[[], [1], [1, 2], [2]]","[[], [], [], []]","[[1, 2]]","It raises an error"],"c":1,"a":"<code>res</code> holds four references to the <i>same</i> list. After all the pops, that list is empty, so every entry shows <code>[]</code>. Always snapshot: <code>path[:]</code> or <code>list(path)</code>.","L":"recursion.html"},{"id":"qz-recursion-q7","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"Combination Sum lets you reuse a number, e.g. <code>[2, 2, 3]</code> for target 7. Which recursive call makes reuse possible?","code":"","o":["backtrack(i + 1, remaining - c[i])","backtrack(i, remaining - c[i])","backtrack(0, remaining - c[i])","backtrack(start + 1, remaining - c[i])"],"c":1,"a":"Passing <code>i</code> lets the next level pick the same element again, while still never looking back at smaller indexes. Passing 0 would allow reuse but produce reordered duplicates like [2, 3, 2].","L":"recursion.html"},{"id":"qz-recursion-q8","y":"quiz","lb":"","tr":"dsa","s":"Recursion & Backtracking","q":"In Subsets II on <code>[1, 2, 2]</code>, someone writes <code>if i &gt; 0 and nums[i] == nums[i-1]: continue</code>. What goes missing?","code":"","o":["[2, 2] and [1, 2, 2]","Only []","Nothing, it still works","[1]"],"c":0,"a":"<code>i &gt; 0</code> also blocks taking the second 2 <i>deeper</i> on a branch that already took the first 2. We only want to skip twins that are siblings at the same level, which is exactly what <code>i &gt; start</code> means.","L":"recursion.html"},{"id":"qz-recursion-d1","y":"quiz","lb":"Name the pattern","tr":"dsa","s":"Recursion & Backtracking","q":"“Return every possible arrangement of the letters in <code>\"abc\"</code>.”","code":"","o":["Start index, record every node","used[], record at full length","Grid DFS with marking","Bottom-up tree recursion"],"c":1,"a":"“Arrangement” means order matters. Loop from 0 every time and track which letters are already placed.","L":"recursion.html"},{"id":"qz-recursion-d2","y":"quiz","lb":"Name the pattern","tr":"dsa","s":"Recursion & Backtracking","q":"“Coins can be used unlimited times. List every combination that adds up to the amount.”","code":"","o":["used[], record at full length","Start index, recurse with i + 1","Start index, recurse with i","Level-order BFS"],"c":2,"a":"A combination, so order doesn't matter: start index. Unlimited reuse: recurse with <code>i</code>. Sort and break when a coin exceeds what's left.","L":"recursion.html"},{"id":"qz-recursion-d3","y":"quiz","lb":"Name the pattern","tr":"dsa","s":"Recursion & Backtracking","q":"“Split <code>\"aab\"</code> into pieces so every piece is a palindrome. Return all ways.”","code":"","o":["Try every cut end from a start index","used[] permutations","Two-pointer only","Postorder on a tree"],"c":0,"a":"Partition problems choose where the next piece ends. Loop <code>end</code> from start + 1, prune non-palindromes, recurse from <code>end</code>.","L":"recursion.html"},{"id":"qz-recursion-d4","y":"quiz","lb":"Name the pattern","tr":"dsa","s":"Recursion & Backtracking","q":"“Can the word be formed from sequentially adjacent cells, each used once?”","code":"","o":["Start index subsets","Grid DFS: mark, explore 4 ways, unmark","Inorder traversal","Sort and skip duplicates"],"c":1,"a":"Adjacent cells, each used once: classic grid backtracking. Mark before exploring, unmark on the way out.","L":"recursion.html"},{"id":"qz-recursion-d5","y":"quiz","lb":"Name the pattern","tr":"dsa","s":"Recursion & Backtracking","q":"“Is this binary tree height-balanced?”","code":"","o":["Top-down, pass depth as a parameter","Bottom-up: return heights, combine","Backtracking with used[]","Level order with a queue"],"c":1,"a":"Each node needs both subtree heights to decide, so return heights upward. Return −1 as a “not balanced” signal to stop early.","L":"recursion.html"},{"id":"qz-recursion-cq1","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Time complexity?","code":"def f(n):\n    if n <= 1:\n        return 1\n    return f(n - 1) + f(n - 1)","o":["O(n)","O(n²)","O(2ⁿ)","O(log n)"],"c":2,"a":"2 calls on n − 1 with O(1) work: levels of 1, 2, 4, … 2ⁿ. Bottom-heavy → O(2ⁿ). (Writing <code>2 * f(n - 1)</code> would make it O(n).)","L":"recursion.html"},{"id":"qz-recursion-cq2","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Time complexity?","code":"def f(n):\n    if n <= 1:\n        return\n    for i in range(n):\n        work()\n    f(n // 2)","o":["O(n log n)","O(n)","O(log n)","O(n²)"],"c":1,"a":"One call on n/2, O(n) loop: n + n/2 + n/4 + … ≈ 2n. Top-heavy → O(n).","L":"recursion.html"},{"id":"qz-recursion-cq3","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Space complexity of naive <code>fib(n)</code> (not counting the answer)?","code":"","o":["O(2ⁿ)","O(n)","O(1)","O(log n)"],"c":1,"a":"Millions of calls, but at most n frames alive at once: the depth of the tree.","L":"recursion.html"},{"id":"qz-recursion-cq4","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Time complexity?","code":"def is_pal(s):\n    if len(s) <= 1:\n        return True\n    return s[0] == s[-1] and is_pal(s[1:-1])","o":["O(n)","O(n²)","O(log n)","O(n log n)"],"c":1,"a":"n/2 calls, but <code>s[1:-1]</code> copies the string each time: n + (n−2) + (n−4) + … ≈ n²/4 → O(n²). Pass indices to get O(n).","L":"recursion.html"},{"id":"qz-recursion-cq5","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Time complexity?","code":"def f(a, lo, hi):\n    if lo >= hi:\n        return\n    mid = (lo + hi) // 2\n    f(a, lo, mid)\n    f(a, mid + 1, hi)\n    for i in range(lo, hi + 1):\n        visit(a[i])","o":["O(n)","O(n log n)","O(n²)","O(log n)"],"c":1,"a":"Two calls on halves plus O(n) work per call: every level costs n, log n levels → O(n log n). It’s merge sort’s shape.","L":"recursion.html"},{"id":"qz-recursion-cq6","y":"quiz","lb":"What is the complexity?","tr":"dsa","s":"Recursion & Backtracking","q":"Grid paths with memo: <code>paths(r, c) = paths(r-1, c) + paths(r, c-1)</code> on an m × n grid. Time?","code":"","o":["O(2^(m+n))","O(m · n)","O(m + n)","O((m+n)!)"],"c":1,"a":"m·n distinct states, O(1) work each. Without memo it would be exponential.","L":"recursion.html"},{"id":"qz-heap-p1","y":"quiz","lb":"","tr":"dsa","s":"Heap","q":"In an array-stored heap, where are the children of index 3?","code":"","o":["4 and 5","6 and 7","7 and 8","1 and 2"],"c":2,"a":"Children are 2i + 1 and 2i + 2: 7 and 8. The parent of i is (i − 1) // 2.","L":"heap.html"},{"id":"qz-heap-p2","y":"quiz","lb":"","tr":"dsa","s":"Heap","q":"Turning an unsorted list of n items into a heap with <code>heapify</code> costs…","code":"","o":["O(n log n)","O(n)","O(log n)","O(n²)"],"c":1,"a":"Most nodes are near the bottom and sift down only a little; the sum is linear.","L":"heap.html"},{"id":"qz-heap-p3","y":"quiz","lb":"","tr":"dsa","s":"Heap","q":"To find the 10 largest values in a stream of a billion numbers, use…","code":"","o":["A max-heap of all numbers","A min-heap capped at size 10","Sort everything","A max-heap capped at size 10"],"c":1,"a":"The min-heap’s root is the weakest of your current top 10, the one to evict.","L":"heap.html"},{"id":"qz-heap-p4","y":"quiz","lb":"","tr":"dsa","s":"Heap","q":"In a min-heap, is <code>heap[1]</code> always the second smallest value?","code":"","o":["Yes","No: the second smallest is heap[1] or heap[2]","Only if the heap is sorted","Only for even sizes"],"c":1,"a":"The two children of the root aren’t ordered relative to each other.","L":"heap.html"},{"id":"qz-heap-d1","y":"quiz","lb":"Which heap?","tr":"dsa","s":"Heap","q":"“Find the k pairs with the smallest sums from two sorted arrays.” (373)","code":"","o":["Min-heap seeded with (a[i] + b[0], i, 0), push (i, j + 1) on pop","Sort all pairs","Two pointers","Max-heap of everything"],"c":0,"a":"It’s merge k sorted lists in disguise: each row i is a sorted list a[i] + b[j].","L":"heap.html"},{"id":"qz-heap-d2","y":"quiz","lb":"Which heap?","tr":"dsa","s":"Heap","q":"“Minimum cost to connect sticks: always join the two shortest.” (1167)","code":"","o":["Max-heap","Min-heap: pop two, push their sum","Sort once","Stack"],"c":1,"a":"Each step needs the two smallest current values, which change after every merge.","L":"heap.html"},{"id":"qz-heap-d3","y":"quiz","lb":"Which heap?","tr":"dsa","s":"Heap","q":"“Return the k most frequent words, ties broken alphabetically.” (692)","code":"","o":["Min-heap of size k with key (count, reversed word order)","Plain sort by count","Stack","Two heaps"],"c":0,"a":"Size-k heap; the tiebreak must make the alphabetically larger word the “weaker” one.","L":"heap.html"},{"id":"qz-heap-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Heap","q":"Merge k sorted lists with N total nodes using a heap of the k current heads. Time?","code":"","o":["O(N k)","O(N log k)","O(N log N)","O(k log N)"],"c":1,"a":"Each of the N nodes is pushed and popped once on a heap of size k.","L":"heap.html"},{"id":"qz-heap-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Heap","q":"Median of a stream with two heaps. Cost per insertion?","code":"","o":["O(1)","O(log n)","O(n)","O(n log n)"],"c":1,"a":"A push and possibly one rebalance move between heaps: a constant number of O(log n) operations.","L":"heap.html"},{"id":"qz-trie-t1","y":"quiz","lb":"","tr":"dsa","s":"Trie","q":"You inserted only “cat”. What do <code>search(\"ca\")</code> and <code>startsWith(\"ca\")</code> return?","code":"","o":["True, True","False, True","False, False","True, False"],"c":1,"a":"The path c → a exists, but no word ends at “a”.","L":"trie.html"},{"id":"qz-trie-t2","y":"quiz","lb":"","tr":"dsa","s":"Trie","q":"Searching a word of length L in a trie holding N words costs…","code":"","o":["O(N)","O(log N)","O(L)","O(N · L)"],"c":2,"a":"You walk one node per character; N doesn’t matter.","L":"trie.html"},{"id":"qz-trie-t3","y":"quiz","lb":"","tr":"dsa","s":"Trie","q":"Wildcard search for a pattern of only dots, like “...”, in the worst case visits…","code":"","o":["One path","Every node down to depth 3","Only end nodes","Nothing"],"c":1,"a":"Every “.” branches into every child, so it’s a full DFS of the top levels.","L":"trie.html"},{"id":"qz-trie-d1","y":"quiz","lb":"Trie or not?","tr":"dsa","s":"Trie","q":"“Given a dictionary, check whether each of q query words exists.”","code":"","o":["Trie required","A set is enough","Heap","Union-find"],"c":1,"a":"Exact lookups only: a set is simpler.","L":"trie.html"},{"id":"qz-trie-d2","y":"quiz","lb":"Trie or not?","tr":"dsa","s":"Trie","q":"“Count how many dictionary words have each query as a prefix.”","code":"","o":["Set","Trie with counts on nodes","Sort and scan","Stack"],"c":1,"a":"Prefix counts → counter stored on each trie node.","L":"trie.html"},{"id":"qz-trie-d3","y":"quiz","lb":"Trie or not?","tr":"dsa","s":"Trie","q":"“A stream of characters; after each one, report whether some dictionary word is a suffix of what you’ve seen.” (1032)","code":"","o":["Trie of reversed words, walk backward from the newest char","Set of words","Heap","Binary search"],"c":0,"a":"Suffix matching becomes prefix matching once words and the stream are reversed.","L":"trie.html"},{"id":"qz-trie-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Trie","q":"Insert N words of average length L into a trie. Total time?","code":"","o":["O(N)","O(N · L)","O(L)","O(N log N)"],"c":1,"a":"Each word costs O(L); N of them → O(N·L), i.e. the total number of characters.","L":"trie.html"},{"id":"qz-trie-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Trie","q":"Word Search II prunes the board DFS with a trie of the dictionary. Why does the trie help?","code":"","o":["It sorts the words","A path stops as soon as its prefix isn’t in any word","It removes duplicates","It makes DFS iterative"],"c":1,"a":"Dead prefixes are cut immediately, instead of running one DFS per word.","L":"trie.html"},{"id":"qz-graphs-g1","y":"quiz","lb":"","tr":"dsa","s":"Graphs","q":"Number of Islands: what if you never mark land as visited during the flood?","code":"","o":["It still works, just slower","The DFS loops forever between neighbouring land cells","It counts water","It returns 0"],"c":1,"a":"Two land neighbours keep calling each other. Sink the cell (or add it to a set) before recursing.","L":"graphs.html"},{"id":"qz-graphs-g2","y":"quiz","lb":"","tr":"dsa","s":"Graphs","q":"Shortest path in an <b>unweighted</b> graph: which traversal?","code":"","o":["DFS","BFS","Either; same result","Dijkstra is required"],"c":1,"a":"BFS explores by distance. DFS may find a long path first.","L":"graphs.html"},{"id":"qz-graphs-g3","y":"quiz","lb":"","tr":"dsa","s":"Graphs","q":"Kahn’s algorithm returns only 4 of 6 courses. What does that mean?","code":"","o":["Two courses have no prerequisites","There’s a cycle among the missing courses","A bug","Two courses are disconnected"],"c":1,"a":"Disconnected courses still come out (in-degree 0). Only a cycle keeps nodes stuck.","L":"graphs.html"},{"id":"qz-graphs-g4","y":"quiz","lb":"","tr":"dsa","s":"Graphs","q":"In union-find, <code>union(a, b)</code> finds <code>find(a) == find(b)</code>. What does that tell you?","code":"","o":["a and b are the same node","a and b were already connected, so edge (a, b) closes a cycle","The parents array is broken","You must restart"],"c":1,"a":"This is exactly how Redundant Connection and Graph Valid Tree detect cycles.","L":"graphs.html"},{"id":"qz-graphs-g5","y":"quiz","lb":"","tr":"dsa","s":"Graphs","q":"Can Dijkstra handle a graph with negative edge weights?","code":"","o":["Yes, always","No: a settled node might later be reachable more cheaply","Only if the graph is a tree","Only with a max-heap"],"c":1,"a":"Use Bellman-Ford for negative weights.","L":"graphs.html"},{"id":"qz-graphs-d1","y":"quiz","lb":"Which algorithm?","tr":"dsa","s":"Graphs","q":"“Minimum knight moves from (0, 0) to (x, y) on an infinite board.”","code":"","o":["DFS","BFS over positions","Dijkstra","Union-find"],"c":1,"a":"Every move costs 1: BFS on an implicit graph of positions.","L":"graphs.html"},{"id":"qz-graphs-d2","y":"quiz","lb":"Which algorithm?","tr":"dsa","s":"Graphs","q":"“Accounts with a shared email belong to the same person; merge them.” (721)","code":"","o":["Topological sort","Union-find over emails (or DFS)","Dijkstra","Two pointers"],"c":1,"a":"Grouping by shared items is connected components; union-find handles it directly.","L":"graphs.html"},{"id":"qz-graphs-d3","y":"quiz","lb":"Which algorithm?","tr":"dsa","s":"Graphs","q":"“Path with minimum effort: minimize the largest height difference along the path.” (1631)","code":"","o":["BFS","Dijkstra with max instead of sum (or binary search + BFS)","Topological sort","Kruskal only"],"c":1,"a":"Minimax path → Dijkstra on the max edge so far.","L":"graphs.html"},{"id":"qz-graphs-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Graphs","q":"Number of islands with DFS on a 1000 × 1000 grid. Roughly how many cell visits?","code":"","o":["~1,000","~1,000,000","~10⁹","~2¹⁰⁰⁰"],"c":1,"a":"Each of the 10⁶ cells is visited a constant number of times: O(R·C).","L":"graphs.html"},{"id":"qz-graphs-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Graphs","q":"Course Schedule (Kahn’s topological sort) with V courses and E prerequisites. Time?","code":"","o":["O(V²)","O(V + E)","O(E log V)","O(V · E)"],"c":1,"a":"Each course enters the queue once, each prerequisite edge decrements one in-degree once.","L":"graphs.html"},{"id":"qz-dp-p1","y":"quiz","lb":"","tr":"dsa","s":"Dynamic Programming","q":"Why is plain recursive <code>climb(n)</code> exponential?","code":"","o":["Recursion is slow in Python","It recomputes the same smaller n many times in different branches","The base case is wrong","It uses too much memory"],"c":1,"a":"climb(n − 2) is computed by climb(n) and again inside climb(n − 1), and so on all the way down.","L":"dp.html"},{"id":"qz-dp-p2","y":"quiz","lb":"","tr":"dsa","s":"Dynamic Programming","q":"In House Robber, what exactly does <code>dp[i]</code> mean?","code":"","o":["Money in house i","Best total from the first i houses","Whether house i is robbed","Best total if house i is robbed"],"c":1,"a":"A precise state sentence makes the recurrence obvious: skip → dp[i − 1], take → dp[i − 2] + nums[i − 1].","L":"dp.html"},{"id":"qz-dp-p3","y":"quiz","lb":"","tr":"dsa","s":"Dynamic Programming","q":"Coin Change II counts combinations with coins as the outer loop. If you swap the loops, you count…","code":"","o":["The same thing","Ordered sequences (permutations) instead of combinations","Only one combination","Nothing; it errors"],"c":1,"a":"Amount outer tries every coin as the last one, so 1 + 2 and 2 + 1 count separately.","L":"dp.html"},{"id":"qz-dp-p4","y":"quiz","lb":"","tr":"dsa","s":"Dynamic Programming","q":"0/1 knapsack in one row, but the capacity loop goes <b>forward</b>. What breaks?","code":"","o":["Nothing","Items can be reused, making it unbounded knapsack","It gets slower","The answer is always 0"],"c":1,"a":"dp[c − w] was already updated by this item, so the item can be counted again.","L":"dp.html"},{"id":"qz-dp-p5","y":"quiz","lb":"","tr":"dsa","s":"Dynamic Programming","q":"In LCS, the last characters match. Which cell do you extend?","code":"","o":["Above","Left","Diagonal (both prefixes shorter by one)","Max of all three"],"c":2,"a":"The match uses one character from each string, so both prefixes shrink.","L":"dp.html"},{"id":"qz-dp-d1","y":"quiz","lb":"Name the state","tr":"dsa","s":"Dynamic Programming","q":"“Minimum number of perfect squares that sum to n.” (279)","code":"","o":["dp[i] = fewest squares summing to i, unbounded knapsack","Greedy largest square first","BFS only","Binary search"],"c":0,"a":"Exactly coin change with coins 1, 4, 9, …","L":"dp.html"},{"id":"qz-dp-d2","y":"quiz","lb":"Name the state","tr":"dsa","s":"Dynamic Programming","q":"“Is s3 an interleaving of s1 and s2?” (97)","code":"","o":["dp[i][j] = can s1[:i] and s2[:j] form s3[:i + j]","Two pointers greedy","Stack","Heap"],"c":0,"a":"Two-string DP: the last character of s3[:i + j] came from s1 or from s2.","L":"dp.html"},{"id":"qz-dp-d3","y":"quiz","lb":"Name the state","tr":"dsa","s":"Dynamic Programming","q":"“Max profit with at most 2 transactions.” (123)","code":"","o":["State machine: buy1, sell1, buy2, sell2","Greedy","Sort prices","Prefix sums only"],"c":0,"a":"Each day updates four states from yesterday’s values.","L":"dp.html"},{"id":"qz-dp-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Dynamic Programming","q":"Coin change (min coins) for amount A with C coin types, bottom-up. Time and space?","code":"","o":["O(A + C), O(A)","O(A · C), O(A)","O(C^A), O(A)","O(A²), O(1)"],"c":1,"a":"A states × C choices each; the table is size A + 1.","L":"dp.html"},{"id":"qz-dp-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Dynamic Programming","q":"Edit distance between strings of length m and n. Best possible space with the usual DP?","code":"","o":["O(m·n)","O(min(m, n))","O(1)","O(m + n)²"],"c":1,"a":"Each row needs only the previous row; make the row the shorter string.","L":"dp.html"},{"id":"qz-greedy-intervals-q1","y":"quiz","lb":"","tr":"dsa","s":"Greedy & Intervals","q":"Jump Game with <code>nums = [3, 2, 1, 0, 4]</code>: what happens?","code":"","o":["Returns True","At i = 4, reach is only 3, so it returns False","Infinite loop","Returns 4"],"c":1,"a":"Every path lands on index 3, whose 0 traps you.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-q2","y":"quiz","lb":"","tr":"dsa","s":"Greedy & Intervals","q":"Kadane: what does <code>cur = max(x, cur + x)</code> do when cur is negative?","code":"","o":["Keeps adding","Starts a new run at x, since a negative prefix only lowers the sum","Resets best","Skips x"],"c":1,"a":"x alone beats x plus something negative.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-q3","y":"quiz","lb":"","tr":"dsa","s":"Greedy & Intervals","q":"To keep the most non-overlapping intervals, sort by…","code":"","o":["Start","End","Length","It doesn’t matter"],"c":1,"a":"Finishing earliest leaves the most room. Sorting by start can pick one long interval that blocks many.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-q4","y":"quiz","lb":"","tr":"dsa","s":"Greedy & Intervals","q":"Are <code>[1, 2]</code> and <code>[2, 3]</code> overlapping?","code":"","o":["Always yes","Always no","It depends on the problem: check whether touching endpoints count","Only if sorted"],"c":2,"a":"Merge Intervals (56) merges them; Non-overlapping Intervals (435) treats them as compatible. Read the statement.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-d1","y":"quiz","lb":"Greedy or not?","tr":"dsa","s":"Greedy & Intervals","q":"“Fewest coins to make an amount with coins [1, 3, 4].”","code":"","o":["Greedy: largest coin first","DP: greedy fails (6 = 3 + 3, not 4 + 1 + 1)","Sort by end","Kadane"],"c":1,"a":"No exchange argument holds for arbitrary coin systems.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-d2","y":"quiz","lb":"Greedy or not?","tr":"dsa","s":"Greedy & Intervals","q":"“Minimum number of platforms so no train waits.”","code":"","o":["Sweep arrivals and departures","DP","Backtracking","Binary search only"],"c":0,"a":"It’s Meeting Rooms II with trains.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-d3","y":"quiz","lb":"Greedy or not?","tr":"dsa","s":"Greedy & Intervals","q":"“Assign cookies to children so the most children are content.” (455)","code":"","o":["Sort both; give each child the smallest cookie that satisfies them","DP over subsets","Heap only","Union-find"],"c":0,"a":"Using the smallest sufficient cookie never hurts a later child: exchange argument.","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Greedy & Intervals","q":"Insert one interval into an already sorted, non-overlapping list. Best time?","code":"","o":["O(n log n)","O(n)","O(log n)","O(n²)"],"c":1,"a":"No sort needed: one pass to copy, merge and copy the rest. (Binary search finds the spot in O(log n), but the output still costs O(n).)","L":"greedy-intervals.html"},{"id":"qz-greedy-intervals-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Greedy & Intervals","q":"Jump Game greedy: track the farthest reachable index in one pass. Time and space?","code":"","o":["O(n²), O(n)","O(n), O(1)","O(n log n), O(1)","O(2ⁿ), O(n)"],"c":1,"a":"One loop, one variable. The DP version would be O(n²).","L":"greedy-intervals.html"},{"id":"qz-bits-b1","y":"quiz","lb":"","tr":"dsa","s":"Bit Manipulation","q":"What is <code>5 ^ 3 ^ 5</code>?","code":"","o":["13","3","5","0"],"c":1,"a":"The two 5s cancel; order doesn’t matter.","L":"bits.html"},{"id":"qz-bits-b2","y":"quiz","lb":"","tr":"dsa","s":"Bit Manipulation","q":"What is <code>12 &amp; 11</code>? (12 = 1100, 11 = 1011)","code":"","o":["8","4","0","12"],"c":0,"a":"1100 &amp; 1011 = 1000 = 8: the lowest set bit of 12 was erased.","L":"bits.html"},{"id":"qz-bits-b3","y":"quiz","lb":"","tr":"dsa","s":"Bit Manipulation","q":"What is <code>12 &amp; −12</code>?","code":"","o":["12","4","8","1"],"c":1,"a":"It keeps only the lowest set bit of 1100, which is 0100 = 4.","L":"bits.html"},{"id":"qz-bits-b4","y":"quiz","lb":"","tr":"dsa","s":"Bit Manipulation","q":"In Python, <code>~5</code> is…","code":"","o":["2","−6","4294967290","Error"],"c":1,"a":"~x = −x − 1 for Python’s unbounded ints. Use a 32-bit mask when a problem assumes fixed width.","L":"bits.html"},{"id":"qz-bits-d1","y":"quiz","lb":"Name the trick","tr":"dsa","s":"Bit Manipulation","q":"“Find the number that appears once when every other appears exactly three times.”","code":"","o":["XOR all","Count bits mod 3","Sort","x &amp; −x"],"c":1,"a":"XOR only cancels pairs; triples need counting mod 3.","L":"bits.html"},{"id":"qz-bits-d2","y":"quiz","lb":"Name the trick","tr":"dsa","s":"Bit Manipulation","q":"“Hamming distance between x and y.”","code":"","o":["Popcount of x ^ y","x &amp; y","x | y","Sum of digits"],"c":0,"a":"x ^ y has 1s exactly where they differ; count them.","L":"bits.html"},{"id":"qz-bits-d3","y":"quiz","lb":"Name the trick","tr":"dsa","s":"Bit Manipulation","q":"“Shortest path that visits every node in a small graph (n ≤ 12).” (847)","code":"","o":["Plain BFS by node","BFS over states (node, visited mask)","Union-find","Kadane"],"c":1,"a":"The visited set is part of the state; a mask makes it a small integer.","L":"bits.html"},{"id":"qz-bits-cxq1","y":"quiz","lb":"Cost check","tr":"dsa","s":"Bit Manipulation","q":"Single Number: XOR all n elements together. Time and space?","code":"","o":["O(n), O(n)","O(n), O(1)","O(n log n), O(1)","O(1), O(1)"],"c":1,"a":"One pass, one accumulator.","L":"bits.html"},{"id":"qz-bits-cxq2","y":"quiz","lb":"Cost check","tr":"dsa","s":"Bit Manipulation","q":"Generate all subsets of n items with a bitmask from 0 to 2ⁿ − 1, building each subset by checking n bits. Time?","code":"","o":["O(2ⁿ)","O(n · 2ⁿ)","O(n²)","O(n!)"],"c":1,"a":"2ⁿ masks × n bit checks each.","L":"bits.html"},{"id":"qz-sd-start-s1","y":"quiz","lb":"","tr":"sd","s":"Start Here: Design Thinking","q":"A food app adds new discount types every month (flat, %, BOGO, first-order). What should you isolate behind an interface?","code":"","o":["The Order class","The discount rule","The database","The restaurant list"],"c":1,"a":"The discount rule is the part that keeps changing. <code>interface Discount { Money apply(Cart c); }</code> and one class per rule.","L":"sd-start.html"},{"id":"qz-sd-start-u1","y":"quiz","lb":"Read the diagram","tr":"sd","s":"Start Here: Design Thinking","q":"A <b>dashed</b> line with a <b>hollow triangle</b> from <code>UpiPayment</code> to <code>Payment</code> means…","code":"","o":["UpiPayment extends Payment","UpiPayment implements the Payment interface","UpiPayment uses Payment as a parameter","Payment owns UpiPayment"],"c":1,"a":"Dashed + triangle = implements. Solid + triangle would be extends.","L":"sd-start.html"},{"id":"qz-sd-start-u2","y":"quiz","lb":"Read the diagram","tr":"sd","s":"Start Here: Design Thinking","q":"<code>ParkingLot ◆── * Level</code>. What does it say?","code":"","o":["A level owns many lots","A parking lot owns many levels, which don’t exist without it","Levels are passed in and shared","ParkingLot extends Level"],"c":1,"a":"Filled diamond at the owner = composition; <code>*</code> on the Level end = many levels.","L":"sd-start.html"},{"id":"qz-sd-start-u3","y":"quiz","lb":"Draw it","tr":"sd","s":"Start Here: Design Thinking","q":"<code>class Checkout { void pay(Order o, PaymentGateway g) { g.charge(o); } }</code>. Which line from Checkout to PaymentGateway?","code":"","o":["Composition ◆","Inheritance ▷","Dependency ⇢ (dashed arrow)","Aggregation ◇"],"c":2,"a":"The gateway is only a parameter used during one call: a dependency.","L":"sd-start.html"},{"id":"qz-sd-java-j1","y":"quiz","lb":"","tr":"sd","s":"Java & OOP","q":"What does this print?","code":"List<Integer> a = new ArrayList<>(List.of(1, 2));\nList<Integer> b = a;\nb.add(3);\nSystem.out.println(a.size());","o":["2","3","Compile error","It depends on the JVM"],"c":1,"a":"<code>b = a</code> copies the reference. Both variables point at one list, so adding through b is visible through a.","L":"sd-java.html"},{"id":"qz-sd-java-j2","y":"quiz","lb":"","tr":"sd","s":"Java & OOP","q":"Two <code>Point(1, 2)</code> objects override <code>equals</code> but not <code>hashCode</code>. You put one in a HashSet and call <code>contains</code> with the other. Result?","code":"","o":["Always true","Usually false","Compile error","Throws"],"c":1,"a":"Different default hash codes send the lookup to a different bucket, so equals is never even called.","L":"sd-java.html"},{"id":"qz-sd-java-j3","y":"quiz","lb":"","tr":"sd","s":"Java & OOP","q":"<code>Animal a = new Dog(); greet(a);</code> with overloads <code>greet(Animal)</code> and <code>greet(Dog)</code>. Which runs?","code":"","o":["greet(Dog)","greet(Animal)","Ambiguous, compile error","Depends on runtime"],"c":1,"a":"Overloads are resolved at compile time from the declared type, Animal.","L":"sd-java.html"},{"id":"qz-sd-java-j4","y":"quiz","lb":"","tr":"sd","s":"Java & OOP","q":"Why can’t you write <code>new T()</code> inside a generic class?","code":"","o":["T might be abstract","Type erasure removes T at runtime","Generics only work with interfaces","You can, it just warns"],"c":1,"a":"After compilation T is erased to Object (or its bound), so the JVM doesn’t know which class to construct. Pass a <code>Supplier&lt;T&gt;</code> or a <code>Class&lt;T&gt;</code> instead.","L":"sd-java.html"},{"id":"qz-sd-java-d1","y":"quiz","lb":"Name the concept","tr":"sd","s":"Java & OOP","q":"“A method changes a field on the object you passed, but setting the parameter to a new object has no effect outside.” Why?","code":"","o":["Java is pass-by-reference","Java passes the reference by value","Garbage collection","The object is immutable"],"c":1,"a":"The method gets a copy of the arrow: it can follow it, but repointing the copy doesn’t touch the caller’s variable.","L":"sd-java.html"},{"id":"qz-sd-java-d2","y":"quiz","lb":"Name the concept","tr":"sd","s":"Java & OOP","q":"“Add sound, colour and size options in any combination without a class per combination.”","code":"","o":["Deep inheritance","Composition (HAS-A), e.g. Decorator","Overloading","Static methods"],"c":1,"a":"Combinations multiply with inheritance; composition stacks small objects instead.","L":"sd-java.html"},{"id":"qz-sd-java-d3","y":"quiz","lb":"Name the concept","tr":"sd","s":"Java & OOP","q":"“Several unrelated classes (Invoice, User, Report) must all be exportable.”","code":"","o":["Abstract class Exportable","Interface Exportable","Enum","A static utility"],"c":1,"a":"Unrelated classes sharing a capability, with no shared state: an interface.","L":"sd-java.html"},{"id":"qz-sd-solid-s1","y":"quiz","lb":"","tr":"sd","s":"SOLID","q":"A <code>ReportService</code> has a method with a 9-branch <code>switch(format)</code> for PDF, CSV, XLSX… and product wants JSON next week. Which principle is under pressure?","code":"","o":["SRP","OCP","LSP","ISP"],"c":1,"a":"Adding a format means editing a working method. Put each format behind a <code>ReportFormatter</code> interface.","L":"sd-solid.html"},{"id":"qz-sd-solid-s2","y":"quiz","lb":"","tr":"sd","s":"SOLID","q":"<code>Square extends Rectangle</code>. A test sets width 5, height 4 and expects area 20. With a Square it gets 16. Which principle broke?","code":"","o":["SRP","OCP","LSP","DIP"],"c":2,"a":"A Square can’t be substituted where a Rectangle is expected because it changes the meaning of setWidth/setHeight.","L":"sd-solid.html"},{"id":"qz-sd-solid-s3","y":"quiz","lb":"","tr":"sd","s":"SOLID","q":"Your <code>OrderService</code> unit tests need a running MySQL instance. What’s the best fix?","code":"","o":["Use an in-memory MySQL","Make OrderRepo an interface and inject a fake","Make the repo static","Mock the JDBC driver"],"c":1,"a":"Depend on an abstraction and inject it (DIP); tests pass an in-memory implementation.","L":"sd-solid.html"},{"id":"qz-sd-solid-d1","y":"quiz","lb":"Name the principle","tr":"sd","s":"SOLID","q":"“Printer interface has print, scan and fax. A basic printer throws on scan and fax.”","code":"","o":["SRP","OCP","LSP","ISP"],"c":3,"a":"The interface is too fat. Split into Printable, Scannable, Faxable. (The throwing overrides also smell of LSP.)","L":"sd-solid.html"},{"id":"qz-sd-solid-d2","y":"quiz","lb":"Name the principle","tr":"sd","s":"SOLID","q":"“The User class validates input, hashes passwords, sends welcome emails and writes to the DB.”","code":"","o":["SRP","ISP","DIP","LSP"],"c":0,"a":"Four reasons to change in one class. Split into focused collaborators.","L":"sd-solid.html"},{"id":"qz-sd-solid-d3","y":"quiz","lb":"Name the principle","tr":"sd","s":"SOLID","q":"“NotificationService does <code>new SmtpClient()</code> and we want to add SMS.”","code":"","o":["LSP","DIP (and OCP)","ISP","SRP only"],"c":1,"a":"Depend on a <code>Channel</code> interface and inject implementations; adding SMS becomes a new class.","L":"sd-solid.html"},{"id":"qz-sd-creational-c1","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Creational Patterns","q":"Two threads call the naive lazy <code>getInstance()</code> at the same moment. What can happen?","code":"","o":["Deadlock","Two instances get created","NullPointerException always","Nothing, statics are thread-safe"],"c":1,"a":"Both see null before either assigns. Check-then-act is not atomic without a lock.","L":"sd-creational.html"},{"id":"qz-sd-creational-c2","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Creational Patterns","q":"You need a button, checkbox and menu that all match the OS theme. Which pattern?","code":"","o":["Simple Factory","Factory Method","Abstract Factory","Prototype"],"c":2,"a":"A family of related products that must be consistent → one factory per family.","L":"sd-creational.html"},{"id":"qz-sd-creational-c3","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Creational Patterns","q":"Main reason to validate inside <code>build()</code> rather than in each setter?","code":"","o":["Speed","Rules can involve several fields, checked once on a complete object","Setters can’t throw","Builders must be static"],"c":1,"a":"For example “thin crust can’t have more than 3 toppings” needs both fields at once.","L":"sd-creational.html"},{"id":"qz-sd-creational-c4","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Creational Patterns","q":"<code>Document copy = original.shallowCopy(); copy.pages.add(\"x\");</code> What happens to <code>original.pages</code>?","code":"","o":["Unchanged","Also gets \"x\"","Throws","Becomes null"],"c":1,"a":"A shallow copy shares the same list object. Copy the list: <code>new ArrayList&lt;&gt;(other.pages)</code>.","L":"sd-creational.html"},{"id":"qz-sd-creational-d1","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Creational Patterns","q":"“An HTTP request object with URL, method, 12 optional headers, timeout and body.”","code":"","o":["Singleton","Builder","Prototype","Abstract Factory"],"c":1,"a":"Many optional parts and an immutable result: Builder (exactly what <code>HttpRequest.newBuilder()</code> does).","L":"sd-creational.html"},{"id":"qz-sd-creational-d2","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Creational Patterns","q":"“Create a Car, Bike or Truck object depending on the vehicle type at the parking gate.”","code":"","o":["Factory","Builder","Prototype","Singleton"],"c":0,"a":"The class depends on input → factory returning a Vehicle.","L":"sd-creational.html"},{"id":"qz-sd-creational-d3","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Creational Patterns","q":"“Spawn 500 enemies that share a heavy configuration but then move independently.”","code":"","o":["Singleton","Prototype","Abstract Factory","Builder"],"c":1,"a":"Configure once, copy many. (Shared immutable parts could also use Flyweight.)","L":"sd-creational.html"},{"id":"qz-sd-structural-t1","y":"quiz","lb":"","tr":"sd","s":"Structural Patterns","q":"<code>new Milk(new Milk(new Espresso()))</code> with Espresso = 100 and Milk = +10. What does <code>cost()</code> return?","code":"","o":["110","120","100","Compile error"],"c":1,"a":"Each Milk delegates inward and adds 10: 100 → 110 → 120.","L":"sd-structural.html"},{"id":"qz-sd-structural-t2","y":"quiz","lb":"","tr":"sd","s":"Structural Patterns","q":"Your app expects <code>sendSms(to, text)</code>; the new vendor SDK has <code>dispatch(MessageRequest)</code>. Which pattern?","code":"","o":["Facade","Adapter","Bridge","Decorator"],"c":1,"a":"Translate one interface into another you already depend on.","L":"sd-structural.html"},{"id":"qz-sd-structural-t3","y":"quiz","lb":"","tr":"sd","s":"Structural Patterns","q":"4 notification types × 3 channels with inheritance means 12 classes. With Bridge?","code":"","o":["12","7","4","3"],"c":1,"a":"4 notification classes + 3 channel classes; the notification holds a channel.","L":"sd-structural.html"},{"id":"qz-sd-structural-d1","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Structural Patterns","q":"“Add logging, retries and metrics to an HTTP client, any combination, configurable at startup.”","code":"","o":["Adapter","Decorator","Facade","Flyweight"],"c":1,"a":"Stackable features on the same interface.","L":"sd-structural.html"},{"id":"qz-sd-structural-d2","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Structural Patterns","q":"“Load a high-resolution image only when it’s first displayed.”","code":"","o":["Virtual Proxy","Decorator","Composite","Builder"],"c":0,"a":"Same interface, delays creating the expensive real object.","L":"sd-structural.html"},{"id":"qz-sd-structural-d3","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Structural Patterns","q":"“A menu contains items and submenus; render the whole thing with one call.”","code":"","o":["Composite","Bridge","Facade","Chain of Responsibility"],"c":0,"a":"Part-whole tree with a shared operation.","L":"sd-structural.html"},{"id":"qz-sd-behavioral-b1","y":"quiz","lb":"","tr":"sd","s":"Behavioral Patterns","q":"The order service calls 3 listeners synchronously. The SMS listener takes 4 seconds. What happens to <code>place()</code>?","code":"","o":["Unaffected","It takes at least 4 extra seconds","SMS is skipped","It throws"],"c":1,"a":"Plain Observer runs listeners in the caller’s thread. Make slow listeners async or publish to a queue.","L":"sd-behavioral.html"},{"id":"qz-sd-behavioral-b2","y":"quiz","lb":"","tr":"sd","s":"Behavioral Patterns","q":"An order goes Created → Paid → Shipped → Delivered, and cancel is only allowed before Shipped. Best fit?","code":"","o":["Strategy","State","Observer","Template Method"],"c":1,"a":"A lifecycle with transition rules: each state knows what’s allowed and what comes next.","L":"sd-behavioral.html"},{"id":"qz-sd-behavioral-b3","y":"quiz","lb":"","tr":"sd","s":"Behavioral Patterns","q":"CSV, Excel and JSON importers all validate → parse → save → audit; only parse differs. Pattern?","code":"","o":["Strategy","Template Method","Chain of Responsibility","Command"],"c":1,"a":"Fixed skeleton with one varying step. (Strategy would also work by injecting a Parser; Template uses inheritance.)","L":"sd-behavioral.html"},{"id":"qz-sd-behavioral-d1","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Behavioral Patterns","q":"“Users can undo and redo the last 50 actions in a drawing app.”","code":"","o":["Memento only","Command","Observer","Iterator"],"c":1,"a":"Actions as objects on undo/redo stacks. (Memento can complement it for complex state.)","L":"sd-behavioral.html"},{"id":"qz-sd-behavioral-d2","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Behavioral Patterns","q":"“Leave requests up to 2 days go to the lead, up to 10 to the manager, more to HR.”","code":"","o":["Chain of Responsibility","State","Mediator","Strategy"],"c":0,"a":"Escalating handlers, each either approves or passes it on.","L":"sd-behavioral.html"},{"id":"qz-sd-behavioral-d3","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"Behavioral Patterns","q":"“A stock price changes and all open dashboards must update.”","code":"","o":["Observer","Command","Facade","Memento"],"c":0,"a":"One subject, many subscribers reacting to changes.","L":"sd-behavioral.html"},{"id":"qz-sd-lld-l1","y":"quiz","lb":"","tr":"sd","s":"LLD Problems","q":"Requirement: “Charges are hourly on weekdays and flat on weekends, and the business may add event pricing.” How do you model charging?","code":"","o":["if-else in ParkingLot.exit()","A FeePolicy interface with one class per rule","A field per rule on Ticket","Subclass ParkingLot per rule"],"c":1,"a":"A changing business rule is a Strategy; ParkingLot just calls fees.fee(ticket, now).","L":"sd-lld.html"},{"id":"qz-sd-lld-l2","y":"quiz","lb":"","tr":"sd","s":"LLD Problems","q":"Two cars reach the last free spot at the same moment via different gates (same JVM). What prevents both parking there?","code":"","o":["Nothing; rare enough","A synchronized tryOccupy (check + set in one step)","Making Spot immutable","A larger thread pool"],"c":1,"a":"Claim the spot atomically; the loser moves on to the next spot.","L":"sd-lld.html"},{"id":"qz-sd-lld-l3","y":"quiz","lb":"","tr":"sd","s":"LLD Problems","q":"Elevator at floor 6 going up with requests at 8 and 2. Someone presses 4. Next stop under SCAN?","code":"","o":["4","8","2","Back to 6"],"c":1,"a":"Keep serving requests ahead in the current direction (8) before reversing for 4 and 2.","L":"sd-lld.html"},{"id":"qz-sd-lld-l4","y":"quiz","lb":"","tr":"sd","s":"LLD Problems","q":"Ten app servers book seats. Which actually prevents double booking?","code":"","o":["synchronized on the book() method","ConcurrentHashMap.putIfAbsent","UPDATE … WHERE status = 'FREE' and check rows affected","volatile seat status"],"c":2,"a":"Only shared storage can arbitrate between servers; JVM-level tools only protect one process.","L":"sd-lld.html"},{"id":"qz-sd-lld-d1","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"LLD Problems","q":"“A notification should be sent by email, SMS and push when a booking is confirmed; more channels later.”","code":"","o":["Observer (or Strategy per channel)","Singleton","Builder","Prototype"],"c":0,"a":"Listeners react to the booking-confirmed event; each channel is a pluggable implementation.","L":"sd-lld.html"},{"id":"qz-sd-lld-d2","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"LLD Problems","q":"“A traffic signal cycles Red → Green → Yellow and pedestrians can request a crossing only on Red.”","code":"","o":["Strategy","State","Composite","Facade"],"c":1,"a":"Allowed actions depend on the current light; transitions are owned by the states.","L":"sd-lld.html"},{"id":"qz-sd-lld-d3","y":"quiz","lb":"Pick the pattern","tr":"sd","s":"LLD Problems","q":"“Support multiple elevator dispatch algorithms and switch at night.”","code":"","o":["State","Strategy","Observer","Command"],"c":1,"a":"Interchangeable algorithms chosen by configuration or time: Strategy.","L":"sd-lld.html"},{"id":"qz-sd-basics-b1","y":"quiz","lb":"","tr":"sd","s":"System Design Basics","q":"50M daily active users, each making 20 requests a day. Roughly what average QPS?","code":"","o":["~1k","~10k","~100k","~1M"],"c":1,"a":"10<sup>9</sup> requests / 10<sup>5</sup> s ≈ 10k QPS average (plan for ~30k peak).","L":"sd-basics.html"},{"id":"qz-sd-basics-b2","y":"quiz","lb":"","tr":"sd","s":"System Design Basics","q":"You add a second app server behind a load balancer, and users randomly get logged out. Most likely cause?","code":"","o":["DNS caching","Sessions stored in each server’s memory","The LB is L4","Too few threads"],"c":1,"a":"Stateful servers: the other server doesn’t know the session. Move sessions to Redis or use signed tokens.","L":"sd-basics.html"},{"id":"qz-sd-basics-b3","y":"quiz","lb":"","tr":"sd","s":"System Design Basics","q":"A feed uses <code>?page=500&amp;size=20</code> (OFFSET 10000). Two problems?","code":"","o":["None","Slow deep pages; items skip or repeat when new rows arrive","Only slow","Only duplicates"],"c":1,"a":"OFFSET still reads and discards 10,000 rows, and inserts shift every page. Use a cursor on an indexed key.","L":"sd-basics.html"},{"id":"qz-sd-basics-d1","y":"quiz","lb":"Pick the tool","tr":"sd","s":"System Design Basics","q":"“Live cricket score updates on a web page, millions of viewers, no input from viewers.”","code":"","o":["WebSockets","Server-Sent Events (or CDN-cached polling)","Long polling only","gRPC"],"c":1,"a":"One-way server→client stream; SSE is simpler than WebSockets. Polling a CDN-cached endpoint every few seconds also works at that scale.","L":"sd-basics.html"},{"id":"qz-sd-basics-d2","y":"quiz","lb":"Pick the tool","tr":"sd","s":"System Design Basics","q":"“Client retries POST /payments after a timeout; the first one actually succeeded.”","code":"","o":["Return 409","Idempotency key","Disable retries","Use PUT"],"c":1,"a":"The server recognises the key and returns the original result instead of charging again.","L":"sd-basics.html"},{"id":"qz-sd-basics-d3","y":"quiz","lb":"Pick the tool","tr":"sd","s":"System Design Basics","q":"“Internal service calls are slow JSON over HTTP/1.1, hundreds of thousands per second.”","code":"","o":["GraphQL","gRPC","SOAP","WebSockets"],"c":1,"a":"Binary protobuf over HTTP/2 with multiplexing: built for internal high-throughput RPC.","L":"sd-basics.html"},{"id":"qz-sd-databases-q1","y":"quiz","lb":"","tr":"sd","s":"Databases","q":"An e-commerce checkout must reserve stock, create an order and record a payment, all or nothing. First choice of store?","code":"","o":["Cassandra","Relational DB with a transaction","Redis","Elasticsearch"],"c":1,"a":"Multi-row atomicity and constraints are what relational databases are built for.","L":"sd-databases.html"},{"id":"qz-sd-databases-q2","y":"quiz","lb":"","tr":"sd","s":"Databases","q":"Index on <code>(user_id, created_at)</code>. Which query can NOT use it efficiently?","code":"","o":["WHERE user_id = 5","WHERE user_id = 5 AND created_at > X","WHERE created_at > X","WHERE user_id = 5 ORDER BY created_at"],"c":2,"a":"No user_id condition, so the leftmost column is missing; times are sorted only within each user.","L":"sd-databases.html"},{"id":"qz-sd-databases-q3","y":"quiz","lb":"","tr":"sd","s":"Databases","q":"Two transactions run <code>SELECT stock</code> (both see 1) then <code>UPDATE SET stock = 0</code> and both create an order. What went wrong?","code":"","o":["Dirty read","Lost update / check-then-act race","Phantom read","Deadlock"],"c":1,"a":"Both checked a stale value. Use <code>UPDATE … SET stock = stock - 1 WHERE stock &gt; 0</code> and check rows affected.","L":"sd-databases.html"},{"id":"qz-sd-databases-q4","y":"quiz","lb":"","tr":"sd","s":"Databases","q":"You cache with <code>hash(key) % 10</code> across 10 Redis nodes and add an 11th. Roughly what fraction of keys now map to a different node?","code":"","o":["~1/11","~1/2","~90%","0"],"c":2,"a":"With mod N almost every key changes node; consistent hashing would move about 1/11.","L":"sd-databases.html"},{"id":"qz-sd-databases-d1","y":"quiz","lb":"Pick the store","tr":"sd","s":"Databases","q":"“Store billions of chat messages, always read as the latest 50 in a conversation.”","code":"","o":["MySQL single table","Cassandra partitioned by conversation_id, clustered by time","Neo4j","Elasticsearch"],"c":1,"a":"Append-heavy, one access pattern, partition + clustering key fits exactly.","L":"sd-databases.html"},{"id":"qz-sd-databases-d2","y":"quiz","lb":"Pick the fix","tr":"sd","s":"Databases","q":"“Users sometimes don’t see the comment they just posted.”","code":"","o":["Bigger primary","Read-your-writes: read from primary after a write","Serializable isolation","Drop the replicas"],"c":1,"a":"Replica lag; route that user’s reads to the primary briefly (or wait for the replica to catch up).","L":"sd-databases.html"},{"id":"qz-sd-databases-d3","y":"quiz","lb":"Pick the fix","tr":"sd","s":"Databases","q":"“The orders page runs 101 queries for 100 orders.”","code":"","o":["Add an index","N+1 problem: JOIN FETCH or batch IN query","Add a replica","Increase pool size"],"c":1,"a":"One query for orders plus one per order for items. Fetch them together.","L":"sd-databases.html"},{"id":"qz-sd-distributed-c1","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Caching, Queues & Resilience","q":"After updating a product, you write the new value into the cache (not delete). Two updates race. What can go wrong?","code":"","o":["Nothing","The cache can end up holding the older value indefinitely (until TTL)","The DB gets the old value","Cache crashes"],"c":1,"a":"Writer A updates DB, writer B updates DB and cache, then A’s slower cache write lands last. Deleting the key avoids it.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-c2","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Caching, Queues & Resilience","q":"Topic with 4 partitions, consumer group with 6 consumers. How many consumers receive messages?","code":"","o":["6","4","1","2"],"c":1,"a":"Each partition goes to one consumer in a group; 2 sit idle. Partitions cap parallelism.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-c3","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Caching, Queues & Resilience","q":"Which feature should choose CP over AP?","code":"","o":["Like counts","Social feed","Bank account balance","Online presence dots"],"c":2,"a":"Showing or acting on a stale balance can lose money; better to refuse during a partition.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-c4","y":"quiz","lb":"What is the complexity?","tr":"sd","s":"Caching, Queues & Resilience","q":"Three services in series, each 99.9% available. Approximate end-to-end availability?","code":"","o":["99.9%","99.7%","99.99%","97%"],"c":1,"a":"0.999³ ≈ 0.997.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-d1","y":"quiz","lb":"Pick the tool","tr":"sd","s":"Caching, Queues & Resilience","q":"“After a deploy, every server retries a failing dependency every 100 ms and it never recovers.”","code":"","o":["More retries","Exponential backoff with jitter + circuit breaker","Bigger thread pool","Disable timeouts"],"c":1,"a":"Synchronised retries hammer the dependency; backoff spreads them, a breaker stops them.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-d2","y":"quiz","lb":"Pick the tool","tr":"sd","s":"Caching, Queues & Resilience","q":"“Check whether a username is taken across 1B users without hitting the DB for most checks.”","code":"","o":["HyperLogLog","Bloom filter","Geohash","Count-min sketch"],"c":1,"a":"A Bloom “no” is certain, so most new usernames skip the DB; only “maybe” goes to the DB.","L":"sd-distributed.html"},{"id":"qz-sd-distributed-d3","y":"quiz","lb":"Pick the tool","tr":"sd","s":"Caching, Queues & Resilience","q":"“Order saved in Postgres but the OrderPlaced event sometimes never reaches Kafka.”","code":"","o":["Saga","Outbox pattern","CQRS","Bigger Kafka cluster"],"c":1,"a":"Dual-write gap; write the event to an outbox table in the same transaction.","L":"sd-distributed.html"},{"id":"qz-sd-hld-h1","y":"quiz","lb":"","tr":"sd","s":"HLD Problems","q":"Why not generate the short code as the first 7 characters of MD5(longUrl)?","code":"","o":["MD5 is too slow","Collisions: different URLs can share a prefix, so you need checks and retries","It’s too long","It can’t be Base62"],"c":1,"a":"Truncated hashes collide; counter-based IDs encoded in Base62 are unique by construction.","L":"sd-hld.html"},{"id":"qz-sd-hld-h2","y":"quiz","lb":"","tr":"sd","s":"HLD Problems","q":"A user follows 300 normal people and 2 celebrities with 50M followers each. How does their home feed get the celebrity posts in a hybrid design?","code":"","o":["Pushed into their timeline at post time","Pulled and merged when they open the feed","Not shown","Emailed"],"c":1,"a":"Celebrity posts aren’t fanned out on write; they’re fetched and merged at read time.","L":"sd-hld.html"},{"id":"qz-sd-hld-h3","y":"quiz","lb":"","tr":"sd","s":"HLD Problems","q":"In a chat system, the recipient is connected to a different WebSocket server than the sender. How does the message reach them?","code":"","o":["Broadcast to all servers","Look up the recipient’s server in a presence registry and route via pub/sub","The client polls","Store it and wait"],"c":1,"a":"Presence (user → server) plus pub/sub between connection servers; push notification if offline.","L":"sd-hld.html"},{"id":"qz-sd-hld-h4","y":"quiz","lb":"","tr":"sd","s":"HLD Problems","q":"Where do drivers’ live locations (updated every 4 s) belong in Uber’s design?","code":"","o":["Main Postgres table updated every 4 s","An in-memory geo index (Redis GEO / quadtree)","S3","Kafka only"],"c":1,"a":"High-frequency, short-lived data needing proximity queries → in-memory geo index.","L":"sd-hld.html"},{"id":"qz-sd-hld-d1","y":"quiz","lb":"Name the deep dive","tr":"sd","s":"HLD Problems","q":"“Design Dropbox.”","code":"","o":["Fan-out","Chunking, dedupe by hash and conflict-aware sync","Geo index","Rate limiting"],"c":1,"a":"The interesting part is moving only changed chunks and reconciling versions across devices.","L":"sd-hld.html"},{"id":"qz-sd-hld-d2","y":"quiz","lb":"Name the deep dive","tr":"sd","s":"HLD Problems","q":"“Design an API rate limiter for 10 gateway servers.”","code":"","o":["Local counters per server","Token bucket state in Redis, updated atomically","A SQL table per request","Client-side throttling only"],"c":1,"a":"Shared, atomic state across servers; Lua makes read-refill-decrement one operation.","L":"sd-hld.html"},{"id":"qz-sd-hld-d3","y":"quiz","lb":"Name the deep dive","tr":"sd","s":"HLD Problems","q":"“Design Airbnb booking.”","code":"","o":["Video transcoding","Preventing double booking across date ranges","Typeahead","Fan-out"],"c":1,"a":"Atomic hold of every night in the range, then confirm after payment.","L":"sd-hld.html"},{"id":"rx-hashing-seen","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"“Contains duplicate”, “have we seen this before?”, “first repeated”","a":"A set. Check, then add. One pass.","x":"If the question is really “has this value shown up before?”, keep a set of everything you’ve already looked at. For each new item, check the set first: if it’s there, you found a repeat. If not, add it and move on. You only walk the array once.","L":"hashing.html#rx-seen"},{"id":"rx-hashing-complement","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Two numbers that combine to a target (sum, difference)","a":"Dict value → index. For each x, look up <code>target − x</code> <b>before","x":"When two numbers must add up to a target, each number already tells you its partner: partner = target − x. Keep a dictionary of the numbers you’ve passed (value → index). At each x, first ask “is my partner in the dictionary?”, and only then store x.","L":"hashing.html#rx-complement"},{"id":"rx-hashing-group","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Group things that are “the same” after rearranging (anagrams, shifted strings)","a":"Dict keyed by a canonical form: sorted string, or a tuple of 26 counts.","x":"Words that are “the same after rearranging” should land in the same bucket. Give every word a label that ignores the order of its letters, for example the word with its letters sorted. Use that label as a dictionary key and append the word to its list.","L":"hashing.html#rx-group"},{"id":"rx-hashing-count","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Frequencies: “most common”, “top k frequent”, “is it an anagram”","a":"<code>Counter</code>. For top k without sorting, bucket by frequency (index = count).","x":"Any question about “how often” starts with counting: one dictionary of value → count. To get the k most frequent without sorting, make buckets where the position is the count (bucket 3 holds everything seen 3 times), then read the buckets from the highest count down.","L":"hashing.html#rx-count"},{"id":"rx-hashing-consec","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Longest consecutive run in an unsorted array, in O(n)","a":"Put everything in a set. Only start counting at x where x − 1 is missing.","x":"Sorting would find runs but costs O(n log n). Instead put every number in a set. A run can only start at a number whose left neighbour (x − 1) is missing; from there count up x + 1, x + 2, … while they exist. Every number is counted once, so it’s O(n).","L":"hashing.html#rx-consec"},{"id":"rx-hashing-range","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Many “sum of range” queries on a fixed array","a":"Prefix array with a leading 0: <code>sum(l..r) = pre[r+1] − pre[l]</code>.","x":"If you’ll ask “what’s the sum from l to r?” many times, add up once in advance. pre[i] is the sum of the first i numbers, starting with pre[0] = 0. Then any range is a subtraction: everything up to r, minus everything before l.","L":"hashing.html#rx-range"},{"id":"rx-hashing-subk","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Count subarrays whose sum is k (negatives allowed)","a":"Running sum + dict of prefix counts seeded <code>{0: 1}</code>. Add <code>seen[running − k]</code> each step.","x":"Keep a running total as you walk. A subarray ending here sums to k exactly when some earlier running total equals running − k. So keep a dictionary of how many times each running total has appeared (start with {0: 1} for the empty prefix) and add that count at each step.","L":"hashing.html#rx-subk"},{"id":"rx-hashing-leftright","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Each answer depends on everything to its left and right (product except self, trapping water)","a":"Two passes: left-to-right with a running value, then right-to-left.","x":"When each answer needs “everything on my left” and “everything on my right”, don’t look both ways from every position (that’s O(n²)). Sweep once left → right keeping a running value, sweep once right → left keeping another, and combine.","L":"hashing.html#rx-leftright"},{"id":"rx-hashing-indexhash","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"O(1) extra space and values in the range 1…n","a":"Use the array as its own hash: mark value v by flipping the sign at index v − 1.","x":"With values from 1 to n and no extra memory allowed, the array itself can be your “seen” set: position v − 1 stands for value v. To mark v as seen, make the number at index v − 1 negative. A position still positive at the end means its value never appeared.","L":"hashing.html#rx-indexhash"},{"id":"rx-hashing-rotate","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Rotate a square matrix 90° clockwise in place","a":"Transpose, then reverse each row.","x":"A 90° clockwise turn is two easy moves. Transpose (swap across the diagonal, so rows become columns), then reverse each row. Both happen in place.","L":"hashing.html#rx-rotate"},{"id":"rx-hashing-spiral","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Walk a matrix in a spiral","a":"Four walls: top, bottom, left, right. Walk one edge, move that wall in, repeat while they haven’t crossed.","x":"Picture four walls closing in. Walk the top row left → right then move the top wall down; walk the right column down then move the right wall left; then the bottom row right → left, then the left column up. Repeat while top ≤ bottom and left ≤ right.","L":"hashing.html#rx-spiral"},{"id":"rx-hashing-markers","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Mark rows / columns of a matrix with O(1) extra space","a":"Store the flags in row 0 and column 0. Keep two booleans for whether they had zeros themselves.","x":"To remember which rows and columns contain a zero without another matrix, write the notes into the matrix itself: the first row stores “this column has a zero”, the first column stores “this row has a zero”. Two extra booleans remember whether the first row and column needed zeroing themselves.","L":"hashing.html#rx-markers"},{"id":"rx-hashing-cxhinner","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"An inner loop that searches the input for a partner or a duplicate","a":"Replace it with a set/dict lookup: O(n²) → O(n) time, at the price of O(n) space.","x":"If your code has a loop inside a loop just to find a matching item, the inner loop is a search. A set or dictionary answers “is it here?” in O(1) on average, so the inner loop disappears. You pay with memory for the stored items.","L":"hashing.html#rx-cxhinner"},{"id":"rx-hashing-cxhspace","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"“What’s the space complexity?” for a hashing solution","a":"Count what the dict can hold: up to n keys → O(n). A fixed 26-letter count array → O(1).","x":"Space is “how big can my dictionary get?”. Storing each input value can grow to n keys → O(n). Counting letters of the alphabet never exceeds 26 keys, so it’s O(1), no matter how long the input is.","L":"hashing.html#rx-cxhspace"},{"id":"rx-hashing-cxhkey","y":"reflex","tr":"dsa","s":"Arrays & Hashing","q":"Building a key for each item (sorted string, tuple, serialised path)","a":"Multiply: n items × cost of one key. Sorted key O(n·k log k), count key O(n·k).","x":"When you build a key per item, the cost is (number of items) × (cost of one key). For n words of length k: sorting each word costs k log k, counting its letters costs k.","L":"hashing.html#rx-cxhkey"},{"id":"rx-two-pointers-pairsum","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Sorted array + find a pair with a target sum","a":"<code>l</code> at the start, <code>r</code> at the end. Too small → l += 1. Too big → r −= 1.","x":"In a sorted array, put one finger at each end. If the pair is too small, only moving the left finger right can make it bigger; if too big, move the right finger left. Every step throws away one number for good, so it’s one pass.","L":"two-pointers.html#rx-pairsum"},{"id":"rx-two-pointers-container","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Max area / water between two lines chosen from an array","a":"Start widest. Always move the shorter wall inward.","x":"Area = width × the shorter wall. Start as wide as possible. Moving the taller wall can never help (the short wall still limits you and the width shrinks), so always move the shorter one inward and keep the best area seen.","L":"two-pointers.html#rx-container"},{"id":"rx-two-pointers-threesum","y":"reflex","tr":"dsa","s":"Two Pointers","q":"3Sum, 4Sum, “triplets that sum to …”","a":"Sort. Fix the first number(s) in a loop, two-pointer the rest. Skip equal neighbours to kill duplicates.","x":"Sort first. Then pick the first number with a normal loop and find the other two with the pair-sum fingers on the part to its right. Skipping a number equal to the one before stops the same triplet appearing twice.","L":"two-pointers.html#rx-threesum"},{"id":"rx-two-pointers-palin","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Palindrome check (maybe ignoring symbols, maybe one deletion allowed)","a":"Pointers at both ends, move inward comparing. On a mismatch with one deletion allowed, try skipping either side once.","x":"A palindrome reads the same from both ends, so compare the outermost pair and walk inward. If one deletion is allowed and you hit a mismatch, try deleting the left character or the right one; if either remainder is a palindrome, answer yes.","L":"two-pointers.html#rx-palin"},{"id":"rx-two-pointers-trap","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Trapping rain water","a":"Two pointers with <code>lmax</code> and <code>rmax</code>. Process whichever side has the lower bar.","x":"Water above a bar = (the lower of the tallest wall on its left and on its right) − its height. With a pointer at each end, the side whose wall is lower is the limit, so you can settle that side right away and step inward.","L":"two-pointers.html#rx-trap"},{"id":"rx-two-pointers-slowfast","y":"reflex","tr":"dsa","s":"Two Pointers","q":"“In place”: remove, dedupe, compact, move zeroes","a":"Writer <code>w</code> and reader <code>r</code>. Copy to w only when the reader finds something worth keeping.","x":"To change an array in place, use two indexes: a reader r that looks at every item, and a writer w that marks where the next kept item goes. When the reader finds something worth keeping, copy it to w and move w on. Everything before w is the answer.","L":"two-pointers.html#rx-slowfast"},{"id":"rx-two-pointers-dutch","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Partition into three groups (0/1/2, low/mid/high) in one pass","a":"<code>lo</code>, <code>i</code>, <code>hi</code>. 0 → swap to lo, advance both. 2 → swap to hi, shrink hi, <b>don’t","x":"Keep three zones: everything before lo is 0, everything after hi is 2, and i scans the middle. A 0 is swapped to lo (both move on). A 2 is swapped to hi (hi shrinks, but i stays because the swapped-in value hasn’t been checked). A 1 just lets i move on.","L":"two-pointers.html#rx-dutch"},{"id":"rx-two-pointers-mergeback","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Merge into an array that has empty space at the end","a":"Fill from the back: compare the largest remaining of each, write at the end.","x":"If the first array has empty space at its end, merge from the back. Compare the largest remaining number of each array and write the bigger one into the last free slot. Nothing you still need ever gets overwritten.","L":"two-pointers.html#rx-mergeback"},{"id":"rx-two-pointers-subseq","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Is s a subsequence of t? Compare two sequences in order","a":"One pointer per sequence. Advance the s pointer only on a match; always advance t.","x":"To check that s appears inside t in order (gaps allowed), walk t once with one pointer and keep a second pointer at the next letter of s you still need. Advance it only when they match. If you use up all of s, the answer is yes.","L":"two-pointers.html#rx-subseq"},{"id":"rx-two-pointers-cycle","y":"reflex","tr":"dsa","s":"Two Pointers","q":"Cycle in a linked list or in repeated function application (happy number, duplicate number 287)","a":"Fast and slow pointers. Fast moves 2, slow moves 1. If they meet, there’s a cycle.","x":"Send two runners around: slow takes 1 step, fast takes 2. Without a loop, fast falls off the end. With a loop, fast eventually laps slow and they land on the same node, like runners on a circular track.","L":"two-pointers.html#rx-cycle"},{"id":"rx-two-pointers-cxtpmoves","y":"reflex","tr":"dsa","s":"Two Pointers","q":"A while loop with two pointers moving towards each other (or both forward)","a":"Count total moves: each pointer travels at most n → O(n), not O(n²).","x":"Two pointers inside one while loop look like nested work, but count moves instead: each pointer only moves forward (or inward) and never comes back, so together they make at most about 2n moves. That’s O(n).","L":"two-pointers.html#rx-cxtpmoves"},{"id":"rx-two-pointers-cxtpsort","y":"reflex","tr":"dsa","s":"Two Pointers","q":"“Sort the array first, then two pointers”","a":"Say O(n log n) for the sort, O(n) for the scan → O(n log n) overall; space O(1) or O(n) depending on the sort.","x":"When you sort first, the total is the sort plus the scan. Sorting is O(n log n) and the scan is O(n); the bigger term wins, so say O(n log n). Mention space too: O(1) if you sort in place.","L":"two-pointers.html#rx-cxtpsort"},{"id":"rx-two-pointers-cxtp3","y":"reflex","tr":"dsa","s":"Two Pointers","q":"k-Sum with two pointers inside k − 2 loops","a":"O(n^(k−1)): 3Sum O(n²), 4Sum O(n³).","x":"k-Sum = (k − 2) ordinary loops around one two-pointer scan. Each loop multiplies by n, and the scan is n, so it’s n to the power (k − 1).","L":"two-pointers.html#rx-cxtp3"},{"id":"rx-sliding-window-longest","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Longest substring / subarray such that …” (contiguous)","a":"Expand r every step. <b>While","x":"A window is a stretch of neighbours from l to r. Grow it by moving r one step every time. If the rule breaks, move l right until it holds again, and only then record the length. The longest valid window you ever saw is the answer.","L":"sliding-window.html#rx-longest"},{"id":"rx-sliding-window-shortest","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Shortest / minimum length subarray such that …”","a":"Expand r. <b>While","x":"For the shortest window, flip the order: grow r until the window is valid, then shrink from the left as long as it stays valid, recording the length every time. You stop shrinking the moment it breaks.","L":"sliding-window.html#rx-shortest"},{"id":"rx-sliding-window-counts","y":"reflex","tr":"dsa","s":"Sliding Window","q":"The window rule depends on letter counts (covers t, at most k distinct, anagram)","a":"Keep a count dict for the window. Track one number (missing, distinct, formed) so validity is O(1).","x":"When “valid” depends on which letters are inside, keep a count dictionary for the window. Also keep one summary number (for example, how many required letters are still missing) so you can tell valid from invalid without rescanning.","L":"sliding-window.html#rx-counts"},{"id":"rx-sliding-window-replace","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Replace at most k characters to make them all the same”","a":"Valid when <code>window length − max frequency ≤ k</code>.","x":"To make a window all one letter with at most k changes, keep its most common letter and change the rest. The number of changes is length − (count of the most common letter). The window is fine while that is ≤ k.","L":"sliding-window.html#rx-replace"},{"id":"rx-sliding-window-atmostk","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“At most K distinct”, “at most K zeros”","a":"Window with a count dict; shrink while the rule exceeds K.","x":"“At most K” is a growing window with a count dictionary. Add the new item on the right; while the rule is exceeded (more than K kinds, more than K zeros), remove items from the left. Record the length after fixing.","L":"sliding-window.html#rx-atmostk"},{"id":"rx-sliding-window-exactk","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Exactly K distinct”, “exactly K odd numbers” (counting subarrays)","a":"<code>atMost(K) − atMost(K − 1)</code>. Count windows ending at r as <code>r − l + 1</code>.","x":"“Exactly K” is awkward for a window, but “at most K” is easy. Exactly K = (at most K) − (at most K − 1). Each at-most count adds r − l + 1 at every step: the number of valid windows ending at r.","L":"sliding-window.html#rx-exactk"},{"id":"rx-sliding-window-fixed","y":"reflex","tr":"dsa","s":"Sliding Window","q":"Window size k is given (average, sum, max vowels in k)","a":"Add <code>nums[r]</code>, subtract <code>nums[r − k]</code>. Never recompute.","x":"When the window size k is fixed, don’t re-add k numbers every step. Slide: add the number entering on the right and subtract the one leaving on the left. Each step is O(1).","L":"sliding-window.html#rx-fixed"},{"id":"rx-sliding-window-anagram","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Permutation of p inside s”, “all anagram start indexes”","a":"Fixed window of size len(p) with letter counts; compare to p’s counts.","x":"An anagram of p has the same letter counts as p. So slide a window of exactly len(p) across s, keep its letter counts up to date, and compare them with p’s counts at every position.","L":"sliding-window.html#rx-anagram"},{"id":"rx-sliding-window-deque","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Max (or min) of every window of size k”","a":"Deque of indexes with decreasing values. Pop smaller from the back, pop expired from the front. Front is the max.","x":"Keep a short list (deque) of indexes whose values are decreasing. When a new number arrives, remove smaller numbers from the back: they can never be a maximum again. Drop the front if it has slid out of the window. The front is always the current maximum.","L":"sliding-window.html#rx-deque"},{"id":"rx-sliding-window-negatives","y":"reflex","tr":"dsa","s":"Sliding Window","q":"Subarray sum target, but the array has negative numbers","a":"Not a window. Use prefix sums + a dict.","x":"A sliding window assumes that adding a number moves the sum one way. With negative numbers, growing the window can make the sum smaller, so shrinking decisions become wrong. Use prefix sums with a dictionary instead (see Arrays & Hashing).","L":"sliding-window.html#rx-negatives"},{"id":"rx-sliding-window-complement","y":"reflex","tr":"dsa","s":"Sliding Window","q":"“Take k items from the two ends” (cards, operations to reduce x to zero)","a":"Flip it: the items you <b>don’t","x":"Taking k cards from the two ends means the cards you leave form one block in the middle, of length n − k. So find the middle block with the smallest sum (a fixed-size window), and subtract it from the total.","L":"sliding-window.html#rx-complement"},{"id":"rx-sliding-window-stock","y":"reflex","tr":"dsa","s":"Sliding Window","q":"Best single buy-then-sell, or “max later minus earlier”","a":"Track the minimum so far; at each step compare today minus that minimum.","x":"You must buy before you sell, so for each day ask: “what if I sell today?” The best buy is the cheapest day so far. Keep that minimum as you go and compare today − minimum with the best profit.","L":"sliding-window.html#rx-stock"},{"id":"rx-sliding-window-cxswamort","y":"reflex","tr":"dsa","s":"Sliding Window","q":"while (shrink) inside for (grow) over the same array","a":"O(n): count that each index enters once and leaves at most once.","x":"A shrinking while-loop inside the growing for-loop looks like O(n²), but count what happens to each index: it joins the window once (r passes it) and leaves at most once (l passes it). That’s at most 2n steps in total: O(n).","L":"sliding-window.html#rx-cxswamort"},{"id":"rx-sliding-window-cxswspace","y":"reflex","tr":"dsa","s":"Sliding Window","q":"Space of a window solution","a":"Size of the window’s bookkeeping: count map bounded by distinct values (O(26) for letters), a deque up to O(k).","x":"The extra space is whatever the window remembers. Letter counts are capped at 26 keys (O(1)); counts of arbitrary values can grow with the window; a max-deque holds at most k indexes.","L":"sliding-window.html#rx-cxswspace"},{"id":"rx-sliding-window-cxswfixed","y":"reflex","tr":"dsa","s":"Sliding Window","q":"Fixed-size window recomputed from scratch each step","a":"Make it incremental: add the new element, remove the old one → O(n) instead of O(n·k).","x":"Re-adding all k numbers for each of the n windows does k work n times. Updating the previous window (add the new number, drop the old) is 1 unit of work per step.","L":"sliding-window.html#rx-cxswfixed"},{"id":"rx-stack-brackets","y":"reflex","tr":"dsa","s":"Stack","q":"Brackets, tags, nesting, “valid parentheses”","a":"Push openers. On a closer, the top must be its partner; pop it. Valid if the stack ends empty.","x":"Every closing bracket must match the most recent unmatched opening one, which is exactly what a stack’s top gives you. Push each opener. On a closer, the top must be its partner (pop it), otherwise it’s invalid. At the end nothing may be left open.","L":"stack.html#rx-brackets"},{"id":"rx-stack-expr","y":"reflex","tr":"dsa","s":"Stack","q":"Evaluate an expression (RPN, calculator, + − × with precedence)","a":"Stack of numbers. RPN: operators pop two. Infix: push signed terms, apply × ÷ to the top immediately, sum at the end.","x":"In Reverse Polish notation the operator comes after its two numbers. Push numbers onto a stack; when an operator appears, pop the last two numbers, apply it, and push the result back. The final number on the stack is the answer.","L":"stack.html#rx-expr"},{"id":"rx-stack-decode","y":"reflex","tr":"dsa","s":"Stack","q":"Nested repeats like 3[a2[c]] , nested lists, mini-parsers","a":"On “[” push (current text, count) and reset. On “]” pop and build <code>prev + cur × count</code>.","x":"Nested brackets mean “pause what I was building, build the inside, then come back”. On “[”, save (text so far, repeat count) on a stack and start fresh. On “]”, pop the saved pair and set text = saved text + inside × count.","L":"stack.html#rx-decode"},{"id":"rx-stack-undo","y":"reflex","tr":"dsa","s":"Stack","q":"Backspace, undo, “..” in a path, cancel the last thing","a":"A stack: push normal items, pop on the cancel action.","x":"Whenever something can cancel the most recent thing (backspace, undo, “..” in a path), keep the kept items on a stack. Normal items are pushed; the cancel action pops the latest one.","L":"stack.html#rx-undo"},{"id":"rx-stack-minstack","y":"reflex","tr":"dsa","s":"Stack","q":"Stack that also returns min (or max) in O(1)","a":"Store pairs <code>(value, min so far)</code> on every push.","x":"A stack can’t search for its minimum quickly. So when you push a value, also store what the minimum is at that moment. The top pair always knows the current minimum, and popping restores the previous one for free.","L":"stack.html#rx-minstack"},{"id":"rx-stack-nextgreater","y":"reflex","tr":"dsa","s":"Stack","q":"“Next greater / warmer / higher element” for every position","a":"Stack of indexes with decreasing values. When x beats the top, pop: x is that index’s answer.","x":"Walk left to right keeping a stack of positions still waiting for a bigger number. When the current number is bigger than the one on top, that position just found its answer: pop it and record. The stack stays in decreasing order.","L":"stack.html#rx-nextgreater"},{"id":"rx-stack-prevsmaller","y":"reflex","tr":"dsa","s":"Stack","q":"“Previous smaller / greater element”, “span of days with price ≤ today”","a":"Same scan. After popping everything that x beats, whatever remains on top is x’s previous greater (or smaller).","x":"It’s the same scan, but you read the answer from what survives. After popping everything the current value beats, the item left on top is the nearest earlier value that’s bigger. For stock span, add up the spans you popped.","L":"stack.html#rx-prevsmaller"},{"id":"rx-stack-histogram","y":"reflex","tr":"dsa","s":"Stack","q":"Largest rectangle in a histogram, max area under bars","a":"Increasing stack of indexes plus a 0 sentinel. When popping bar j: width = i − new top − 1.","x":"Each bar’s best rectangle stretches until a lower bar on each side. Keep bars in increasing height on a stack. When a lower bar arrives, the bar you pop has found its right edge (here) and its left edge (the new top), so width = i − new top − 1.","L":"stack.html#rx-histogram"},{"id":"rx-stack-circular","y":"reflex","tr":"dsa","s":"Stack","q":"Next greater in a circular array","a":"Loop i over 2n and use <code>nums[i % n]</code>; only push during the first pass.","x":"In a circular array the next bigger number may sit before you. Walk the array twice (index i % n): the second lap gives the early positions a chance to find their answer. Only push positions during the first lap.","L":"stack.html#rx-circular"},{"id":"rx-stack-removek","y":"reflex","tr":"dsa","s":"Stack","q":"“Remove k digits to make the smallest number”, smallest subsequence","a":"Increasing stack: while k and top &amp;gt; current, pop. Trim leftovers from the end, strip leading zeros.","x":"To make the smallest number, earlier digits matter most. Walk the digits keeping a stack; while you still may delete and the top digit is bigger than the current one, delete the top. Delete any leftovers from the end and strip leading zeros.","L":"stack.html#rx-removek"},{"id":"rx-stack-asteroid","y":"reflex","tr":"dsa","s":"Stack","q":"Things moving and colliding (asteroids, cancelling pairs)","a":"Stack of survivors. A new left-mover fights the top right-movers until it dies or none are left.","x":"Keep the survivors on a stack. A collision only happens when something moving left meets the right-moving things before it. Let the new one fight the top: the smaller explodes, equal sizes both explode, and repeat until it dies or nothing is left to hit.","L":"stack.html#rx-asteroid"},{"id":"rx-stack-carfleet","y":"reflex","tr":"dsa","s":"Stack","q":"Cars catching up and merging into fleets","a":"Sort by position, closest to target first. Keep a stack of arrival times; a slower (larger) time starts a new fleet.","x":"A car can’t overtake, so it joins the fleet ahead if it would arrive no later than that fleet. Sort cars by position, closest to the target first, and work out each one’s arrival time. A car that arrives later than the fleet ahead starts a new fleet.","L":"stack.html#rx-carfleet"},{"id":"rx-stack-cxstamort","y":"reflex","tr":"dsa","s":"Stack","q":"while stack and …: pop inside a for loop","a":"O(n): every element is pushed once and popped at most once.","x":"A while-pop inside a for loop looks quadratic, but follow one element: it is pushed once and popped at most once. Over the whole run that’s at most 2n stack operations, so the time is O(n).","L":"stack.html#rx-cxstamort"},{"id":"rx-stack-cxstspace","y":"reflex","tr":"dsa","s":"Stack","q":"Space of a stack solution","a":"Worst-case stack height: O(n) (sorted input never pops, or nested brackets).","x":"Space is the tallest the stack can get. If nothing ever gets popped (an increasing list for next-greater, or “((((((”), every item stays on it: O(n).","L":"stack.html#rx-cxstspace"},{"id":"rx-stack-cxstbrute","y":"reflex","tr":"dsa","s":"Stack","q":"For each element, scanning left or right for the first bigger/smaller one","a":"That’s O(n²). A monotonic stack does it in O(n).","x":"Scanning outward from every position to find the first bigger or smaller one does up to n steps for each of n positions. The monotonic stack finds all the answers in one pass.","L":"stack.html#rx-cxstbrute"},{"id":"rx-binary-search-sorted","y":"reflex","tr":"dsa","s":"Binary Search","q":"Sorted input and “find”, “search”, “insert position”, or a required O(log n)","a":"Binary search.","x":"Sorted data lets you throw away half the candidates with one comparison: look at the middle; if it’s too small, the answer can only be to the right, otherwise to the left. A million items need about 20 looks.","L":"binary-search.html#rx-sorted"},{"id":"rx-binary-search-firsttrue","y":"reflex","tr":"dsa","s":"Binary Search","q":"“First / smallest index where …”, “insert position”, “first bad version”","a":"<code>lo, hi = 0, n</code>; <code>while lo &lt; hi</code>; true → <code>hi = mid</code>, false → <code>lo = mid + 1</code>. Return lo.","x":"Many questions are “where does false turn into true?” (first bad version, insert position). Keep lo and hi around that switch point. If mid is true, the first true is at mid or before it (hi = mid); if false, it’s after mid (lo = mid + 1). When lo meets hi, that’s the answer.","L":"binary-search.html#rx-firsttrue"},{"id":"rx-binary-search-invariant","y":"reflex","tr":"dsa","s":"Binary Search","q":"You’re unsure about < vs ≤ , mid vs mid ± 1","a":"Decide what [lo, hi] means first (“answer is inside”), then make every branch keep that true.","x":"Off-by-one bugs come from not deciding what lo and hi mean. Write one sentence first, for example “the answer is somewhere in [lo, hi]”. Then each branch must keep that sentence true: if mid might be the answer keep it (hi = mid); if it can’t be, skip it (lo = mid + 1).","L":"binary-search.html#rx-invariant"},{"id":"rx-binary-search-rotated","y":"reflex","tr":"dsa","s":"Binary Search","q":"“Rotated sorted array”","a":"Compare nums[lo] and nums[mid]: one half is sorted. If the target fits that half’s range go there, else the other half.","x":"A rotated sorted array is two sorted pieces. Whatever the middle is, one side of it is still in order (check nums[lo] ≤ nums[mid]). If the target fits inside that ordered side’s range, search there; otherwise search the other side.","L":"binary-search.html#rx-rotated"},{"id":"rx-binary-search-findmin","y":"reflex","tr":"dsa","s":"Binary Search","q":"Minimum of a rotated sorted array","a":"Compare <code>nums[mid]</code> with <code>nums[hi]</code>. Greater → lo = mid + 1, else hi = mid.","x":"The minimum is where the rotation “drop” happens. Compare the middle with the last element: if the middle is bigger, the drop (and the minimum) is to its right; otherwise the minimum is the middle or to its left.","L":"binary-search.html#rx-findmin"},{"id":"rx-binary-search-bisect","y":"reflex","tr":"dsa","s":"Binary Search","q":"Python and you need a first/last position in a sorted list","a":"<code>bisect_left(a, x)</code> = first index ≥ x. <code>bisect_right(a, x)</code> = first index &gt; x.","x":"Python already has binary search. bisect_left gives the first position where x could go (the first index ≥ x). bisect_right gives the position just after the last x. Together they give the range of all copies of x.","L":"binary-search.html#rx-bisect"},{"id":"rx-binary-search-answer","y":"reflex","tr":"dsa","s":"Binary Search","q":"“Minimum capacity / speed / largest-sum limit such that it’s possible”, “minimize the maximum”","a":"Binary search the answer in [lo, hi] with a greedy <code>feasible(x)</code>. Find the first x that works.","x":"Sometimes you can’t search the input, but you can search the answer. Ask “could speed k work?”. If k works, any bigger k works too, so the answers form ✗✗✗✓✓✓. Binary search for the first ✓, checking each guess with a quick greedy simulation.","L":"binary-search.html#rx-answer"},{"id":"rx-binary-search-peak","y":"reflex","tr":"dsa","s":"Binary Search","q":"“Find a peak”, “mountain array”, local max in O(log n)","a":"Compare mid with mid + 1. Uphill to the right → lo = mid + 1, else hi = mid.","x":"Compare the middle with its right neighbour. If the right one is higher you’re walking uphill, and a peak must exist to the right. Otherwise one exists at mid or to its left. Every step halves the search.","L":"binary-search.html#rx-peak"},{"id":"rx-binary-search-matrix","y":"reflex","tr":"dsa","s":"Binary Search","q":"Matrix sorted row by row, each row starting above the previous row’s end","a":"Treat it as one list of R × C: <code>matrix[mid // C][mid % C]</code>.","x":"If each row continues where the previous one ended, the matrix is really one sorted list split into rows. Binary search positions 0 … R·C − 1 and turn a position into a cell with row = mid // C, col = mid % C.","L":"binary-search.html#rx-matrix"},{"id":"rx-binary-search-kth","y":"reflex","tr":"dsa","s":"Binary Search","q":"“Kth smallest” in a sorted matrix / multiplication table / pair distances","a":"Binary search on the <b>value","x":"Instead of searching positions, search the value itself. Guess a value and count how many items are ≤ it (quick in a sorted matrix). The k-th smallest is the first value whose count reaches k.","L":"binary-search.html#rx-kth"},{"id":"rx-binary-search-median","y":"reflex","tr":"dsa","s":"Binary Search","q":"Median of two sorted arrays in O(log)","a":"Binary search how many items to take from the shorter array; the rest come from the other. Valid when both left maxes ≤ both right mins.","x":"The median splits all numbers into a left half and a right half. Binary search how many of the left half come from the shorter array (the rest come from the other). The split is right when every left number ≤ every right number.","L":"binary-search.html#rx-median"},{"id":"rx-binary-search-rounding","y":"reflex","tr":"dsa","s":"Binary Search","q":"Template that does lo = mid (largest x that works: sqrt, last true)","a":"Round mid <b>up","x":"If a branch sets lo = mid (you’re finding the largest value that works), mid must round up. Otherwise, with lo and hi next to each other, mid equals lo again and the loop never moves.","L":"binary-search.html#rx-rounding"},{"id":"rx-binary-search-cxbslog","y":"reflex","tr":"dsa","s":"Binary Search","q":"A loop that halves the range (lo/hi/mid), or n //= 2","a":"O(log n) iterations. Multiply by the work inside.","x":"A loop that halves the range each time runs about log₂ n times: 1,000,000 shrinks to 1 in about 20 steps. Multiply by the work done in each step.","L":"binary-search.html#rx-cxbslog"},{"id":"rx-binary-search-cxbsanswer","y":"reflex","tr":"dsa","s":"Binary Search","q":"“Minimum speed / capacity / days such that …”","a":"Binary search the answer range: O(log(range) × cost of the check).","x":"Searching the answer costs (number of guesses) × (cost of one check). The guesses are log of the size of the answer range; each check usually walks the input once.","L":"binary-search.html#rx-cxbsanswer"},{"id":"rx-binary-search-cxbssort","y":"reflex","tr":"dsa","s":"Binary Search","q":"Unsorted data and one lookup","a":"Just scan, O(n). Sort (O(n log n)) only if you’ll do many binary searches afterwards.","x":"Binary search needs sorted data. Sorting costs O(n log n), more than simply scanning once (O(n)). Sort only when you’ll search many times afterwards.","L":"binary-search.html#rx-cxbssort"},{"id":"rx-linked-list-reverse","y":"reflex","tr":"dsa","s":"Linked List","q":"“Reverse the list” (or part of it)","a":"<code>prev, curr = None, head</code>. Loop: save next, point curr back to prev, step both.","x":"Walk the list turning every arrow around. Keep three names: prev (the part already reversed), curr (the node you’re fixing) and next (saved first, so you don’t lose the rest). Point curr at prev, then step both forward.","L":"linked-list.html#rx-reverse"},{"id":"rx-linked-list-dummy","y":"reflex","tr":"dsa","s":"Linked List","q":"The head might change: delete, insert at front, merge, partition, build a new list","a":"<code>dummy = ListNode(0, head)</code>, work from it, return <code>dummy.next</code>.","x":"When the first node might be deleted or replaced, put a fake node in front of it. Now every real node has a node before it, so there are no special cases for the head. At the end return dummy.next.","L":"linked-list.html#rx-dummy"},{"id":"rx-linked-list-nth","y":"reflex","tr":"dsa","s":"Linked List","q":"“Nth node from the end” in one pass","a":"Dummy, then move fast n + 1 steps ahead. Move both until fast is None. slow is just before the target.","x":"To find the n-th node from the end in one pass, give one pointer a head start of n + 1 steps (from a dummy). Then move both together. When the leader falls off the end, the follower is right before the node to remove.","L":"linked-list.html#rx-nth"},{"id":"rx-linked-list-addtwo","y":"reflex","tr":"dsa","s":"Linked List","q":"Numbers stored as digit lists (add, multiply)","a":"Dummy + tail, loop while l1 or l2 or carry. <code>carry, digit = divmod(s, 10)</code>.","x":"Add like on paper, one digit column at a time, carrying the extra. The lists store digits in reverse, so the head is the ones digit. Keep going while either list has digits or a carry is left.","L":"linked-list.html#rx-addtwo"},{"id":"rx-linked-list-reversek","y":"reflex","tr":"dsa","s":"Linked List","q":"“Reverse nodes in groups of k”","a":"Dummy. For each group: find the kth node (stop if missing), reverse inside, reconnect group_prev → kth, group_prev = old first.","x":"Cut the list into groups of k. For each full group: reverse it on its own, then reconnect the node before the group to the new first node, and the old first node (now last) to what follows. A short final group stays as it is.","L":"linked-list.html#rx-reversek"},{"id":"rx-linked-list-copyrandom","y":"reflex","tr":"dsa","s":"Linked List","q":"Deep copy a list with random pointers (or any graph)","a":"Dict old → new. Pass 1 creates copies, pass 2 wires next and random through the dict.","x":"Random pointers can point anywhere, even ahead, so build the copies first and connect them second. Pass 1: create a copy of every node and remember old → new in a dictionary. Pass 2: copy.next = map[old.next], copy.random = map[old.random].","L":"linked-list.html#rx-copyrandom"},{"id":"rx-linked-list-lru","y":"reflex","tr":"dsa","s":"Linked List","q":"“LRU cache”, “O(1) get and put with eviction”","a":"Dict key → node plus a doubly linked list with head/tail sentinels. Touch = move to the tail; evict head.next.","x":"A dictionary finds a key in O(1), and a doubly linked list keeps keys in “last used” order, also changeable in O(1). Every get or put moves that key to the most-recent end. When over capacity, remove from the least-recent end.","L":"linked-list.html#rx-lru"},{"id":"rx-linked-list-middle","y":"reflex","tr":"dsa","s":"Linked List","q":"“Middle of the list”, split a list in half","a":"slow 1 step, fast 2 steps, while <code>fast and fast.next</code>.","x":"Fast moves two nodes for every one that slow moves. When fast reaches the end, slow has gone half as far: the middle.","L":"linked-list.html#rx-middle"},{"id":"rx-linked-list-cycle","y":"reflex","tr":"dsa","s":"Linked List","q":"“Does the list have a cycle?” with O(1) space","a":"Floyd: slow 1, fast 2. If they ever meet, there’s a cycle.","x":"Two runners: slow takes 1 step, fast takes 2. Without a loop fast reaches the end. With a loop, fast eventually laps slow and they land on the same node.","L":"linked-list.html#rx-cycle"},{"id":"rx-linked-list-cyclestart","y":"reflex","tr":"dsa","s":"Linked List","q":"“Where does the cycle begin?”","a":"After they meet, reset slow to head. Move both one step at a time. They meet at the entrance.","x":"After slow and fast meet inside the loop, put slow back at the head and move both one step at a time. The maths works out so they meet again exactly where the loop starts.","L":"linked-list.html#rx-cyclestart"},{"id":"rx-linked-list-reorder","y":"reflex","tr":"dsa","s":"Linked List","q":"“Reorder L0 → Ln → L1 → Ln−1 …”, palindrome list","a":"Three steps: find the middle, reverse the second half, then weave or compare.","x":"Weaving the front with the back is three standard moves you already know: find the middle (slow/fast), reverse the second half, then take one node from each half in turn.","L":"linked-list.html#rx-reorder"},{"id":"rx-linked-list-palin","y":"reflex","tr":"dsa","s":"Linked List","q":"“Is the linked list a palindrome?” in O(1) space","a":"Middle, reverse the second half, compare the halves.","x":"A list can’t be read backwards, so turn its second half around. Find the middle, reverse the second half, then walk both halves side by side comparing values.","L":"linked-list.html#rx-palin"},{"id":"rx-linked-list-intersect","y":"reflex","tr":"dsa","s":"Linked List","q":"“Where do two lists intersect?”","a":"p walks A then B, q walks B then A. They meet at the intersection (or both reach None).","x":"The lists have different lengths before they join. If pointer p walks A then B, and q walks B then A, both cover the same total distance, so they arrive at the shared node at the same moment (or both reach the end together if there is none).","L":"linked-list.html#rx-intersect"},{"id":"rx-linked-list-mergek","y":"reflex","tr":"dsa","s":"Linked List","q":"“Merge k sorted lists”","a":"Min-heap of (value, list index, node). Pop the smallest, push its next.","x":"The next smallest overall is always one of the k current list heads. Keep those heads in a min-heap. Take the smallest, add it to the result, and push the node after it from the same list.","L":"linked-list.html#rx-mergek"},{"id":"rx-linked-list-cxllhops","y":"reflex","tr":"dsa","s":"Linked List","q":"Walking a linked list","a":"Count hops: a full walk is O(n); reaching index k is O(k); there is no O(1) random access.","x":"A linked list has no jump-to-index. Getting to the k-th node means following k arrows, so it costs O(k). A full walk is O(n).","L":"linked-list.html#rx-cxllhops"},{"id":"rx-linked-list-cxllfast","y":"reflex","tr":"dsa","s":"Linked List","q":"Fast/slow pointers (middle, cycle detection, k-th from end)","a":"O(n) time, O(1) space.","x":"Slow/fast pointer tricks walk the list a constant number of times and only keep two pointers, so they’re O(n) time and O(1) extra space.","L":"linked-list.html#rx-cxllfast"},{"id":"rx-linked-list-cxllrec","y":"reflex","tr":"dsa","s":"Linked List","q":"A recursive linked-list function","a":"Add O(n) stack space and mention the recursion limit; offer the iterative O(1)-space version.","x":"A recursive solution keeps one call frame per node until it returns, so the call stack uses O(n) memory, and very long lists can hit Python’s recursion limit. Mention that, and offer the iterative version that uses O(1).","L":"linked-list.html#rx-cxllrec"},{"id":"rx-recursion-trust","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A recursive call, like fact(n - 1) or solve(node.left)","a":"Don’t step inside. Read it as “the correct answer for the smaller input” and keep reading.","x":"Don’t try to follow a recursive call down into all its levels; your head will overflow. Treat the call as a finished helper that already returns the right answer for the smaller input, and just use that answer.","L":"recursion.html#rx-trust"},{"id":"rx-recursion-write","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A blank function you need to make recursive","a":"Write the base case first. Then write the final <code>return</code> as if the recursive call already works. Fill in the middle last.","x":"Write a recursive function in this order. First the base case (the smallest input you can answer directly). Then the last line, pretending the recursive calls already work. Only then the middle: what you need from the smaller calls.","L":"recursion.html#rx-write"},{"id":"rx-recursion-memo","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"The same arguments showing up in more than one branch of the call tree","a":"Put <code>@lru_cache(None)</code> on it, or keep a dict keyed by the arguments.","x":"If the call tree asks the same question in several branches, you’re redoing work, often exponentially. Remember each answer the first time (a dict, or @lru_cache) and return the saved one afterwards.","L":"recursion.html#rx-memo"},{"id":"rx-recursion-cost","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“What’s the time complexity?” for a recursive solution","a":"Count the boxes in the call tree, multiply by the work inside one box. Space is the height of the tree.","x":"Draw the call tree. Time = (number of calls, the boxes) × (work done inside one call). Space is not the number of boxes: it’s how deep the tree goes, because only one path of calls is open at a time.","L":"recursion.html#rx-cost"},{"id":"rx-recursion-none","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"if not node:","a":"Return the empty-tree answer: <code>0</code> for counts and heights, <code>True</code> for “is it valid”, <code>None</code> for build or search, <code>[]</code> for lists.","x":"The empty tree still needs an answer, and it’s the value that makes the parent’s formula work without special cases. A height of 0 makes leaves get 1. “Valid?” is True, so it never breaks an and-chain.","L":"recursion.html#rx-none"},{"id":"rx-recursion-children","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A node’s answer depends on its children’s answers (height, size, balanced, sum)","a":"<code>l = f(node.left)</code>, <code>r = f(node.right)</code>, combine. Postorder, every time.","x":"When a node’s answer is built from its children’s answers, ask both children first and then combine. Answers flow from the leaves up to the root (postorder).","L":"recursion.html#rx-children"},{"id":"rx-recursion-above","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A node needs something from above: running sum, max so far, allowed range, depth","a":"Add a parameter. Pass the updated value into both recursive calls.","x":"When a node needs information from above (the sum so far, the allowed range, the depth), pass it down as an extra parameter. Each call hands its children an updated copy.","L":"recursion.html#rx-above"},{"id":"rx-recursion-bend","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"The answer is a path that can bend through a node (diameter, max path sum)","a":"Return the best one-sided path to the parent. Update a <code>nonlocal best</code> with left + right + node.","x":"A path may go up into a node and down the other side, but a parent can only continue one side of it. So each node does two things: it tries the bent path left + node + right as a candidate for the global best, and it returns only the better single side to its parent.","L":"recursion.html#rx-bend"},{"id":"rx-recursion-bst","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Binary search tree”","a":"Inorder gives sorted order. And the ordering lets you go only left or only right: O(h) instead of O(n).","x":"In a BST everything left is smaller and everything right is bigger. Two consequences: an inorder walk (left, node, right) lists values in sorted order; and to find a value you only go one way at each node, so it costs the height, not the size.","L":"recursion.html#rx-bst"},{"id":"rx-recursion-pair","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Two trees at once: same tree, symmetric, merge, subtree","a":"Recurse on a pair <code>f(a, b)</code>. Base: both None, or exactly one None.","x":"To compare two trees, recurse on a pair of nodes. If both are empty they match. If only one is empty, or the values differ, they don’t. Otherwise compare their children pairwise (for a mirror, pair left with right).","L":"recursion.html#rx-pair"},{"id":"rx-recursion-level","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Level”, “row”, “right side view”, “zigzag”, “minimum depth”","a":"BFS with a deque, and <code>for _ in range(len(q))</code> to process one level at a time.","x":"Anything about “levels” is breadth-first: use a queue. At the start of each round the queue holds exactly one level, so loop len(queue) times to process just that level before moving on.","L":"recursion.html#rx-level"},{"id":"rx-recursion-found","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Find” a node in a tree, or the lowest common ancestor","a":"Return the found node (or None) upward. Parent: both sides found → it’s me; one side → pass it up.","x":"Each call reports upward “I found p or q here” (the node) or nothing (None). A node that hears back from both sides is where the two paths meet: the lowest common ancestor. If only one side reports, pass that report up.","L":"recursion.html#rx-found"},{"id":"rx-recursion-reshape","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"You’re changing the tree’s shape: delete, insert, trim, flatten","a":"Return the new subtree root and reassign: <code>root.left = f(root.left)</code>. Need old pointers? Process in reverse with a <code>prev</code>.","x":"When a call may replace a subtree (deleting a node, trimming), let it return the new subtree root and assign it back: root.left = f(root.left). The parent never needs to know what changed.","L":"recursion.html#rx-reshape"},{"id":"rx-recursion-upward","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Distance K”, “nodes within reach”, anything that walks up toward the parent","a":"One DFS to build a parent map. Now it’s a graph: BFS from the target.","x":"Tree nodes only point down. If you need to move up too (nodes within distance k), first walk the tree once and record each node’s parent. Now each node has up to three neighbours (left, right, parent) and it’s an ordinary graph search.","L":"recursion.html#rx-upward"},{"id":"rx-recursion-prefix","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Number of paths that sum to k”, starting anywhere and going down","a":"Running prefix sum + a hashmap of prefixes on the current path. Add on the way in, remove on the way out.","x":"Paths can start at any node above you. Track the running sum from the root to the current node and a count of earlier running sums on this path. If running − k appeared before, the part between them sums to k. Remove the current sum when you return (backtrack).","L":"recursion.html#rx-prefix"},{"id":"rx-recursion-tuple","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Each node has two states: rob or skip, take or leave, camera or not","a":"Return a tuple with one answer per state. The parent combines them.","x":"When each node can be in one of two states (rob it or skip it, camera or no camera), return both answers from every call as a pair. The parent picks the combination it needs, so nothing is recomputed.","L":"recursion.html#rx-tuple"},{"id":"rx-recursion-all","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Return all…”, “list every…”, “generate all possible…”","a":"Backtracking. Start writing the template before you finish reading.","x":"“Return all” means trying every choice and undoing it afterwards. Choose an option (add it to the path), explore everything after it with a recursive call, then un-choose it (pop) so the next option starts clean.","L":"recursion.html#rx-all"},{"id":"rx-recursion-copy","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"res.append(path)","a":"Make it <code>res.append(path[:])</code>. Every time, no exceptions.","x":"path is one list that keeps changing as you backtrack. Appending path itself stores a reference to that same changing list, so every saved answer ends up identical (usually empty). Save a copy of how it looks right now.","L":"recursion.html#rx-copy"},{"id":"rx-recursion-order","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Combinations, subsets, “in any order”, {1,2} same as {2,1}","a":"Start index: <code>for i in range(start, n)</code>. If order matters (permutations), use <code>used[]</code> and loop from 0.","x":"If {1, 2} and {2, 1} count as the same answer, only look forward: the next choice starts after the current index. If order matters (permutations), loop over everything each time and skip what’s already used.","L":"recursion.html#rx-order"},{"id":"rx-recursion-reuse","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Unlimited”, “may be chosen more than once”","a":"Recurse with <code>i</code>. Otherwise recurse with <code>i + 1</code>.","x":"If a number may be picked again, the next call starts at the same index i. If each can be used once, it starts at i + 1.","L":"recursion.html#rx-reuse"},{"id":"rx-recursion-dups","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Input “may contain duplicates” but results must be unique","a":"<code>nums.sort()</code>, then <code>if i &gt; start and nums[i] == nums[i-1]: continue</code>.","x":"With repeated numbers, two branches at the same level could make the same choice and produce identical answers. Sort first so equal numbers sit together, then at each level skip a number equal to the one just tried.","L":"recursion.html#rx-dups"},{"id":"rx-recursion-sortbreak","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A target sum with positive numbers","a":"Sort first. In the loop: <code>if nums[i] &gt; remaining: break</code>.","x":"With only positive numbers, once a number is bigger than what’s left of the target, every later number in sorted order is too. So sort, and break out of the loop instead of trying them.","L":"recursion.html#rx-sortbreak"},{"id":"rx-recursion-constraint","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Place them so no two conflict” (queens, sudoku, coloring)","a":"Fill one slot at a time. Keep sets of what’s taken for O(1) checks. Return <code>True</code> up the chain if one solution is enough.","x":"Fill one slot at a time (one queen per row). Keep sets of what’s already taken, such as columns and both diagonals, so “is this allowed?” is a quick lookup. Undo the choice when you come back.","L":"recursion.html#rx-constraint"},{"id":"rx-recursion-grid","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"A grid and “each cell may be used once”","a":"Mark the cell (<code>board[r][c] = \"#\"</code>), try 4 directions, restore it.","x":"To use each cell at most once, mark it as visited before going deeper (for example, write “#” into it), try the four directions, then put the original letter back so other paths can use it.","L":"recursion.html#rx-grid"},{"id":"rx-recursion-split","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“Partition”, “split into pieces”, “restore”, “segment” a string","a":"<code>for end in range(start + 1, len(s) + 1)</code>: take <code>s[start:end]</code>, validate, recurse from <code>end</code>.","x":"To cut a string into valid pieces, try every possible first piece s[start:end]. If it’s valid, recurse on the rest from end. Reaching the end of the string means one complete answer.","L":"recursion.html#rx-split"},{"id":"rx-recursion-cxcalls","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“What’s the time complexity of this recursion?”","a":"Ask three things: how many calls per call (on what size), how much work per call, then add the tree up level by level.","x":"Three questions give you the complexity of any recursion. How many calls does each call make, and on what size? How much work happens inside one call? Then add up the cost of each level of the call tree.","L":"recursion.html#rx-cxcalls"},{"id":"rx-recursion-cxbranch","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"b recursive calls per call, each shrinking by 1","a":"Tree has depth n and ~bⁿ boxes → O(bⁿ) × work per box.","x":"If every call makes b more calls and the size only drops by 1, the tree is n levels deep and roughly bⁿ boxes wide at the bottom: exponential.","L":"recursion.html#rx-cxbranch"},{"id":"rx-recursion-cxhalve","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"One recursive call on half the input (binary search, fast pow)","a":"log n levels × work per call → O(log n) if the work is O(1).","x":"One call on half the input means the size goes n, n/2, n/4, … 1: about log₂ n levels. With constant work per level that’s O(log n).","L":"recursion.html#rx-cxhalve"},{"id":"rx-recursion-cxtwohalves","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Two recursive calls on halves","a":"O(n) work per call → every level costs n → O(n log n). O(1) work per call → leaves dominate → O(n).","x":"Two calls on halves give log n levels. What matters is the work per level: if each call does O(n) work, every level costs n in total → O(n log n) (merge sort). If each does O(1), the n leaves dominate → O(n).","L":"recursion.html#rx-cxtwohalves"},{"id":"rx-recursion-cxtrap","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"f(n//2) * f(n//2) : the same half computed twice","a":"Store it once: <code>h = f(n//2); h * h</code>. Two calls on n/2 is O(n), one is O(log n).","x":"Calling f(n // 2) twice computes the same value twice. Each level doubles the calls, which cancels the halving and gives O(n). Store it once and reuse it for O(log n).","L":"recursion.html#rx-cxtrap"},{"id":"rx-recursion-cxspace","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"“What’s the space complexity of this recursion?”","a":"Max depth of the call tree × frame size, plus memo tables, path lists and other extras. Not the total number of calls.","x":"Only the calls on the current path are in memory at once, so stack space = the depth of the call tree, not the number of calls. Add any extra storage you keep: memo tables, path lists.","L":"recursion.html#rx-cxspace"},{"id":"rx-recursion-cxmemo","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Memoized recursion or top-down DP","a":"Time = distinct states × work per state. Space = states (cache) + depth (stack).","x":"With memoization each distinct input is solved once. Time = (number of different inputs) × (work per input). Space = the cache plus the recursion depth.","L":"recursion.html#rx-cxmemo"},{"id":"rx-recursion-cxslice","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Slicing or copying inside a recursive call ( s[1:] , a[:mid] , path[:] )","a":"Add O(length) work per call. <code>f(s[1:])</code> turns O(n) into O(n²); pass an index instead.","x":"Slicing copies. f(s[1:]) copies n − 1 characters, then n − 2, … which adds up to O(n²). Pass an index instead of a new string or list.","L":"recursion.html#rx-cxslice"},{"id":"rx-recursion-cxbt","y":"reflex","tr":"dsa","s":"Recursion & Backtracking","q":"Backtracking that outputs every answer","a":"Time ≈ number of answers × cost to copy one: subsets O(n·2ⁿ), permutations O(n·n!), combinations O(k·C(n,k)).","x":"When you must output every answer, the time is at least (number of answers) × (cost to copy one).","L":"recursion.html#rx-cxbt"},{"id":"rx-heap-python","y":"reflex","tr":"dsa","s":"Heap","q":"You need a max-heap in Python","a":"<code>heapq</code> is min-only: push <code>-x</code>, read <code>-heap[0]</code>.","x":"Python’s heapq always keeps the smallest on top. To get the largest instead, store negated numbers: the most negative is the largest original. Flip the sign back when you read it.","L":"heap.html#rx-python"},{"id":"rx-heap-heapify","y":"reflex","tr":"dsa","s":"Heap","q":"You already have all the items up front","a":"<code>heapq.heapify(list)</code> in O(n), not n pushes.","x":"If you already have all the items, heapify arranges the list into a heap in O(n). Pushing them one by one costs O(log n) each, O(n log n) in total.","L":"heap.html#rx-heapify"},{"id":"rx-heap-tuples","y":"reflex","tr":"dsa","s":"Heap","q":"Heap entries need a priority plus payload (nodes, strings)","a":"Push tuples <code>(priority, tiebreak, payload)</code>. Use a counter or index as the tiebreak.","x":"A heap compares whole entries. Put the priority first. If two priorities tie, Python compares the next field, and objects like nodes can’t be compared. So add a unique counter as the second field to break ties.","L":"heap.html#rx-tuples"},{"id":"rx-heap-lazy","y":"reflex","tr":"dsa","s":"Heap","q":"You need to delete or update an item that’s deep inside the heap","a":"Lazy deletion: push the new version, and when an outdated entry reaches the top, skip it.","x":"You can’t cheaply find and change an entry deep inside a heap. Instead push the updated entry, and leave the old one. When an outdated entry reaches the top, notice it’s stale and skip it.","L":"heap.html#rx-lazy"},{"id":"rx-heap-topk","y":"reflex","tr":"dsa","s":"Heap","q":"“k largest”, “kth largest”, “top k” from a big list or a stream","a":"<b>Min","x":"To keep the k largest, hold a small min-heap of size k. Push every number, and when the heap grows past k, pop the smallest. What stays is the k largest, and the top is the k-th largest.","L":"heap.html#rx-topk"},{"id":"rx-heap-kclosest","y":"reflex","tr":"dsa","s":"Heap","q":"“k smallest”, “k closest points”","a":"<b>Max","x":"For the k smallest it’s the mirror image: keep a max-heap of size k (negate distances in Python). When it overflows, pop the farthest. The k closest remain.","L":"heap.html#rx-kclosest"},{"id":"rx-heap-mergek","y":"reflex","tr":"dsa","s":"Heap","q":"“Merge k sorted lists / arrays”, “smallest range covering k lists”","a":"Heap of (value, which list, index). Pop the min, push that list’s next.","x":"The next smallest overall is always one of the k current fronts. Put the fronts in a min-heap, take the smallest, then push the next item from the list it came from.","L":"heap.html#rx-mergek"},{"id":"rx-heap-median","y":"reflex","tr":"dsa","s":"Heap","q":"“Median of a data stream”, sliding median","a":"Two heaps: max-heap for the lower half, min-heap for the upper. Keep sizes equal or lo one bigger.","x":"Split the numbers into a lower half and an upper half. Keep the lower half in a max-heap and the upper half in a min-heap, with sizes equal or the lower half one bigger. The median is the top of the lower half, or the average of both tops.","L":"heap.html#rx-median"},{"id":"rx-heap-schedule","y":"reflex","tr":"dsa","s":"Heap","q":"Resources unlock over time and you always take the best available (IPO, meeting rooms, CPU tasks)","a":"Sort by unlock time. Push newly available items into a heap keyed by “best”, pop when you act.","x":"When options become available over time and you always want the best available one, sort the options by when they unlock. As time (or money) moves on, push newly unlocked options into a heap ordered by “best”, and pop the best when you act.","L":"heap.html#rx-schedule"},{"id":"rx-heap-cooldown","y":"reflex","tr":"dsa","s":"Heap","q":"“Same item can’t repeat within n” (task scheduler, reorganize string)","a":"Max-heap by remaining count. Take the most frequent; hold it out (a queue or a prev slot) until it’s allowed back.","x":"Use the most common item first, since it’s the hardest to space out. Keep a max-heap by remaining count. After using an item, hold it aside until its cooldown ends, then put it back.","L":"heap.html#rx-cooldown"},{"id":"rx-heap-dijkstra","y":"reflex","tr":"dsa","s":"Heap","q":"Shortest path with non-negative weights","a":"Min-heap of (distance, node). Pop the closest, relax its edges, skip stale entries.","x":"Always settle the closest unsettled node next; with no negative edges, nobody can later find a shorter way to it. Keep (distance, node) in a min-heap, and when you pop an entry whose distance is out of date, skip it.","L":"heap.html#rx-dijkstra"},{"id":"rx-heap-cxhplog","y":"reflex","tr":"dsa","s":"Heap","q":"heappush / heappop","a":"O(log n) each (height of a complete binary tree). heap[0] is O(1).","x":"A heap is a complete binary tree, so its height is about log₂ n. A push or pop moves one item up or down that height. Looking at the top doesn’t move anything.","L":"heap.html#rx-cxhplog"},{"id":"rx-heap-cxhptopk","y":"reflex","tr":"dsa","s":"Heap","q":"“k largest / k closest / k most frequent”","a":"Heap capped at size k: O(n log k) time, O(k) space.","x":"With the heap capped at k items, each of the n pushes costs log k, not log n. Better than sorting everything when k is small.","L":"heap.html#rx-cxhptopk"},{"id":"rx-heap-cxhpify","y":"reflex","tr":"dsa","s":"Heap","q":"Building a heap from a full list","a":"<code>heapq.heapify(list)</code> is O(n). n separate pushes would be O(n log n).","x":"heapify fixes the list from the bottom up. Most nodes are near the bottom and barely move, so the total work is O(n), cheaper than n separate pushes.","L":"heap.html#rx-cxhpify"},{"id":"rx-trie-prefix","y":"reflex","tr":"dsa","s":"Trie","q":"“starts with”, “prefix”, “autocomplete”, many lookups sharing beginnings","a":"A trie.","x":"A trie stores words letter by letter in a tree, so words with the same beginning share the same path. “Is there any word starting with ca?” becomes: walk c → a and see whether anything is below. You don’t check every word.","L":"trie.html#rx-prefix"},{"id":"rx-trie-node","y":"reflex","tr":"dsa","s":"Trie","q":"You need to write a trie fast in an interview","a":"Node = <code>children</code> dict + <code>end</code> flag. Or plain nested dicts with a <code>\"$\"</code> key for the end.","x":"A trie node needs only two things: a map from letter to child node, and a flag saying “a word ends here”. In Python, nested dictionaries with a special \"$\" key work just as well.","L":"trie.html#rx-node"},{"id":"rx-trie-endflag","y":"reflex","tr":"dsa","s":"Trie","q":"Both “do” and “dog” are words","a":"Mark the end node. <code>search</code> checks the flag, <code>startsWith</code> doesn’t.","x":"After inserting “dog”, the path d → o exists too, but “do” was never inserted. The end flag tells them apart: search needs the flag on the last node, startsWith only needs the path.","L":"trie.html#rx-endflag"},{"id":"rx-trie-counts","y":"reflex","tr":"dsa","s":"Trie","q":"“How many words start with …”, “sum of values with prefix”","a":"Store a counter (or running sum) on every node, updated during insert.","x":"If you’ll ask “how many words start with this?” or “sum of values with this prefix”, keep a running number on every node and update it as each word passes through during insert. A query is then just a walk plus reading one number.","L":"trie.html#rx-counts"},{"id":"rx-trie-replace","y":"reflex","tr":"dsa","s":"Trie","q":"“Replace each word with the shortest root from a dictionary”","a":"Trie of roots; walk each word and stop at the first end flag.","x":"Put the root words in a trie. For each word in the sentence, walk its letters down the trie and stop at the first node marked as the end of a root. That shortest root replaces the word; if you fall off the trie, keep the word.","L":"trie.html#rx-replace"},{"id":"rx-trie-lcp","y":"reflex","tr":"dsa","s":"Trie","q":"“Longest common prefix” of many strings","a":"Walk down while the node has exactly one child and no word ends there.","x":"Insert all the strings. The common prefix is the path from the root as long as there’s only one way to continue and no word has ended yet.","L":"trie.html#rx-lcp"},{"id":"rx-trie-wildcard","y":"reflex","tr":"dsa","s":"Trie","q":"Pattern search with “.” matching any letter","a":"DFS: on a letter follow one child; on “.” try every child; at the end check the flag.","x":"A normal letter means follow that one child. A “.” could be any letter, so try every child with a small DFS. At the end of the pattern, the node must carry the end flag.","L":"trie.html#rx-wildcard"},{"id":"rx-trie-suggest","y":"reflex","tr":"dsa","s":"Trie","q":"Type-ahead: “top 3 suggestions after each character”","a":"Sort words, then store up to 3 words on every node during insert. Walk the typed prefix.","x":"For type-ahead, do the work once at insert time. Insert words in sorted order and keep the first 3 that pass through each node. Then each typed prefix is just a walk to a node and a read of its list.","L":"trie.html#rx-suggest"},{"id":"rx-trie-manywords","y":"reflex","tr":"dsa","s":"Trie","q":"Find many words in one grid","a":"One trie of all words + grid DFS that follows trie children.","x":"Searching the grid once per word repeats the same walks. Put all the words in one trie and run one DFS over the grid that follows trie children. A path stops the moment no word has that prefix.","L":"trie.html#rx-manywords"},{"id":"rx-trie-prune","y":"reflex","tr":"dsa","s":"Trie","q":"Trie-guided search keeps revisiting finished branches","a":"Remove found words (pop the end marker) and delete empty child nodes on the way back.","x":"Once a word is found, it shouldn’t be found again. Remove its end flag, and on the way back delete nodes that no longer have children, so later searches don’t walk dead branches.","L":"trie.html#rx-prune"},{"id":"rx-trie-xor","y":"reflex","tr":"dsa","s":"Trie","q":"“Maximum XOR of two numbers”","a":"Binary trie of 32-bit numbers, high bit first. For each number, greedily walk the opposite bit when possible.","x":"XOR is biggest when the two numbers differ in the highest bits. Store the numbers in a trie of bits, highest bit first. For each number, walk down choosing the opposite bit whenever that child exists; that greedily builds the best partner.","L":"trie.html#rx-xor"},{"id":"rx-trie-notneeded","y":"reflex","tr":"dsa","s":"Trie","q":"Only exact-word lookups, no prefixes","a":"Use a set. Mention the trie only if prefixes or wildcards appear.","x":"A trie earns its keep only when prefixes matter. If you only ask “is this exact word in the list?”, a set is simpler and just as fast.","L":"trie.html#rx-notneeded"},{"id":"rx-trie-cxtrlen","y":"reflex","tr":"dsa","s":"Trie","q":"Trie insert / search / startsWith","a":"O(L) for a word or prefix of length L, independent of how many words are stored.","x":"Insert, search and startsWith each walk one node per letter, so they cost the length of the word. How many words are stored doesn’t matter.","L":"trie.html#rx-cxtrlen"},{"id":"rx-trie-cxtrspace","y":"reflex","tr":"dsa","s":"Trie","q":"Space of a trie","a":"O(total characters) nodes in the worst case, less with shared prefixes; mention the per-node children map (26 array or dict).","x":"In the worst case every inserted character needs its own node: O(total characters). Shared prefixes reuse nodes, so real tries are smaller. Each node also carries a children map (a dict, or an array of 26).","L":"trie.html#rx-cxtrspace"},{"id":"rx-trie-cxtrhash","y":"reflex","tr":"dsa","s":"Trie","q":"Trie vs hash set of words","a":"Exact lookups: a set is simpler (O(L) to hash). Prefix queries, autocomplete, word-search pruning: trie.","x":"For exact lookups a set does the same O(L) work (hashing the word) with less code. Choose a trie for prefix questions, autocomplete and pruning word searches.","L":"trie.html#rx-cxtrhash"},{"id":"rx-graphs-gridgraph","y":"reflex","tr":"dsa","s":"Graphs","q":"A 2-D grid with moves to neighbouring cells","a":"Treat cells as nodes and the 4 directions as edges. No adjacency list needed.","x":"A grid is already a graph: every cell is a node and it connects to its up, down, left and right neighbours. You don’t build an adjacency list; you generate the 4 neighbours on the fly and skip ones outside the grid.","L":"graphs.html#rx-gridgraph"},{"id":"rx-graphs-components","y":"reflex","tr":"dsa","s":"Graphs","q":"“Number of islands / provinces / connected groups”","a":"Loop over every node; on an unvisited one, count += 1 and flood-fill (DFS/BFS) its whole group.","x":"Visit every cell or node. When you hit one that isn’t visited yet, you’ve found a new group: count it and flood-fill the whole group so it’s marked. The count at the end is the number of groups.","L":"graphs.html#rx-components"},{"id":"rx-graphs-multisource","y":"reflex","tr":"dsa","s":"Graphs","q":"Several starting points spreading at once (rotting oranges, walls and gates, distance to nearest 0)","a":"Multi-source BFS: put <b>all","x":"When several places spread at the same time (all rotten oranges, all gates), put all of them in the queue first. BFS then grows outward from all of them together, one ring per minute.","L":"graphs.html#rx-multisource"},{"id":"rx-graphs-bfsshortest","y":"reflex","tr":"dsa","s":"Graphs","q":"“Minimum steps / moves / transformations” with equal-cost moves","a":"BFS. The first time you reach the target is the shortest.","x":"BFS explores in rings: everything 1 move away, then 2 moves, and so on. So the first time it reaches the target, that’s the fewest moves, as long as every move costs the same.","L":"graphs.html#rx-bfsshortest"},{"id":"rx-graphs-markenqueue","y":"reflex","tr":"dsa","s":"Graphs","q":"Writing BFS","a":"Mark a node as seen when you <b>enqueue","x":"Mark a node as seen at the moment you put it in the queue. If you wait until it’s popped, other nodes can add it again in the meantime, so it gets processed several times.","L":"graphs.html#rx-markenqueue"},{"id":"rx-graphs-clone","y":"reflex","tr":"dsa","s":"Graphs","q":"“Clone / deep copy a graph”","a":"Dict old → new. Create the copy before recursing into neighbours; return the existing copy if seen.","x":"Keep a dictionary original → copy. Create a node’s copy and store it before visiting its neighbours. When a neighbour is already in the dictionary, reuse its copy; that also stops infinite loops on cycles.","L":"graphs.html#rx-clone"},{"id":"rx-graphs-border","y":"reflex","tr":"dsa","s":"Graphs","q":"“Surrounded regions”, “which cells reach the ocean / edge”","a":"Flip it: flood from the border (or ocean) inward, then everything not reached is the answer.","x":"Asking “which cells can’t reach the edge?” is hard. Turn it around: start from the border and flood inward. Everything the flood touches is safe; everything it never reached is the answer.","L":"graphs.html#rx-border"},{"id":"rx-graphs-bipartite","y":"reflex","tr":"dsa","s":"Graphs","q":"“Split into two groups so every edge crosses”, “two-colour the graph”","a":"BFS/DFS colouring with 0/1. A neighbour with the same colour means False.","x":"Try to colour nodes with two colours so every edge joins different colours. Colour a start node A, its neighbours B, their neighbours A, and so on. If you ever find an edge with the same colour on both ends, it can’t be done.","L":"graphs.html#rx-bipartite"},{"id":"rx-graphs-implicit","y":"reflex","tr":"dsa","s":"Graphs","q":"States that transform into other states (word ladder, lock combinations, puzzles)","a":"States are nodes, one move is an edge. BFS over states, generating neighbours on the fly.","x":"Sometimes the graph isn’t given. Each possible state (a word, a lock combination) is a node, and one allowed move connects two states. Run BFS over states, creating the neighbours of a state only when you reach it.","L":"graphs.html#rx-implicit"},{"id":"rx-graphs-topo","y":"reflex","tr":"dsa","s":"Graphs","q":"“Prerequisites”, “order of tasks”, “build order”, dependencies","a":"Kahn’s algorithm: in-degrees, queue of zeros, pop and decrement.","x":"Count how many prerequisites each task still has (its in-degree). Tasks with 0 can be done now, so queue them. Each time you finish one, reduce the counts of the tasks that depended on it; any that drop to 0 join the queue.","L":"graphs.html#rx-topo"},{"id":"rx-graphs-cycle","y":"reflex","tr":"dsa","s":"Graphs","q":"“Is it possible to finish?” / cycle in a directed graph","a":"Run Kahn’s: if fewer than n nodes come out, there’s a cycle. (Or DFS with 3 states.)","x":"In a cycle every task waits for another task in the cycle, so none of them ever reaches in-degree 0. If Kahn’s algorithm outputs fewer than n tasks, there’s a cycle and the schedule is impossible.","L":"graphs.html#rx-cycle"},{"id":"rx-graphs-unionfind","y":"reflex","tr":"dsa","s":"Graphs","q":"Groups merging as edges arrive; “are x and y connected?” many times","a":"Union-find with path compression (and union by rank/size).","x":"Union-find keeps a “parent” for every item; following parents leads to the group’s representative (root). Merging two groups = point one root at the other. Two items are connected if they have the same root.","L":"graphs.html#rx-unionfind"},{"id":"rx-graphs-redundant","y":"reflex","tr":"dsa","s":"Graphs","q":"“Which edge creates a cycle?”, “redundant connection”","a":"Process edges in order; the first edge whose endpoints already share a root is the answer.","x":"Add edges one by one with union-find. An edge whose two ends already have the same root connects nodes that were already connected, so it closes a cycle: that’s the extra edge.","L":"graphs.html#rx-redundant"},{"id":"rx-graphs-tree","y":"reflex","tr":"dsa","s":"Graphs","q":"“Is this graph a valid tree?”","a":"Exactly n − 1 edges and no cycle (union-find never sees a shared root).","x":"A tree on n nodes is connected with no cycles, which means exactly n − 1 edges and union-find never meets an edge whose ends are already joined.","L":"graphs.html#rx-tree"},{"id":"rx-graphs-dijkstra","y":"reflex","tr":"dsa","s":"Graphs","q":"Shortest path with non-negative weights","a":"Min-heap of (dist, node). Pop, skip if stale, relax neighbours.","x":"Always settle the closest unsettled node next; with no negative edges, nothing found later can be shorter. Keep (distance, node) in a min-heap, relax the edges of each popped node, and skip popped entries that are out of date.","L":"graphs.html#rx-dijkstra"},{"id":"rx-graphs-kstops","y":"reflex","tr":"dsa","s":"Graphs","q":"Cheapest path with “at most k stops” (or negative edges)","a":"Bellman-Ford for k + 1 rounds, each round reading a copy of the previous costs.","x":"With a limit on stops, “shortest so far” isn’t enough; a cheaper route might use too many flights. Bellman-Ford in rounds fixes this: round i finds the cheapest prices using at most i flights. Each round reads a copy of the previous round, so no route takes two new flights in one round.","L":"graphs.html#rx-kstops"},{"id":"rx-graphs-minimax","y":"reflex","tr":"dsa","s":"Graphs","q":"Minimize the maximum along a path (swim in rising water, min effort path)","a":"Dijkstra where a path’s cost is the max edge so far, not the sum.","x":"Sometimes a path’s cost is its highest point, not the sum (how deep the water must be to swim it). Dijkstra still works: the cost of reaching a neighbour is max(cost so far, neighbour’s height) instead of a sum.","L":"graphs.html#rx-minimax"},{"id":"rx-graphs-mst","y":"reflex","tr":"dsa","s":"Graphs","q":"“Connect all points / cities with minimum total cost”","a":"Minimum spanning tree: Prim (heap from one node) or Kruskal (sort edges + union-find).","x":"To connect everything as cheaply as possible, choose cheap edges that don’t form loops. Kruskal: sort all edges by cost and take each one that joins two different groups. Prim: grow one tree, always adding the cheapest edge that leaves it.","L":"graphs.html#rx-mst"},{"id":"rx-graphs-cxgrve","y":"reflex","tr":"dsa","s":"Graphs","q":"BFS, DFS, topological sort, connected components","a":"O(V + E) time, O(V) space.","x":"BFS and DFS visit every node once and look at every edge once (twice for undirected graphs): O(V + E). The visited set and the queue or stack hold up to V nodes.","L":"graphs.html#rx-cxgrve"},{"id":"rx-graphs-cxgrgrid","y":"reflex","tr":"dsa","s":"Graphs","q":"Traversal on an R × C grid","a":"O(R·C) time; O(R·C) visited (or in-place marking); recursion depth up to R·C for DFS.","x":"On a grid every cell is a node with at most 4 edges, so V + E is about R·C. A DFS can go as deep as the number of cells, which matters for Python’s recursion limit.","L":"graphs.html#rx-cxgrgrid"},{"id":"rx-graphs-cxgrdijk","y":"reflex","tr":"dsa","s":"Graphs","q":"Dijkstra with a binary heap","a":"O((V + E) log V) time, O(V + E) space.","x":"Each edge can push one entry onto the heap, and each push or pop costs log of the heap size.","L":"graphs.html#rx-cxgrdijk"},{"id":"rx-dp-isdp","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"“How many ways”, “minimum / maximum”, “is it possible” + a sequence of choices","a":"DP. Before coding, write the state as a sentence.","x":"Dynamic programming fits when you make a sequence of choices and the question is “how many ways”, “what’s the best” or “is it possible”. The same smaller questions come up again and again, so you answer each once and reuse it.","L":"dp.html#rx-isdp"},{"id":"rx-dp-state","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"You’re stuck on a DP problem","a":"Ask: “what’s the minimum I need to know about the past to decide the future?” That’s the state.","x":"The state is the smallest summary of the past that is enough to decide what comes next. For climbing stairs, how you got here doesn’t matter, only which step you’re on, so the state is just i.","L":"dp.html#rx-state"},{"id":"rx-dp-memofirst","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"The recurrence is clear but the table order isn’t","a":"Write the recursion, add <code>@lru_cache</code>, and convert to a table later if needed.","x":"If you can write the recursion but not the table order, don’t fight it. Write the recursive function, add a cache, and you already have a correct DP. Convert it to a loop later only if needed.","L":"dp.html#rx-memofirst"},{"id":"rx-dp-order","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Writing a bottom-up loop","a":"Fill in the order your recurrence reads: if dp[i] reads dp[i − 1], go up; if it reads dp[i + 1], go down.","x":"A cell can only be filled after the cells it reads. If dp[i] uses dp[i − 1], fill from small i upwards; if it uses dp[i + 1], fill from the end downwards.","L":"dp.html#rx-order"},{"id":"rx-dp-twovars","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"dp[i] reads only dp[i − 1] and dp[i − 2] (or one previous row)","a":"Replace the table with rolling variables or one row.","x":"If each step only looks back one or two cells, you don’t need the whole table. Keep just those last values in variables and shift them forward each step.","L":"dp.html#rx-twovars"},{"id":"rx-dp-takeskip","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Choose items with a conflict between neighbours (house robber, delete and earn)","a":"<code>dp[i] = max(dp[i − 1], dp[i − 2] + value[i])</code>.","x":"At each item you either skip it (keep the best answer up to the previous item) or take it, which forbids the previous item, so add it to the best answer up to two items back. Take whichever is bigger.","L":"dp.html#rx-takeskip"},{"id":"rx-dp-unbounded","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Fewest / most items to reach an amount, items reusable (coin change, perfect squares)","a":"<code>dp[a] = min over c of dp[a − c] + 1</code>, with dp[0] = 0 and others ∞.","x":"dp[a] is the fewest coins to make amount a. The last coin used was some coin c, leaving a − c to make, so try every coin and take the best dp[a − c] + 1. Start with dp[0] = 0 and everything else “impossible” (∞).","L":"dp.html#rx-unbounded"},{"id":"rx-dp-combos","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Count ways to reach an amount","a":"Combinations (order doesn’t matter): loop items <b>outer","x":"When counting ways to reach an amount, the loop order decides whether 1 + 2 and 2 + 1 are the same way. Coins in the outer loop counts each combination once; amounts in the outer loop counts every ordering.","L":"dp.html#rx-combos"},{"id":"rx-dp-endinghere","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Best subsequence / subarray with a property (LIS, longest chain)","a":"<code>dp[i]</code> = best that <b>ends at","x":"Let dp[i] be the best answer that ends exactly at position i. To compute it, look at earlier positions j that can come before i and extend the best one. The final answer is the best over all i, because the best sequence can end anywhere.","L":"dp.html#rx-endinghere"},{"id":"rx-dp-minmax","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Max product subarray (negatives flip signs)","a":"Track both the max and the min ending here.","x":"Multiplying by a negative number turns the smallest product into the largest. So at every position keep both the largest and the smallest product ending there; a negative number swaps their roles.","L":"dp.html#rx-minmax"},{"id":"rx-dp-segment","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"“Can the string be split into dictionary words?”, decode ways","a":"<code>dp[i]</code> = answer for the prefix of length i; try every last piece <code>s[j:i]</code>.","x":"dp[i] answers the question for the first i characters. To fill it, try every possible last piece s[j:i]: if that piece is valid and dp[j] is true (or has ways), the first i characters work too.","L":"dp.html#rx-segment"},{"id":"rx-dp-palin","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Palindromic substrings / longest palindromic substring","a":"Expand around every center (2n − 1 of them).","x":"Every palindrome has a middle. Try each middle (on a letter, or between two letters: 2n − 1 middles) and expand outward while both ends match. No table is needed.","L":"dp.html#rx-palin"},{"id":"rx-dp-twostrings","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Two strings: common subsequence, edit distance, interleaving","a":"<code>dp[i][j]</code> over prefixes, table (m + 1) × (n + 1). Compare the last characters.","x":"With two strings, dp[i][j] is the answer for the first i letters of one and the first j letters of the other. Look at the last letters of each: if they match, extend the diagonal answer; otherwise take the best of dropping one letter from either string.","L":"dp.html#rx-twostrings"},{"id":"rx-dp-gridpaths","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Count paths or min cost in a grid moving right/down","a":"<code>dp[r][c] = combine(dp[r − 1][c], dp[r][c − 1])</code>. First row and column are base cases.","x":"If you can only move right or down, every cell is reached from the cell above or the cell to the left. So its value combines those two (add them for counting, min for cost). The first row and column have only one way in.","L":"dp.html#rx-gridpaths"},{"id":"rx-dp-editops","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Minimum edits (insert, delete, replace)","a":"Match: diagonal. Else 1 + min(above = delete, left = insert, diagonal = replace).","x":"Compare the last letters of the two prefixes. If they match, no edit is needed: take the diagonal. If not, try the three edits (delete = cell above, insert = cell to the left, replace = diagonal), each costing 1, and keep the cheapest.","L":"dp.html#rx-editops"},{"id":"rx-dp-knap","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"0/1 knapsack in one row","a":"Loop capacity <b>backwards","x":"In a one-row knapsack, going through capacities from high to low means each cell still reads values from before this item, so each item is used at most once. Going low to high would let the same item be added again.","L":"dp.html#rx-knap"},{"id":"rx-dp-subsetsum","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"“Partition into equal sums”, “target sum with + and −”","a":"Turn it into subset sum: boolean (or counting) 0/1 knapsack over sums.","x":"Splitting into two equal halves means finding a subset that adds up to half the total. Keep track of which sums are reachable; each number either joins a subset or doesn’t.","L":"dp.html#rx-subsetsum"},{"id":"rx-dp-statemachine","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Stock problems with cooldowns, fees, or k transactions","a":"One variable per state (holding, sold, resting) and transitions for each day.","x":"Stock problems are easiest as a few states you can be in each day: holding a stock, just sold, or resting. Each day, compute the best profit for every state from yesterday’s states.","L":"dp.html#rx-statemachine"},{"id":"rx-dp-interval","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"Burst balloons, merge stones, best way to split a range","a":"<code>dp[l][r]</code> over ranges, filled by increasing length; try every k as the last (or first) action.","x":"For problems on a range (burst balloons, split a range), let dp[l][r] be the best answer for just that range. Try every position k as the last thing done inside it, combine the two smaller ranges, and fill shorter ranges before longer ones.","L":"dp.html#rx-interval"},{"id":"rx-dp-cxdpstates","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"“What’s the complexity of this DP?”","a":"Count states (table size), multiply by work per state (how many earlier cells one cell reads).","x":"DP time = (number of cells in the table) × (work to fill one cell, i.e. how many earlier cells it reads).","L":"dp.html#rx-cxdpstates"},{"id":"rx-dp-cxdptrans","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"An inner loop choosing among earlier states (LIS, word break, partition)","a":"Work per state is O(n) (or O(k) choices) → multiply it in: LIS O(n²), coin change O(amount × coins).","x":"If filling one cell loops over many earlier choices, that loop multiplies the time.","L":"dp.html#rx-cxdptrans"},{"id":"rx-dp-cxdpspace","y":"reflex","tr":"dsa","s":"Dynamic Programming","q":"A 2-D table where row i only reads row i − 1 (or 1-D reading the last few)","a":"Keep only the rows you need: O(m·n) → O(n), or O(n) → O(1).","x":"If each row only reads the row before it, keep two rows (or one) instead of the whole table. If each cell only reads the last one or two, keep two variables.","L":"dp.html#rx-cxdpspace"},{"id":"rx-greedy-intervals-greedy","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"You’re tempted to always take the biggest / earliest / cheapest","a":"Before coding, state why it’s safe (an exchange argument). Can’t? Use DP.","x":"Greedy means taking the locally best option each time and never looking back. It’s only correct if you can argue that swapping the greedy choice into any optimal solution doesn’t make it worse. If you can’t make that argument, or you find a counterexample, use DP.","L":"greedy-intervals.html#rx-greedy"},{"id":"rx-greedy-intervals-reach","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Can you reach the last index?”","a":"Track the farthest reachable index; fail if i ever exceeds it.","x":"You don’t need to try every path. Walk left to right remembering the farthest index you can reach so far. If you ever stand on an index beyond that, you’re stuck.","L":"greedy-intervals.html#rx-reach"},{"id":"rx-greedy-intervals-levels","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Minimum number of jumps”","a":"BFS levels without a queue: when i hits the current level’s end, jump and set end = far.","x":"Think of BFS levels. With j jumps you can reach a window of indexes; while scanning that window, compute the farthest point reachable with one more jump. When you reach the window’s end, take the jump and the next window ends at that farthest point.","L":"greedy-intervals.html#rx-levels"},{"id":"rx-greedy-intervals-kadane","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Maximum subarray sum”","a":"<code>cur = max(x, cur + x)</code>; track the best cur.","x":"At each number, decide: is the best subarray ending here “just me” or “me added to the best one ending just before”? If the previous run is negative, it only drags you down, so start fresh. Keep the best value you ever see.","L":"greedy-intervals.html#rx-kadane"},{"id":"rx-greedy-intervals-gasreset","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Circular route with gains and costs (gas station)","a":"If total ≥ 0 an answer exists. Scan once; when the tank goes negative, start after this station.","x":"If total gas ≥ total cost, some start works. Drive from station 0. If the tank goes negative at station i, no station from your start up to i can be the start, so restart just after i with an empty tank.","L":"greedy-intervals.html#rx-gasreset"},{"id":"rx-greedy-intervals-twopass","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Constraints with both neighbours (candy, trapping water)","a":"Left-to-right pass for the left neighbour, right-to-left pass for the right, combine with max.","x":"A rule involving both neighbours is easier as two one-sided rules. The left-to-right pass satisfies “more than my left neighbour”, the right-to-left pass satisfies “more than my right neighbour”, and taking the max of both satisfies both.","L":"greedy-intervals.html#rx-twopass"},{"id":"rx-greedy-intervals-lastocc","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Partition so each letter appears in at most one part”","a":"Record each letter’s last index. Extend the current part’s end to the last index of every letter seen; cut when i == end.","x":"A part can only end once every letter in it has appeared for the last time. Record the last position of each letter. Walk the string, stretching the current part’s end to the last position of every letter you see; when you reach that end, cut.","L":"greedy-intervals.html#rx-lastocc"},{"id":"rx-greedy-intervals-smallestfirst","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Group cards into consecutive runs (hand of straights)","a":"Sorted counter; the smallest remaining card must start a run.","x":"The smallest card left can’t be in the middle of a run (nothing smaller is left), so it must start one. Take it and the next size − 1 consecutive cards, and repeat.","L":"greedy-intervals.html#rx-smallestfirst"},{"id":"rx-greedy-intervals-lohi","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Wildcards that could be several things (“*” as “(”, “)” or empty)","a":"Track a range [lo, hi] of possible states instead of branching.","x":"A “*” could be “(”, “)” or nothing; branching on all three explodes. Instead track the range of possible open-bracket counts: lo (fewest) and hi (most). If hi drops below 0 it’s invalid; clamp lo at 0; at the end lo must be 0.","L":"greedy-intervals.html#rx-lohi"},{"id":"rx-greedy-intervals-sortdiff","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Split people between two options at different costs (two city scheduling)","a":"Sort by cost difference; the first half takes option A.","x":"Ask how much each person saves by going to A instead of B (cost A − cost B). Sort by that difference: the people with the most negative values save the most by going to A, so the first half goes to A and the rest to B.","L":"greedy-intervals.html#rx-sortdiff"},{"id":"rx-greedy-intervals-mergestart","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Merge overlapping intervals”","a":"Sort by start. If s ≤ last end, extend; else append.","x":"Sort by start time; then overlapping intervals sit next to each other. Walk them: if the next one starts before (or when) the last merged one ends, stretch that end. Otherwise start a new merged interval.","L":"greedy-intervals.html#rx-mergestart"},{"id":"rx-greedy-intervals-keepend","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Max non-overlapping”, “remove the fewest”, “fewest arrows”","a":"Sort by <b>end","x":"To fit the most non-overlapping intervals, always keep the one that ends earliest; it leaves the most room for the rest. Sort by end, and keep each interval that starts after the last kept one ends.","L":"greedy-intervals.html#rx-keepend"},{"id":"rx-greedy-intervals-overlap","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Do two intervals overlap?","a":"<code>a.start &lt;= b.end and b.start &lt;= a.end</code>. Check whether touching ends count (≤ vs &lt;).","x":"Two intervals overlap when each one starts before the other ends. Decide up front whether intervals that only touch (one ends exactly when the next starts) count as overlapping.","L":"greedy-intervals.html#rx-overlap"},{"id":"rx-greedy-intervals-rooms","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Minimum rooms / platforms / max overlap at once”","a":"Sweep sorted starts and ends (or a min-heap of end times).","x":"Count how many meetings are running at once at their busiest moment. Sort start times and end times separately and sweep through time: a start needs a room, an end frees one. The largest count you see is the number of rooms.","L":"greedy-intervals.html#rx-rooms"},{"id":"rx-greedy-intervals-insert3","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Insert an interval into a sorted, non-overlapping list","a":"Three phases: copy those ending before it, absorb those overlapping it, copy the rest.","x":"The list is already sorted and non-overlapping, so the new interval splits it into three parts: intervals entirely before it (copy them), intervals touching it (merge them all into one), and intervals entirely after it (copy them).","L":"greedy-intervals.html#rx-insert3"},{"id":"rx-greedy-intervals-queries","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Many queries about intervals (smallest interval containing q)","a":"Answer offline: sort queries and intervals, sweep, keep a heap of candidates and drop expired ones.","x":"Answer the queries in sorted order instead of the order asked (then put answers back). As the query value grows, add intervals that have started into a heap keyed by size, and drop ones that have already ended. The heap top answers the query.","L":"greedy-intervals.html#rx-queries"},{"id":"rx-greedy-intervals-cxgisort","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"“Sort intervals by start/end, then one pass”","a":"O(n log n) total: the sort dominates the O(n) sweep.","x":"Sorting costs O(n log n) and the sweep afterwards is O(n). The sort is the bigger cost, so the total is O(n log n).","L":"greedy-intervals.html#rx-cxgisort"},{"id":"rx-greedy-intervals-cxgiheap","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Interval scheduling with a min-heap of end times (meeting rooms, CPU tasks)","a":"O(n log n) time, O(n) heap space.","x":"Each interval is pushed onto the heap and popped at most once, and each heap operation costs log n.","L":"greedy-intervals.html#rx-cxgiheap"},{"id":"rx-greedy-intervals-cxgipair","y":"reflex","tr":"dsa","s":"Greedy & Intervals","q":"Checking every interval against every other","a":"That’s O(n²). Sort so related intervals sit next to each other, then sweep.","x":"Comparing every interval with every other is n × n work. After sorting, intervals that interact are neighbours, so one sweep is enough.","L":"greedy-intervals.html#rx-cxgipair"},{"id":"rx-bits-xorpairs","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Every element appears twice except one”","a":"XOR everything together.","x":"XOR has two handy rules: x ^ x = 0 and x ^ 0 = x, and order doesn’t matter. So XOR-ing everything makes every pair cancel out, and only the single number is left.","L":"bits.html#rx-xorpairs"},{"id":"rx-bits-lowclear","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"Count set bits, or remove them one by one","a":"<code>n &amp;= n − 1</code> in a loop.","x":"n − 1 flips the lowest 1-bit of n to 0 and the zeros below it to 1s. So n & (n − 1) is n with its lowest 1 removed. Repeat until n is 0, counting the loops: that’s the number of 1s.","L":"bits.html#rx-lowclear"},{"id":"rx-bits-lowbit","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"You need the lowest set bit of x (Fenwick trees, splitting groups)","a":"<code>x &amp; −x</code>.","x":"In two’s complement, −x is “flip every bit, then add 1”. Every bit above the lowest 1 ends up opposite in x and −x, so x & −x keeps only the lowest 1-bit.","L":"bits.html#rx-lowbit"},{"id":"rx-bits-pow2","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Is n a power of two?”","a":"<code>n &gt; 0 and n &amp; (n − 1) == 0</code>.","x":"A power of two has exactly one 1-bit. Removing the lowest 1 (n & (n − 1)) leaves 0 only in that case. Check n > 0 too, because 0 also gives 0.","L":"bits.html#rx-pow2"},{"id":"rx-bits-checkbit","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"Test, set, clear or toggle bit i","a":"Test <code>x &gt;&gt; i &amp; 1</code>. Set <code>x | 1 &lt;&lt; i</code>. Clear <code>x &amp; ~(1 &lt;&lt; i)</code>. Toggle <code>x ^ 1 &lt;&lt; i</code>.","x":"1 << i is a number with only bit i set. AND with it to test the bit, OR to set it, AND with its inverse to clear it, XOR to flip it.","L":"bits.html#rx-checkbit"},{"id":"rx-bits-missingxor","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“One number missing from 0…n”","a":"XOR all indexes 0…n with all values.","x":"XOR every index 0 … n together with every value in the array. Each number that’s present appears twice (once as an index, once as a value) and cancels; the missing one appears only once and survives.","L":"bits.html#rx-missingxor"},{"id":"rx-bits-pymask","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"Bit tricks with negatives in Python (sum without +, reverse bits)","a":"Mask with <code>0xFFFFFFFF</code> to emulate 32 bits; convert back with <code>~(a ^ MASK)</code> if above 0x7FFFFFFF.","x":"Python integers never overflow, and a negative number behaves as if it had infinitely many 1s in front. To imitate 32-bit integers, keep only the low 32 bits with & 0xFFFFFFFF, and convert results above 0x7FFFFFFF back to negative.","L":"bits.html#rx-pymask"},{"id":"rx-bits-masks","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"Every subset of a small set (n ≤ 20), or “visited set” as part of a DP state","a":"Loop <code>mask</code> over 0 … 2ⁿ − 1; item i is chosen when <code>mask &gt;&gt; i &amp; 1</code>.","x":"With n small items, each subset is an n-bit number: bit i = 1 means item i is in the subset. Counting from 0 to 2ⁿ − 1 lists every subset exactly once.","L":"bits.html#rx-masks"},{"id":"rx-bits-dpbits","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Count bits for every number 0…n”","a":"<code>dp[i] = dp[i &gt;&gt; 1] + (i &amp; 1)</code>.","x":"i >> 1 is i without its last bit, a smaller number you’ve already counted. So bits(i) = bits(i >> 1) + (the last bit of i).","L":"bits.html#rx-dpbits"},{"id":"rx-bits-split","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Two numbers appear once, the rest twice”","a":"XOR all → a ^ b. Take its lowest set bit; XOR each group (bit set / not set) separately.","x":"XOR everything to get a ^ b (the two singles). They differ in at least one bit, the lowest 1-bit of a ^ b. Split all numbers by that bit: a and b fall into different groups, pairs stay together, and XOR-ing each group gives one single.","L":"bits.html#rx-split"},{"id":"rx-bits-mod3","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Every element appears three times except one”","a":"Count each bit position mod 3 (or the ones/twos trick).","x":"Look at one bit position at a time and add up that bit over all numbers. Numbers that appear three times contribute a multiple of 3, so the count mod 3 is exactly the single number’s bit.","L":"bits.html#rx-mod3"},{"id":"rx-bits-commonprefix","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"“Bitwise AND of all numbers in [left, right]”","a":"Shift both right until equal, then shift back.","x":"ANDing a whole range of numbers keeps only the leading bits that all of them share; every lower bit is 0 somewhere in the range. So shift left and right until they’re equal (that’s the shared prefix), then shift it back.","L":"bits.html#rx-commonprefix"},{"id":"rx-bits-cxbtlog","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"A loop doing n >>= 1 or n //= 2","a":"O(log n) rounds; O(1) if n is a fixed 32/64-bit integer.","x":"Each n >>= 1 removes one binary digit, and n has about log₂ n digits. For a fixed 32- or 64-bit integer that’s at most 32 or 64 steps, a constant.","L":"bits.html#rx-cxbtlog"},{"id":"rx-bits-cxbtkern","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"n &= n - 1 in a loop","a":"Runs once per set bit: O(popcount) ≤ O(log n).","x":"n &= n − 1 removes one 1-bit per loop, so the loop runs once per 1-bit, not once per bit position.","L":"bits.html#rx-cxbtkern"},{"id":"rx-bits-cxbtrange","y":"reflex","tr":"dsa","s":"Bit Manipulation","q":"A bit answer for every number 0…n","a":"Reuse smaller answers (<code>i &gt;&gt; 1</code> or <code>i &amp; (i − 1)</code>) for O(n) total.","x":"When you need an answer for every number up to n, build each one from a smaller number you’ve already solved (i >> 1, or i & (i − 1)). Each takes O(1), so all of them take O(n).","L":"bits.html#rx-cxbtrange"},{"id":"rx-sd-start-whatchanges","y":"reflex","tr":"sd","s":"Start Here: Design Thinking","q":"Any design question, big or small","a":"Ask “what will change?” first, and name the exact thing (channel, pricing rule, storage, traffic).","x":"Good design starts by spotting what is likely to change. Before drawing anything, name it concretely: “new notification channels will be added”, “pricing rules differ per city”, “traffic will grow 10×”. That decides where you need flexibility.","L":"sd-start.html#rx-whatchanges"},{"id":"rx-sd-start-hideit","y":"reflex","tr":"sd","s":"Start Here: Design Thinking","q":"You’ve found the part that changes","a":"Put it behind an interface (code) or an API/queue (system), and pass the implementation in from outside.","x":"Once you know what changes, wrap it so the rest of the code doesn’t care which version it gets. In code that’s an interface; in a system it’s an API or a queue. Hand the actual implementation in from outside, so swapping it needs no other edits.","L":"sd-start.html#rx-hideit"},{"id":"rx-sd-start-readuml","y":"reflex","tr":"sd","s":"Start Here: Design Thinking","q":"A class diagram","a":"Read each line as Java: ▷ solid = extends, ▷ dashed = implements, ◆ = owns a field, ⇢ dashed = uses as a parameter.","x":"Each arrow in a class diagram is a line of Java. Read them one by one: a solid line with a hollow triangle means extends, a dashed one means implements, a filled diamond means “owns this as a field”, and a dashed open arrow means “uses it, e.g. as a parameter”.","L":"sd-start.html#rx-readuml"},{"id":"rx-sd-start-diamond","y":"reflex","tr":"sd","s":"Start Here: Design Thinking","q":"Composition (◆) or aggregation (◇)?","a":"Does the owner create the part and does the part die with it? Yes → ◆ composition. Passed in and shared → ◇ aggregation.","x":"Ask who creates the part and whether it can outlive the owner. If the owner creates it and it dies with the owner (a car’s engine), that’s composition ◆. If it’s passed in and can be shared or exist alone (a team’s players), that’s aggregation ◇.","L":"sd-start.html#rx-diamond"},{"id":"rx-sd-java-pillars","y":"reflex","tr":"sd","s":"Java & OOP","q":"“Explain the four pillars of OOP”","a":"One line each with an example: encapsulation (private balance + withdraw rule), abstraction (interface hides how), inheritance (reuse a parent), polymorphism (one call, many behaviours).","x":"Give one sentence and one tiny example per pillar. Encapsulation: data is private and changed only through methods with rules. Abstraction: callers use what it does, not how. Inheritance: a child reuses a parent. Polymorphism: one call does different things depending on the object.","L":"sd-java.html#rx-pillars"},{"id":"rx-sd-java-passvalue","y":"reflex","tr":"sd","s":"Java & OOP","q":"“Is Java pass-by-reference?”","a":"No. Always pass-by-value. For objects, the value copied is the reference, so a method can mutate the object but can’t repoint the caller’s variable.","x":"Java always copies the argument. For an object, what gets copied is the reference (the address), so both variables point at the same object: changes to the object are visible to the caller, but reassigning the parameter only changes the copy.","L":"sd-java.html#rx-passvalue"},{"id":"rx-sd-java-equals","y":"reflex","tr":"sd","s":"Java & OOP","q":"Comparing objects, or using objects as HashMap keys","a":"<code>==</code> compares references; <code>equals()</code> compares values. Override <code>equals</code> and <code>hashCode</code> together.","x":"== asks “are these the very same object?”. equals() asks “do they mean the same value?”. Hash maps first use hashCode() to find the bucket, then equals() inside it, so if you override one you must override the other, or equal keys get lost.","L":"sd-java.html#rx-equals"},{"id":"rx-sd-java-access","y":"reflex","tr":"sd","s":"Java & OOP","q":"Choosing an access modifier","a":"Start <code>private</code>. Widen only when needed: package-private → protected → public. Expose methods, not fields.","x":"Make everything private by default and open it up only when something outside truly needs it. Let callers go through methods, so you can add checks or change the internals later without breaking them.","L":"sd-java.html#rx-access"},{"id":"rx-sd-java-static","y":"reflex","tr":"sd","s":"Java & OOP","q":"static , final , this","a":"static = belongs to the class (one copy). final = assign once (variable), no override (method), no subclass (class). this = the current object.","x":"static belongs to the class itself: one shared copy, usable without an object. final means “fixed”: a variable can’t be reassigned, a method can’t be overridden, a class can’t be extended. this is the current object.","L":"sd-java.html#rx-static"},{"id":"rx-sd-java-ifaceabs","y":"reflex","tr":"sd","s":"Java & OOP","q":"Interface or abstract class?","a":"Capability many unrelated classes share → interface. Shared state or a fixed algorithm across a family → abstract class.","x":"Use an interface for a capability that unrelated classes can have (Comparable, Payable). Use an abstract class when related classes share fields or a fixed series of steps (a base Report with a shared header/footer).","L":"sd-java.html#rx-ifaceabs"},{"id":"rx-sd-java-dispatch","y":"reflex","tr":"sd","s":"Java & OOP","q":"Overriding vs overloading","a":"Overriding: same signature in a subclass, chosen at runtime by the object. Overloading: same name, different parameters, chosen at compile time by declared types.","x":"Overriding is the same method redefined in a subclass; Java picks the version by the real object at runtime. Overloading is several methods with the same name but different parameters; Java picks one by the declared types when compiling.","L":"sd-java.html#rx-dispatch"},{"id":"rx-sd-java-generics","y":"reflex","tr":"sd","s":"Java & OOP","q":"A collection or helper that should work for any type, safely","a":"Generics <code>&lt;T&gt;</code>. Bound with <code>T extends X</code> when you need X’s methods. PECS: <code>? extends</code> to read, <code>? super</code> to write.","x":"Generics let one class or method work with any type while the compiler still checks types for you. Add a bound when you need methods of a type; for wildcards remember PECS: a Producer you read from is ? extends, a Consumer you write into is ? super.","L":"sd-java.html#rx-generics"},{"id":"rx-sd-java-enums","y":"reflex","tr":"sd","s":"Java & OOP","q":"A fixed set of values (vehicle types, states, operations)","a":"Enum with fields and methods, or constant-specific bodies. Use <code>EnumMap</code> for lookups.","x":"When the values are a fixed list known in advance, use an enum instead of strings or ints: typos become compile errors. Enums can carry fields and methods, and EnumMap is a fast map keyed by them.","L":"sd-java.html#rx-enums"},{"id":"rx-sd-java-hasa","y":"reflex","tr":"sd","s":"Java & OOP","q":"Tempted to extend a class just to reuse code","a":"Prefer composition (HAS-A) and delegate. Inherit only for a true IS-A that respects the parent’s contract.","x":"Inheritance ties you to everything the parent does and promises. If you only want to reuse some code, keep an instance of the other class as a field and call it (HAS-A). Inherit only when the child truly IS-A parent everywhere the parent is used.","L":"sd-java.html#rx-hasa"},{"id":"rx-sd-java-coupling","y":"reflex","tr":"sd","s":"Java & OOP","q":"“Is this a good design?”","a":"Aim for low coupling (depend on interfaces, inject dependencies) and high cohesion (each class does one focused job).","x":"Low coupling: classes know little about each other (they depend on interfaces and receive their dependencies), so a change in one doesn’t ripple. High cohesion: everything inside a class serves one purpose.","L":"sd-java.html#rx-coupling"},{"id":"rx-sd-solid-srp","y":"reflex","tr":"sd","s":"SOLID","q":"A class that changes for unrelated reasons (maths, formatting, storage)","a":"Split by reason to change: one class per actor who could request a change.","x":"Ask who could request a change to this class. If the finance team (calculations), the design team (formatting) and the DBA (storage) could each force edits, it has three jobs. Split it so each class has one reason to change.","L":"sd-solid.html#rx-srp"},{"id":"rx-sd-solid-godclass","y":"reflex","tr":"sd","s":"SOLID","q":"A 1,000-line Manager / Util / Service class","a":"List its responsibilities, then extract each into a focused class the original delegates to.","x":"A giant Manager or Util class is many classes glued together. List what it does, give each responsibility its own small class, and let the old class delegate to them, so callers don’t break while you refactor.","L":"sd-solid.html#rx-godclass"},{"id":"rx-sd-solid-ocp","y":"reflex","tr":"sd","s":"SOLID","q":"“We’ll need to add more types later”","a":"Put the varying behaviour behind an interface. New type = new class, no edits to existing code.","x":"Open for extension, closed for modification. If new types will arrive, put the varying behaviour behind an interface. Adding a type then means writing a new class, not editing code that already works and is tested.","L":"sd-solid.html#rx-ocp"},{"id":"rx-sd-solid-switchtype","y":"reflex","tr":"sd","s":"SOLID","q":"switch / if-else on a type field that keeps growing","a":"Replace conditional with polymorphism: interface + one class per branch (Strategy).","x":"A switch on a type field grows with every new type and is copied into several places. Replace it with an interface and one class per case; each class holds its own behaviour, and adding a case touches nothing else.","L":"sd-solid.html#rx-switchtype"},{"id":"rx-sd-solid-lsp","y":"reflex","tr":"sd","s":"SOLID","q":"A subclass that weakens the parent’s promise (throws, ignores input, changes meaning)","a":"It isn’t a true IS-A. Use separate classes under a smaller shared interface.","x":"A subclass must work everywhere its parent is expected, keeping every promise the parent makes. If it throws for a normal call, ignores input or changes the meaning, it isn’t really a subtype; give both classes a smaller shared interface instead.","L":"sd-solid.html#rx-lsp"},{"id":"rx-sd-solid-throwoverride","y":"reflex","tr":"sd","s":"SOLID","q":"An override that throws UnsupportedOperationException","a":"Smell for LSP and ISP. Split the interface so the class never inherits that method.","x":"An override that throws UnsupportedOperationException says “I was forced to have a method I can’t support”. That’s a sign the interface is too big or the inheritance is wrong. Split the interface so the class never receives that method.","L":"sd-solid.html#rx-throwoverride"},{"id":"rx-sd-solid-isp","y":"reflex","tr":"sd","s":"SOLID","q":"An interface where implementers leave methods empty","a":"Break it into small role interfaces; a class implements only the roles it plays.","x":"If classes implement an interface but leave some methods empty, the interface is doing too much. Break it into small role interfaces, so each class implements only what it really does.","L":"sd-solid.html#rx-isp"},{"id":"rx-sd-solid-dip","y":"reflex","tr":"sd","s":"SOLID","q":"Business logic depends on a concrete DB, API client or framework class","a":"Define an interface on the business side; inject the implementation through the constructor.","x":"Business rules shouldn’t depend on a specific database or API. The business side defines the interface it needs (OrderRepository), the details implement it (MySqlOrderRepository), and the implementation is passed in through the constructor.","L":"sd-solid.html#rx-dip"},{"id":"rx-sd-solid-newconcrete","y":"reflex","tr":"sd","s":"SOLID","q":"new ConcreteThing() inside a service method","a":"Move creation out: constructor injection, or a factory if creation depends on input.","x":"Calling new ConcreteThing() inside a service glues the service to that class and makes it hard to test. Receive the object through the constructor instead; if what to create depends on input, ask a factory.","L":"sd-solid.html#rx-newconcrete"},{"id":"rx-sd-solid-overdo","y":"reflex","tr":"sd","s":"SOLID","q":"Tempted to add an interface for every class “for SOLID”","a":"Add abstraction where variation is real or likely (payments, storage, channels). Keep the rest concrete.","x":"Interfaces are useful where things really vary (payment providers, storage, channels). An interface for every class with exactly one implementation just adds files to jump through. Abstract the parts that change, keep the rest simple.","L":"sd-solid.html#rx-overdo"},{"id":"rx-sd-creational-singleton","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Exactly one instance per process (config, pool, registry)","a":"Singleton, but prefer injecting that single instance over calling <code>X.getInstance()</code> everywhere.","x":"Some things must exist exactly once per process (configuration, a connection pool). A singleton enforces that. Still, give it to the classes that need it through their constructors rather than calling X.getInstance() everywhere; hidden global access is hard to test.","L":"sd-creational.html#rx-singleton"},{"id":"rx-sd-creational-singletonimpl","y":"reflex","tr":"sd","s":"Creational Patterns","q":"“Write a thread-safe singleton”","a":"Enum singleton (simplest, safe against reflection and serialization) or the holder idiom for lazy init. Mention DCL with <code>volatile</code> if asked.","x":"The simplest thread-safe singleton in Java is an enum with one value: the JVM guarantees one instance, even against reflection and serialization tricks. For lazy creation, the holder idiom loads the instance only when first asked.","L":"sd-creational.html#rx-singletonimpl"},{"id":"rx-sd-creational-volatile","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Double-checked locking without volatile","a":"Bug. Add <code>volatile</code> so the reference is published only after the constructor finishes.","x":"Without volatile, another thread can see the instance reference before the constructor has finished writing its fields, and use a half-built object. volatile makes the reference visible only after construction completes.","L":"sd-creational.html#rx-volatile"},{"id":"rx-sd-creational-simplefactory","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Which class to create depends on input (a string, an enum, config)","a":"Factory method <code>of(type)</code> returning the interface. Keep all the <code>new</code> calls in one place.","x":"When which class to create depends on input (a string, an enum, a config value), put that decision in one factory method that returns the interface. The rest of the code never writes new SpecificThing() or repeats the if-else.","L":"sd-creational.html#rx-simplefactory"},{"id":"rx-sd-creational-factorymethod","y":"reflex","tr":"sd","s":"Creational Patterns","q":"A base class runs a fixed algorithm but subclasses decide which object it uses","a":"Factory Method: an abstract <code>createX()</code> the subclass overrides.","x":"The parent class runs a fixed process but leaves one creation step abstract. Each subclass overrides that step to create its own kind of object, so the process is shared and only the object differs.","L":"sd-creational.html#rx-factorymethod"},{"id":"rx-sd-creational-abstractfactory","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Several related objects that must match (theme, platform, region)","a":"Abstract Factory: one interface with a create method per product; one implementation per family.","x":"When several objects must come from the same family (all dark-theme widgets, all AWS services), one factory interface creates each of them, and one implementation exists per family. Choosing the factory chooses a consistent set.","L":"sd-creational.html#rx-abstractfactory"},{"id":"rx-sd-creational-builder","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Constructor with many optional parameters, or several booleans in a row","a":"Builder: fluent setters returning <code>this</code>, validate in <code>build()</code>, produce an immutable object.","x":"A constructor with many optional parameters is unreadable: new Pizza(true, false, true, 2, null). A builder names each option, lets you set only what you need, checks everything in build(), and returns a finished, unchangeable object.","L":"sd-creational.html#rx-builder"},{"id":"rx-sd-creational-prototype","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Many similar objects that are expensive to set up","a":"Prototype: configure one, then copy it (copy constructor or <code>copy()</code>).","x":"If creating an object is expensive or fiddly (lots of configuration, loading data), set one up carefully and make copies of it. Each copy is then adjusted a little.","L":"sd-creational.html#rx-prototype"},{"id":"rx-sd-creational-deepcopy","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Copying an object that holds lists, maps or other mutable objects","a":"Deep copy the mutable parts (new list, new map, copied children). Prefer a copy constructor to <code>clone()</code>.","x":"A shallow copy shares the inner lists and maps with the original, so changing one changes the other. For a real copy, create new lists or maps and copy their contents too. A copy constructor makes this explicit and is safer than clone().","L":"sd-creational.html#rx-deepcopy"},{"id":"rx-sd-creational-newinlogic","y":"reflex","tr":"sd","s":"Creational Patterns","q":"Business code full of new ConcreteX()","a":"Move creation to a factory or to the composition root and inject.","x":"If business methods are full of new ConcreteX(), creation is mixed with logic. Do the creating in one place (a factory, or the main setup code) and pass the finished objects in.","L":"sd-creational.html#rx-newinlogic"},{"id":"rx-sd-structural-decorator","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Add optional features in any combination, at runtime","a":"Decorator: each feature wraps the same interface, delegates inward, then adds its part.","x":"Each optional feature is a wrapper that implements the same interface as the thing it wraps. It forwards the call inward, then adds its own bit. Stack wrappers in any combination at runtime.","L":"sd-structural.html#rx-decorator"},{"id":"rx-sd-structural-proxy","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Control access to an object: lazy loading, caching, permissions, remote calls","a":"Proxy: same interface as the real object, holds it, and decides when or whether to forward.","x":"A proxy looks exactly like the real object (same interface) but stands in front of it, deciding when or whether to pass calls on: create it only when first needed, return a cached answer, check permissions, or forward over the network.","L":"sd-structural.html#rx-proxy"},{"id":"rx-sd-structural-adapter","y":"reflex","tr":"sd","s":"Structural Patterns","q":"A third-party or legacy class has the wrong interface","a":"Adapter: implement your interface, translate calls to theirs.","x":"When a library’s class doesn’t match the interface your code expects, write a small adapter that implements your interface and translates each call into the library’s calls. Your code stays unaware of the library.","L":"sd-structural.html#rx-adapter"},{"id":"rx-sd-structural-facade","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Clients must call many subsystems in the right order","a":"Facade: one higher-level method that orchestrates them.","x":"If clients must call several subsystems in a careful order (reserve stock, charge, ship), give them one simple method that does the whole sequence. The subsystems remain available for advanced use.","L":"sd-structural.html#rx-facade"},{"id":"rx-sd-structural-composite","y":"reflex","tr":"sd","s":"Structural Patterns","q":"A tree where leaves and groups support the same operation (files/folders, menu/submenu, org chart)","a":"Composite: common interface; the group implements it by looping over children.","x":"When a tree mixes single items and groups (files and folders), give both the same interface. A group implements it by asking each child and combining the answers, so callers never check which kind they hold.","L":"sd-structural.html#rx-composite"},{"id":"rx-sd-structural-bridge","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Two independent dimensions of variation (shape × renderer, notification × channel)","a":"Bridge: one hierarchy holds a reference to the other.","x":"If something varies along two independent axes (shape × renderer, message type × channel), subclasses for every pair explode. Make one hierarchy hold a reference to the other: shapes have a renderer, and the two grow separately.","L":"sd-structural.html#rx-bridge"},{"id":"rx-sd-structural-flyweight","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Huge numbers of objects that repeat the same heavy data","a":"Flyweight: share immutable intrinsic state from a factory cache; pass extrinsic state per use.","x":"When thousands of objects repeat the same heavy data (font glyphs, tree textures), store that shared data once in a cache and let objects point to it. Pass the per-object bits (position, colour) in when used.","L":"sd-structural.html#rx-flyweight"},{"id":"rx-sd-structural-combos","y":"reflex","tr":"sd","s":"Structural Patterns","q":"Class names like MilkSugarWhipCoffee or RedCircleVector","a":"Combination explosion. Use composition: Decorator for stackable add-ons, Bridge for two axes.","x":"Class names that list feature combinations (MilkSugarWhipCoffee) multiply: every new feature doubles the classes. Use objects that combine at runtime instead: decorators for stackable extras, a bridge when there are two separate dimensions.","L":"sd-structural.html#rx-combos"},{"id":"rx-sd-behavioral-strategy","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"An if-else or switch choosing an algorithm (pricing, sorting, routing, compression)","a":"Strategy: interface for the algorithm, one class (or lambda) per variant, injected.","x":"When a method picks between algorithms with if-else (pricing per city, sort order, route type), make each algorithm its own small class behind one interface, and pass in the one to use. Adding an algorithm never touches the others.","L":"sd-behavioral.html#rx-strategy"},{"id":"rx-sd-behavioral-observer","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"“When X happens, notify A, B and C” (and more later)","a":"Observer: listeners subscribe to the subject; the subject loops and calls them.","x":"When one event must trigger reactions in several places (and more will be added), let them subscribe. The subject keeps a list of listeners and calls each one when the event happens; it doesn’t need to know what they do.","L":"sd-behavioral.html#rx-observer"},{"id":"rx-sd-behavioral-command","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Undo/redo, queues of jobs, macros, audit log of actions","a":"Command: wrap each action in an object with <code>execute()</code> (and <code>undo()</code>).","x":"Turn each action into an object with execute() (and undo()). Now actions can be stored, queued, logged, replayed, or undone by keeping a history stack.","L":"sd-behavioral.html#rx-command"},{"id":"rx-sd-behavioral-iterator","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Traverse a custom collection without exposing its internals","a":"Implement <code>Iterable&lt;T&gt;</code> and return an <code>Iterator</code>.","x":"Let callers loop over your collection without knowing how it’s stored inside. Implement Iterable<T> and return an Iterator, and then a for-each loop just works.","L":"sd-behavioral.html#rx-iterator"},{"id":"rx-sd-behavioral-state","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Behaviour depends on a mode, with rules about which mode comes next","a":"State: one class per state; each method returns the next state; the context delegates.","x":"If behaviour depends on a mode with rules about which mode comes next (a vending machine: idle → has coin → dispensing), make each mode a class. Each handles the actions its own way and returns the next mode; the main object just delegates to its current mode.","L":"sd-behavioral.html#rx-state"},{"id":"rx-sd-behavioral-cor","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"A request must pass a sequence of checks, any of which may stop it","a":"Chain of Responsibility: handlers linked with <code>next</code>; each processes or stops.","x":"When a request goes through a series of checks (auth → rate limit → validation), make each check a handler that either stops the request or passes it to the next one. You can reorder, add or remove checks without touching the others.","L":"sd-behavioral.html#rx-cor"},{"id":"rx-sd-behavioral-template","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Several classes share the same algorithm skeleton but differ in a step","a":"Template Method: <code>final</code> skeleton in an abstract class, abstract hook methods.","x":"When several classes run the same steps and differ only in one or two of them, write the steps once in a parent method (marked final) and leave the differing steps as abstract methods that subclasses fill in.","L":"sd-behavioral.html#rx-template"},{"id":"rx-sd-behavioral-mediator","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Many objects talking to each other directly (N×N links)","a":"Mediator: they all talk to one hub that routes messages.","x":"If many objects all talk to each other directly, the links multiply (every pair is connected) and every change ripples. Route them through one hub that knows the rules: each object only talks to the hub.","L":"sd-behavioral.html#rx-mediator"},{"id":"rx-sd-behavioral-memento","y":"reflex","tr":"sd","s":"Behavioral Patterns","q":"Save and restore an object’s state (undo, checkpoints) without exposing internals","a":"Memento: the object creates an opaque snapshot and can restore from it; a caretaker stores them.","x":"To support undo without exposing an object’s private fields, the object itself creates a sealed snapshot (memento) and can later restore from one. Someone else (the caretaker) just stores the snapshots without looking inside.","L":"sd-behavioral.html#rx-memento"},{"id":"rx-sd-lld-clarify","y":"reflex","tr":"sd","s":"LLD Problems","q":"“Design a parking lot” (or any LLD prompt)","a":"Spend 3–5 minutes on scope: actors, 3–5 use cases, what’s out of scope. Write them down.","x":"Don’t start drawing classes straight away. Spend a few minutes agreeing on the scope: who uses the system, the 3–5 things it must do, and what you’re leaving out. Write that list down; it stops you from designing the wrong thing.","L":"sd-lld.html#rx-clarify"},{"id":"rx-sd-lld-nouns","y":"reflex","tr":"sd","s":"LLD Problems","q":"A list of use cases","a":"Nouns → classes, verbs → methods on the class that owns the data.","x":"Read your use cases out loud. The nouns (lot, level, spot, ticket, vehicle) become classes; the verbs (park, pay, exit) become methods, placed on the class that owns the data the method needs.","L":"sd-lld.html#rx-nouns"},{"id":"rx-sd-lld-enums","y":"reflex","tr":"sd","s":"LLD Problems","q":"A fixed set of categories (vehicle type, spot size, seat class, coin)","a":"Use an <code>enum</code>, optionally with fields and methods.","x":"Categories that come from a fixed list (vehicle type, spot size, seat class) should be enums, not strings. The compiler catches typos, and the enum can carry data like a rate.","L":"sd-lld.html#rx-enums"},{"id":"rx-sd-lld-policy","y":"reflex","tr":"sd","s":"LLD Problems","q":"Rules the business will change (pricing, spot allocation, dispatch)","a":"Strategy interface, injected into the main class.","x":"Anything the business will tweak (pricing, which spot to give, which elevator answers) goes behind a strategy interface passed into the main class. Changing the rule then means swapping one object, not editing the lot.","L":"sd-lld.html#rx-policy"},{"id":"rx-sd-lld-modes","y":"reflex","tr":"sd","s":"LLD Problems","q":"An object whose allowed actions depend on what happened before (ATM, vending machine, order)","a":"State pattern: one class per state, transitions returned by methods.","x":"If what’s allowed depends on what happened earlier (an ATM can’t dispense before a PIN is entered), make each situation a state class. Each one handles actions its own way and says which state comes next.","L":"sd-lld.html#rx-modes"},{"id":"rx-sd-lld-lotmanager","y":"reflex","tr":"sd","s":"LLD Problems","q":"Temptation to make ParkingLot a singleton","a":"Mention one instance per process, but create it once and inject it. Don’t call <code>getInstance()</code> everywhere.","x":"It’s fine that only one ParkingLot exists per process, but don’t make every class fetch it via getInstance(). Create it once at startup and pass it to whoever needs it; tests can then use a different one.","L":"sd-lld.html#rx-lotmanager"},{"id":"rx-sd-lld-atmchain","y":"reflex","tr":"sd","s":"LLD Problems","q":"Dispense an amount using several note denominations","a":"Chain of Responsibility from the largest note down; each takes <code>amount / note</code> notes and passes the remainder.","x":"To pay out an amount in notes, start with the largest note: take as many as fit, then pass the remainder to the next smaller note’s handler, and so on. Each handler only knows its own note.","L":"sd-lld.html#rx-atmchain"},{"id":"rx-sd-lld-scan","y":"reflex","tr":"sd","s":"LLD Problems","q":"Elevator request scheduling","a":"SCAN: keep direction, serve requests ahead in sorted order (TreeSet), reverse when none are ahead.","x":"An elevator works like a lift sweeping a building: keep going in the current direction, stopping at requested floors ahead in order, and turn around only when nothing is left ahead. A sorted set of requested floors makes “next stop ahead” quick.","L":"sd-lld.html#rx-scan"},{"id":"rx-sd-lld-showseat","y":"reflex","tr":"sd","s":"LLD Problems","q":"Seat booking for movies, flights, events","a":"Model <code>ShowSeat</code> (seat × show) with status FREE/HELD/BOOKED and a hold expiry.","x":"A seat exists once, but its availability differs per show. So model ShowSeat (seat × show) with a status FREE / HELD / BOOKED and a hold expiry time, so abandoned holds free themselves.","L":"sd-lld.html#rx-showseat"},{"id":"rx-sd-lld-checkact","y":"reflex","tr":"sd","s":"LLD Problems","q":"if (available) take() on shared state","a":"Race. Make it atomic: lock, CAS (<code>putIfAbsent</code>, <code>AtomicInteger</code>) or a conditional DB update.","x":"“If it’s free, take it” written as two steps lets two threads both see “free” before either takes it, and both succeed. Make the check and the take a single atomic step.","L":"sd-lld.html#rx-checkact"},{"id":"rx-sd-lld-multiserver","y":"reflex","tr":"sd","s":"LLD Problems","q":"The same race across several app servers","a":"JVM locks don’t help. Use the DB (conditional UPDATE / row lock / unique constraint) or a distributed lock with TTL.","x":"Java locks only protect threads inside one server. With several servers, the shared truth is the database: let it decide with a conditional UPDATE, a row lock or a unique constraint. Use a distributed lock with an expiry if there’s no database to lean on.","L":"sd-lld.html#rx-multiserver"},{"id":"rx-sd-lld-optimistic","y":"reflex","tr":"sd","s":"LLD Problems","q":"Conflicts are rare and you don’t want to hold locks","a":"Optimistic locking: version column, <code>UPDATE … WHERE version = ?</code>, retry on 0 rows.","x":"When conflicts are rare, don’t lock while the user thinks. Read the row with its version number; when saving, update only if the version is still the same. If 0 rows change, someone else won: reload and retry or tell the user.","L":"sd-lld.html#rx-optimistic"},{"id":"rx-sd-lld-idempotent","y":"reflex","tr":"sd","s":"LLD Problems","q":"Retries on payment or booking (network timeouts, double clicks)","a":"Send an idempotency key (booking id); the server stores results by key and returns the same result on repeats.","x":"Networks time out and users double-click, so the same payment or booking request can arrive twice. The client sends a unique key with it; the server stores the result under that key and, if the key shows up again, returns the saved result instead of doing it twice.","L":"sd-lld.html#rx-idempotent"},{"id":"rx-sd-basics-reqfirst","y":"reflex","tr":"sd","s":"System Design Basics","q":"“Design X” and a blank whiteboard","a":"Requirements first: 3–4 core features, then scale, latency and consistency needs. Confirm before drawing.","x":"Before drawing boxes, agree on what you’re building: the 3–4 core features and the scale and quality targets. Say them back to the interviewer and get a nod. A design for the wrong requirements scores nothing.","L":"sd-basics.html#rx-reqfirst"},{"id":"rx-sd-basics-nfr","y":"reflex","tr":"sd","s":"System Design Basics","q":"Non-functional requirements","a":"Ask: DAU and peak QPS, read/write ratio, latency target, availability vs strong consistency, data size and retention.","x":"Non-functional requirements are the numbers and qualities that shape the design: how many users and requests at peak, reads vs writes, how fast it must respond, whether it must always be up or always be exactly correct, and how much data it keeps.","L":"sd-basics.html#rx-nfr"},{"id":"rx-sd-basics-estimate","y":"reflex","tr":"sd","s":"System Design Basics","q":"Need numbers fast","a":"1 day ≈ 10<sup>5</sup> s. QPS = daily requests / 10<sup>5</sup>, peak ×2–3. Storage = writes/day × size × 365 × years.","x":"A day has about 100,000 seconds (86,400). So requests per second ≈ requests per day ÷ 100,000, and peak is 2–3× that. Storage per year ≈ writes per day × size × 365.","L":"sd-basics.html#rx-estimate"},{"id":"rx-sd-basics-stateless","y":"reflex","tr":"sd","s":"System Design Basics","q":"App servers must scale horizontally","a":"Make them stateless: sessions in Redis or JWT, files in object storage, no local caches that must agree.","x":"To add servers freely, any server must be able to handle any request. So keep nothing on the server that the next request needs: sessions go to Redis or a signed token, files to object storage.","L":"sd-basics.html#rx-stateless"},{"id":"rx-sd-basics-lb","y":"reflex","tr":"sd","s":"System Design Basics","q":"More than one app server, or a single point of failure","a":"Put a load balancer in front with health checks; run at least two of everything.","x":"One server is a single point of failure and a ceiling. Put a load balancer in front of several servers; it spreads traffic and stops sending to servers that fail health checks. Run at least two of everything, including the load balancer.","L":"sd-basics.html#rx-lb"},{"id":"rx-sd-basics-lbalgo","y":"reflex","tr":"sd","s":"System Design Basics","q":"Choosing a load-balancing algorithm","a":"Round robin for uniform requests; least connections when request cost varies; consistent hashing when you need stickiness (caches, sockets).","x":"Round robin takes turns, fine when requests cost about the same. Least connections sends to the least busy server, better when some requests are slow. Consistent hashing sends the same key to the same server, needed when a server holds that key’s cache or socket.","L":"sd-basics.html#rx-lbalgo"},{"id":"rx-sd-basics-gateway","y":"reflex","tr":"sd","s":"System Design Basics","q":"Many microservices, each needing auth, rate limiting, logging","a":"API gateway at the edge: authenticate, rate limit, route, add trace IDs.","x":"Instead of every microservice re-implementing login checks, rate limits and logging, put one gateway at the edge that does them once and routes each request to the right service.","L":"sd-basics.html#rx-gateway"},{"id":"rx-sd-basics-cursor","y":"reflex","tr":"sd","s":"System Design Basics","q":"Paginating a feed or a large, changing list","a":"Cursor pagination: <code>?after=lastId&amp;limit=20</code> with an index on the sort key.","x":"Page numbers (OFFSET) get slow deep into a list and skip or repeat items when new ones are added. A cursor says “give me 20 items after the last one I saw”, which uses the index and stays correct while the list changes.","L":"sd-basics.html#rx-cursor"},{"id":"rx-sd-basics-idem","y":"reflex","tr":"sd","s":"System Design Basics","q":"A write that must not happen twice (payment, order) and clients that retry","a":"Require an <code>Idempotency-Key</code>; store the result by key; return it on repeats.","x":"Clients retry when they don’t hear back, which can repeat a payment. Make the client send an Idempotency-Key header; the server stores the result for that key and returns it again on a repeat instead of charging twice.","L":"sd-basics.html#rx-idem"},{"id":"rx-sd-basics-protocol","y":"reflex","tr":"sd","s":"System Design Basics","q":"REST vs gRPC vs GraphQL","a":"REST for public CRUD, gRPC for internal low-latency calls (protobuf, HTTP/2, streaming), GraphQL for many clients needing different shapes.","x":"Pick by who’s calling. REST is simple and universal for public APIs. gRPC is fast and typed for service-to-service calls. GraphQL lets many different clients ask for exactly the fields they need.","L":"sd-basics.html#rx-protocol"},{"id":"rx-sd-basics-realtime","y":"reflex","tr":"sd","s":"System Design Basics","q":"Server must push updates to clients","a":"Rare updates → polling. One-way stream → SSE. Two-way, low latency (chat, games, collaborative editing) → WebSocket.","x":"Match the tool to how often and in which direction updates flow. Occasional updates: just poll. A one-way stream from server to client: Server-Sent Events. Constant two-way traffic (chat, games): WebSockets.","L":"sd-basics.html#rx-realtime"},{"id":"rx-sd-basics-wsscale","y":"reflex","tr":"sd","s":"System Design Basics","q":"WebSockets at millions of users","a":"Dedicated connection servers + a registry (user → server) in Redis + pub/sub between servers; heartbeats; reconnect with resume.","x":"Millions of open sockets need dedicated connection servers. Keep a registry of which server holds each user’s connection, and use pub/sub so any server can push a message to a user connected elsewhere. Heartbeats detect dead connections; clients reconnect and resume.","L":"sd-basics.html#rx-wsscale"},{"id":"rx-sd-databases-default","y":"reflex","tr":"sd","s":"Databases","q":"Not sure which database","a":"Start with Postgres/MySQL. Move a specific workload to another store only when an access pattern or scale number demands it.","x":"A relational database (Postgres or MySQL) handles most products well: transactions, joins, indexes, and it scales further than people expect. Move a specific workload elsewhere only when a real access pattern or number demands it.","L":"sd-databases.html#rx-default"},{"id":"rx-sd-databases-nosql","y":"reflex","tr":"sd","s":"Databases","q":"Massive write volume, simple key-based access, or flexible schema","a":"Key-value (Redis/Dynamo) for lookups by key, Cassandra for append-heavy time-ordered data, Mongo for whole-document reads.","x":"NoSQL stores trade joins and flexible queries for scale on one access pattern. Pick by how you’ll read: by key (Redis/DynamoDB), huge append-only time series (Cassandra), or whole documents at once (MongoDB).","L":"sd-databases.html#rx-nosql"},{"id":"rx-sd-databases-denorm","y":"reflex","tr":"sd","s":"Databases","q":"A hot read path that needs several joins","a":"Denormalise: copy the few fields you need into the read model, update copies asynchronously.","x":"If a page is read constantly and needs several joins each time, store the needed fields together in a read-friendly copy. Writes then update the copies (often asynchronously), trading some write work and staleness for fast reads.","L":"sd-databases.html#rx-denorm"},{"id":"rx-sd-databases-index","y":"reflex","tr":"sd","s":"Databases","q":"Slow query filtering or sorting on a column","a":"Add a B-tree index on that column; verify with <code>EXPLAIN</code> that the plan uses it.","x":"Without an index, the database reads every row to find matches. A B-tree index on the column is like a book index: it jumps straight to the matching rows. Check with EXPLAIN that the query actually uses it.","L":"sd-databases.html#rx-index"},{"id":"rx-sd-databases-composite","y":"reflex","tr":"sd","s":"Databases","q":"Query filters on A and sorts or filters on B","a":"Composite index (A, B), equality columns first, range/sort column last.","x":"A composite index is sorted by its first column, then the second within it. Put columns you filter with = first and the range or ORDER BY column last, so the database can jump to the right block and read it already sorted.","L":"sd-databases.html#rx-composite"},{"id":"rx-sd-databases-explain","y":"reflex","tr":"sd","s":"Databases","q":"“This query is slow, what do you do?”","a":"Run <code>EXPLAIN ANALYZE</code>: look for Seq Scan on big tables, bad row estimates, sorts and nested loops; then index, rewrite or cache.","x":"Don’t guess why a query is slow; ask the database. EXPLAIN ANALYZE shows the plan and real timings. Look for full table scans on big tables, wildly wrong row estimates, big sorts and nested loops over many rows. Then add an index, rewrite or cache.","L":"sd-databases.html#rx-explain"},{"id":"rx-sd-databases-txn","y":"reflex","tr":"sd","s":"Databases","q":"Several writes that must all happen or none (transfer, order + payment record)","a":"Wrap them in one transaction; guard invariants inside the UPDATE (<code>WHERE balance &gt;= ?</code>).","x":"Group writes that must succeed or fail together into one transaction. Put the business rule inside the UPDATE itself, so the database checks it atomically.","L":"sd-databases.html#rx-txn"},{"id":"rx-sd-databases-lostupdate","y":"reflex","tr":"sd","s":"Databases","q":"Read a value in code, change it, write it back","a":"Atomic UPDATE (<code>SET x = x - ?</code>), <code>SELECT … FOR UPDATE</code>, or a version column.","x":"Reading a value into code, changing it and writing it back lets two requests overwrite each other (both read 10, both write 9). Let the database do the change in one statement, lock the row while you work, or use a version check.","L":"sd-databases.html#rx-lostupdate"},{"id":"rx-sd-databases-replicas","y":"reflex","tr":"sd","s":"Databases","q":"Read-heavy load on one database","a":"Add read replicas; send reads there, writes to the primary; route a user’s reads to the primary just after they write.","x":"If reads overwhelm one database, copy it to read replicas and send reads there; writes still go to the primary. Replicas lag slightly, so right after a user writes, read their data from the primary so they see their own change.","L":"sd-databases.html#rx-replicas"},{"id":"rx-sd-databases-quorum","y":"reflex","tr":"sd","s":"Databases","q":"Leaderless replication (Cassandra/Dynamo) with N copies","a":"Choose W and R so that W + R &amp;gt; N for strong reads (e.g. N=3, W=2, R=2).","x":"With N copies, write to W of them and read from R. If W + R > N, every read overlaps at least one copy that has the latest write, so reads are up to date.","L":"sd-databases.html#rx-quorum"},{"id":"rx-sd-databases-shardkey","y":"reflex","tr":"sd","s":"Databases","q":"One primary can’t take the writes or hold the data","a":"Shard by a high-cardinality key that keeps a request’s data together (user_id, tenant_id); avoid hot keys.","x":"When one database can’t handle the writes or the size, split the rows across several by a key. Choose a key with many different values that keeps one request’s data on one shard (user_id), and avoid keys where one value is very hot.","L":"sd-databases.html#rx-shardkey"},{"id":"rx-sd-databases-ring","y":"reflex","tr":"sd","s":"Databases","q":"Mapping keys to a changing set of servers (caches, shards)","a":"Consistent hashing with virtual nodes.","x":"With plain hash % n, adding one server moves almost every key. Consistent hashing places servers and keys on a ring; each key belongs to the next server clockwise, so adding a server only moves the keys next to it. Virtual nodes spread the load evenly.","L":"sd-databases.html#rx-ring"},{"id":"rx-sd-distributed-cacheaside","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Read-heavy data that tolerates seconds of staleness","a":"Cache-aside: read cache → miss → DB → set with TTL.","x":"The app checks the cache first. On a miss, it reads the database, stores the result in the cache with an expiry (TTL), and returns it. Later reads are fast until the entry expires.","L":"sd-distributed.html#rx-cacheaside"},{"id":"rx-sd-distributed-invalidate","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Updating data that is cached","a":"Write the DB, then delete the cache key (plus a TTL as a safety net).","x":"After changing data, update the database first, then delete the cache entry so the next read fetches the fresh value. A TTL covers the rare case where the delete is lost.","L":"sd-distributed.html#rx-invalidate"},{"id":"rx-sd-distributed-stampede","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"A hot key expires and thousands of requests hit the DB at once","a":"Lock/single-flight so one request reloads, others wait or serve stale; add TTL jitter; refresh hot keys early.","x":"When a popular cache entry expires, thousands of requests miss at once and all hit the database. Let only one request rebuild the entry while the others wait or get the slightly stale value, and randomise expiries so hot keys don’t all expire together.","L":"sd-distributed.html#rx-stampede"},{"id":"rx-sd-distributed-blob","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Images, videos, PDFs, uploads","a":"Object storage (S3) with pre-signed upload/download URLs; store only the key and metadata in the DB.","x":"Big files don’t belong in the database. Store them in object storage (S3) and keep only the file’s key and metadata in the DB. Clients upload and download directly using short-lived pre-signed URLs, so file bytes skip your servers.","L":"sd-distributed.html#rx-blob"},{"id":"rx-sd-distributed-cdn","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Static assets or media served to users worldwide","a":"Put a CDN in front with long cache headers and versioned file names.","x":"A CDN keeps copies of static files on servers near users, so they download from nearby. Give files long cache lifetimes and put a version in the file name (app.v42.js); a new version gets a new name, so nobody sees a stale file.","L":"sd-distributed.html#rx-cdn"},{"id":"rx-sd-distributed-queue","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Work that doesn’t need to finish before replying (email, thumbnails, reports), or spiky traffic","a":"Put it on a queue; workers process at their own pace.","x":"If the user doesn’t need to wait for a job (sending email, making thumbnails), reply immediately and put the job on a queue. Workers process it at their own pace, and traffic spikes just make the queue longer instead of overloading servers.","L":"sd-distributed.html#rx-queue"},{"id":"rx-sd-distributed-kafkaorder","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Events for the same entity must be processed in order","a":"Use the entity ID as the Kafka message key so they share a partition.","x":"Kafka only keeps order within one partition. Messages with the same key go to the same partition, so use the entity’s ID (order id, user id) as the key and all of that entity’s events stay in order.","L":"sd-distributed.html#rx-kafkaorder"},{"id":"rx-sd-distributed-atleastonce","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Consuming from Kafka/SQS","a":"Assume at-least-once delivery: make handlers idempotent (dedupe by event ID, upserts, conditional updates).","x":"Queues may deliver the same message more than once (after a crash or retry). Make processing safe to repeat: skip event IDs you’ve already handled, or write in a way where doing it twice has the same effect (upserts, conditional updates).","L":"sd-distributed.html#rx-atleastonce"},{"id":"rx-sd-distributed-saga","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"A business transaction spanning several services’ databases","a":"Saga: sequence of local transactions with compensating actions on failure (orchestrated or choreographed).","x":"A business process that spans several services can’t use one database transaction. Run it as a series of local steps, and for each step define an undo (compensation). If a later step fails, run the undos for the steps already done.","L":"sd-distributed.html#rx-saga"},{"id":"rx-sd-distributed-outbox","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Save to DB and publish an event, both must happen","a":"Transactional outbox: event row in the same transaction; a relay/CDC publishes it.","x":"Saving to the database and publishing an event are two systems; one can fail after the other succeeded. Write the event as a row in an outbox table inside the same transaction as the data, and let a separate relay publish outbox rows to the queue.","L":"sd-distributed.html#rx-outbox"},{"id":"rx-sd-distributed-cqrs","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Reads need very different shapes or scale than writes","a":"CQRS: write model for commands, separate read models (built from events) for queries.","x":"When reads and writes need very different shapes or scale, separate them. Commands update the write model; events from it build read models shaped exactly for each query.","L":"sd-distributed.html#rx-cqrs"},{"id":"rx-sd-distributed-cap","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Consistency vs availability decision","a":"Name it per feature: money, stock, uniqueness → CP. Feeds, likes, presence, carts → AP with eventual consistency.","x":"During a network split you must choose: refuse some requests to stay correct (consistency) or keep answering with possibly stale data (availability). Decide per feature: money, stock and uniqueness need correctness; likes, feeds and presence can be eventually consistent.","L":"sd-distributed.html#rx-cap"},{"id":"rx-sd-distributed-timeouts","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Any remote call","a":"Timeout + bounded retries with exponential backoff and jitter, only for idempotent operations.","x":"A remote call without a timeout can hang forever and tie up your threads. Always set one. Retry a few times with growing, randomised waits (backoff with jitter), but only for operations that are safe to repeat.","L":"sd-distributed.html#rx-timeouts"},{"id":"rx-sd-distributed-breaker","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"A dependency failing or slow repeatedly","a":"Circuit breaker (CLOSED → OPEN → HALF_OPEN) with a fallback; bulkhead its thread pool.","x":"If a dependency keeps failing, stop calling it for a while (open circuit) and return a fallback immediately, so you don’t pile up waiting requests. After a pause, let a few test calls through (half-open); if they succeed, close the circuit.","L":"sd-distributed.html#rx-breaker"},{"id":"rx-sd-distributed-micro","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"“Should we use microservices?”","a":"Start with a modular monolith; split a service when a team, scaling need or deployment cadence demands it.","x":"Microservices add network calls, deployments and data consistency problems. Start with one well-organised application (a modular monolith). Split out a service when there’s a concrete reason: a separate team, very different scaling, or a different release pace.","L":"sd-distributed.html#rx-micro"},{"id":"rx-sd-distributed-bloom","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"“Have we seen this before?” over a huge set, where a rare false yes is OK","a":"Bloom filter in front of the real lookup.","x":"A Bloom filter is a tiny bit array that answers “definitely not seen” or “maybe seen”. Put it in front of an expensive lookup: “definitely not” skips the lookup entirely; “maybe” does the real check.","L":"sd-distributed.html#rx-bloom"},{"id":"rx-sd-distributed-geo","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Find nearby drivers, restaurants, stays","a":"Geohash (prefix = area) or quadtree; query your cell plus 8 neighbours, then filter by exact distance. Redis GEO does this.","x":"Comparing distances to every driver is too slow. Divide the map into cells (a geohash: longer shared prefix = closer). Look in your cell and its 8 neighbours, then compute exact distances only for those candidates.","L":"sd-distributed.html#rx-geo"},{"id":"rx-sd-distributed-hll","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Count distinct users/IPs at huge scale","a":"HyperLogLog (Redis PFADD/PFCOUNT).","x":"Counting exact unique visitors at huge scale needs memory for every ID. HyperLogLog estimates the count within about 1% using around 12 KB, no matter how many IDs.","L":"sd-distributed.html#rx-hll"},{"id":"rx-sd-distributed-nines","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Availability target","a":"99.9% ≈ 8.8 h/yr down, 99.99% ≈ 53 min/yr. Serial deps multiply; redundancy in parallel adds nines.","x":"Availability is quoted in nines. 99.9% still means about 9 hours down a year; 99.99% about 53 minutes. Services in a chain multiply their availabilities (worse); redundant copies in parallel push it up.","L":"sd-distributed.html#rx-nines"},{"id":"rx-sd-distributed-jwt","y":"reflex","tr":"sd","s":"Caching, Queues & Resilience","q":"Authenticating requests across many services","a":"Short-lived signed JWT access token + refresh token; verify the signature locally; check roles for authorisation.","x":"After login, give the client a short-lived signed token (JWT) listing who they are and their roles. Every service can check the signature locally without calling the auth server. A longer-lived refresh token gets new access tokens.","L":"sd-distributed.html#rx-jwt"},{"id":"rx-sd-hld-shortcode","y":"reflex","tr":"sd","s":"HLD Problems","q":"Generate short unique IDs at scale (URL codes, order numbers)","a":"Counter ranges leased per server + Base62 (or Snowflake IDs). Avoid hash-and-truncate.","x":"Each server leases a block of numbers from a counter (say 1,000,000 to 1,000,999) and hands them out locally; no collisions, no coordination per request. Encode each number in Base62 (0–9, a–z, A–Z) for a short code.","L":"sd-hld.html#rx-shortcode"},{"id":"rx-sd-hld-redirect","y":"reflex","tr":"sd","s":"HLD Problems","q":"301 or 302 for the redirect?","a":"302 (temporary) if you want analytics on every click; 301 if you want browsers to cache and reduce load.","x":"A 301 tells browsers the move is permanent, so they cache it and skip your server next time: less load, but you can’t count those clicks. A 302 is temporary, so every click comes through you: you can count every click.","L":"sd-hld.html#rx-redirect"},{"id":"rx-sd-hld-ratelimit","y":"reflex","tr":"sd","s":"HLD Problems","q":"Rate limiter design","a":"Token bucket per user/API key in Redis, atomic via Lua; return 429 with Retry-After; enforce at the gateway.","x":"A token bucket gives each user a bucket that refills at a steady rate; each request takes a token, and an empty bucket means “429 Too Many Requests”. Keep buckets in Redis, update them atomically (a Lua script), and enforce at the gateway.","L":"sd-hld.html#rx-ratelimit"},{"id":"rx-sd-hld-fanout","y":"reflex","tr":"sd","s":"HLD Problems","q":"News feed / timeline","a":"Hybrid: fan-out on write into per-user timeline caches; fan-out on read for celebrity accounts; merge at read.","x":"Push each new post into followers’ ready-made timelines when it’s written (fast reads). That breaks for celebrities with millions of followers, so pull their posts at read time and merge them in.","L":"sd-hld.html#rx-fanout"},{"id":"rx-sd-hld-notify","y":"reflex","tr":"sd","s":"HLD Problems","q":"Notification system","a":"Accept → 202, dedupe by idempotency key, check preferences, queue per channel, workers with rate limits, retries and a dead-letter queue.","x":"Accept the request quickly (202), drop duplicates with an idempotency key, check the user’s preferences, then queue it per channel. Channel workers respect provider rate limits, retry failures, and move hopeless messages to a dead-letter queue.","L":"sd-hld.html#rx-notify"},{"id":"rx-sd-hld-typeahead","y":"reflex","tr":"sd","s":"HLD Problems","q":"Autocomplete / typeahead","a":"Precompute top-K completions per prefix offline from query logs (trie), serve from memory/Redis; debounce and cache on the client.","x":"Don’t search on every keystroke. Precompute, offline from query logs, the top suggestions for each prefix and keep them in memory or Redis. Typing a prefix then becomes a single lookup; the client also waits for a pause and caches results.","L":"sd-hld.html#rx-typeahead"},{"id":"rx-sd-hld-chat","y":"reflex","tr":"sd","s":"HLD Problems","q":"Chat app (WhatsApp)","a":"WebSocket connection servers + presence registry (user → server) + pub/sub between servers + Cassandra for messages + push for offline users.","x":"Each phone keeps a WebSocket open to a connection server. A registry records which server holds each user. To deliver, look up the recipient’s server and publish to it; store messages durably (Cassandra); if the recipient is offline, send a push notification.","L":"sd-hld.html#rx-chat"},{"id":"rx-sd-hld-nearby","y":"reflex","tr":"sd","s":"HLD Problems","q":"Ride matching / nearby search (Uber, Zomato)","a":"Drivers stream locations into a geo index (Redis GEO / geohash / quadtree); query nearby; lock a driver while offering.","x":"Drivers send their location every few seconds into a geo index (Redis GEO, geohash cells). A ride request queries nearby drivers, then locks one driver while the offer is pending so two riders can’t get the same driver.","L":"sd-hld.html#rx-nearby"},{"id":"rx-sd-hld-video","y":"reflex","tr":"sd","s":"HLD Problems","q":"Video platform (YouTube)","a":"Resumable upload to object storage → queue transcoding jobs into several bitrates → HLS/DASH segments on a CDN → adaptive bitrate playback.","x":"Upload the original in resumable chunks to object storage. A queue triggers transcoding into several qualities, cut into short segments (HLS/DASH) and served from a CDN. The player switches quality as bandwidth changes.","L":"sd-hld.html#rx-video"},{"id":"rx-sd-hld-booking","y":"reflex","tr":"sd","s":"HLD Problems","q":"Booking system (Airbnb, BookMyShow, hotels)","a":"Availability row per resource per slot; atomic conditional update to HOLD all slots; confirm after payment; expire holds.","x":"Keep one availability row per resource per time slot. To book, atomically switch all the needed rows from FREE to HELD in one conditional update; if any was taken, nothing changes. Confirm after payment, and let holds expire on their own.","L":"sd-hld.html#rx-booking"},{"id":"rx-sd-hld-sync","y":"reflex","tr":"sd","s":"HLD Problems","q":"File sync (Dropbox, Drive)","a":"Chunk files (~4 MB), address chunks by hash, upload only missing chunks, store metadata/versions separately, notify devices of changes.","x":"Split files into chunks (~4 MB) named by their hash. To sync, upload only chunks the server doesn’t already have, which makes small edits cheap. Keep file metadata and versions separately, and notify the user’s other devices to pull the changes.","L":"sd-hld.html#rx-sync"},{"id":"cn-c-oop-pillars","y":"concept","tr":"con","s":"Java & OOP","q":"What are the four pillars of object-oriented programming? Give a quick example of each.","a":"Encapsulation hides state behind methods, like a private balance changed only through deposit. Abstraction exposes what, not how, like a PaymentGateway interface. Inheritance reuses a base type, like SavingsAccount extends Account. Polymorphism lets one call behave per type, like payment.pay() running UPI or card logic at runtime.","k":["encapsulation","abstraction","inheritance","polymorphism"],"d":"c-oop-pillars"},{"id":"cn-c-equals-hashcode","y":"concept","tr":"con","s":"Java & OOP","q":"Why must you override hashCode whenever you override equals in Java?","a":"Hash-based collections use hashCode to pick the bucket and equals only inside it. If two equal objects have different hash codes, a HashSet or HashMap looks in the wrong bucket and misses the match. The contract: equal objects must have equal hash codes.","k":["bucket","contract","equal objects","lookup"],"d":"c-equals-hashcode"},{"id":"cn-c-pass-by-value","y":"concept","tr":"con","s":"Java & OOP","q":"Is Java pass-by-value or pass-by-reference?","a":"Always pass-by-value. For objects, the value passed is a copy of the reference, so a method can mutate the object it points to, but reassigning the parameter doesn't affect the caller's variable.","k":["pass by value","copy of the reference","mutate","reassign"],"d":"c-pass-by-value"},{"id":"cn-c-interface-vs-abstract","y":"concept","tr":"con","s":"Java & OOP","q":"When would you use an interface versus an abstract class?","a":"An interface defines a capability that unrelated classes can share, and a class can implement many. An abstract class is a partial base for a family that shares state and steps, and a class can extend only one. Since Java 8, interfaces can have default methods, but still no instance state.","k":["capability","multiple","state","single inheritance","default methods"],"d":"c-interface-vs-abstract"},{"id":"cn-c-overload-vs-override","y":"concept","tr":"con","s":"Java & OOP","q":"What's the difference between overloading and overriding?","a":"Overloading is the same method name with different parameters in one class, resolved at compile time by the declared types. Overriding is a subclass redefining an inherited method with the same signature, resolved at runtime by the actual object type.","k":["compile time","runtime","parameters","subclass"],"d":"c-overload-vs-override"},{"id":"cn-c-immutability","y":"concept","tr":"con","s":"Java & OOP","q":"How do you make a class immutable in Java, and why bother?","a":"Make the class final, fields private final, no setters, set everything in the constructor, and defensively copy mutable inputs and outputs. Immutable objects are thread-safe without locks, safe as map keys, and easy to reason about.","k":["final","private final","no setters","defensive copy","thread safe"],"d":"c-immutability"},{"id":"cn-c-string-immutable","y":"concept","tr":"con","s":"Java & OOP","q":"Why are Java Strings immutable, and when do you use StringBuilder?","a":"Immutability lets Strings be pooled and shared, cached for hash codes, and safely used as keys and across threads. Concatenating in a loop creates a new String each time, which is O(n squared), so use StringBuilder for repeated appends.","k":["string pool","hash code","thread safe","stringbuilder"],"d":"c-string-immutable"},{"id":"cn-c-checked-exceptions","y":"concept","tr":"con","s":"Java & OOP","q":"What's the difference between checked and unchecked exceptions?","a":"Checked exceptions extend Exception and must be caught or declared, used for recoverable conditions like IOException. Unchecked ones extend RuntimeException and signal programming errors, like NullPointerException, and don't need declaring.","k":["checked","unchecked","declare","recoverable"],"d":"c-checked-exceptions"},{"id":"cn-c-generics-erasure","y":"concept","tr":"con","s":"Java & OOP","q":"What is type erasure in Java generics, and what can't you do because of it?","a":"Generic types are checked at compile time and then erased to their bound, usually Object, at runtime. So you can't do new T(), instanceof List of String, or create generic arrays; pass a Class or Supplier instead.","k":["erasure","compile time","object","new T","supplier"],"d":"c-generics-erasure"},{"id":"cn-c-composition-over-inheritance","y":"concept","tr":"con","s":"Java & OOP","q":"Why do people say prefer composition over inheritance?","a":"Inheritance couples a subclass to its parent's internals and fixes the relationship at compile time, so changes ripple and combinations explode. Composition holds collaborators behind interfaces, so behaviour can be swapped and combined at runtime.","k":["coupling","has-a","is-a","runtime","interfaces"],"d":"c-composition-over-inheritance"},{"id":"cn-c-hashmap-internals","y":"concept","tr":"con","s":"Java collections","q":"How does a HashMap work internally in Java?","a":"It's an array of buckets. The key's hashCode is spread and masked to pick a bucket; collisions chain in a linked list that turns into a red-black tree beyond eight entries. When size exceeds capacity times load factor, 0.75, it doubles and rehashes.","k":["buckets","hashcode","collision","tree","load factor"],"d":"c-hashmap-internals"},{"id":"cn-c-concurrenthashmap","y":"concept","tr":"con","s":"Java concurrency","q":"How is ConcurrentHashMap different from a synchronized HashMap?","a":"A synchronized map locks the whole map for every call. ConcurrentHashMap allows lock-free reads and locks only a single bin on writes using CAS, so many threads proceed in parallel. It also offers atomic compound operations like computeIfAbsent and merge.","k":["lock","bin","cas","reads","computeifabsent"],"d":"c-concurrenthashmap"},{"id":"cn-c-arraylist-vs-linkedlist","y":"concept","tr":"con","s":"Java collections","q":"ArrayList versus LinkedList: which would you pick and why?","a":"Almost always ArrayList: O(1) random access, contiguous memory and good cache locality, with amortised O(1) appends. LinkedList only wins for frequent inserts or removals at an iterator position, and even then the pointer-chasing often makes it slower.","k":["random access","cache","amortized","insert"],"d":"c-arraylist-vs-linkedlist"},{"id":"cn-c-fail-fast","y":"concept","tr":"con","s":"Java collections","q":"What does fail-fast iteration mean, and how do you remove items while iterating?","a":"Most collections keep a modification count; if the collection changes outside the iterator during iteration, the next call throws ConcurrentModificationException. Remove through iterator.remove() or use removeIf.","k":["modcount","concurrentmodificationexception","iterator remove","removeif"],"d":"c-fail-fast"},{"id":"cn-c-treemap","y":"concept","tr":"con","s":"Java collections","q":"When would you use a TreeMap instead of a HashMap?","a":"When you need keys in sorted order or range queries: floorKey, ceilingKey, headMap, subMap. It's a red-black tree, so operations are O(log n) instead of average O(1).","k":["sorted","range","red black","log n"],"d":"c-treemap"},{"id":"cn-c-thread-vs-process","y":"concept","tr":"con","s":"OS & runtime","q":"What's the difference between a process and a thread?","a":"A process has its own address space and resources; switching or communicating between processes is costlier and needs IPC. Threads live inside a process and share its memory, so they're cheaper and communicate directly, but need synchronisation to avoid races.","k":["address space","share","ipc","context switch","synchronization"],"d":"c-thread-vs-process"},{"id":"cn-c-deadlock","y":"concept","tr":"con","s":"Java concurrency","q":"What is a deadlock and how do you prevent one?","a":"Threads each hold a lock and wait for another's, forming a cycle so none proceed. The four conditions are mutual exclusion, hold and wait, no preemption and circular wait. Prevent it by acquiring locks in a global order, using timeouts with tryLock, or holding fewer locks.","k":["cycle","hold and wait","lock ordering","trylock"],"d":"c-deadlock"},{"id":"cn-c-volatile","y":"concept","tr":"con","s":"Java concurrency","q":"What does volatile guarantee in Java, and what doesn't it?","a":"Volatile guarantees visibility, so every read sees the latest write, and prevents reordering around it. It does not make compound actions atomic: count plus plus on a volatile is still a race; use AtomicInteger or a lock.","k":["visibility","reordering","not atomic","atomicinteger"],"d":"c-volatile"},{"id":"cn-c-synchronized-vs-lock","y":"concept","tr":"con","s":"Java concurrency","q":"synchronized versus ReentrantLock: when would you use each?","a":"synchronized is simpler and releases automatically. ReentrantLock adds tryLock with timeouts, interruptible waits, fairness and multiple Condition objects, but you must unlock in a finally block.","k":["synchronized","reentrantlock","trylock","finally","fairness"],"d":"c-synchronized-vs-lock"},{"id":"cn-c-executor","y":"concept","tr":"con","s":"Java concurrency","q":"Why use an ExecutorService instead of creating threads directly?","a":"Thread creation is expensive and unbounded threads can exhaust memory. A pool reuses threads, bounds concurrency, queues work, and gives Futures for results and cancellation. Size CPU-bound pools near core count and I/O-bound pools larger.","k":["pool","reuse","bounded","queue","future"],"d":"c-executor"},{"id":"cn-c-completablefuture","y":"concept","tr":"con","s":"Java concurrency","q":"What problem does CompletableFuture solve?","a":"It composes asynchronous steps without blocking: thenApply, thenCompose and thenCombine chain or join results, allOf waits for many, and exceptionally or handle deal with errors. Plain Future only offers a blocking get.","k":["async","compose","non blocking","allof","exceptionally"],"d":"c-completablefuture"},{"id":"cn-c-gc","y":"concept","tr":"con","s":"OS & runtime","q":"Explain Java garbage collection at a high level.","a":"The JVM reclaims objects no longer reachable from GC roots. The heap is generational: most objects die young, so frequent cheap young collections copy survivors, and long-lived objects are promoted to the old generation. Modern collectors like G1 and ZGC aim for short pauses.","k":["reachable","generational","promote","g1"],"d":"c-gc"},{"id":"cn-c-spring-di","y":"concept","tr":"con","s":"Spring Boot","q":"What is dependency injection and how does Spring do it?","a":"Objects receive their collaborators instead of constructing them, so code depends on interfaces and is easy to test. Spring's container creates beans and wires them, preferably through constructor injection, based on component scanning and configuration.","k":["inject","container","constructor injection","interface","test"],"d":"c-spring-di"},{"id":"cn-c-bean-scopes","y":"concept","tr":"con","s":"Spring Boot","q":"What bean scopes does Spring have, and what's the default?","a":"Singleton is the default: one instance per container. Prototype creates a new one per injection. Web apps add request, session and application scopes.","k":["singleton","prototype","request","session"],"d":"c-bean-scopes"},{"id":"cn-c-transactional","y":"concept","tr":"con","s":"Spring Boot","q":"How does @Transactional work, and what are its common pitfalls?","a":"Spring wraps the bean in a proxy that begins a transaction before the method and commits or rolls back after. Pitfalls: calling a transactional method from the same class bypasses the proxy, private methods aren't proxied, and checked exceptions don't roll back by default.","k":["proxy","self invocation","private","checked","propagation"],"d":"c-transactional"},{"id":"cn-c-spring-boot-autoconfig","y":"concept","tr":"con","s":"Spring Boot","q":"What does Spring Boot add on top of Spring?","a":"Auto-configuration that sets up beans based on the classpath and properties, starter dependencies, an embedded server, and production features like Actuator health and metrics, so an app runs with almost no configuration.","k":["auto configuration","starters","embedded","actuator","properties"],"d":"c-spring-boot-autoconfig"},{"id":"cn-c-solid","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"Walk me through the SOLID principles in a sentence each.","a":"Single responsibility: one reason to change. Open-closed: extend behaviour without editing working code. Liskov: subtypes must keep the parent's promises. Interface segregation: small, client-specific interfaces. Dependency inversion: business logic depends on abstractions, not concrete infrastructure.","k":["single responsibility","open closed","liskov","interface segregation","dependency inversion"],"d":"c-solid"},{"id":"cn-c-liskov","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"Explain the Liskov substitution principle with an example of a violation.","a":"Code written against a base type must work with any subtype without surprises. Square extending Rectangle breaks it: setting width on a Square also changes height, so code expecting width times height gets the wrong area.","k":["substitute","subtype","promise","square"],"d":"c-liskov"},{"id":"cn-c-singleton","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"How do you implement a thread-safe singleton in Java?","a":"The simplest is an enum with one constant, which is thread-safe and serialization-safe. For lazy init, use the holder idiom or double-checked locking with a volatile field. In Spring apps, a singleton-scoped bean is usually better.","k":["enum","holder","double checked","thread safe","spring bean"],"d":"c-singleton"},{"id":"cn-c-factory-vs-builder","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"Factory versus Builder: when do you use each?","a":"A factory decides which class to create from some input, returning an interface, like a Vehicle for a type string. A builder assembles one complex object step by step when there are many optional parameters, validating once in build().","k":["factory","builder","optional parameters","build","interface"],"d":"c-factory-vs-builder"},{"id":"cn-c-strategy-vs-state","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"What's the difference between the Strategy and State patterns?","a":"Both delegate to an interface. With Strategy, the client picks an interchangeable algorithm, like a pricing rule. With State, the object switches its own behaviour as its internal state changes, and states decide transitions, like an order going from Paid to Shipped.","k":["strategy","state","client chooses","internal","interface"],"d":"c-strategy-vs-state"},{"id":"cn-c-observer","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"Explain the Observer pattern and its pitfalls.","a":"A subject keeps a list of listeners and notifies them on events, decoupling the publisher from reactions. Pitfalls: listeners run synchronously in the caller's thread, so a slow one blocks; an exception can stop others; and forgotten unsubscribes leak memory.","k":["subject","listeners","notify","synchronous","leak"],"d":"c-observer"},{"id":"cn-c-decorator-vs-proxy","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"Decorator versus Proxy: both wrap an object, so what's the difference?","a":"A decorator adds behaviour, and decorators stack in combinations, like adding retry and logging to a client. A proxy controls access to the same object, like lazy loading, caching, security checks or a remote stub, usually without the caller choosing it.","k":["decorator","proxy","lazy","same interface"],"d":"c-decorator-vs-proxy"},{"id":"cn-c-adapter-facade","y":"concept","tr":"con","s":"Design patterns & SOLID","q":"When would you use an Adapter versus a Facade?","a":"An adapter converts one interface into another your code already expects, like wrapping a vendor SMS SDK behind your Notifier interface. A facade gives a simple entry point over many subsystem calls, like one checkout() that calls inventory, payment and shipping.","k":["adapter","facade","vendor","subsystem"],"d":"c-adapter-facade"},{"id":"cn-c-sql-vs-nosql","y":"concept","tr":"con","s":"Databases","q":"How do you choose between SQL and NoSQL for a new service?","a":"Start from the access patterns. Choose SQL when you need transactions, joins and constraints, like orders and payments. Choose a NoSQL store when you have one dominant access pattern at huge scale or flexible schemas, like Cassandra for chat messages by conversation or DynamoDB for key lookups.","k":["access pattern","transactions","joins","scale","cassandra"],"d":"c-sql-vs-nosql"},{"id":"cn-c-acid","y":"concept","tr":"con","s":"Databases","q":"What does ACID mean?","a":"Atomicity: all of a transaction happens or none. Consistency: constraints hold before and after. Isolation: concurrent transactions don't see each other's partial work. Durability: committed data survives crashes, via the write-ahead log.","k":["atomicity","consistency","isolation","durability"],"d":"c-acid"},{"id":"cn-c-isolation-levels","y":"concept","tr":"con","s":"Databases","q":"Explain the transaction isolation levels and the anomalies they prevent.","a":"Read uncommitted allows dirty reads. Read committed stops them but allows non-repeatable reads. Repeatable read stops those but may allow phantoms. Serializable behaves like transactions ran one at a time. Postgres defaults to read committed and MySQL InnoDB to repeatable read.","k":["read committed","repeatable read","serializable","dirty read","phantom"],"d":"c-isolation-levels"},{"id":"cn-c-indexes","y":"concept","tr":"con","s":"Databases","q":"How does a database index work and what does it cost?","a":"Usually a B-plus tree that keeps keys sorted, so lookups and range scans are O(log n) instead of a full table scan. The cost is extra storage and slower writes, since every insert or update maintains each index.","k":["b tree","sorted","log n","full scan","slower writes"],"d":"c-indexes"},{"id":"cn-c-n-plus-1","y":"concept","tr":"con","s":"Databases","q":"What is the N plus one query problem and how do you fix it?","a":"Loading a list with one query, then lazily loading a relation per row with N more queries. Fix it by fetching together: a JOIN FETCH or entity graph in JPA, or a batched IN query.","k":["lazy","one per row","join fetch","batch","entity graph"],"d":"c-n-plus-1"},{"id":"cn-c-optimistic-pessimistic","y":"concept","tr":"con","s":"Databases","q":"Optimistic versus pessimistic locking: when do you use each?","a":"Pessimistic locks the row up front, SELECT FOR UPDATE, which suits high contention. Optimistic reads a version, then updates WHERE version equals the one read; zero rows updated means someone else won, so retry. It suits rare conflicts.","k":["pessimistic","optimistic","contention","retry","rows updated"],"d":"c-optimistic-pessimistic"},{"id":"cn-c-replication","y":"concept","tr":"con","s":"Databases","q":"How does database replication help, and what problem does it introduce?","a":"Replicas copy the primary's writes, so reads scale out and a replica can take over on failure. With asynchronous replication, replicas lag, so a user may not see their own write; fix with read-your-writes routing to the primary for a short time.","k":["primary","replica","read scaling","lag","read your writes"],"d":"c-replication"},{"id":"cn-c-sharding","y":"concept","tr":"con","s":"Databases","q":"What is sharding, and how do you pick a shard key?","a":"Splitting data across databases so each holds a subset. Pick a key with high cardinality that spreads load evenly and keeps a request's data together, like user_id or tenant_id. Avoid monotonic keys like timestamps that create hot shards.","k":["split","shard key","cardinality","hot shard","together"],"d":"c-sharding"},{"id":"cn-c-consistent-hashing","y":"concept","tr":"con","s":"Distributed systems","q":"Explain consistent hashing and why it's used.","a":"Servers and keys are hashed onto a ring, and each key belongs to the next server clockwise. Adding or removing a server moves only about one over n of the keys, unlike hash mod n, which moves almost all. Virtual nodes even out the load.","k":["ring","clockwise","one over n","mod n","virtual nodes"],"d":"c-consistent-hashing"},{"id":"cn-c-cap","y":"concept","tr":"con","s":"Distributed systems","q":"What does the CAP theorem say, practically?","a":"During a network partition you must choose between consistency, refusing or failing some requests, and availability, answering with possibly stale data. Without a partition you can have both. Payments and balances lean CP; feeds, likes and presence lean AP.","k":["partition","consistency","availability","stale","trade off"],"d":"c-cap"},{"id":"cn-c-caching-strategies","y":"concept","tr":"con","s":"Caching & messaging","q":"What caching strategies do you know, and which would you default to?","a":"Cache-aside: read the cache, on a miss read the DB and fill it; on writes update the DB and delete the key. Write-through writes both synchronously; write-back writes the cache and flushes later. I default to cache-aside with a TTL.","k":["cache aside","write through","write back","ttl","delete"],"d":"c-caching-strategies"},{"id":"cn-c-cache-stampede","y":"concept","tr":"con","s":"Caching & messaging","q":"What's a cache stampede and how do you prevent it?","a":"A hot key expires and thousands of requests miss at once and hammer the database. Prevent it with request coalescing or a lock so one request refills, jittered TTLs, or early probabilistic refresh before expiry.","k":["hot key","database","lock","jitter","refresh early"],"d":"c-cache-stampede"},{"id":"cn-c-eviction","y":"concept","tr":"con","s":"Caching & messaging","q":"Compare LRU and LFU eviction.","a":"LRU evicts what was used least recently, good for recency-driven workloads and simple with a hash map plus doubly linked list. LFU evicts what's used least often, better for stable hot sets but slow to adapt and needs frequency buckets.","k":["lru","lfu","recency","frequency","hash map"],"d":"c-eviction"},{"id":"cn-c-kafka-basics","y":"concept","tr":"con","s":"Caching & messaging","q":"How does Kafka achieve ordering and parallelism?","a":"A topic is split into partitions, each an append-only ordered log. Messages with the same key go to the same partition, so they stay in order. In a consumer group, each partition is read by one consumer, so partitions cap parallelism.","k":["partition","key","order","consumer group","offset"],"d":"c-kafka-basics"},{"id":"cn-c-delivery-semantics","y":"concept","tr":"con","s":"Caching & messaging","q":"Explain at-most-once, at-least-once and exactly-once delivery.","a":"At-most-once may lose messages but never repeats. At-least-once retries until acknowledged, so duplicates happen. Exactly-once is usually at-least-once plus idempotent processing, or transactions within one system like Kafka's.","k":["at most once","at least once","exactly once","idempotent","acknowledge"],"d":"c-delivery-semantics"},{"id":"cn-c-queue-vs-pubsub","y":"concept","tr":"con","s":"Caching & messaging","q":"What's the difference between a message queue and pub-sub?","a":"In a queue, each message goes to one consumer, which spreads work like a job queue. In pub-sub, each subscriber group gets every message, so several services react to the same event. Kafka does both via consumer groups.","k":["queue","pub sub","every subscriber","work","consumer group"],"d":"c-queue-vs-pubsub"},{"id":"cn-c-idempotency","y":"concept","tr":"con","s":"Networking & APIs","q":"What is idempotency, and how do you make a payment API idempotent?","a":"Repeating an operation has the same effect as doing it once. The client sends an idempotency key with POST; the server stores the key with the result and returns the stored result for repeats, under a unique constraint so concurrent duplicates fail.","k":["same effect","idempotency key","store","unique","retry"],"d":"c-idempotency"},{"id":"cn-c-rest-status-codes","y":"concept","tr":"con","s":"Networking & APIs","q":"Which HTTP status codes would you use for common API outcomes?","a":"200 OK, 201 Created with a Location, 204 No Content; 400 bad input, 401 not authenticated, 403 not allowed, 404 not found, 409 conflict, 422 validation failed, 429 rate limited; 500 server bug, 502 or 503 upstream or overload, 504 timeout.","k":["201","400","401","403","429","503"],"d":"c-rest-status-codes"},{"id":"cn-c-url-typed","y":"concept","tr":"con","s":"Networking & APIs","q":"What happens when you type a URL into the browser and press enter?","a":"DNS resolves the domain to an IP, using caches first. The browser opens a TCP connection and a TLS handshake for HTTPS, then sends the HTTP request, often through a CDN and load balancer to an app server. The response HTML is parsed, more resources are fetched, and the page is rendered.","k":["dns","tcp","tls","load balancer","render"],"d":"c-url-typed"},{"id":"cn-c-tcp-udp","y":"concept","tr":"con","s":"Networking & APIs","q":"TCP versus UDP: what's the difference and when do you use each?","a":"TCP is connection-based with ordered, reliable delivery, retransmission and congestion control: web, APIs, databases. UDP is connectionless with no guarantees but lower latency: video calls, gaming, DNS. QUIC builds reliability on UDP.","k":["reliable","connection","udp","latency","video"],"d":"c-tcp-udp"},{"id":"cn-c-http2","y":"concept","tr":"con","s":"Networking & APIs","q":"What did HTTP/2 improve over HTTP/1.1?","a":"Multiplexing many requests over one connection without blocking each other at the HTTP level, binary framing, header compression with HPACK, and stream prioritisation. That removes the need for many parallel connections.","k":["multiplexing","binary","header compression","head of line"],"d":"c-http2"},{"id":"cn-c-websockets-sse","y":"concept","tr":"con","s":"Networking & APIs","q":"Polling, long polling, server-sent events and WebSockets: how do you choose?","a":"Polling is simple but wasteful. Long polling holds a request until data arrives. Server-sent events stream one-way from server to client over HTTP, great for live scores. WebSockets are full-duplex, for chat and multiplayer.","k":["polling","long polling","sse","websocket"],"d":"c-websockets-sse"},{"id":"cn-c-rest-vs-grpc","y":"concept","tr":"con","s":"Networking & APIs","q":"REST, GraphQL or gRPC: when would you use each?","a":"REST for public, resource-oriented APIs with simple caching. GraphQL when clients need flexible queries across many entities, like a mobile app. gRPC for internal service-to-service calls needing low latency, typed contracts and streaming.","k":["rest","graphql","grpc","internal","caching"],"d":"c-rest-vs-grpc"},{"id":"cn-c-load-balancing","y":"concept","tr":"con","s":"Distributed systems","q":"Explain L4 versus L7 load balancing and common algorithms.","a":"L4 balances on IP and port, fast and protocol-agnostic. L7 understands HTTP, so it can route by path or header and terminate TLS. Algorithms include round robin, least connections for uneven work, and consistent hashing for stickiness.","k":["l4","l7","round robin","least connections","health check"],"d":"c-load-balancing"},{"id":"cn-c-rate-limiting","y":"concept","tr":"con","s":"Distributed systems","q":"How would you implement rate limiting?","a":"Token bucket is the usual choice: tokens refill at a steady rate up to a burst size and each request spends one. Across many servers, keep the bucket in Redis and update it atomically with a Lua script; return 429 with Retry-After when empty.","k":["token bucket","refill","burst","redis","429"],"d":"c-rate-limiting"},{"id":"cn-c-circuit-breaker","y":"concept","tr":"con","s":"Distributed systems","q":"What's a circuit breaker, and how does it work with retries?","a":"After repeated failures to a dependency, the breaker opens and fails fast instead of piling on load; after a cool-down it lets a few trial requests through, half-open, and closes on success. Retries should use exponential backoff with jitter and stay within the breaker.","k":["open","half open","closed","backoff","jitter"],"d":"c-circuit-breaker"},{"id":"cn-c-saga","y":"concept","tr":"con","s":"Distributed systems","q":"How do you keep data consistent across microservices without distributed transactions?","a":"A saga: each service commits its local step and publishes an event; if a later step fails, compensating actions undo earlier steps, like refunding a payment. Orchestration uses a coordinator; choreography lets services react to each other's events.","k":["saga","local transaction","compensating","orchestration","choreography"],"d":"c-saga"},{"id":"cn-c-outbox","y":"concept","tr":"con","s":"Distributed systems","q":"What is the transactional outbox pattern?","a":"When a service must update its database and publish an event, writing both separately can lose one. Instead it writes the event into an outbox table in the same transaction, and a relay or CDC process publishes outbox rows to the broker afterwards.","k":["outbox","same transaction","dual write","relay","publish"],"d":"c-outbox"},{"id":"cn-c-bloom-filter","y":"concept","tr":"con","s":"Distributed systems","q":"What's a Bloom filter and where would you use it?","a":"A bit array with k hash functions. Adding sets k bits; checking tests them. If any is zero the item is definitely absent; if all are set it's probably present. It's tiny and fast, used to skip DB lookups for usernames, or in Cassandra to skip SSTables.","k":["bit array","hash functions","definitely not","false positive","memory"],"d":"c-bloom-filter"},{"id":"cn-c-microservices","y":"concept","tr":"con","s":"Distributed systems","q":"When would you split a monolith into microservices, and what does it cost?","a":"When teams or parts of the system need to deploy and scale independently. The cost is distributed complexity: network failures, data consistency across services, observability, versioned contracts and more infrastructure. Start with a modular monolith and split along clear domain boundaries.","k":["independent","scale","team","complexity","consistency"],"d":"c-microservices"},{"id":"cn-c-observability","y":"concept","tr":"con","s":"Distributed systems","q":"What would you put in place to debug a production issue across services?","a":"The three pillars: structured logs with a correlation or trace id, metrics with dashboards and alerts on latency, errors and saturation, and distributed tracing to follow a request across services. Plus SLOs to know when users are hurting.","k":["logs","metrics","tracing","alerts","correlation id"],"d":"c-observability"},{"id":"cn-c-jwt","y":"concept","tr":"con","s":"Networking & APIs","q":"How do JWTs work, and what are their trade-offs?","a":"A JWT is a signed token holding claims like user id and expiry. Servers verify the signature without a session lookup, so auth is stateless and scales easily. The trade-off is revocation: a token is valid until it expires, so keep access tokens short-lived and use refresh tokens.","k":["signed","claims","stateless","expiry","refresh token"],"d":"c-jwt"},{"id":"cn-c-oauth","y":"concept","tr":"con","s":"Networking & APIs","q":"Explain OAuth 2 in simple terms.","a":"It lets a user grant an app limited access to their data on another service without sharing their password. In the authorization code flow, the user signs in at the provider, the app receives a code, exchanges it server-side for tokens, and calls the API with the access token. OpenID Connect adds identity.","k":["delegate","authorization code","access token","scope","openid connect"],"d":"c-oauth"},{"id":"cn-c-estimation","y":"concept","tr":"con","s":"System design basics","q":"Fifty million daily users each make twenty requests a day. What's the average QPS, and what peak would you plan for?","a":"One billion requests a day, and a day is about ten to the five seconds, so roughly ten thousand QPS on average. Plan for two to three times that at peak, around twenty to thirty thousand QPS.","k":["billion","10^5","10k","peak"],"d":"c-estimation"},{"id":"cn-c-scale-steps","y":"concept","tr":"con","s":"System design basics","q":"How would you scale a web app from one server to a million users?","a":"Split app and database, put stateless app servers behind a load balancer with sessions in Redis, add a cache and a CDN, add read replicas, move slow work to queues, then shard the database when writes outgrow one primary. Fix the current bottleneck at each step.","k":["load balancer","stateless","cache","cdn","replicas","queue","shard"],"d":"c-scale-steps"},{"id":"cn-c-cdn","y":"concept","tr":"con","s":"System design basics","q":"What does a CDN do and what would you put on it?","a":"It caches content at edge servers near users, cutting latency and origin load. Put static assets, images and video segments on it, and cacheable API responses with short TTLs. Use versioned file names so you never need to purge.","k":["edge","latency","static","ttl","origin"],"d":"c-cdn"},{"id":"cn-c-api-design","y":"concept","tr":"con","s":"System design basics","q":"What makes a good REST API design?","a":"Resource-oriented URLs with nouns and correct verbs, consistent status codes, pagination with cursors, idempotency keys for unsafe retries, versioning, clear error bodies, and authentication plus rate limits at the gateway.","k":["resources","verbs","pagination","idempotency","versioning"],"d":"c-api-design"},{"id":"cn-c-stateless","y":"concept","tr":"con","s":"System design basics","q":"Why should app servers be stateless?","a":"So any server can handle any request, which makes horizontal scaling, load balancing and replacing failed servers trivial. Keep state in shared stores: sessions in Redis or signed tokens, files in object storage, data in the database.","k":["any server","horizontal","sessions","shared store","failover"],"d":"c-stateless"},{"id":"cn-c-blob-storage","y":"concept","tr":"con","s":"System design basics","q":"Where should an app store user-uploaded images and videos?","a":"In object storage like S3, with metadata and the object key in the database, served through a CDN. Clients upload directly with pre-signed URLs so bytes never pass through app servers.","k":["object storage","metadata","cdn","pre signed","direct upload"],"d":"c-blob-storage"},{"id":"cn-c-geohash","y":"concept","tr":"con","s":"System design basics","q":"How would you find drivers near a rider quickly?","a":"Index locations spatially: geohash turns latitude and longitude into a prefix string where nearby points share prefixes, so you query the cell and its neighbours. Keep live driver positions in an in-memory geo index like Redis GEO or a quadtree.","k":["geohash","prefix","neighbours","redis geo","latitude"],"d":"c-geohash"},{"id":"cn-c-search-index","y":"concept","tr":"con","s":"System design basics","q":"How does full-text search work, and why not just use SQL LIKE?","a":"Search engines build an inverted index from terms to the documents containing them, with analysis like lowercasing and stemming, and rank by relevance such as BM25. LIKE with a leading wildcard can't use a B-tree index and has no ranking.","k":["inverted index","terms","ranking","elasticsearch","like"],"d":"c-search-index"},{"id":"cn-c-big-o-sorts","y":"concept","tr":"con","s":"Algorithms","q":"Compare quicksort, merge sort and heap sort.","a":"Quicksort is O(n log n) average, O(n squared) worst, in place and fastest in practice. Merge sort is always O(n log n), stable, but needs O(n) extra space. Heap sort is O(n log n) worst case and in place, but not stable and cache-unfriendly.","k":["quicksort","merge sort","heap sort","n log n","worst case"],"d":"c-big-o-sorts"},{"id":"cn-c-bfs-dfs","y":"concept","tr":"con","s":"Algorithms","q":"When do you use BFS versus DFS?","a":"BFS explores by distance, so it finds shortest paths in unweighted graphs and handles level-by-level questions; it needs a queue and can use more memory on wide graphs. DFS goes deep with a stack or recursion and suits connectivity, cycle detection, topological sort and backtracking.","k":["bfs","shortest path","dfs","cycle","level"],"d":"c-bfs-dfs"},{"id":"cn-c-dp-vs-greedy","y":"concept","tr":"con","s":"Algorithms","q":"How do you decide between greedy and dynamic programming?","a":"Greedy works when a locally best choice is provably safe, shown by an exchange argument, like interval scheduling by earliest end. If choices interact so a local best can hurt later, like coin change with coins one, three and four, you need DP over states.","k":["greedy","exchange argument","dp","overlapping subproblems","counterexample"],"d":"c-dp-vs-greedy"},{"id":"cn-c-heap-uses","y":"concept","tr":"con","s":"Algorithms","q":"When is a heap the right data structure?","a":"When you repeatedly need the current smallest or largest while items keep arriving: top-k, merging k sorted lists, Dijkstra, scheduling, and a running median with two heaps. Push and pop are O(log n), peek is O(1), and heapify is O(n).","k":["smallest","top k","merge k","dijkstra","log n"],"d":"c-heap-uses"},{"id":"cn-c-two-pointers-when","y":"concept","tr":"con","s":"Algorithms","q":"How do you recognise a two-pointer or sliding-window problem?","a":"Two pointers fit sorted arrays and pair or triplet searches, or in-place rewrites with a reader and a writer. A sliding window fits contiguous subarrays or substrings with a condition that you can maintain incrementally, like at most k distinct or a sum with positive numbers.","k":["sorted","pair","contiguous","window","positive"],"d":"c-two-pointers-when"},{"id":"cn-c-complexity-space","y":"concept","tr":"con","s":"Algorithms","q":"What's the space complexity of a recursive DFS on a tree, and why?","a":"O(h), the height, because the call stack holds one frame per level of the current path. That's O(log n) for a balanced tree and O(n) for a skewed one, which is when stack overflow becomes a risk.","k":["height","call stack","balanced","skewed","overflow"],"d":"c-complexity-space"},{"id":"cn-c-system-design-framework","y":"concept","tr":"con","s":"System design basics","q":"How do you structure a system design interview answer?","a":"Clarify functional and non-functional requirements, estimate scale, define the APIs and data model, draw the high-level design, then deep-dive into the hardest parts like scaling, consistency and failure handling, and finish with trade-offs and bottlenecks.","k":["requirements","estimate","api","data model","high level","deep dive"],"d":"c-system-design-framework"},{"id":"cn-c-tell-me-tradeoff","y":"concept","tr":"con","s":"System design basics","q":"Strong consistency or eventual consistency for a social media like count?","a":"Eventual consistency. A slightly stale count is harmless, and it lets us buffer increments, shard counters and serve from cache at huge scale. I'd keep the user's own like state consistent so their button reflects their action immediately.","k":["eventual","stale","counter","cache","read your writes"],"d":"c-tell-me-tradeoff"},{"id":"cn-c-leader-election","y":"concept","tr":"con","s":"Distributed systems","q":"Why do distributed systems need leader election, and how is it done?","a":"Some work must happen once, like assigning partitions or running a scheduler, so one node is chosen as leader. Use a consensus-backed store like ZooKeeper, etcd or Raft with leases and heartbeats; when the leader's lease expires, another takes over. Fencing tokens stop a stale leader from writing.","k":["leader","consensus","zookeeper","lease","fencing"],"d":"c-leader-election"},{"id":"cn-c-quorum","y":"concept","tr":"con","s":"Distributed systems","q":"In a replicated store with N copies, how do read and write quorums give consistency?","a":"Write to W replicas and read from R. If R plus W is greater than N, every read set overlaps the latest write set, so you read the newest value. Tune it: W equals N for durability, or small R for fast reads.","k":["quorum","r plus w","greater than n","replicas","tune"],"d":"c-quorum"},{"id":"cn-c-event-sourcing","y":"concept","tr":"con","s":"Distributed systems","q":"What is event sourcing and CQRS?","a":"Event sourcing stores every state change as an append-only event and rebuilds current state by replaying them, giving a full audit trail. CQRS separates the write model from read models built from those events, so each side scales and is shaped for its job.","k":["events","replay","audit","cqrs","projection"],"d":"c-event-sourcing"},{"id":"cn-c-behavioural-star","y":"concept","tr":"con","s":"Interview craft","q":"How do you structure an answer to a behavioural question like tell me about a time you handled a conflict?","a":"STAR: situation in a sentence or two, the task you owned, the actions you personally took with specifics, and the result with numbers if possible, plus what you learned. Keep it to about two minutes and say I, not we.","k":["situation","task","action","result","learned"],"d":"c-behavioural-star"},{"id":"cn-c-thinking-aloud","y":"concept","tr":"con","s":"Interview craft","q":"You don't know the optimal solution in a coding round. What do you say in the first minute?","a":"Restate the problem and confirm inputs, outputs and constraints, give a working brute force with its complexity, then say what makes it slow and which pattern might remove that work. That keeps the interviewer with you and earns hints.","k":["restate","constraints","brute force","complexity","bottleneck"],"d":"c-thinking-aloud"},{"id":"cn-c-testing-code","y":"concept","tr":"con","s":"Interview craft","q":"You've finished coding in an interview. How do you test it?","a":"Walk through one small normal example line by line, tracking variables, then check edge cases: empty input, one element, duplicates, negatives, and the largest constraints for overflow. Fix bugs out loud, then restate the time and space complexity.","k":["walk through","edge cases","empty","overflow","complexity"],"d":"c-testing-code"},{"id":"cb-sd-url-shortener-0","y":"curveball","tr":"sd","s":"System design · URL shortener","q":"A celebrity tweets one of your links and it gets a million clicks a minute. What breaks?","a":"The single hot key. Serve it from the CDN and local in-memory caches, and keep analytics async through Kafka so counting doesn't touch the redirect path.","d":"sd-url-shortener"},{"id":"cb-sd-url-shortener-1","y":"curveball","tr":"sd","s":"System design · URL shortener","q":"How do you stop people guessing other users' links?","a":"Sequential codes are guessable; shuffle the counter through a bijective permutation or add random bits, and rate-limit enumeration.","d":"sd-url-shortener"},{"id":"cb-sd-rate-limiter-0","y":"curveball","tr":"sd","s":"System design · Distributed rate limiter","q":"Redis goes down. What happens to your API?","a":"Fail open with per-node local limits, set to the global limit divided by node count, and alert; blocking all traffic is worse than a short over-allowance.","d":"sd-rate-limiter"},{"id":"cb-sd-rate-limiter-1","y":"curveball","tr":"sd","s":"System design · Distributed rate limiter","q":"How do you avoid a Redis round trip on every request?","a":"Keep a local token allowance per node and sync with Redis in batches, accepting slight inaccuracy.","d":"sd-rate-limiter"},{"id":"cb-sd-notifications-0","y":"curveball","tr":"sd","s":"System design · Notification system","q":"A marketing campaign wants to send 50 million emails right now. How do you protect OTPs?","a":"Separate queues and worker pools by priority, throttle bulk sends to provider limits, and schedule campaigns across hours.","d":"sd-notifications"},{"id":"cb-sd-notifications-1","y":"curveball","tr":"sd","s":"System design · Notification system","q":"A user complains they got the same notification three times. Why?","a":"Retries after timeouts where the first send succeeded. Dedupe with an idempotency key per notification and channel, and make workers check status before resending.","d":"sd-notifications"},{"id":"cb-sd-autocomplete-0","y":"curveball","tr":"sd","s":"System design · Search autocomplete","q":"How do you stop offensive suggestions appearing?","a":"A blocklist filter in the offline build plus a fast runtime kill switch for terms that slip through.","d":"sd-autocomplete"},{"id":"cb-sd-autocomplete-1","y":"curveball","tr":"sd","s":"System design · Search autocomplete","q":"Short prefixes like 'a' get enormous traffic. What do you do?","a":"Precompute and cache them at the CDN and in the browser; they change slowly.","d":"sd-autocomplete"},{"id":"cb-sd-chat-0","y":"curveball","tr":"sd","s":"System design · Chat app like WhatsApp","q":"The recipient is connected to a different server than the sender. How does the message get there?","a":"Look up the recipient's server in the presence registry and publish to that server's channel; it pushes down the open socket.","d":"sd-chat"},{"id":"cb-sd-chat-1","y":"curveball","tr":"sd","s":"System design · Chat app like WhatsApp","q":"A user has the app on a phone and a laptop. What changes?","a":"Track sessions per device, fan out to each, and keep per-device read cursors; history sync uses the conversation sequence.","d":"sd-chat"},{"id":"cb-sd-news-feed-0","y":"curveball","tr":"sd","s":"System design · News feed like Twitter","q":"A user follows 300 normal people and 2 celebrities. How do they get the celebrity posts?","a":"Pulled and merged when the feed is loaded, from the celebrities' own recent post lists.","d":"sd-news-feed"},{"id":"cb-sd-news-feed-1","y":"curveball","tr":"sd","s":"System design · News feed like Twitter","q":"A post is deleted. How do you remove it from millions of timelines?","a":"Don't rewrite timelines; filter deleted ids at hydration time and let them age out.","d":"sd-news-feed"},{"id":"cb-sd-ride-hailing-0","y":"curveball","tr":"sd","s":"System design · Ride hailing like Uber","q":"Two riders at the same corner request at the same moment. How do you avoid giving them the same driver?","a":"Reserve the driver with an atomic conditional update or Redis SETNX with a TTL before sending the offer; the loser picks the next candidate.","d":"sd-ride-hailing"},{"id":"cb-sd-ride-hailing-1","y":"curveball","tr":"sd","s":"System design · Ride hailing like Uber","q":"Why not store every location update in the main database?","a":"It's 250k writes per second of throwaway data; keep the live position in memory and sample trip paths to cheap storage.","d":"sd-ride-hailing"},{"id":"cb-sd-food-delivery-0","y":"curveball","tr":"sd","s":"System design · Food delivery like Zomato","q":"The restaurant rejects the order after the user paid. What happens?","a":"The order saga moves to cancelled and issues a refund as a compensating action, then notifies the user.","d":"sd-food-delivery"},{"id":"cb-sd-food-delivery-1","y":"curveball","tr":"sd","s":"System design · Food delivery like Zomato","q":"A restaurant goes viral at lunch. How do you protect it and the platform?","a":"Throttle orders per restaurant using its prep capacity and show longer ETAs instead of accepting everything.","d":"sd-food-delivery"},{"id":"cb-sd-video-streaming-0","y":"curveball","tr":"sd","s":"System design · Video streaming like YouTube","q":"A video goes viral in one country. What happens at the origin?","a":"Very little if the CDN caches its segments; use tiered caching so edges fetch from a regional cache, not the origin.","d":"sd-video-streaming"},{"id":"cb-sd-video-streaming-1","y":"curveball","tr":"sd","s":"System design · Video streaming like YouTube","q":"Transcoding a two-hour video takes too long. Speed it up?","a":"Split into chunks at keyframes and transcode chunks in parallel across workers, then stitch the manifest.","d":"sd-video-streaming"},{"id":"cb-sd-booking-0","y":"curveball","tr":"sd","s":"System design · Booking like Airbnb","q":"Two guests click Book on the same nights at the same moment. Who wins and how?","a":"The first transaction that flips all nights from FREE wins; the second sees fewer rows updated, rolls back and gets a \"just booked\" error.","d":"sd-booking"},{"id":"cb-sd-booking-1","y":"curveball","tr":"sd","s":"System design · Booking like Airbnb","q":"Search shows a listing as available but booking fails. Is that a bug?","a":"It's expected: search is eventually consistent; the booking transaction is the source of truth.","d":"sd-booking"},{"id":"cb-sd-file-sync-0","y":"curveball","tr":"sd","s":"System design · File sync like Dropbox","q":"Two devices edit the same file offline and reconnect. What happens?","a":"Commits carry the parent version; the second commit fails the version check, so we keep both and save one as a conflicted copy.","d":"sd-file-sync"},{"id":"cb-sd-file-sync-1","y":"curveball","tr":"sd","s":"System design · File sync like Dropbox","q":"A user renames a 10 GB folder. How much data moves?","a":"Almost none: it's a metadata change, since chunks are addressed by hash.","d":"sd-file-sync"},{"id":"cb-sd-payments-0","y":"curveball","tr":"sd","s":"System design · Payment system","q":"Your call to the provider times out. Did the customer get charged?","a":"Unknown. Mark it pending, query the provider by our idempotency key, and rely on the webhook; never retry with a new key.","d":"sd-payments"},{"id":"cb-sd-payments-1","y":"curveball","tr":"sd","s":"System design · Payment system","q":"Why a double-entry ledger instead of a balance column?","a":"Every movement is an immutable pair of debit and credit entries, so balances can be recomputed and audited, and errors show up as imbalances.","d":"sd-payments"},{"id":"cb-sd-distributed-cache-0","y":"curveball","tr":"sd","s":"System design · Distributed cache","q":"One key gets 100x more traffic than the rest. What do you do?","a":"Replicate it to several nodes with a suffix and read randomly, or add a short-lived local cache in clients.","d":"sd-distributed-cache"},{"id":"cb-sd-distributed-cache-1","y":"curveball","tr":"sd","s":"System design · Distributed cache","q":"A node dies. What happens to the database?","a":"Its keys miss and fall through to the database; consistent hashing limits that to one node's share, and a replica can be promoted to cut the spike.","d":"sd-distributed-cache"},{"id":"cb-sd-web-crawler-0","y":"curveball","tr":"sd","s":"System design · Web crawler","q":"A site generates infinite calendar URLs. How do you avoid getting stuck?","a":"Cap depth and URLs per host, detect repeating URL patterns, and lower priority for hosts with low-value pages.","d":"sd-web-crawler"},{"id":"cb-sd-web-crawler-1","y":"curveball","tr":"sd","s":"System design · Web crawler","q":"How do you make sure you don't hammer a small site?","a":"One queue per host with a minimum delay between requests and respect for robots.txt crawl-delay.","d":"sd-web-crawler"},{"id":"cb-sd-leaderboard-0","y":"curveball","tr":"sd","s":"System design · Gaming leaderboard","q":"The leaderboard grows to a billion players. What changes?","a":"Shard by score buckets; exact rank becomes the sum of counts above plus the rank within the bucket, or switch to approximate ranks for the long tail.","d":"sd-leaderboard"},{"id":"cb-sd-leaderboard-1","y":"curveball","tr":"sd","s":"System design · Gaming leaderboard","q":"Players cheat by sending fake scores. What do you do?","a":"Compute scores server-side from game events, validate ranges and rates, and flag outliers for review.","d":"sd-leaderboard"},{"id":"cb-lld-parking-lot-0","y":"curveball","tr":"sd","s":"Low-level design · Parking lot","q":"Two cars reach the last free spot through different gates at the same moment. What prevents both parking?","a":"Claiming the spot is one atomic step: a synchronized tryOccupy or a CAS on the spot's state; the loser asks for the next spot.","d":"lld-parking-lot"},{"id":"cb-lld-parking-lot-1","y":"curveball","tr":"sd","s":"Low-level design · Parking lot","q":"The business wants weekend flat pricing and special event pricing next month. Where does that change?","a":"Only new FeePolicy implementations; ParkingLot calls feePolicy.fee(ticket, exitTime) and doesn't change.","d":"lld-parking-lot"},{"id":"cb-lld-elevator-0","y":"curveball","tr":"sd","s":"Low-level design · Elevator system","q":"The car is at floor 6 going up with stops at 8 and 2. Someone presses 4. What's the next stop?","a":"8. LOOK keeps serving stops ahead in the current direction before reversing for 4 and then 2.","d":"lld-elevator"},{"id":"cb-lld-elevator-1","y":"curveball","tr":"sd","s":"Low-level design · Elevator system","q":"Management wants a different dispatch algorithm at night. What changes?","a":"Only a new DispatchStrategy implementation, selected by time or config.","d":"lld-elevator"},{"id":"cb-lld-movie-booking-0","y":"curveball","tr":"sd","s":"Low-level design · Movie ticket booking","q":"Ten app servers book seats at once. Why isn't synchronized enough?","a":"It only protects one JVM; the shared database's conditional update or a distributed lock must arbitrate.","d":"lld-movie-booking"},{"id":"cb-lld-movie-booking-1","y":"curveball","tr":"sd","s":"Low-level design · Movie ticket booking","q":"Payment succeeds just after the hold expired and someone else took the seat. What now?","a":"Detect it at confirm time, refund automatically, and apologise; or extend holds while a payment is in flight.","d":"lld-movie-booking"},{"id":"cb-lld-vending-machine-0","y":"curveball","tr":"sd","s":"Low-level design · Vending machine","q":"The machine can't make exact change. What should happen?","a":"Check before dispensing; if change can't be made, refuse the sale or ask for exact money, and refund the inserted coins.","d":"lld-vending-machine"},{"id":"cb-lld-vending-machine-1","y":"curveball","tr":"sd","s":"Low-level design · Vending machine","q":"Why the State pattern instead of if-else?","a":"Each state handles each action in one place, so adding Maintenance is a new class, not edits across every method.","d":"lld-vending-machine"},{"id":"cb-lld-logger-0","y":"curveball","tr":"sd","s":"Low-level design · Logging framework","q":"Logging is slowing down request latency. What do you change?","a":"Make appenders asynchronous with a bounded queue, check the level before building messages, and batch disk writes.","d":"lld-logger"},{"id":"cb-lld-logger-1","y":"curveball","tr":"sd","s":"Low-level design · Logging framework","q":"How would you add a new destination like Kafka?","a":"Implement the Appender interface and register it in config; no logger code changes.","d":"lld-logger"}];